[{"id":"e93f8e4","elType":"container","settings":[],"elements":[{"id":"cb5ea08","elType":"widget","settings":{"html":"<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Program Kerja PK PMII STAIM Kendal</title>

<link href="https://fonts.googleapis.com/css2?family=Playfair+Display:wght@600;700&family=Poppins:wght@300;400;500&display=swap" rel="stylesheet">

<style>
*{
  margin:0;
  padding:0;
  box-sizing:border-box;
}

body{
  background:#d6dde1;
  font-family:'Poppins', sans-serif;
}

/* ================= HEADER ================= */

.header{
  background:#0f7c80;
  color:white;
  text-align:center;
  padding:60px 20px 80px;
  position:relative;
  overflow:hidden;
}

.logo-container{
  background:white;
  width:220px;
  height:70px;
  border-radius:50px;
  margin:0 auto 30px;
  display:flex;
  align-items:center;
  justify-content:space-evenly;
}

.logo-container img{
  height:45px;
}

.header h1{
  font-family:'Playfair Display', serif;
  font-size:34px;
  letter-spacing:2px;
  margin-bottom:10px;
}

.header h2{
  font-size:18px;
  font-weight:400;
  margin-bottom:15px;
}

.header p{
  font-size:14px;
  font-style:italic;
  opacity:0.9;
}

/* Dekorasi bulat kanan */
.header::after{
  content:"";
  position:absolute;
  right:-100px;
  bottom:-120px;
  width:350px;
  height:350px;
  background:rgba(255,255,255,0.08);
  border-radius:50%;
}

/* ================= SECTION TITLE ================= */

.section-title{
  background:#1e8a8f;
  color:white;
  padding:12px 20px;
  font-weight:600;
  font-size:15px;
  letter-spacing:1px;
}

.section{
  padding:30px 40px 50px;
  background:#cfd8dc;
}

/* ================= STRUKTUR BOX ================= */

.struktur-container{
  display:flex;
  gap:20px;
  margin-top:20px;
}

.struktur-box{
  flex:1;
  background:white;
  border-radius:3px;
  overflow:hidden;
  box-shadow:0 2px 6px rgba(0,0,0,0.08);
}

.struktur-box .top-bar{
  height:20px;
}

.struktur-box:nth-child(1) .top-bar{ background:#0f7c80;}
.struktur-box:nth-child(2) .top-bar{ background:#1e8a8f;}
.struktur-box:nth-child(3) .top-bar{ background:#23a39e;}
.struktur-box:nth-child(4) .top-bar{ background:#135f63;}

.struktur-box .content{
  padding:20px;
  text-align:center;
  font-weight:500;
  font-size:14px;
}

.note{
  margin-top:15px;
  font-size:12px;
  font-style:italic;
  text-align:center;
}

/* ================= KETUA & BIDANG ================= */

.ketua-container{
  margin-top:25px;
  display:flex;
  gap:30px;
}

.column{
  flex:1;
}

.column h3{
  font-size:14px;
  margin-bottom:10px;
  border-bottom:3px solid #1e8a8f;
  display:inline-block;
  padding-bottom:3px;
}

.column ul{
  margin-top:10px;
  font-size:12px;
  padding-left:18px;
}

.column ul li{
  margin-bottom:6px;
}

.card{
  background:white;
  padding:20px;
  font-size:12px;
  box-shadow:0 2px 6px rgba(0,0,0,0.08);
  border-radius:3px;
  margin-top:10px;
}

@media(max-width:900px){
  .struktur-container,
  .ketua-container{
    flex-direction:column;
  }
}
</style>
</head>

<body>

<!-- ================= HEADER ================= -->

<div class="header">

  <div class="logo-container">
    <img src="https://upload.wikimedia.org/wikipedia/commons/5/55/Logo_PMII.png" alt="Logo PMII">
    <img src="https://upload.wikimedia.org/wikipedia/commons/3/3a/Logo_Kabupaten_Kendal.png" alt="Logo Kendal">
    <img src="https://upload.wikimedia.org/wikipedia/commons/8/88/Lambang_NU.png" alt="Logo NU">
  </div>

  <h1>PROGRAM KERJA</h1>
  <h2>PK PMII STAIM KENDAL</h2>
  <p>Masa Khidmad 2025/2026</p>

</div>

<!-- ================= STRUKTUR ================= -->

<div class="section-title">
  STRUKTUR ORGANISASI KOMISARIAT
</div>

<div class="section">

  <div class="struktur-container">
    <div class="struktur-box">
      <div class="top-bar"></div>
      <div class="content">
        Ketua I<br>
        (Kaderisasi)
      </div>
    </div>

    <div class="struktur-box">
      <div class="top-bar"></div>
      <div class="content">
        Ketua II<br>
        (Internal)
      </div>
    </div>

    <div class="struktur-box">
      <div class="top-bar"></div>
      <div class="content">
        Ketua III<br>
        (Eksternal)
      </div>
    </div>

    <div class="struktur-box">
      <div class="top-bar"></div>
      <div class="content">
        Biro Media dan<br>
        Pengembangan Publikasi
      </div>
    </div>
  </div>

  <div class="note">
    * Program Kerja PK PMII (Akan Terlampir PDF)
  </div>

</div>

<!-- ================= KETUA I ================= -->

<div class="section-title">
  KETUA I - BIDANG KADERISASI
</div>

<div class="section">

  <div class="ketua-container">

    <div class="column">
      <h3>Kaderisasi Non Formal</h3>
      <ul>
        <li>MAPABA Komisariat</li>
        <li>PKD Rayon</li>
        <li>Pelatihan Administrasi</li>
        <li>Forum Diskusi Rutin</li>
        <li>Bedah Buku</li>
        <li>Pelatihan Kepemimpinan</li>
        <li>Pelatihan Public Speaking</li>
        <li>Pelatihan Media</li>
        <li>Kajian Ideologi PMII</li>
        <li>Makrab & Raker</li>
      </ul>
    </div>

    <div class="column">
      <h3>Kaderisasi Formal</h3>
      <div class="card">
        <p><strong>Pelatihan Kader Dasar (PKD)</strong></p>
        <br>
        <p><strong>Pelatihan Kader Lanjut (PKL)</strong></p>
      </div>
    </div>

  </div>

</div>

</body>
</html>
"},"elements":[],"widgetType":"html"}],"isInner":false}]

[{"id":"782d1d5","elType":"container","settings":[],"elements":[{"id":"4ca4157","elType":"widget","settings":{"html":"<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>PMII Komisariat Kampus</title>

<link href="https://fonts.googleapis.com/css2?family=Poppins:wght@300;400;600;700&display=swap" rel="stylesheet">

<style>
*{
margin:0;
padding:0;
box-sizing:border-box;
font-family:'Poppins',sans-serif;
}

body{
background:#f4f7ff;
color:#111;
overflow-x:hidden;
}

/* NAVBAR */
nav{
position:fixed;
width:100%;
top:0;
left:0;
background:rgba(0,51,160,0.95);
backdrop-filter:blur(10px);
padding:15px 8%;
display:flex;
justify-content:space-between;
align-items:center;
z-index:1000;
}

nav h2{
color:#FFD700;
font-weight:700;
letter-spacing:1px;
}

nav ul{
display:flex;
gap:25px;
list-style:none;
}

nav ul li a{
color:white;
text-decoration:none;
font-weight:500;
transition:.3s;
}

nav ul li a:hover{
color:#FFD700;
}

/* HERO */
.hero{
height:100vh;
display:flex;
justify-content:center;
align-items:center;
text-align:center;
background:linear-gradient(135deg,#0033A0,#0b1c3d);
color:white;
padding:0 10%;
position:relative;
}

.hero::after{
content:"";
position:absolute;
width:400px;
height:400px;
background:#FFD700;
filter:blur(180px);
opacity:.2;
border-radius:50%;
top:20%;
}

.hero-content{
z-index:2;
}

.hero h1{
font-size:48px;
font-weight:700;
margin-bottom:15px;
}

.hero p{
font-size:18px;
opacity:.9;
margin-bottom:30px;
}

.btn{
padding:12px 30px;
border-radius:30px;
border:none;
cursor:pointer;
font-weight:600;
transition:.3s;
margin:5px;
}

.btn-primary{
background:#FFD700;
color:#0033A0;
}

.btn-primary:hover{
box-shadow:0 0 20px #FFD700;
}

.btn-secondary{
background:transparent;
border:2px solid #FFD700;
color:#FFD700;
}

.btn-secondary:hover{
background:#FFD700;
color:#0033A0;
}

/* SECTION */
.section{
padding:100px 10%;
}

.section h2{
text-align:center;
color:#0033A0;
margin-bottom:50px;
font-size:32px;
}

/* CARDS */
.cards{
display:grid;
grid-template-columns:repeat(auto-fit,minmax(250px,1fr));
gap:30px;
}

.card{
background:white;
padding:30px;
border-radius:20px;
box-shadow:0 10px 30px rgba(0,0,0,0.08);
transition:.4s;
}

.card:hover{
transform:translateY(-10px);
box-shadow:0 20px 40px rgba(0,51,160,0.2);
}

.card h3{
color:#0033A0;
margin-bottom:15px;
}

/* FOOTER */
footer{
background:#0b1c3d;
color:white;
text-align:center;
padding:40px 10%;
}

footer p{
opacity:.8;
}

/* RESPONSIVE */
@media(max-width:768px){
.hero h1{
font-size:32px;
}
}
</style>
</head>

<body>

<nav>
<h2>PMII Komisariat</h2>
<ul>
<li><a href="#">Beranda</a></li>
<li><a href="#">Tentang</a></li>
<li><a href="#">Program</a></li>
<li><a href="#">Kontak</a></li>
</ul>
</nav>

<section class="hero">
<div class="hero-content">
<h1>PMII Komisariat Kampus</h1>
<p>Bergerak · Berpikir · Berjuang untuk Peradaban</p>
<button class="btn btn-primary">Gabung Sekarang</button>
<button class="btn btn-secondary">Pelajari Lebih Lanjut</button>
</div>
</section>

<section class="section">
<h2>Tentang Kami</h2>
<div class="cards">
<div class="card">
<h3>Visi</h3>
<p>Mewujudkan kader yang berintelektual, progresif, dan berakhlakul karimah.</p>
</div>
<div class="card">
<h3>Misi</h3>
<p>Mengembangkan kaderisasi, penguatan ideologi, dan kontribusi sosial kemasyarakatan.</p>
</div>
<div class="card">
<h3>Nilai Dasar</h3>
<p>Islam Ahlussunnah wal Jamaah, Kebangsaan, dan Intelektualitas.</p>
</div>
</div>
</section>

<section class="section">
<h2>Program Unggulan</h2>
<div class="cards">
<div class="card">
<h3>Kaderisasi</h3>
<p>Pelatihan PKD, MAPABA, dan forum intelektual rutin.</p>
</div>
<div class="card">
<h3>Pengabdian</h3>
<p>Kegiatan sosial, bakti masyarakat, dan advokasi mahasiswa.</p>
</div>
<div class="card">
<h3>Kajian</h3>
<p>Diskusi ilmiah, seminar, dan pengembangan intelektual.</p>
</div>
</div>
</section>

<footer>
<p>© 2026 PMII Komisariat Kampus. All Rights Reserved.</p>
</footer>

</body>
</html>"},"elements":[],"widgetType":"html"}],"isInner":false}]

a:1:{s:10:"custom_css";s:5661:"<!-- Font Awesome -->
<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css" crossorigin="anonymous" />

<style>
/* === NAVIGATION BAR ULTRA FUTURISTIC (PMII EDITION) === */
.hover-expand-bar {
  position: relative;
  width: 100%;
  height: 18px;
  background: linear-gradient(270deg, #FFD500, #0095FF, #FFD500, #0066CC); /* GRADIENT KUNING-BIRU */
  background-size: 400% 400%;
  animation: moving-gradient 6s linear infinite;
  border-radius: 16px;
  transition: height 0.4s ease;
  cursor: pointer;
  z-index: 10;
  overflow: visible;
  box-shadow: 0 0 30px rgba(0, 170, 255, 0.15), inset 0 0 5px rgba(255, 200, 0, 0.1);
}

/* CAHAYA LINTAS */
.hover-expand-bar::after {
  content: "";
  position: absolute;
  top: 0;
  left: -50%;
  width: 50%;
  height: 100%;
  background: linear-gradient(to right, transparent, rgba(255,255,255,0.18), transparent);
  animation: soft-shine 3s linear infinite;
  pointer-events: none;
  border-radius: inherit;
}

/* PULSE HALUS */
.hover-expand-bar::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at center, rgba(0, 150, 255, 0.12), transparent 80%);
  animation: soft-pulse 3s ease-in-out infinite;
  border-radius: inherit;
  pointer-events: none;
  z-index: 0;
}

/* === HOVER EXPAND === */
.hover-expand-bar:hover {
  height: 140px;
  backdrop-filter: blur(14px);
  box-shadow: 0 12px 40px rgba(0, 150, 255, 0.18);
  background-image:
    repeating-linear-gradient(45deg, rgba(255,255,0,0.05) 0, rgba(255,255,0,0.05) 20px, transparent 20px, transparent 40px),
    repeating-radial-gradient(circle, rgba(0,170,255,0.06) 0, rgba(0,170,255,0.06) 14px, transparent 14px, transparent 34px);
  background-size: 80px 80px;
  animation: moving-gradient 2s linear infinite, bgPattern 12s linear infinite;
}

/* === ISI MENU === */
.bar-content {
  opacity: 0;
  transition: opacity 0.5s ease 0.2s;
  padding: 28px 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  height: 100%;
  position: relative;
  z-index: 5;
}

.hover-expand-bar:hover .bar-content {
  opacity: 1;
}

/* === NAVBAR === */
.navbar {
  display: flex;
  gap: 28px;
  flex-wrap: wrap;
  justify-content: center;
}

.navbar a,
.dropdown-toggle {
  color: #e8f6ff;
  font-size: 16px;
  font-weight: 600;
  text-decoration: none;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 20px;
  border: 1px solid rgba(0, 150, 255, 0.3);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.04);
  backdrop-filter: blur(10px);
  transition: all 0.35s ease;
  box-shadow: inset 0 0 5px rgba(0, 150, 255, 0.15);
}

.navbar a:hover,
.dropdown-toggle:hover {
  background: rgba(0, 150, 255, 0.12);
  color: #FFD500;
  transform: translateY(-2px);
  box-shadow: 0 0 12px rgba(0, 150, 255, 0.25);
}

/* ICON */
.navbar i {
  transition: transform 0.6s ease;
}
.navbar a:hover i,
.dropdown-toggle:hover i {
  animation: iconRotate 2s linear infinite;
}

/* === DROPDOWN === */
.dropdown {
  position: relative;
  display: flex;
  align-items: center;
  cursor: pointer;
}

/* HAPUS sistem hover */
.dropdown:hover .dropdown-menu {
  display: none !important;
  opacity: 0 !important;
  pointer-events: none !important;
  transform: translateY(-14px) !important;
}

/* SISTEM KLIK */
.dropdown.open .dropdown-menu {
  display: flex !important;
  opacity: 1 !important;
  pointer-events: auto !important;
  transform: translateY(0) !important;
}

.dropdown-menu {
  position: absolute;
  top: calc(100% + 12px);
  left: 0;
  display: none;
  flex-direction: column;
  background: rgba(0, 150, 255, 0.12);
  backdrop-filter: blur(20px);
  border-radius: 20px;
  padding: 12px 0;
  box-shadow: 0 20px 40px rgba(0, 150, 255, 0.18);
  min-width: 200px;
  z-index: 99;
  opacity: 0;
  pointer-events: none;
  transform: translateY(-14px);
  transition: 0.35s ease;
}

.dropdown-menu li {
  list-style: none;
  width: 100%;
}

.dropdown-menu li a {
  display: block;
  width: 100%;
  padding: 14px 22px;
  font-size: 15px;
  font-weight: 500;
  color: #d0ecff;
  text-decoration: none;
  border-left: 4px solid transparent;
  transition: all 0.3s ease;
}

.dropdown-menu li a:hover {
  background: rgba(255,215,0,0.15);
  color: #FFD500;
  border-left: 4px solid #FFD500;
  transform: translateX(6px);
}

/* === ANIMASI === */
@keyframes soft-shine {
  0% { left: -50%; }
  100% { left: 150%; }
}
@keyframes soft-pulse {
  0%, 100% { opacity: 0.3; }
  50% { opacity: 0.8; }
}
@keyframes moving-gradient {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}
@keyframes iconRotate {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}
@keyframes bgPattern {
  0% { background-position: 0 0; }
  100% { background-position: 80px 80px; }
}
</style>

<!-- === HTML MENU === -->
<div class="hover-expand-bar">
  <div class="bar-content">
    <nav class="navbar">

      <a href="#"><i class="fas fa-home"></i> Beranda</a>
      <a href="#"><i class="fas fa-info-circle"></i> Tentang</a>

      <div class="dropdown" onclick="this.classList.toggle('open')">
        <div class="dropdown-toggle"><i class="fas fa-bars"></i> Menu</div>
        <ul class="dropdown-menu">
          <li><a href="#">Menu 1</a></li>
          <li><a href="#">Menu 2</a></li>
          <li><a href="#">Menu 3</a></li>
          <li><a href="#">Menu 4</a></li>
          <li><a href="#">Menu 5</a></li>
        </ul>
      </div>

      <a href="#"><i class="fas fa-cogs"></i> Layanan</a>
      <a href="#"><i class="fas fa-envelope"></i> Kontak</a>

    </nav>
  </div>
</div>
";}

[{"id":"7849ac5","elType":"container","settings":{"hide_desktop":"hidden-desktop","hide_tablet":"hidden-tablet","hide_mobile":"hidden-mobile"},"elements":[{"id":"2c0f79b","elType":"widget","settings":{"html":"<!DOCTYPE html>
<html lang="id">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Tentang Kami | PMII – Ultra Futuristic</title>

  <!-- GOOGLE FONT -->
  <link href="https://fonts.googleapis.com/css2?family=Orbitron:wght@400;600;800;900&family=Poppins:wght@300;400;600&display=swap" rel="stylesheet">

  <style>
    *{margin:0;padding:0;box-sizing:border-box}

    body{
      font-family:'Poppins',sans-serif;
      color:#eaffff;
      overflow-x:hidden;
      background:#02030a;
    }

    /* ===== IMAGE FUTURISTIC BACKGROUND ===== */
    body::before{
      content:"";
      position:fixed;
      inset:0;
      background:
        linear-gradient(
          to bottom,
          rgba(2,3,10,.9),
          rgba(2,3,10,.7),
          rgba(2,3,10,.95)
        ),
        url("https://i.supaimg.com/54ba361b-3a27-4a97-ae60-68342c5e0fa4.png");
      background-size:cover;
      background-position:center;
      background-repeat:no-repeat;
      z-index:-1;
      animation:bgFloat 26s ease-in-out infinite;
    }

    @keyframes bgFloat{
      0%{transform:scale(1) translateY(0)}
      50%{transform:scale(1.05) translateY(-30px)}
      100%{transform:scale(1) translateY(0)}
    }

    /* ===== HERO ===== */
    .hero{
      height:100vh;
      display:flex;
      align-items:center;
      justify-content:center;
      text-align:center;
      position:relative;
    }

    .hero::after{
      content:"";
      position:absolute;
      bottom:0;left:0;right:0;
      height:220px;
      background:linear-gradient(to top,#02030a,transparent);
    }

    .hero-content{z-index:1;max-width:900px;padding:20px}

    .hero h1{
      font-family:'Orbitron',sans-serif;
      font-size:4.8rem;
      font-weight:900;
      background:linear-gradient(90deg,#00ffe7,#00aaff,#00ffe7);
      background-size:200% auto;
      -webkit-background-clip:text;
      -webkit-text-fill-color:transparent;
      animation:shine 6s linear infinite;
      text-shadow:0 0 45px rgba(0,255,255,.6);
    }

    @keyframes shine{
      to{background-position:200% center}
    }

    .hero p{
      margin-top:18px;
      font-size:1.4rem;
      color:#bfffff;
      letter-spacing:1px;
    }

    .glow-divider{
      width:170px;
      height:5px;
      margin:35px auto 0;
      background:linear-gradient(90deg,#00ffe7,#0077ff);
      box-shadow:0 0 25px #00ffe7,0 0 60px #0077ff;
      border-radius:4px;
      animation:pulse 2s infinite;
    }

    @keyframes pulse{
      0%,100%{opacity:1}
      50%{opacity:.6}
    }

    /* ===== SECTION ===== */
    section{
      padding:120px 8%;
      position:relative;
    }

    .section-title{
      font-family:'Orbitron',sans-serif;
      font-size:3rem;
      text-align:center;
      margin-bottom:25px;
      color:#00ffe7;
      text-shadow:0 0 25px rgba(0,255,255,.7);
    }

    .section-desc{
      max-width:950px;
      margin:0 auto 80px;
      text-align:center;
      font-size:1.1rem;
      line-height:2;
      color:#d8ffff;
    }

    /* ===== HOLOGRAM CARDS ===== */
    .grid{
      display:grid;
      grid-template-columns:repeat(auto-fit,minmax(280px,1fr));
      gap:40px;
    }

    .card{
      position:relative;
