  border-top:1px solid rgba(0,255,255,.25);
  color:#8affff;
  font-size:.85rem;
  z-index:3;
  position:relative;
}

@media(max-width:768px){
  .hero h1{font-size:3.5rem;}
  .section-title{font-size:2.4rem;}
}

/* Particle generator helper */
</style>
</head>

