  text-shadow:
    2px 2px 0 #000,
    -2px -2px 0 #000,
    1px -1px 0 #000,
    -1px 1px 0 #000;
  animation: yellowComicPulse 2.5s infinite alternate;
}

/* === PULSE COMIC === */
@keyframes blueComicPulse {
  0% { text-shadow: 1px 1px 0 #000, -1px -1px 0 #000; }
  50% { text-shadow: 3px 3px 0 #000, -3px -3px 0 #000; }
  100% { text-shadow: 1px 1px 0 #000, -1px -1px 0 #000; }
}

@keyframes yellowComicPulse {
  0% { text-shadow: 1px 1px 0 #000, -1px -1px 0 #000; }
  50% { text-shadow: 3px 3px 0 #000, -3px -3px 0 #000; }
  100% { text-shadow: 1px 1px 0 #000, -1px -1px 0 #000; }
}

/* === MICRO COMIC GLITCH === */
.pmii-dual::before,
.pmii-dual::after {
  content: attr(data-text);
  position: absolute;
  left: 0;
  top: 0;
  opacity: .2;
  pointer-events: none;
  white-space: nowrap;
  font-family: 'Bangers', cursive;
}

.pmii-dual::before {
  color: #1e90ff;
  animation: comicGlitchLeft 4s infinite;
}

.pmii-dual::after {
  color: #ffd700;
  animation: comicGlitchRight 5s infinite;
}

@keyframes comicGlitchLeft {
  0%,94%,100% { transform: translate(0,0) rotate(0deg); }
  96% { transform: translate(-2px,1px) rotate(-1deg); }
}

@keyframes comicGlitchRight {
  0%,95%,100% { transform: translate(0,0) rotate(0deg); }
  97% { transform: translate(2px,-1px) rotate(1deg); }
}

/* === COMIC HIGHLIGHT LINE === */
.pmii-dual-wrap::after {
  content: "";
  display: block;
  width: 200px;
  height: 3px;
  margin: 10px auto 0;
  background: linear-gradient(90deg, transparent, #1e90ff, #ffd700, transparent);
  animation: comicLinePulse 2.5s infinite alternate;
}

@keyframes comicLinePulse {
  0% { opacity: .5; transform: scaleX(.5); }
  50% { opacity: 1; transform: scaleX(1); }
  100% { opacity: .5; transform: scaleX(.5); }
}
</style>"},"elements":[],"widgetType":"html"}],"isInner":true},{"id":"4ecc923","elType":"container","settings":{"content_width":"full"},"elements":[],"isInner":true}],"isInner":false},{"id":"6d7e94f","elType":"container","settings":{"flex_direction":"column"},"elements":[{"id":"8ff33b4","elType":"widget","settings":{"html":"<!DOCTYPE html>
<html lang="id">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">

    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Montserrat:ital,wght@0,400;0,500;0,600;0,700;0,800&display=swap" rel="stylesheet">

    <style>
        /* RESET & PENGATURAN DASAR - SCROLL NORMAL KEMBALI */
        html, body {
            margin: 0;
            padding: 0;
            width: 100%;
            /* height: 100%; DIHAPUS AGAR BISA SCROLL */
            background-color: #154835;
            -webkit-text-size-adjust: 100%;
        }

        #ks-mobile-lockdown {
            font-family: 'Montserrat', sans-serif;
            background: linear-gradient(135deg, #f4f8f6 0%, #e8f0ea 100%);
            color: #333;
            width: 100%;
            min-height: 100vh;
            display: flex;
            flex-direction: column;
            overflow-x: hidden;
            box-sizing: border-box;
            line-height: 1.6;
        }

        #ks-mobile-lockdown * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        /* ANIMASI MASUK MENGALUN */
        @keyframes pageFadeInUp {
            0% { opacity: 0; transform: translateY(15px); }
            100% { opacity: 1; transform: translateY(0); }
        }

        /* AREA KONTEN UTAMA */
        .ks-content-area {
            flex: 1;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            padding: 40px 24px;
            width: 100%;
            max-width: 420px;
            margin: 0 auto;
            animation: pageFadeInUp 0.8s cubic-bezier(0.2, 0.8, 0.2, 1) forwards;
        }

        /* LOGO */
        .ks-header-logo {
            width: 75px;
            height: auto;
            margin-bottom: 24px;
            filter: drop-shadow(0 6px 12px rgba(21, 72, 53, 0.15));
        }

        /* KELOMPOK JUDUL */
        .ks-title-group {
            text-align: center;
            margin-bottom: 20px;
            width: 100%;
        }

        .ks-title-group h1 {
            font-size: 22px;
            font-weight: 800;
            color: #154835;
            margin-bottom: 10px;
            text-transform: uppercase;
            line-height: 1.35;
            letter-spacing: 0.5px;
            text-shadow: 0 4px 12px rgba(0, 0, 0, 0.6); 
        }

        .ks-subtitle-row {
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 12px;
            width: 100%;
        }

        .ks-subtitle-row h2 {
            font-size: 13px;
            font-weight: 700;
            color: #c29b46;
            text-transform: uppercase;
            letter-spacing: 1.5px;
            white-space: nowrap;
        }

        .ks-gold-line {
            height: 1px;
            flex: 1;
            max-width: 35px;
            background-color: #c29b46;
            opacity: 0.8;
        }

        /* DESKRIPSI UTAMA */
        .ks-description {
            text-align: center;
            font-size: 13px;
            color: #5a6b63;
            font-weight: 500;
            line-height: 1.65;
            margin-bottom: 32px;
            padding: 0 10px;
        }

        /* KOTAK KONTEN (CARD UI MODERN) */
        .ks-premium-card {
            background-color: #ffffff;
            border-radius: 14px;
            width: 100%;
            padding: 20px 22px;
            margin-bottom: 20px;
            box-shadow: 0 8px 25px rgba(21, 72, 53, 0.05);
            border: 1px solid rgba(21, 72, 53, 0.04);
            display: flex;
            flex-direction: column;
            gap: 16px;
        }

        /* CARD PERINGATAN KHUSUS */
        .ks-alert-card {
            border-left: 5px solid #154835;
            flex-direction: row;
            align-items: center; /* Diubah ke center agar sejajar sempurna */
        }

        .ks-icon-wrap {
            width: 38px;
            height: 38px;
            flex-shrink: 0;
            display: block; /* Mencegah extra margin dari inline SVG */
        }

        .ks-alert-card p {
            font-size: 13px;
            font-weight: 600;
            color: #154835;
            line-height: 1.55;
            margin: 0;
        }

        .ks-alert-card p strong {
            color: #c29b46;
            font-weight: 800;
        }

        /* PEMISAH (DIVIDER) */
        .ks-divider-row {
            display: flex;
            align-items: center;
            width: 100%;
            margin-bottom: 20px;
            opacity: 0.5;
        }

        .ks-div-line {
            flex: 1;
            height: 1px;
            background-image: linear-gradient(to right, transparent, #c29b46, transparent);
        }

        .ks-div-icon {
            width: 16px;
            height: 16px;
            margin: 0 12px;
            stroke: #c29b46;
            display: block;
        }

        /* BAGIAN REKOMENDASI */
        .ks-rec-row {
            display: flex;
            align-items: center; /* Diubah ke center agar sejajar rapi antara ikon & teks */
            gap: 14px;
        }

        .ks-rec-text {
            display: flex;
            flex-direction: column;
            gap: 2px;
        }

        .ks-rec-text h3 {
            font-size: 13.5px;
            font-weight: 800;
            color: #154835;
            letter-spacing: 0.5px;
            line-height: 1.2;
        }

        .ks-rec-text p {
            font-size: 12.5px;
            color: #666;
            font-weight: 500;
            line-height: 1.5;
        }

        /* ANIMASI CHECKLIST (MOCKUP MENU) */
        .ks-anim-title {
            font-size: 10px;
            font-weight: 700;
            color: #999;
            text-transform: uppercase;
            letter-spacing: 1.2px;
            margin-bottom: 6px;
        }

        /* PERBAIKAN ALIGNMENT SUPER PRESISI DI BAR MOCKUP */
        .ks-mock-menu-item {
            display: flex;
            justify-content: space-between;
            align-items: center;
            background: #f4f8f6;
            padding: 12px 16px;
            border-radius: 8px;
            position: relative;
            border: 1px solid #e0e8e4;
        }

        .ks-mock-text {
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .ks-mock-text svg {
            display: block;
            margin-top: -1px; /* Koreksi optikal halus */
        }

        .ks-mock-text span {
            font-size: 13px;
            font-weight: 600;
            color: #154835;
            line-height: 1; /* Mematikan tinggi baris berlebih agar sejajar sempurna */
            padding-top: 1px; /* Koreksi optikal untuk huruf besar */
        }

        .ks-checkbox-mock {
            width: 22px;
            height: 22px;
            border: 1.5px solid #cbd5e1;
            border-radius: 5px;
            position: relative;
            background: transparent;
            animation: boxCheck 4s infinite;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        /* Presisi absolute center untuk tanda centang */
        .ks-checkmark-mock {
            position: absolute;
            top: 45%;
            left: 50%;
            width: 5px;
            height: 11px;
            border: solid white;
            border-width: 0 2px 2px 0;
            /* Membawa titik tengah elemen tepat ke titik tengah kotak */
            transform: translate(-50%, -50%) rotate(45deg);
            opacity: 0;
            animation: markCheck 4s infinite;
        }

        .ks-pointer-mock {
            position: absolute;
            right: -10px;
            top: 22px;
            width: 24px;
            height: 24px;
            fill: #c29b46;
            opacity: 0;
            z-index: 10;
            filter: drop-shadow(0 4px 4px rgba(0,0,0,0.25));
            animation: pointerClick 4s infinite;
        }

        @keyframes boxCheck {
            0%, 20% { background: transparent; border-color: #cbd5e1; }
            35%, 85% { background: #154835; border-color: #154835; box-shadow: 0 2px 6px rgba(21, 72, 53, 0.3); }
            100% { background: transparent; border-color: #cbd5e1; }
        }

        @keyframes markCheck {
            0%, 20% { opacity: 0; }
            35%, 85% { opacity: 1; }
            100% { opacity: 0; }
        }

        @keyframes pointerClick {
            0% { transform: translate(15px, 15px); opacity: 0; }
            15% { transform: translate(0, 0); opacity: 1; }
            25% { transform: translate(0, 0) scale(0.85); opacity: 1; } 
            35% { transform: translate(0, 0) scale(1); opacity: 0; } 
            100% { opacity: 0; }
        }

        /* AREA FOOTER */
        .ks-footer-area {
            width: 100%;
            margin-top: auto;
        }

        .ks-wave {
            display: block;
            width: 100%;
            height: auto;
            margin-bottom: -1px;
        }

        .ks-footer-bg {
            background-color: #154835;
            padding: 5px 24px 35px 24px;
            display: flex;
            flex-direction: column;
            gap: 20px;
        }

        .ks-footer-info {
            display: flex;
            align-items: center;
            gap: 14px;
            justify-content: center;
        }

        .ks-footer-logo {
            width: 45px;
            height: auto;
            flex-shrink: 0;
            filter: drop-shadow(0 2px 4px rgba(0,0,0,0.25));
        }

        .ks-footer-text {
            display: flex;
            flex-direction: column;
            gap: 1px;
            text-align: left;
        }

        .ks-footer-text strong {
            color: #ffffff;
            font-size: 13.5px;
            font-weight: 700;
            letter-spacing: 0.5px;
        }

        .ks-footer-text span.sub {
            color: #c29b46;
            font-size: 10px;
            font-weight: 700;
            letter-spacing: 0.5px;
            text-transform: uppercase;
        }

        .ks-footer-text span.quote {
            color: rgba(255, 255, 255, 0.6);
            font-size: 9.5px;
            font-style: italic;
            margin-top: 4px;
        }

        .ks-footer-socials {
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 25px;
            border-top: 1px solid rgba(255, 255, 255, 0.08);
            padding-top: 18px;
        }

        .ks-soc-icon {
            fill: none;
            stroke: #ffffff;
            stroke-width: 1.5;
            width: 18px;
            height: 18px;
            opacity: 0.7;
            transition: all 0.3s ease;
            display: block;
        }

        .ks-soc-icon:hover {
            opacity: 1;
            transform: scale(1.1);
        }
    </style>
</head>
<body>

