<html lang="id">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Neo-Brutalism Final Navbar - Tentang Kami Outside</title>

    <!-- Font Awesome 6.5.0 -->
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css" crossorigin="anonymous" />
    <!-- Google Font: Outfit -->
    <link href="https://fonts.googleapis.com/css2?family=Outfit:wght@500;900&display=swap" rel="stylesheet">

    <style>
        /* ================= RESET ================= */
        * { box-sizing: border-box; margin: 0; padding: 0; }
        body { 
            background: transparent; 
            font-family: 'Outfit', sans-serif; 
            padding: 120px 20px; 
        }

        /* ============ BAR UTAMA (SLIM) ============ */
        .hover-expand-bar {
            position: relative;
            width: 100%;
            height: 20px; 
            background: linear-gradient(90deg, #0066CC, #FFD500, #0095FF, #FFD500);
            background-size: 300% 300%;
            border-radius: 40px;
            border: 4px solid #000;
            box-shadow: 10px 10px 0px #000;
            transition: all .6s cubic-bezier(0.23, 1, 0.32, 1);
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            animation: moving-gradient 8s ease infinite;
            z-index: 10;
        }

        .hover-expand-bar::before {
            content: "";
            position: absolute;
            top: 0; left: 0; width: 100%; height: 100%;
            background-image: 
                radial-gradient(circle at 50% 50%, transparent 20%, rgba(255,255,255,0.15) 21%, transparent 25%),
                radial-gradient(circle at 20% 30%, transparent 10%, rgba(0,0,0,0.1) 11%, transparent 15%),
                repeating-radial-gradient(circle at 0 0, transparent 0, transparent 40px, rgba(255,213,0,0.1) 41px, rgba(255,213,0,0.1) 45px, transparent 46px);
            background-size: 100px 100px;
            animation: spiral-rotate 20s linear infinite;
            pointer-events: none;
            opacity: 0.6;
            border-radius: 35px;
        }

        /* ============ HANDLE PANAH ============ */
        .white-handle {
            position: absolute;
            width: 110px;  
            height: 50px;  
            background: #fff;
            border: 5px solid #000; 
            border-radius: 20px;
            display: flex;
            align-items: center;
            justify-content: center;
            box-shadow: 6px 6px 0px #000;
            z-index: 15;
            transition: all 0.5s cubic-bezier(0.68, -0.6, 0.32, 1.6);
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
        }

        .panah-group {
            display: flex;
            flex-direction: column; 
            color: #000;
            font-size: 16px; 
            line-height: 0.5; 
        }

        .panah-group i { animation: slide-down-anim 1.5s infinite ease-in-out; }
        .panah-group i:nth-child(2) { animation-delay: 0.2s; }
        .panah-group i:nth-child(3) { animation-delay: 0.4s; }

        /* ============ POPUP OPEN ============ */
        .hover-expand-bar:hover {
            height: 120px; 
            transform: translateY(-10px);
            box-shadow: 20px 20px 0px rgba(0,0,0,0.1), 12px 12px 0px #000;
        }

        .hover-expand-bar:hover .white-handle { 
            opacity: 0; 
            transform: translate(-50%, -180%) scale(0) rotate(15deg); 
        }

        /* ============ CONTENT ============ */
        .bar-content {
            opacity: 0;
            transition: all .4s ease .1s;
            transform: translateY(10px);
            height: 100%;
            display: flex;
            align-items: center;
            justify-content: center;
            width: 100%;
            z-index: 5;
        }

        .hover-expand-bar:hover .bar-content { 
            opacity: 1; 
            transform: translateY(0);
        }

        /* ============ NAVBAR ITEMS ============ */
        .navbar {
            display: flex;
            gap: 10px; 
            align-items: center;
            justify-content: center;
        }

        .navbar a,
        .dropdown-toggle {
            display: flex;
            align-items: center;
            gap: 6px;
            padding: 10px 16px; 
            color: #000;
            font-weight: 900;
            text-decoration: none;
            border-radius: 15px;
            background: #fff;
            border: 4px solid #000;
            box-shadow: 4px 4px 0px #000;
            transition: all .3s cubic-bezier(0.175, 0.885, 0.32, 1.275);
            text-transform: uppercase;
            font-size: 17px; /* Ukuran font disesuaikan agar muat banyak menu */
            white-space: nowrap;
            cursor: pointer;
        }

        .navbar a:hover,
        .dropdown-toggle:hover {
            transform: scale(1.05) translateY(-3px);
            background: #FFD500;
            box-shadow: 8px 8px 0px #000;
        }

        /* ============ DROPDOWN ============ */
        .dropdown { position: relative; }
        .dropdown-menu {
            position: absolute;
            top: calc(100% + 30px);
            left: 50%;
            transform: translateX(-50%) translateY(15px) scale(0.9);
            min-width: 300px; 
            padding: 12px 0;
            background: #0095FF;
            border: 5px solid #000;
            border-radius: 22px;
            box-shadow: 10px 10px 0px #000;
            opacity: 0;
            pointer-events: none;
            transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
            list-style: none;
            z-index: 100;
        }

        .dropdown.open .dropdown-menu {
            opacity: 1;
            pointer-events: auto;
            transform: translateX(-50%) translateY(0) scale(1);
        }

        .dropdown-menu li a {
            display: flex;
            justify-content: space-between;
            margin: 6px 12px;
            padding: 10px 18px; 
            background: #fff;
            border: 3px solid #000;
            border-radius: 12px;
            color: #000;
            font-size: 26px;
            box-shadow: 4px 4px 0px #000;
            text-decoration: none;
            font-weight: 900;
            transition: .3s;
        }

        .dropdown-menu li a:hover {
            background: #FFD500;
            transform: translateX(8px);
            box-shadow: -5px 5px 0px #000;
        }

        /* ============ KEYFRAMES ============ */
        @keyframes moving-gradient { 0% {background-position:0% 50%;} 50% {background-position:100% 50%;} 100% {background-position:0% 50%;} }
        @keyframes spiral-rotate { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
        @keyframes slide-down-anim {
            0% { transform: translateY(-10px); opacity: 0; }
            50% { transform: translateY(0); opacity: 1; }
            100% { transform: translateY(10px); opacity: 0; }
        }
    </style>
</head>
<body>

