   Elementor Slider – SUPER COMIC STYLE
   ===================================================== */

/* Font Comic */
@import url('https://fonts.googleapis.com/css2?family=Bangers&family=Comic+Neue:wght@400;700&display=swap');


/* Slide container */
selector .elementor-swiper-slide{
    position:relative;
    overflow:hidden;
    border-radius:18px;
    border:4px solid #000;
    box-shadow:8px 8px 0 #000;
    transition:transform .5s ease;
}

/* Hover comic pop */
selector .elementor-swiper-slide:hover{
    transform:scale(1.05) rotate(-1deg);
}

/* Gambar */
selector .elementor-swiper-slide img{
    width:100%;
    height:auto;
    object-fit:cover;
    display:block;
    border-radius:14px;
    filter:contrast(1.2) saturate(1.2);
}


/* Halftone comic dots */
selector .elementor-swiper-slide::before{
    content:"";
    position:absolute;
    inset:0;
    z-index:2;
    background-image:radial-gradient(rgba(0,0,0,0.15) 2px, transparent 2px);
    background-size:16px 16px;
    mix-blend-mode:multiply;
    pointer-events:none;
}


/* Grid comic overlay */
selector .grid-overlay{
    position:absolute;
    inset:0;
    z-index:3;
    pointer-events:none;

    background-image:
        linear-gradient(#00000020 2px, transparent 2px),
        linear-gradient(90deg,#00000020 2px, transparent 2px);

    background-size:30px 30px;

    transform:perspective(600px) rotateX(6deg) rotateY(-6deg);
}


/* Teks container */
selector .elementor-slide-content{
    position:absolute;
    top:50%;
    left:50%;
    transform:translate(-50%,-50%);
    text-align:center;
    width:85%;
    z-index:10;

    opacity:0;
    transition:.6s;
}


/* muncul */
selector .elementor-swiper-slide-active .elementor-slide-content,
selector .elementor-swiper-slide:hover .elementor-slide-content{
    opacity:1;
    transform:translate(-50%,-55%);
}



/* =====================
   JUDUL COMIC
   ===================== */

selector .elementor-slide-title{

    font-family:'Bangers',cursive;

    font-size:3.2rem;

    letter-spacing:2px;

    color:#fff;

    -webkit-text-stroke:3px #000;

    text-shadow:
        4px 4px 0 #000,
        8px 8px 0 rgba(0,0,0,.3);

    transform:skew(-3deg);
}



/* =====================
   SUBTITLE
   ===================== */

selector .elementor-slide-description{

    font-family:'Comic Neue',cursive;

    font-size:1.2rem;

    font-weight:700;

    color:#fff;

    background:#000;

    display:inline-block;

    padding:6px 14px;

    border-radius:10px;

    border:3px solid #fff;

    box-shadow:4px 4px 0 #000;

    margin-top:10px;
}



/* =====================
   COMIC BUTTON
   ===================== */

