  <comic-clock-mini></comic-clock-mini>
</div>

<style>
  /* Container untuk memposisikan jam di tengah */
  .center-wrapper {
    display: flex;
    justify-content: center; /* Tengah horizontal */
    align-items: center;     /* Tengah vertikal */
    min-height: 250px;       /* Memberi ruang agar terlihat di tengah */
    width: 100%;
    padding: 20px 0;
    box-sizing: border-box;
  }
</style>

<script>
class ComicClockMini extends HTMLElement {
  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() {
    this.render();
    this.startClock();
  }

  render() {
    this.shadowRoot.innerHTML = `
    <style>
      :host {
        display: block;
        font-family: 'Bangers', cursive;
        --yellow: #fff200;
        --red: #ff2d55;
        --blue: #00c3ff;
      }

      @import url('https://fonts.googleapis.com/css2?family=Bangers&display=swap');

      .card {
        position: relative;
        padding: 12px;
        background: #fff;
        border: 3px solid #000;
        border-radius: 12px;
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 12px;
        box-shadow: 6px 6px 0 rgba(0,0,0,0.15);
        width: 150px; /* Ukuran pas untuk mobile */
      }

      .speech-bubble {
        position: absolute;
        top: -10px;
        left: -10px;
        background: #fff;
        border: 2px solid #000;
        padding: 2px 8px;
        transform: rotate(-15deg);
        z-index: 10;
        font-size: 0.7rem;
        box-shadow: 2px 2px 0 #000;
        pointer-events: none;
      }

      .analog-box {
        width: 90px;
        height: 90px;
        border-radius: 50%;
        background: var(--yellow);
        position: relative;
        border: 4px solid #000;
      }

      .burst {
        position: absolute;
        inset: -6px;
        background: radial-gradient(circle, var(--red) 20%, transparent 21%);
        background-size: 8px 8px;
        z-index: -1;
        animation: spin 20s linear infinite;
        opacity: 0.5;
      }

      @keyframes spin { from { transform: rotate(0); } to { transform: rotate(360deg); } }

      .num {
        position: absolute;
        font-size: 12px;
        color: #000;
        width: 100%;
        text-align: center;
      }
      .n12 { top: 2px; }
      .n3  { top: 38px; right: 5px; width: auto; }
      .n6  { bottom: 2px; }
      .n9  { top: 38px; left: 5px; width: auto; }

      .hand {
        position: absolute;
        bottom: 50%;
        left: 50%;
        transform-origin: bottom center;
        border: 1.5px solid #000;
        border-radius: 2px;
      }
      .hh { width: 4px; height: 25px; background: #000; z-index: 3; }
      .mm { width: 3px; height: 35px; background: var(--blue); z-index: 4; }
      .ss { width: 1.5px; height: 40px; background: var(--red); z-index: 5; }

      .dot {
        position: absolute;
        width: 8px;
        height: 8px;
        background: var(--red);
        border: 2px solid #000;
        border-radius: 50%;
        top: 50%; left: 50%;
        transform: translate(-50%, -50%);
        z-index: 6;
      }

      .digi-val {
        font-size: 1.3rem;
        color: #fff;
        background: var(--blue);
        padding: 4px 10px;
        border: 3px solid #000;
        box-shadow: 3px 3px 0 var(--red), 5px 5px 0 #000;
        transform: rotate(1deg);
      }

      .tick { animation: kick 0.1s ease-out; }
      @keyframes kick { 
        0% { transform: rotate(1deg) scale(1); } 
        50% { transform: rotate(1deg) scale(1.1); } 
        100% { transform: rotate(1deg) scale(1); } 
      }
    </style>

    <div class="card">
      <div class="speech-bubble">TICK-TOCK!</div>
      <div class="analog-box">
        <div class="burst"></div>
        <div class="dot"></div>
        <div class="hand hh"></div>
        <div class="hand mm"></div>
        <div class="hand ss"></div>
        <div class="num n12">12</div>
        <div class="num n3">3</div>
        <div class="num n6">6</div>
        <div class="num n9">9</div>
      </div>
      <div class="digi-val">00:00:00</div>
    </div>
    `;
  }

  startClock() {
    const root = this.shadowRoot;
    const hh = root.querySelector('.hh');
    const mm = root.querySelector('.mm');
    const ss = root.querySelector('.ss');
    const digi = root.querySelector('.digi-val');
    let lastS = -1;

    const run = () => {
      const d = new Date();
      const h = d.getHours();
      const m = d.getMinutes();
      const s = d.getSeconds();
      const ms = d.getMilliseconds();

      if (s !== lastS) {
        digi.textContent = `${h.toString().padStart(2,'0')}:${m.toString().padStart(2,'0')}:${s.toString().padStart(2,'0')}`;
        digi.classList.remove('tick');
        void digi.offsetWidth;
        digi.classList.add('tick');
        lastS = s;
      }

      const sDeg = (s + ms / 1000) * 6;
      const mDeg = (m + s / 60) * 6;
      const hDeg = ((h % 12) + m / 60) * 30;

      ss.style.transform = `translateX(-50%) rotate(${sDeg}deg)`;
      mm.style.transform = `translateX(-50%) rotate(${mDeg}deg)`;
      hh.style.transform = `translateX(-50%) rotate(${hDeg}deg)`;

      requestAnimationFrame(run);
    };
    run();
  }
}

customElements.define('comic-clock-mini', ComicClockMini);
</script>"},"elements":[],"widgetType":"html"}],"isInner":true},{"id":"5c7f6f0","elType":"container","settings":{"flex_direction":"column","content_width":"full","width":{"unit":"%","size":"25"}},"elements":[],"isInner":true},{"id":"ccb5614","elType":"widget","settings":[],"elements":[],"widgetType":"html"}],"isInner":false},{"id":"19a6867","elType":"container","settings":{"flex_direction":"column","background_background":"classic","background_image":{"url":"http://pmiikomiskenda.42web.io/wp-content/uploads/2025/12/ligg.jpg","id":271,"size":"","alt":"","source":"library"},"hide_desktop":"hidden-desktop","hide_mobile":"hidden-mobile"},"elements":[{"id":"4e8079d","elType":"widget","settings":{"space":{"unit":"px","size":36,"sizes":[]}},"elements":[],"widgetType":"spacer"}],"isInner":false},{"id":"86213dc","elType":"container","settings":{"flex_direction":"column"},"elements":[{"id":"034c9d2","elType":"widget","settings":{"html":"<style>
