<div class="comic-halftone-overlay"></div>"},"elements":[],"widgetType":"html"}],"isInner":false},{"id":"d28b315","elType":"container","settings":{"flex_direction":"row","flex_gap":{"unit":"px","size":0,"column":"0","row":"0"},"hide_mobile":"hidden-mobile","background_background":"classic","background_image":{"url":"http://pmiikomiskenda.42web.io/wp-content/uploads/2026/07/20260712_2036081-1.png","id":7345,"size":"","alt":"","source":"library"}},"elements":[{"id":"d58d8e8","elType":"container","settings":{"flex_direction":"column","content_width":"full","width":{"unit":"%","size":"50"}},"elements":[{"id":"c4035df","elType":"widget","settings":{"html":"<div class="comic-clock-container">
