<style>
    /* ==========================================
       ISOLATED CSS - AMAN DARI KONFLIK
       ========================================== */

    /* 1. Master Wrapper */
    .isolated-dock-wrapper {
        position: relative;
        display: flex;
        justify-content: center;
        align-items: center;
        padding: 70px 20px 40px 20px; 
        font-family: 'Inter', sans-serif;
        z-index: 50;
        background: transparent;
        overflow: visible;
    }

    .isolated-dock-wrapper *, 
    .isolated-dock-wrapper *::before, 
    .isolated-dock-wrapper *::after {
        box-sizing: border-box;
        margin: 0;
        padding: 0;
    }

    /* 2. Dock Container (Animasi Gradien Mengalir) */
    .isolated-dock-wrapper .super-dock-container {
        position: relative;
        z-index: 10;

        /* LIQUID AURA GRADIENT */
        background: linear-gradient(
            -45deg, 
            #ff3a78, /* Pink */
            #803aff, /* Purple */
            #3abaff, /* Blue */
            #3affa3  /* Green */
        );
        background-size: 300% 300%;
        animation: liquidGradient 8s ease infinite;

        border: 2px solid rgba(255, 255, 255, 0.4);
        padding: 12px 24px;
        border-radius: 100px; /* Rounded pill */
        display: inline-flex;
        gap: 16px;

        /* Efek 3D dan Cahaya memendar di luar bar */
        box-shadow: 0 20px 40px rgba(0, 0, 0, 0.25),
                    0 0 30px rgba(128, 58, 255, 0.4),
                    inset 0 3px 6px rgba(255, 255, 255, 0.6);
    }

    /* Animasi pergerakan warna gradien */
    @keyframes liquidGradient {
        0% { background-position: 0% 50%; }
        50% { background-position: 100% 50%; }
        100% { background-position: 0% 50%; }
    }

    /* 3. Dock Items (Tombol Ikon Kaca Gelap) */
    .isolated-dock-wrapper .super-dock-item {
        position: relative;
        width: 60px;
        height: 60px;
        border-radius: 50%;
        display: flex;
        justify-content: center;
        align-items: center;
        text-decoration: none;

        /* Kaca gelap agar ikon kontras dengan bar gradien */
        background: rgba(0, 0, 0, 0.35);
        color: rgba(255, 255, 255, 0.9);
        border: 1px solid rgba(255, 255, 255, 0.15);
        backdrop-filter: blur(8px);
        -webkit-backdrop-filter: blur(8px);

        font-size: 24px;
        transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
    }

    .isolated-dock-wrapper .super-dock-item i {
        transition: all 0.3s ease;
        pointer-events: none;
    }

    /* 4. Efek Hover (Berubah jadi putih & memancarkan warna Brand) */
    .isolated-dock-wrapper .super-dock-item:hover {
        transform: translateY(-15px) scale(1.15);
        background: #ffffff; /* Tombol berubah jadi putih murni */
        border: 1px solid #ffffff;
        z-index: 20;
    }

    /* YouTube - Merah */
    .isolated-dock-wrapper .super-dock-item.youtube:hover {
        box-shadow: 0 15px 25px rgba(255, 0, 0, 0.4);
    }
    .isolated-dock-wrapper .super-dock-item.youtube:hover i {
        color: #ff0000;
        text-shadow: 0 0 10px rgba(255, 0, 0, 0.2);
    }

    /* TikTok - Hitam dengan Glow Neon Cyan & Pink */
    .isolated-dock-wrapper .super-dock-item.tiktok:hover {
        box-shadow: 0 15px 25px rgba(0, 0, 0, 0.3);
    }
    .isolated-dock-wrapper .super-dock-item.tiktok:hover i {
        color: #111111; 
        text-shadow: -2px 2px 0px #00f2fe, 2px -2px 0px #fe0979;
    }

    /* Instagram - Gradien Asli IG */
    .isolated-dock-wrapper .super-dock-item.instagram:hover {
        box-shadow: 0 15px 25px rgba(225, 48, 108, 0.4);
    }
    .isolated-dock-wrapper .super-dock-item.instagram:hover i {
        background: -webkit-linear-gradient(45deg, #f09433 0%, #e6683c 25%, #dc2743 50%, #cc2366 75%, #bc1888 100%);
        -webkit-background-clip: text;
        -webkit-text-fill-color: transparent;
    }

    /* Email - Biru Profesional */
    .isolated-dock-wrapper .super-dock-item.email:hover {
        box-shadow: 0 15px 25px rgba(0, 123, 255, 0.4);
    }
    .isolated-dock-wrapper .super-dock-item.email:hover i {
        color: #007bff;
        text-shadow: 0 0 10px rgba(0, 123, 255, 0.2);
    }

    /* 5. Tooltips (Label teks melayang) */
    .isolated-dock-wrapper .super-tooltip {
        position: absolute;
        top: -45px;
        background: #111111;
        color: #fff;
        padding: 6px 14px;
        border-radius: 8px;
        font-size: 13px;
        font-weight: 600;
        letter-spacing: 0.5px;
        opacity: 0;
        pointer-events: none;
        transform: translateY(10px) scale(0.8);
        transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
        border: 1px solid rgba(255, 255, 255, 0.1);
        box-shadow: 0 5px 15px rgba(0, 0, 0, 0.4);
        white-space: nowrap;
        z-index: 30;
    }

    /* Segitiga kecil di bawah tooltip */
    .isolated-dock-wrapper .super-tooltip::after {
        content: '';
        position: absolute;
        bottom: -4px;
        left: 50%;
        transform: translateX(-50%) rotate(45deg);
        width: 8px;
        height: 8px;
        background: #111111;
        border-right: 1px solid rgba(255, 255, 255, 0.1);
        border-bottom: 1px solid rgba(255, 255, 255, 0.1);
    }

    .isolated-dock-wrapper .super-dock-item:hover .super-tooltip {
        opacity: 1;
        transform: translateY(0) scale(1);
    }
</style>

<script>
    /* ==========================================
       ISOLATED JS - MAGNETIC PARALLAX EFFECT
       ========================================== */
    document.addEventListener("DOMContentLoaded", () => {
        const wrapper = document.querySelector('.isolated-dock-wrapper');
        if (!wrapper) return;

        const dockItems = wrapper.querySelectorAll('.super-dock-item');

        dockItems.forEach(item => {
            const icon = item.querySelector('i');
            if (!icon) return;

            item.addEventListener('mousemove', (e) => {
                const rect = item.getBoundingClientRect();
                const x = e.clientX - rect.left - rect.width / 2;
                const y = e.clientY - rect.top - rect.height / 2;

                icon.style.transform = `translate(${x * 0.4}px, ${y * 0.4}px)`;
            });

            item.addEventListener('mouseleave', () => {
                icon.style.transform = `translate(0px, 0px)`;
                icon.style.transition = `transform 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275)`;
            });

            item.addEventListener('mouseenter', () => {
                icon.style.transition = 'none';
            });
        });
    });
</script>
