<!-- ==========================================
     START: SUPER MODERN KUNING-BIRU SLIDE-DOWN TICKER
     ========================================== -->
<div class="pmii-ticker-wrapper">
    <!-- Efek cahaya memendar di belakang bar (Kuning-Biru) -->
    <div class="pmii-glow-backdrop"></div>

    <!-- Bar Utama (Glassmorphism yang disempurnakan) -->
