            <div class="check-badge">
                <i class="fa-solid fa-check-double"></i>
            </div>
        </div>

        <!-- ITEM 3 (Selesai) -->
        <div class="pmii-event-item completed">
            <span class="event-name">PKD</span>
            <div class="check-badge">
                <i class="fa-solid fa-shield-check"></i>
                <i class="fa-solid fa-check"></i> <!-- Fallback fontawesome -->
            </div>
        </div>

        <!-- ITEM 4 (Belum) -->
        <div class="pmii-event-item upcoming">
            <span class="event-name">PKL</span>
            <!-- Tanpa ceklis -->
