</div>

<style>
    /* ==========================================
        CSS - SUPER MODERN UI & ANIMATION (REVISI)
        ========================================== */
    .pmii-ticker-wrapper {
        position: relative;
        display: flex;
        justify-content: center;
        align-items: center;
        padding: 50px 20px;
        /* Gunakan font premium Poppins sebagai default, tapi label menggunakan Righteous */
        font-family: 'Poppins', sans-serif;
    }

    /* Latar cahaya RGB bergerak (Kuning ke Biru Tua) */
    .pmii-glow-backdrop {
        position: absolute;
        width: 320px;
        height: 70px;
        background: linear-gradient(135deg, #FFD700 0%, #FF8C00 30%, #001F3F 70%, #007BFF 100%);
        filter: blur(25px);
        opacity: 0.6;
        border-radius: 100px;
        animation: pulseGlow 4s ease-in-out infinite alternate;
        z-index: 1;
    }

    @keyframes pulseGlow {
        0% { transform: scale(0.95); opacity: 0.5; }
        100% { transform: scale(1.05); opacity: 0.8; }
    }

    /* Bar Kaca (Glassmorphism Disempurnakan) */
    .pmii-ticker-bar {
        position: relative;
        width: 300px;
        height: 65px; /* Tinggi Fix Bar */
        /* Gunakan warna dasar kaca biru tua tua yang kaya */
        background: rgba(0, 31, 63, 0.6);
        border: 2px solid rgba(255, 215, 0, 0.15); /* Bingkai kuning emas tipis */
        border-radius: 50px;
        backdrop-filter: blur(16px);
        -webkit-backdrop-filter: blur(16px);
        box-shadow: inset 0 2px 4px rgba(255, 255, 255, 0.1), 
                    inset 0 -2px 4px rgba(0, 0, 0, 0.2),
                    0 10px 30px rgba(0, 0, 0, 0.4),
                    0 0 15px rgba(255, 215, 0, 0.1); /* Tambahkan cahaya tepi kuning halus */
        overflow: hidden; /* Penting agar item yang di luar bar tersembunyi */
        z-index: 10;
        display: flex;
        justify-content: center;
        align-items: center;
    }

    /* Container untuk setiap teks (Default: Stanby di ATAS bar / tidak terlihat) */
    .pmii-event-item {
        position: absolute;
        width: 100%;
        height: 100%;
        display: flex;
        justify-content: center;
        align-items: center;
        gap: 12px;

        /* Posisi awal sebelum slide-down (di atas) */
        transform: translateY(-100%);
        opacity: 0;
        transition: all 0.7s cubic-bezier(0.68, -0.55, 0.265, 1.55);
    }

    /* Teks Event (Gunakan Font 'Righteous' untuk Label) */
    .pmii-event-item .event-name {
        font-family: 'Righteous', cursive; /* Font super duper keren untuk label */
        font-size: 20px;
        font-weight: 800;
        letter-spacing: 1px;
        background: linear-gradient(to right, #FFD700, #DAA520); /* Gradien kuning emas berkilau */
        -webkit-background-clip: text;
        -webkit-text-fill-color: transparent;
        text-shadow: 0 4px 10px rgba(255, 215, 0, 0.1);
    }

    /* ==========================================
        LOGIKA ANIMASI SLIDE DOWN (Via Class JS)
        ========================================== */

    /* 1. Aktif: Turun ke tengah (Muncul) */
    .pmii-event-item.active {
        transform: translateY(0);
        opacity: 1;
    }

    /* 2. Keluar: Turun ke bawah (Menghilang) */
    .pmii-event-item.exit {
        transform: translateY(100%);
        opacity: 0;
        transition: all 0.6s cubic-bezier(0.55, 0.085, 0.68, 0.53); /* Efek jatuh ke bawah lebih cepat */
    }

    /* ==========================================
        ANIMASI CEKLIS (SUPER MODERN POP) (Kuning)
        ========================================== */
    .pmii-event-item .check-badge {
        display: flex;
        justify-content: center;
        align-items: center;
        width: 32px;
        height: 32px;
        border-radius: 50%;
        background: linear-gradient(135deg, #FFD700, #FF8C00); /* Gradien kuning emas ke oranye kuning */
        color: white;
        font-size: 14px;
        box-shadow: 0 0 15px rgba(255, 215, 0, 0.6), 
                    inset 0 2px 4px rgba(255, 255, 255, 0.5);
        border: 2px solid rgba(255, 255, 255, 0.9);

        /* Posisi awal ceklis tersembunyi & mengecil */
        transform: scale(0) rotate(-180deg);
        opacity: 0;
        transition: all 0.6s cubic-bezier(0.175, 0.885, 0.32, 1.275);
    }

    /* Ceklis HANYA animasi (muncul) ketika eventnya sedang ACTIVE/ditengah bar */
    .pmii-event-item.active .check-badge {
        transform: scale(1) rotate(0deg);
        opacity: 1;
        transition-delay: 0.35s; /* Jeda sedikit setelah teks turun */
    }
</style>

<script>
    /* ==========================================
        JS - TICKER LOGIC (MENGATUR SLIDE DOWN)
        ========================================== */
    document.addEventListener("DOMContentLoaded", () => {
        const events = document.querySelectorAll('.pmii-event-item');
        if (events.length === 0) return;

        let currentIndex = 0;

        function slideNextEvent() {
            // 1. Bersihkan semua class
            events.forEach(item => {
                item.classList.remove('active', 'exit');
            });

            // 2. Beri class 'exit' pada event saat ini agar jatuh ke bawah (Slide down hilangnya)
            const currentEvent = events[currentIndex];
            currentEvent.classList.add('exit');

            // 3. Tentukan indeks event berikutnya
            currentIndex = (currentIndex + 1) % events.length;

            // 4. Beri class 'active' pada event baru agar turun dari atas ke tengah (Slide down munculnya)
            const nextEvent = events[currentIndex];

            // Sedikit trik agar CSS sempat me-reset posisi ke atas sebelum diberi class active
            setTimeout(() => {
                currentEvent.classList.remove('exit'); // Reset yang udah di bawah
                nextEvent.classList.add('active');     // Turunkan yang baru
            }, 50); // Delay sepersekian detik untuk rendering browser
        }

        // Jalankan event pertama kali saat web diload
        events[0].classList.add('active');

        // Atur interval pergantian nama otomatis (Setiap 3 detik / 3000ms)
        setInterval(slideNextEvent, 3000);
    });
</script>
