iner","settings":{"flex_direction":"column","background_background":"classic","hide_mobile":"hidden-mobile","background_image":{"url":"http://pmiikomiskenda.42web.io/wp-content/uploads/2026/07/ChatGPT-Image-Jul-13-2026-12_23_52-PM.png","id":7540,"size":"","alt":"","source":"library"},"background_position":"initial","background_xpos":{"unit":"px","size":132,"sizes":[]}},"elements":[{"id":"e0d609a","elType":"widget","settings":{"html":"<!-- Google Fonts (Aman & Ringan) -->
<link href="https://fonts.googleapis.com/css2?family=Bangers&family=Comic+Neue:wght@700;800&display=swap" rel="stylesheet">

<style>
    /* --- SCOPED & COMPACT COMIC ZONE --- */

    .comic-isolated-zone, 
    .comic-isolated-zone * {
        box-sizing: border-box;
        margin: 0;
        padding: 0;
        font-family: 'Comic Neue', sans-serif;
        font-weight: 800;
    }

    /* Background Dibuat Transparan Total Tanpa Titik-Titik */
    .comic-isolated-zone {
        width: 100%;
        padding: 30px 10px;
        background: transparent; /* Bersih & Transparan */
        display: flex;
        justify-content: center;
        align-items: center;
    }

    /* KONTAINER UTAMA */
    .comic-isolated-zone .comic-wrapper {
        width: 100%;
        max-width: 780px; 
        background: #ffffff;
        border: 4px solid #000000;
        box-shadow: 8px 8px 0px #000000, 16px 16px 0px #00E5FF;
        position: relative;
        padding: 45px 20px 30px 20px;
        margin-top: 20px;
        border-radius: 4px;
    }

    /* JUDUL BAR */
    .comic-isolated-zone .comic-wrapper::before {
        content: "BERALIH MODE";
        position: absolute;
        top: -24px; 
        left: 20px;
        font-family: 'Bangers', cursive;
        font-size: 28px;
        letter-spacing: 2px;
        background: #FFDE4D;
        color: #000000;
        padding: 5px 20px;
        border: 4px solid #000000;
        box-shadow: 4px 4px 0px #FF0055;
        transform: rotate(-3deg);
        z-index: 10;
        transition: 0.2s ease;
    }

    .comic-isolated-zone .comic-wrapper:hover::before {
        transform: rotate(-1deg) scale(1.02);
    }

    /* GRID MINI */
    .comic-isolated-zone .comic-grid {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
        gap: 20px;
        width: 100%;
    }

    /* PANEL KOMIK MINI */
    .comic-isolated-zone .comic-panel {
        background: #ffffff;
        border: 4px solid #000000;
        box-shadow: 5px 5px 0px #000000;
        border-radius: 4px;
        cursor: pointer;
        position: relative;
        overflow: visible;
        display: flex;
        flex-direction: column;
        transition: transform 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275), 
                    box-shadow 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275);
    }

    .comic-isolated-zone .comic-panel:hover {
        transform: translateY(-8px) scale(1.02) rotate(1deg);
        box-shadow: 8px 12px 0px #000000, -3px 3px 10px rgba(0,229,255,0.3);
    }

    .comic-isolated-zone .comic-panel:nth-child(2):hover {
        transform: translateY(-8px) scale(1.02) rotate(-1deg);
    }

    /* BADGE MINI */
    .comic-isolated-zone .panel-badge {
        position: absolute;
        top: -13px;
        left: 12px;
        background: #FF0055;
        color: #ffffff;
        font-family: 'Bangers', cursive;
        font-size: 12px;
        padding: 2px 8px;
        border: 3px solid #000;
        transform: skewX(-10deg);
        z-index: 5;
        box-shadow: 2px 2px 0 #000;
        letter-spacing: 0.5px;
    }
    .comic-isolated-zone .comic-panel:nth-child(2) .panel-badge { background: #00E5FF; color: #000; }
    .comic-isolated-zone .comic-panel:nth-child(3) .panel-badge { background: #9D00FF; }

    /* BINGKAI GAMBAR */
    .comic-isolated-zone .panel-frame {
        width: 100%;
        aspect-ratio: 16 / 11;
        overflow: hidden;
        border-bottom: 4px solid #000000;
        position: relative;
        background: #000;
    }

    .comic-isolated-zone .panel-frame::after {
        content: "";
        position: absolute;
        inset: 0;
        background: linear-gradient(rgba(255,255,255,0.08) 50%, rgba(0,0,0,0.08) 50%);
        background-size: 100% 3px;
        z-index: 2;
        pointer-events: none;
    }

    .comic-isolated-zone .panel-frame img {
        width: 100%;
        height: 100%;
        object-fit: cover;
        display: block;
        transition: transform 0.4s ease;
    }

    .comic-isolated-zone .comic-panel:hover .panel-frame img {
        transform: scale(1.08) rotate(1deg);
    }

    /* FOOTER PANEL MINI */
    .comic-isolated-zone .panel-footer {
        padding: 12px 10px;
        background: #ffffff;
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 8px;
        flex-grow: 1;
    }

    .comic-isolated-zone .action-title {
        font-size: 14px;
        color: #000000;
        text-transform: uppercase;
        letter-spacing: -0.2px;
        text-align: center;
    }

    .comic-isolated-zone .comic-panel:hover .action-title {
        color: #FF0055;
    }

    /* POWER BAR MINI */
    .comic-isolated-zone .power-bar {
        width: 50%;
        height: 10px;
        border: 2px solid #000000;
        background: #EAEAEA;
        box-shadow: 2px 2px 0px #000000;
        position: relative;
        overflow: hidden;
        transition: width 0.3s ease;
    }

    .comic-isolated-zone .power-bar::before {
        content: "";
        position: absolute;
        left: 0; top: 0; bottom: 0;
        width: 0%;
        background: #FFDE4D;
        transition: width 0.3s ease;
    }

    .comic-isolated-zone .comic-panel:hover .power-bar {
        width: 85%;
    }
    .comic-isolated-zone .comic-panel:hover .power-bar::before {
        width: 100%;
        background: linear-gradient(90deg, #FF0055, #FFDE4D);
    }

    /* TRANSISI MINI SHAZAM */
    .safe-comic-shazam {
        position: fixed;
        inset: 0;
        z-index: 999999;
        display: none;
        background: #000000;
        clip-path: circle(0% at 50% 50%);
    }

    .safe-comic-vortex {
        position: absolute;
        inset: -50%;
        background: repeating-conic-gradient(from 0deg, 
            #FFDE4D 0deg 2deg, 
            #FF5F00 2deg 12deg, 
            #000000 12deg 13deg);
        animation: safeVortexSpin 0.3s linear infinite;
        opacity: 0.9;
    }

    @keyframes safeVortexSpin {
        100% { transform: rotate(360deg); }
    }

    .safe-comic-burst-text {
        position: absolute;
        top: 50%; left: 50%;
        transform: translate(-50%, -50%) scale(0);
        font-family: 'Bangers', cursive;
        font-size: clamp(50px, 10vw, 110px);
        color: #ffffff;
        text-shadow: 6px 6px 0px #FF0055, 12px 12px 0px #000000;
        -webkit-text-stroke: 2px #000000;
        white-space: nowrap;
        z-index: 10;
    }

    @keyframes safePopComic {
        0% { transform: translate(-50%, -50%) scale(0) rotate(-30deg); }
        60% { transform: translate(-50%, -50%) scale(1.3) rotate(15deg); }
        100% { transform: translate(-50%, -50%) scale(1.05) rotate(-5deg); }
    }
</style>

<!-- ================= WIDGET ZONE ================= -->
<div class="comic-isolated-zone">

    <!-- Layer Transisi Efek Ledakan -->
    <div class="safe-comic-shazam" id="safeTransLayer">
        <div class="safe-comic-vortex"></div>
        <div class="safe-comic-burst-text" id="safeZoomText">BOOM!</div>
    </div>

    <!-- Container Utama Komik -->
    <div class="comic-wrapper">
        <div class="comic-grid">

            <!-- Panel 1 -->
            <div class="comic-panel" data-link="https://www.instagram.com/" data-text="GO!">
                <div class="panel-badge">CHAP 01</div>
                <div class="panel-frame">
                    <img src="https://i.ibb.co.com/Y4sytpY9/Chat-GPT-Image-Jul-12-2026-10-36-09-PM.png">
                </div>
                <div class="panel-footer">
                    <h2 class="action-title">PMII WEB</h2>
                    <div class="power-bar"></div>
                </div>
            </div>

            <!-- Panel 2 -->
            <div class="comic-panel" data-link="https://diglib-pmiistaim.base44.app/" data-text="NEXT!">
                <div class="panel-badge">CHAP 02</div>
                <div class="panel-frame">
                    <img src="https://i.ibb.co.com/cK2fD9Ln/Chat-GPT-Image-Jul-13-2026-04-45-49-PM.png">
                </div>
                <div class="panel-footer">
                    <h2 class="action-title">DIGLIB</h2>
                    <div class="power-bar"></div>
                </div>
            </div>

            <!-- Panel 3 -->
            <div class="comic-panel" data-link="https://pmiikomiskenda.42web.io/halaman-berita/" data-text="READ!">
                <div class="panel-badge">CHAP 03</div>
                <div class="panel-frame">
                    <img src="https://i.ibb.co.com/jvPJNwwq/Chat-GPT-Image-Jul-13-2026-09-55-56-PM.png" alt="Berita">
                </div>
                <div class="panel-footer">
                    <h2 class="action-title">BACA BERITA</h2>
                    <div class="power-bar"></div>
                </div>
            </div>

        </div>
    </div>
</div>

<script>
(function() {
    const panels = document.querySelectorAll(".comic-isolated-zone .comic-panel");
    const transLayer = document.getElementById("safeTransLayer");
    const zoomText = document.getElementById("safeZoomText");

    panels.forEach(panel => {
        panel.addEventListener("click", function() {
            const link = this.getAttribute("data-link");
            const customText = this.getAttribute("data-text");

            if (!link) return;

            zoomText.innerText = customText;
            transLayer.style.display = "block";

            transLayer.animate([
                { clipPath: 'circle(0% at 50% 50%)' },
                { clipPath: 'circle(150% at 50% 50%)' }
            ], {
                duration: 450,
                easing: 'cubic-bezier(0.86, 0, 0.07, 1)',
                fill: 'forwards'
            });

            setTimeout(() => {
                zoomText.style.animation = "safePopComic 0.4s forwards cubic-bezier(0.175, 0.885, 0.32, 1.275)";
            }, 120);

            setTimeout(() => {
                window.location.href = link;
            }, 900);
        });
    });
})();
</script>"},"elements":[],"widgetType":"html"},{"id":"a8b156c","elType":"widget","settings":{"space":{"unit":"px","size":143,"sizes":[]}},"elements":[],"widgetType":"spacer"}],"isInner":false},{"id":"925164a","elType":"container","settings":{"flex_direction":"column","background_background":"classic","background_image":{"url":"http://pmiikomiskenda.42web.io/wp-content/uploads/2025/12/—Pngtree—beautiful-bright-blue-white-yellow_1338572.jpg","id":264,"size":"","alt":"","source":"library"},"hide_mobile":"hidden-mobile"},"elements":[],"isInner":false},{"id":"82b1bf5","elType":"container","settings":{"flex_direction":"column","background_background":"slideshow","background_image":{"url":"","id":"","size":"medium_large","alt":"","source":"library"},"background_slideshow_gallery":[{"id":673,"url":"http://pmiikomiskenda.42web.io/wp-content/uploads/2025/12/bg.web_-scaled.png"}],"background_slideshow_background_size":"contain","hide_mobile":"hidden-mobile"},"elements":[{"id":"cf54562","elType":"widget","settings":{"html":"<!doctype html>
<html lang="id">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">

<title>PMII Comic Style</title>

<link href="https://fonts.googleapis.com/css2?family=Bangers&family=Comic+Neue:wght@400;700&display=swap" rel="stylesheet">

<style>

*{
margin:0;
padding:0;
box-sizing:border-box;
}

/* BODY */

body{
font-family:'Comic Neue',sans-serif;

background:
radial-gradient(circle,#000 3px,transparent 3px),
#ffe600;

background-size:26px 26px;

color:#000;
transition:.4s;
}

body.dark{
background:
radial-gradient(circle,#fff 3px,transparent 3px),
#121212;
background-size:26px 26px;
color:#fff;
}

/* WRAPPER */

.pmi-wrapper{
width:100%;
max-width:1200px;
margin:60px auto;
padding:0 20px;
}

/* PANEL */

.pmi-section{

position:relative;

max-width:1000px;

margin:auto;

padding:100px 50px 70px;

background:#fff;

border:8px solid #000;

border-radius:20px;

box-shadow:12px 12px 0 #000;

line-height:1.9;

transition:.4s;

/* INI PENTING */
overflow:visible;

}

body.dark .pmi-section{
background:#1a1a1a;
border:8px solid #fff;
box-shadow:12px 12px 0 #fff;
}

/* ================= PMII TITLE ================= */

.comic-title{

position:absolute;

left:-120px;
top:-70px;

font-family:'Bangers',cursive;

font-size:110px;

color:#ff2e2e;

text-shadow:
6px 6px 0 #000,
10px 10px 0 #ffe600;

transform:rotate(-12deg);

z-index:999;

}

body.dark .comic-title{
color:#4da6ff;
}

/* JUDUL */

h1{

font-family:'Bangers';

font-size:42px;

letter-spacing:2px;

text-align:center;

margin-bottom:30px;

text-shadow:3px 3px 0 #000;

}

/* SPEECH */

.lead{

background:#fff;

border:6px solid #000;

border-radius:40px;

padding:40px;

max-width:860px;

margin:auto;

text-align:center;

font-size:20px;

font-weight:600;

position:relative;

box-shadow:8px 8px 0 #000;

}

body.dark .lead{
background:#222;
border:6px solid #fff;
box-shadow:8px 8px 0 #fff;
}

/* TAIL */

.lead:after{

content:"";

position:absolute;

bottom:-30px;
left:80px;

border-width:30px 30px 0;

border-style:solid;

border-color:#000 transparent transparent;

}

/* SWITCH */

.controls{

position:absolute;

right:20px;
top:20px;

}

.slider-wrap{

width:110px;
height:44px;

background:#ff3b3b;

border:5px solid #000;

border-radius:40px;

position:relative;

cursor:pointer;

box-shadow:4px 4px 0 #000;

}

.slider-btn{

width:36px;
height:36px;

background:#fff;

border-radius:50%;

position:absolute;

top:2px;
left:2px;

display:flex;

align-items:center;
justify-content:center;

font-size:18px;

border:4px solid #000;

transition:.35s;

}

.dark .slider-btn{
transform:translateX(62px);
}

</style>
</head>

<body>

<div class="pmi-wrapper">

<section class="pmi-section">

<div class="comic-title">PMII!</div>

<div class="controls">
<div id="toggleMode" class="slider-wrap">
<div class="slider-btn" id="toggleIcon">☀️</div>
</div>
</div>

<h1>PERGERAKAN MAHASISWA ISLAM INDONESIA</h1>

<p class="lead">

PMII merupakan organisasi gerakan dan kaderisasi yang berlandaskan nilai-nilai Islam Ahlussunnah wal Jama’ah. Berdiri pada 17 April 1960 di Surabaya, PMII hadir sebagai ruang intelektual, perjuangan sosial, serta pembentukan kader yang berintegritas.

Selama lebih dari setengah abad, PMII terus konsisten menjaga komitmen kebangsaan, memperkuat tradisi keilmuan, serta mendorong lahirnya generasi muda yang kritis, moderat, dan berakhlak.

</p>

</section>

</div>

<script>

const body=document.body;
const toggle=document.getElementById("toggleMode");
const icon=document.getElementById("toggleIcon");

let dark=false;

toggle.onclick=()=>{

dark=!dark;

body.classList.toggle("dark");

icon.textContent=dark?"🌙":"☀️";

};

</script>

