<style>
/* ===== WRAPPER COMPACT ===== */
.comic-wrap {
  font-family: 'Bangers', cursive;
  max-width: 600px;
  padding: 12px;
  border-radius: 8px;
  background: 
    url('https://i.supaimg.com/c705e80f-237a-4b64-b2bb-2b5c629d94a5.jpg');
  background-size: cover;
  background-position: center;
  border: 5px solid #000;
  box-shadow: 8px 8px 0 #000;
  overflow: hidden;
  transform: rotate(-0.5deg);
}

/* ===== BAR RAMPING (TIDAK TINGGI) ===== */
.comic-bar {
  position: relative;
  padding: 6px 20px; /* Sangat tipis */
  margin-bottom: 8px;
  border: 4px solid #000;
  box-shadow: 4px 4px 0 #000;
  transform: skewX(-7deg);
  overflow: hidden;
  transition: 0.2s;
}

/* ===== EFEK FONT DOTS (HALFTONE STYLE) ===== */
.comic-dots-font {
  display: inline-block;
  /* Masking pola titik */
  background-image: radial-gradient(circle, #000 30%, transparent 35%);
  background-size: 2.5px 2.5px;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent; /* Supaya tekstur dots terlihat */
  position: relative;
  animation: wiggle 0.2s infinite alternate;
}

/* Warna fallback untuk stroke font agar tetap terbaca */
.role.comic-dots-font {
  background-color: #fff; /* Warna dasar font */
  -webkit-text-stroke: 1px #000;
  font-size: 1.7rem;
}

.name.comic-dots-font {
  background-color: #000; /* Dots hitam di font kuning */
  background-image: radial-gradient(circle, #333 30%, transparent 35%);
  -webkit-text-stroke: 0.5px #fff;
  font-size: 1.4rem;
}

/* ===== WARNA BAR ===== */
.role-bar { background: #0055ff; }
.name-bar { background: #ffd700; }

/* ===== ANIMASI ===== */
@keyframes wiggle {
  from { transform: translateY(0) rotate(0deg); }
  to { transform: translateY(-1px) rotate(0.5deg); }
}

.scan {
  position: absolute;
  top: 0;
  left: -100%;
  width: 40%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.4), transparent);
  animation: scanMove 3s infinite linear;
}

@keyframes scanMove {
  0% { left: -100%; }
  100% { left: 150%; }
}

.cursor { color: #000; font-weight: bold; animation: blink 0.6s infinite; }
@keyframes blink { 50% { opacity: 0; } }

/* HOVER */
.comic-bar:hover {
  transform: skewX(-7deg) scale(1.02);
  box-shadow: 6px 6px 0 #000;
}
