<style>
/* ===== WRAPPER COMPACT ===== */
.comic-wrap {
  font-family: 'Bangers', cursive;
  max-width: 620px; /* Dipersempit agar lebih padat */
  padding: 15px;
  border-radius: 12px;
  background: 
    radial-gradient(circle at top left, #ffffff33, transparent 50%),
    url('https://i.supaimg.com/c705e80f-237a-4b64-b2bb-2b5c629d94a5.jpg');
  background-size: cover;
  background-position: center;
  border: 6px solid #000;
  box-shadow: 10px 10px 0 #000;
  overflow: hidden;
  transform: rotate(-0.5deg); /* Sedikit miring ala panel komik */
}

/* ===== BAR RAMPING (TIDAK TINGGI) ===== */
.comic-bar {
  position: relative;
  padding: 6px 22px; /* Dibuat sangat ramping */
  margin-bottom: 10px;
  border: 4px solid #000;
  box-shadow: 5px 5px 0 #000;
  transform: skewX(-7deg); /* Kemiringan khas komik */
  overflow: hidden;
  transition: 0.2s;
}

/* ===== EFEK FONT DOTS (HALFTONE STYLE) ===== */
.comic-dots {
  display: inline-block;
  /* Masking pola titik-titik kasar */
  background-image: radial-gradient(circle, currentColor 25%, transparent 30%);
  background-size: 3px 3px;
  -webkit-background-clip: text;
  background-clip: text;
  position: relative;
}

/* Khusus Jabatan (Biru) */
.role {
  font-size: 1.8rem;
  color: #fff;
  letter-spacing: 1px;
  /* Efek Stroke & Bayangan Kaku */
  -webkit-text-stroke: 1px #000;
  text-shadow: 3px 3px 0 #000;
}

/* Khusus Nama (Kuning) */
.name {
  font-size: 1.5rem;
  color: #000;
  -webkit-text-stroke: 0.5px #fff;
  text-shadow: 2px 2px 0 #000;
}

/* ===== WARNA BAR ===== */
.role-bar { background: #0055ff; }
.name-bar { background: #ffcc00; }

/* ===== ANIMASI COMIC STYLE ===== */
.animate-wiggle {
  animation: wiggle 0.25s infinite alternate ease-in-out;
}
@keyframes wiggle {
  from { transform: skewX(-7deg) translateY(0); }
  to { transform: skewX(-5deg) translateY(-2px); }
}

.animate-pop {
  animation: pop 2.5s infinite ease-in-out;
}
@keyframes pop {
  0%, 100% { transform: skewX(-7deg) scale(1); }
  50% { transform: skewX(-7deg) scale(1.04); }
}

/* ===== SCAN LINE (Efek Cahaya Bergerak) ===== */
.scan {
  position: absolute;
  top: 0;
  left: -100%;
  width: 40%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.4), transparent);
  animation: scanMove 3s infinite linear;
}
@keyframes scanMove {
  0% { left: -100%; }
  100% { left: 150%; }
}

/* CURSOR */
.cursor { color: #000; font-weight: bold; animation: blink 0.6s infinite; }
@keyframes blink { 50% { opacity: 0; } }

/* HOVER EFFECT */
.comic-bar:hover {
  transform: skewX(-7deg) scale(1.02) translateY(-2px);
  box-shadow: 8px 8px 0 #000;
}
</style>"},"elements":[],"widgetType":"html"}],"isInner":true}],"isInner":false},{"id":"db3c881","elType":"container","settings":{"flex_direction":"row","flex_gap":{"unit":"px","size":0,"column":"0","row":"0"},"background_background":"slideshow","background_slideshow_gallery":[{"id":723,"url":"http://pmiikomiskenda.42web.io/wp-content/uploads/2025/12/ii-bg2-.1-1-scaled.png"}],"hide_mobile":"hidden-mobile"},"elements":[{"id":"582181e","elType":"container","settings":{"flex_direction":"column","content_width":"full","width":{"unit":"%","size":"25"}},"elements":[],"isInner":true},{"id":"5a167fb","elType":"container","settings":{"flex_direction":"column","content_width":"full","width":{"unit":"%","size":"50"}},"elements":[],"isInner":true},{"id":"a650454","elType":"container","settings":{"flex_direction":"column","content_width":"full","width":{"unit":"%","size":"25"}},"elements":[],"isInner":true}],"isInner":false},{"id":"1ef29c3","elType":"container","settings":{"flex_direction":"column","hide_desktop":"hidden-desktop","hide_tablet":"hidden-tablet","hide_mobile":"hidden-mobile"},"elements":[{"id":"f9892cc","elType":"widget","settings":{"html":"<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Rating 2 Bar Fleksibel</title>

<link href="https://fonts.googleapis.com/css2?family=Bangers&display=swap" rel="stylesheet">

<style>
body {
  font-family: 'Bangers', cursive;
  background: #f5f5f5;
  margin: 0;
  padding: 0;
}

/* ===== CONTAINER UTAMA ===== */
.rating-container {
  display: flex;
  justify-content: space-between; /* bar kiri-kanan tetap rapi */
  max-width: 1000px;
  margin: 20px auto; /* center di halaman */
  flex-wrap: wrap; /* responsive jika layar sempit */
}

/* ===== COMIC CONTAINER ===== */
.comic-container {
  flex: 0 0 300px; /* tetap 300px */
  padding: 25px;
  border-radius: 25px;
  background-image: url('https://i.supaimg.com/c705e80f-237a-4b64-b2bb-2b5c629d94a5.jpg');
  background-size: cover;
  background-position: center;
  min-height: 240px;
  box-shadow: 0 10px 20px rgba(0,0,0,0.25);
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  color: #fff;
  text-shadow: 1px 1px 2px #000;
  margin-bottom: 20px; /* jarak vertikal jika wrap */
}

/* BINTANG */
.stars span {
  font-size: 40px;
  cursor: pointer;
  padding: 5px;
  user-select: none;
  transition: 0.2s;
  color: #fff;
}

.stars span:hover,
.stars span.selected {
  color: gold;
}

/* SKOR */
.score-display {
  margin-top: 15px;
  font-size: 1.3rem;
  text-align: center;
  color: #fff;
  text-shadow: 1px 1px 2px #000;
}

/* ===== BAR KANAN (fiktif jauh) ===== */
.right-bar {
  margin-left: auto; /* otomatis geser ke kanan */
}
</style>
</head>
<body>

<div class="rating-container">
  <!-- BAR KIRI -->
  <div class="comic-container">
    <div class="rating-box" data-doc="globalScore1">
      <div class="stars">
        <span data-value="1">★</span>
        <span data-value="2">★</span>
        <span data-value="3">★</span>
        <span data-value="4">★</span>
        <span data-value="5">★</span>
      </div>
      <div class="score-display">Total skor: 0 (0 penilai)</div>
    </div>
  </div>

  <!-- BAR KANAN -->
  <div class="comic-container right-bar">
    <div class="rating-box" data-doc="globalScore2">
      <div class="stars">
        <span data-value="1">★</span>
        <span data-value="2">★</span>
        <span data-value="3">★</span>
        <span data-value="4">★</span>
        <span data-value="5">★</span>
      </div>
      <div class="score-display">Total skor: 0 (0 penilai)</div>
    </div>
  </div>
</div>

<!-- FIREBASE -->
<script src="https://www.gstatic.com/firebasejs/8.10.0/firebase-app.js"></script>
<script src="https://www.gstatic.com/firebasejs/8.10.0/firebase-firestore.js"></script>

<script>
var firebaseConfig = {
  apiKey: "AIzaSyAfs12ch5ncCZO571X9pnZOn-QTZRmhRJQ",
  authDomain: "ratting-cae52.firebaseapp.com",
  projectId: "ratting-cae52",
  storageBucket: "ratting-cae52.appspot.com",
  messagingSenderId: "1021028020220",
  appId: "1:1021028020220:web:32171f85efda676ad6cc79"
};

firebase.initializeApp(firebaseConfig);
var db = firebase.firestore();

document.querySelectorAll('.rating-box').forEach(function(box){
  var docName = box.getAttribute('data-doc');
  var ratingRef = db.collection("ratings").doc(docName);
  var stars = box.querySelectorAll('.stars span');
  var scoreDisplay = box.querySelector('.score-display');

  function updateDisplay(total, voters) {
    var avg = voters === 0 ? 0 : (total / voters).toFixed(2);
    scoreDisplay.innerHTML = "Total skor: " + avg + " (" + voters + " penilai)";
  }

  ratingRef.get().then(function(doc){
    if(!doc.exists){
      ratingRef.set({totalScore:0,voters:0}).then(()=> updateDisplay(0,0));
    } else {
      updateDisplay(doc.data().totalScore, doc.data().voters);
    }
  });

  stars.forEach(function(star){
    star.addEventListener('click', function(){
      var value = parseInt(this.getAttribute('data-value'));
      ratingRef.get().then(function(doc){
        var total = doc.data().totalScore;
        var voters = doc.data().voters;

        total += value;
        voters += 1;

        ratingRef.set({totalScore: total, voters: voters}).then(function(){
          updateDisplay(total, voters);
          stars.forEach(s=>s.classList.remove('selected'));
          for(var i=0;i<value;i++){ stars[i].classList.add('selected'); }
        });
      });
    });
  });
});
</script>

</body>
</html>
