   COMIC MAP PANEL
========================= */

.elementor-widget-google_maps,
.elementor-widget-google-maps{

position:relative;

padding:35px;

border:10px solid #000;

border-radius:22px;

background:
radial-gradient(circle,#000 2px,transparent 2px),
#ffe600;

background-size:22px 22px;

box-shadow:14px 14px 0 #000;

overflow:visible;

}


/* =========================
   MAP FRAME
========================= */

.elementor-widget-google_maps iframe,
.elementor-widget-google-maps iframe{

border:8px solid #000 !important;

border-radius:14px;

box-shadow:8px 8px 0 #000;

position:relative;

z-index:2;

}


/* =========================
   BURST RIGHT TOP (INSIDE)
========================= */

.elementor-widget-google_maps:after,
.elementor-widget-google-maps:after{

content:"";

position:absolute;

width:220px;
height:220px;

top:10px;
right:10px;

background:
repeating-conic-gradient(
#ff3b3b 0deg 12deg,
#ffe600 12deg 24deg
);

border-radius:50%;

opacity:.9;

z-index:1;

}


/* =========================
   BURST LEFT BOTTOM (INSIDE)
========================= */

.elementor-widget-google_maps:before,
.elementor-widget-google-maps:before{

content:"";

position:absolute;

width:220px;
height:220px;

bottom:10px;
left:10px;

background:
repeating-conic-gradient(
#ff3b3b 0deg 12deg,
#ffe600 12deg 24deg
);

border-radius:50%;

opacity:.9;

z-index:1;

}


/* =========================
   COMIC TITLE (OUTSIDE)
========================= */

.elementor-widget-google_maps .elementor-widget-container:before,
.elementor-widget-google-maps .elementor-widget-container:before{

content:"OUR LOCATION!";

position:absolute;

top:-70px;
left:-20px;

font-family:'Bangers',cursive;

font-size:52px;

color:#ff2e2e;

text-shadow:
4px 4px 0 #000,
8px 8px 0 #ffe600;

transform:rotate(-10deg);

z-index:5;

}


/* =========================
   PIN ICON
========================= */

.elementor-widget-google_maps .elementor-widget-container:after,
.elementor-widget-google-maps .elementor-widget-container:after{

content:"📍";

position:absolute;

bottom:-20px;
right:-10px;

font-size:60px;

transform:rotate(10deg);

z-index:5;

}


/* RESPONSIVE */

@media(max-width:768px){

.elementor-widget-google_maps .elementor-widget-container:before,
.elementor-widget-google-maps .elementor-widget-container:before{

font-size:32px;
