<html lang="en">
<head>
<meta charset="UTF-8">
<title>Ultra Comic Loader</title>

<link href="https://fonts.googleapis.com/css2?family=Bangers&family=Comic+Neue:wght@400;700&display=swap" rel="stylesheet">

<style>

body{margin:0;}

#comicLoader{
position:fixed;
top:0;
left:0;
width:100vw;
height:100vh;
z-index:999999999999;
display:flex;
align-items:center;
justify-content:center;
background:#ffd84d;
font-family:'Comic Neue',sans-serif;
overflow:hidden;
}

#comicLoader::before{
content:"";
position:absolute;
inset:0;
background:radial-gradient(circle, rgba(0,0,0,.18) 1.5px, transparent 1.5px);
background-size:18px 18px;
}

.panel{
position:relative;
background:white;
border:10px solid black;
box-shadow:18px 18px 0 black;
padding:60px 80px;
text-align:center;
z-index:10;
max-width:90vw;
}

.bubble{
position:absolute;
top:-45px;
left:50%;
transform:translateX(-50%);
background:white;
border:7px solid black;
padding:12px 28px;
font-family:'Bangers';
font-size:34px;
box-shadow:6px 6px 0 black;
}

.title{
font-family:'Bangers';
font-size:52px;
letter-spacing:4px;
margin-bottom:10px;
}

.subtitle{
font-size:16px;
margin-bottom:35px;
}

.progress{
width:320px;
height:24px;
border:6px solid black;
background:#ddd;
box-shadow:6px 6px 0 black;
overflow:hidden;
margin:auto;
position:relative;
}

.bar{
position:absolute;
left:0;
top:0;
width:100%;
height:100%;
transform-origin:left;
transform:scaleX(0);
}

.bar::before{
content:"";
position:absolute;
inset:0;
background:repeating-linear-gradient(
45deg,
#ff2a2a 0px,
#ff2a2a 16px,
#ff7070 16px,
#ff7070 32px
);
background-size:60px 60px;
animation:stripeMove 1s linear infinite;
}

@keyframes stripeMove{
from{background-position:0 0;}
to{background-position:60px 0;}
}

.percent{
margin-top:20px;
font-family:'Bangers';
font-size:30px;
}

.fadeOut{
animation:fadeOut .5s forwards;
}

@keyframes fadeOut{
to{
opacity:0;
visibility:hidden;
}
}

</style>
</head>

<body>

<div id="comicLoader">

<div class="panel">

<div class="bubble">PREPARING...</div>

<div class="title">PMII STAIM</div>

<div class="subtitle">Preparing Comic Interface</div>

<div class="progress">
<div class="bar" id="bar"></div>
</div>

<div class="percent" id="percent">0%</div>

</div>

</div>

<script>

(function(){

const duration = 3000; // 🔥 CEPAT (3 DETIK)

const bar=document.getElementById("bar");
const percent=document.getElementById("percent");
const loader=document.getElementById("comicLoader");

let start=null;

function preventScroll(e){ e.preventDefault(); }

window.addEventListener("wheel", preventScroll, {passive:false});
window.addEventListener("touchmove", preventScroll, {passive:false});

function animate(t){

if(!start) start=t;

let progress=t-start;
let p=Math.min(progress/duration,1);

bar.style.transform="scaleX("+p+")";
percent.textContent=Math.floor(p*100)+"%";

if(progress<duration){

requestAnimationFrame(animate);

}else{

loader.classList.add("fadeOut");

window.removeEventListener("wheel", preventScroll);
window.removeEventListener("touchmove", preventScroll);

setTimeout(()=>loader.remove(),500);

}

}

requestAnimationFrame(animate);

})();

</script>

</body>
</html>"},"elements":[],"widgetType":"html"}],"isInner":false},{"id":"3761479","elType":"container","settings":{"flex_direction":"column","hide_mobile":"hidden-mobile"},"elements":[{"id":"4833a0f","elType":"widget","settings":{"html":"<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">

<title>Ultra Comic Footer</title>

<link href="https://fonts.googleapis.com/css2?family=Bangers&family=Poppins:wght@400;600&display=swap" rel="stylesheet">

<style>

/* ===== RESET ===== */
html, body {
  margin:0;
  padding:0;
  font-family:'Poppins',sans-serif;
}

/* ===== WRAPPER ===== */
.footer-wrapper {
  position:relative;
}

/* ===== BOOOM TITLE ===== */
.comic-title {
  position:absolute;
  top:-60px;
  left:50%;
  transform:translateX(-50%) rotate(-4deg);
  font-family:'Bangers',cursive;
  font-size:90px;
  color:#ff0055;
  letter-spacing:3px;
  text-shadow:6px 6px 0 #000, 12px 12px 0 #ffe600;
  z-index:10;
  white-space:nowrap;
  animation:boomTitle 20s infinite;
}

/* ===== FOOTER ===== */
.comic-footer {
  width:100vw;
  margin-left:calc(-50vw + 50%);
  background:
    radial-gradient(circle,#000 3px,transparent 3px),
    #ffe600;
  background-size:24px 24px;
  border-top:12px solid #000;
  position:relative;
  overflow:hidden;
  padding-top:120px;
}

/* ===== EXPLOSION BULAT ===== */
.comic-footer:before,
.comic-footer:after {
  content:"";
  position:absolute;
  width:420px;
  height:420px;
  border-radius:50%;
  background:
    repeating-conic-gradient(
      #ff2e2e 0deg 10deg,
      #ffe600 10deg 20deg
    );
  animation:explode 20s infinite;
}

.comic-footer:before {
  top:-200px;
  left:-200px;
}

.comic-footer:after {
  bottom:-200px;
  right:-200px;
}

/* ===== INNER ===== */
.comic-footer-inner {
  max-width:1200px;
  margin:auto;
  padding:60px 20px;
  position:relative;
  z-index:2;
}

/* ===== PANELS ===== */
.comic-panels {
  display:grid;
  grid-template-columns:repeat(auto-fit,minmax(240px,1fr));
  gap:35px;
}

/* ===== PANEL ===== */
.panel {
  background:#fff;
  border:8px solid #000;
  padding:25px;
  box-shadow:12px 12px 0 #000;
  transform:rotate(-2deg);
}

.panel:nth-child(2){transform:rotate(3deg);}
.panel:nth-child(3){transform:rotate(-1deg);}
.panel:nth-child(4){transform:rotate(2deg);}

/* ===== PANEL TITLE ===== */
.panel h3 {
  font-family:'Bangers',cursive;
  font-size:30px;
  margin-bottom:15px;
}

/* ===== TEXT ===== */
.panel p,
.panel a {
  font-size:15px;
  color:#111;
  text-decoration:none;
  display:block;
  margin-bottom:8px;
}

.panel a:hover {
  color:#ff0055;
}

/* ===== FOOTER BOTTOM ===== */
.footer-bottom {
  background:#000;
  color:#fff;
  text-align:center;
  padding:20px;
  font-size:14px;
}

.footer-bottom span {
  color:#ffe600;
  font-weight:700;
}

/* ===== ANIMATIONS ===== */
@keyframes boomTitle {
  0%,100% { opacity:0; transform:translateX(-50%) rotate(-4deg) scale(0); }
  10%,25% { opacity:1; transform:translateX(-50%) rotate(-4deg) scale(1.2); }
  30% { transform:translateX(-50%) rotate(-4deg) scale(1); }
  35%,90% { opacity:0; transform:translateX(-50%) rotate(-4deg) scale(0); }
}

@keyframes explode {
  0%,100% { opacity:0; }
  10%,40% { opacity:0.8; }
  45%,95% { opacity:0; }
}

</style>
</head>

<body>

<div class="footer-wrapper">

  <div class="comic-title">BOOOM 💥</div>

  <footer class="comic-footer">

    <div class="comic-footer-inner">

      <div class="comic-panels">

        <div class="panel">
          <h3>CAPTER I</h3>
          <p>Website dengan gaya unik, beda, dan penuh karakter.</p>
          <p>Kami tidak mau menjadi biasa-biasa saja 😎</p>
        </div>

        <div class="panel">
          <h3>Menu</h3>
          <a href="#">🏠 Beranda</a>
          <a href="#">📚 Artikel</a>
          <a href="#">🧠 Edukasi</a>
        </div>

        <div class="panel">
          <h3>Sosial Media</h3>
          <a href="#">📸 Instagram</a>
          <a href="#">⚡ TikTok</a>
          <a href="#">▶ YouTube</a>
        </div>

        <div class="panel">
          <h3>Quote Komik</h3>
          <p>“Tetap berbuat baik seperti pahlawan,”</p>
          <p>“Walaupun dianggap sebagai villain.”</p>
        </div>

      </div>

    </div>

    <div class="footer-bottom">
      © 2025 <span>WEBSITE KOMIK STYLE</span> — Powered by SlametKarisna
    </div>

  </footer>

</div>

</body>
</html>"},"elements":[],"widgetType":"html"}],"isInner":false},{"id":"ec56a71","elType":"container","settings":{"flex_direction":"column"},"elements":[{"id":"c498b48","elType":"widget","settings":{"hide_desktop":"hidden-desktop","hide_tablet":"hidden-tablet"},"elements":[],"widgetType":"html"}],"isInner":false}]

