					<link href="https://fonts.googleapis.com/css2?family=Bangers&display=swap" rel="stylesheet">

<div class="pmii-dual-wrap">
  <span class="pmii-dual" data-text="PMII KOMIS KENDAL NGAWI">
    <span class="blue">PMII</span>
    <span class="yellow">KOMIS KENDAL NGAWI</span>
  </span>
</div>

<style>
.pmii-dual-wrap {
  text-align: center;
  padding: 24px 0;
}

/* === MAIN TEXT COMIC STYLE === */
.pmii-dual {
  font-family: 'Bangers', cursive;
  font-size: 36px; /* lebih besar dan bold ala komik */
  letter-spacing: 2px;
  display: inline-block;
  position: relative;
  text-transform: uppercase;
  line-height: 1.2;
}

/* === WARNA & SHADOW COMIC === */
.pmii-dual .blue {
  color: #1e90ff;
  text-shadow:
    2px 2px 0 #000,
    -2px -2px 0 #000,
    1px -1px 0 #000,
    -1px 1px 0 #000;
  animation: blueComicPulse 2.5s infinite alternate;
}

.pmii-dual .yellow {
  color: #ffd700;
  margin-left: 12px;
  text-shadow:
    2px 2px 0 #000,
    -2px -2px 0 #000,
    1px -1px 0 #000,
    -1px 1px 0 #000;
  animation: yellowComicPulse 2.5s infinite alternate;
}

/* === PULSE COMIC === */
@keyframes blueComicPulse {
  0% { text-shadow: 1px 1px 0 #000, -1px -1px 0 #000; }
  50% { text-shadow: 3px 3px 0 #000, -3px -3px 0 #000; }
  100% { text-shadow: 1px 1px 0 #000, -1px -1px 0 #000; }
}

@keyframes yellowComicPulse {
  0% { text-shadow: 1px 1px 0 #000, -1px -1px 0 #000; }
  50% { text-shadow: 3px 3px 0 #000, -3px -3px 0 #000; }
  100% { text-shadow: 1px 1px 0 #000, -1px -1px 0 #000; }
}

/* === MICRO COMIC GLITCH === */
.pmii-dual::before,
.pmii-dual::after {
  content: attr(data-text);
  position: absolute;
  left: 0;
  top: 0;
  opacity: .2;
  pointer-events: none;
  white-space: nowrap;
  font-family: 'Bangers', cursive;
}

.pmii-dual::before {
  color: #1e90ff;
  animation: comicGlitchLeft 4s infinite;
}

.pmii-dual::after {
  color: #ffd700;
  animation: comicGlitchRight 5s infinite;
}

@keyframes comicGlitchLeft {
  0%,94%,100% { transform: translate(0,0) rotate(0deg); }
  96% { transform: translate(-2px,1px) rotate(-1deg); }
}

@keyframes comicGlitchRight {
