    <style>
        /* RESET & PENGATURAN DASAR - SCROLL NORMAL KEMBALI */
        html, body {
            margin: 0;
            padding: 0;
            width: 100%;
            /* height: 100%; DIHAPUS AGAR BISA SCROLL */
            background-color: #154835;
            -webkit-text-size-adjust: 100%;
        }

        #ks-mobile-lockdown {
            font-family: 'Montserrat', sans-serif;
            background: linear-gradient(135deg, #f4f8f6 0%, #e8f0ea 100%);
            color: #333;
            width: 100%;
            min-height: 100vh;
            display: flex;
            flex-direction: column;
            overflow-x: hidden;
            box-sizing: border-box;
            line-height: 1.6;
        }

        #ks-mobile-lockdown * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        /* ANIMASI MASUK MENGALUN */
        @keyframes pageFadeInUp {
            0% { opacity: 0; transform: translateY(15px); }
            100% { opacity: 1; transform: translateY(0); }
        }

        /* AREA KONTEN UTAMA */
        .ks-content-area {
            flex: 1;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            padding: 40px 24px;
            width: 100%;
            max-width: 420px;
            margin: 0 auto;
            animation: pageFadeInUp 0.8s cubic-bezier(0.2, 0.8, 0.2, 1) forwards;
        }

        /* LOGO */
        .ks-header-logo {
            width: 75px;
            height: auto;
            margin-bottom: 24px;
            filter: drop-shadow(0 6px 12px rgba(21, 72, 53, 0.15));
        }

        /* KELOMPOK JUDUL */
        .ks-title-group {
            text-align: center;
            margin-bottom: 20px;
            width: 100%;
        }

        .ks-title-group h1 {
            font-size: 22px;
            font-weight: 800;
            color: #154835;
            margin-bottom: 10px;
            text-transform: uppercase;
            line-height: 1.35;
            letter-spacing: 0.5px;
            text-shadow: 0 4px 12px rgba(0, 0, 0, 0.6); 
        }

        .ks-subtitle-row {
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 12px;
            width: 100%;
        }

        .ks-subtitle-row h2 {
            font-size: 13px;
            font-weight: 700;
            color: #c29b46;
            text-transform: uppercase;
            letter-spacing: 1.5px;
            white-space: nowrap;
