            font-size: 13px;
            font-weight: 600;
            color: #154835;
            line-height: 1.55;
            margin: 0;
        }

        .ks-alert-card p strong {
            color: #c29b46;
            font-weight: 800;
        }

        /* PEMISAH (DIVIDER) */
        .ks-divider-row {
            display: flex;
