            height: 16px;
            margin: 0 12px;
            stroke: #c29b46;
            display: block;
        }

        /* BAGIAN REKOMENDASI */
        .ks-rec-row {
            display: flex;
            align-items: center; /* Diubah ke center agar sejajar rapi antara ikon & teks */
