            font-size: 12.5px;
            color: #666;
            font-weight: 500;
            line-height: 1.5;
        }

        /* ANIMASI CHECKLIST (MOCKUP MENU) */
        .ks-anim-title {
            font-size: 10px;
            font-weight: 700;
            color: #999;
            text-transform: uppercase;
            letter-spacing: 1.2px;
            margin-bottom: 6px;
        }

        /* PERBAIKAN ALIGNMENT SUPER PRESISI DI BAR MOCKUP */
        .ks-mock-menu-item {
            display: flex;
            justify-content: space-between;
            align-items: center;
            background: #f4f8f6;
            padding: 12px 16px;
            border-radius: 8px;
            position: relative;
            border: 1px solid #e0e8e4;
        }

        .ks-mock-text {
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .ks-mock-text svg {
            display: block;
            margin-top: -1px; /* Koreksi optikal halus */
        }

        .ks-mock-text span {
            font-size: 13px;
            font-weight: 600;
            color: #154835;
            line-height: 1; /* Mematikan tinggi baris berlebih agar sejajar sempurna */
            padding-top: 1px; /* Koreksi optikal untuk huruf besar */
        }

        .ks-checkbox-mock {
            width: 22px;
            height: 22px;
            border: 1.5px solid #cbd5e1;
            border-radius: 5px;
            position: relative;
            background: transparent;
            animation: boxCheck 4s infinite;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        /* Presisi absolute center untuk tanda centang */
        .ks-checkmark-mock {
            position: absolute;
            top: 45%;
            left: 50%;
            width: 5px;
            height: 11px;
            border: solid white;
            border-width: 0 2px 2px 0;
            /* Membawa titik tengah elemen tepat ke titik tengah kotak */
            transform: translate(-50%, -50%) rotate(45deg);
            opacity: 0;
            animation: markCheck 4s infinite;
        }

        .ks-pointer-mock {
            position: absolute;
            right: -10px;
            top: 22px;
            width: 24px;
            height: 24px;
            fill: #c29b46;
            opacity: 0;
            z-index: 10;
            filter: drop-shadow(0 4px 4px rgba(0,0,0,0.25));
            animation: pointerClick 4s infinite;
        }

        @keyframes boxCheck {
            0%, 20% { background: transparent; border-color: #cbd5e1; }
            35%, 85% { background: #154835; border-color: #154835; box-shadow: 0 2px 6px rgba(21, 72, 53, 0.3); }
            100% { background: transparent; border-color: #cbd5e1; }
        }

        @keyframes markCheck {
            0%, 20% { opacity: 0; }
            35%, 85% { opacity: 1; }
            100% { opacity: 0; }
        }

        @keyframes pointerClick {
            0% { transform: translate(15px, 15px); opacity: 0; }
            15% { transform: translate(0, 0); opacity: 1; }
            25% { transform: translate(0, 0) scale(0.85); opacity: 1; } 
            35% { transform: translate(0, 0) scale(1); opacity: 0; } 
            100% { opacity: 0; }
        }

        /* AREA FOOTER */
        .ks-footer-area {
            width: 100%;
            margin-top: auto;
        }

        .ks-wave {
            display: block;
            width: 100%;
            height: auto;
            margin-bottom: -1px;
        }

