            stroke-width: 1.5;
            width: 18px;
            height: 18px;
            opacity: 0.7;
            transition: all 0.3s ease;
            display: block;
        }

        .ks-soc-icon:hover {
            opacity: 1;
            transform: scale(1.1);
        }
    </style>
</head>
