					<!DOCTYPE html>
<html lang="id">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
    <title>Comic Futuristic Slider - Full Wide</title>
    <link href="https://fonts.googleapis.com/css2?family=Bangers&family=Comic+Neue:wght@700;800&display=swap" rel="stylesheet">
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css"/>

<style>
    :root {
        --yellow: #ffeb3b;
        --black: #050505;
        --white: #ffffff;
        --blue-dark: #0b1e34;
    }

    * {
        margin: 0;
        padding: 0;
        box-sizing: border-box;
        -webkit-tap-highlight-color: transparent;
    }

    body {
        background: var(--blue-dark);
        font-family: 'Comic Neue', sans-serif;
        overflow-x: hidden;
    }

    /* ================= HERO CONTAINER (DILEBARKAN) ================= */
    .hero {
        position: relative;
        width: 100%; /* Dibuat 100% Lebar */
        height: 85vh; 
        min-height: 500px;
        overflow: hidden;
        border-top: 10px solid var(--black); /* Hanya border atas & bawah agar terlihat wide */
        border-bottom: 10px solid var(--black);
        background: #000;
        margin: 0; /* Menghilangkan margin auto agar menempel ke pinggir */
        box-shadow: 0 10px 0 var(--black); /* Shadow hanya di bawah */
    }

    /* SLIDES */
    .slide {
        position: absolute;
        inset: 0;
        background-size: cover;
        background-position: center;
        opacity: 0;
        transform: scale(1.1) rotate(1deg);
        transition: opacity 1.5s ease-in-out, transform 8s linear;
        filter: contrast(1.1) brightness(0.8);
    }

    .slide.active {
        opacity: 1;
        transform: scale(1) rotate(0deg);
    }

    /* ================= COMIC OVERLAYS ================= */
    .hero::after {
        content: "";
        position: absolute;
        inset: 0;
        background-image: 
            linear-gradient(rgba(255,255,255,0.05) 1px, transparent 1px),
            linear-gradient(90deg, rgba(255,255,255,0.05) 1px, transparent 1px);
        background-size: 25px 25px;
        z-index: 2;
        pointer-events: none;
    }

    .halftone {
        position: absolute;
        inset: 0;
        background-image: radial-gradient(var(--black) 1px, transparent 1px);
        background-size: 4px 4px;
        opacity: 0.25;
        z-index: 3;
        pointer-events: none;
    }

    .speed-lines {
        position: absolute;
        inset: 0;
        background: repeating-conic-gradient(from 0deg, rgba(255,255,255,0.05) 0deg 2deg, transparent 2deg 10deg);
        z-index: 2;
        animation: rotateSpeed 60s linear infinite;
    }

    /* ================= CONTENT & TYPOGRAPHY ================= */
    .content {
        position: absolute;
        bottom: 60px;
        left: 0;
        width: 100%;
        padding: 0 5%; /* Padding samping agar teks tidak nempel layar */
        z-index: 10;
        display: flex;
        flex-direction: column;
        align-items: flex-start;
    }

    .content h1 {
        font-family: 'Bangers', cursive;
        font-size: clamp(38px, 10vw, 65px); /* Sedikit diperbesar karena layar lebar */
        line-height: 1;
        color: var(--white);
        -webkit-text-stroke: 2px var(--black);
        text-shadow: 4px 4px 0 var(--black), 6px 6px 0 rgba(0,0,0,0.2);
        margin-bottom: 5px;
        transform: skewX(-5deg);
    }

    .content h3 {
        font-family: 'Bangers', cursive;
        font-size: clamp(18px, 4vw, 26px);
        color: var(--yellow);
        background: var(--black);
        padding: 5px 12px;
        display: inline-block;
        margin-bottom: 15px;
        transform: rotate(-1deg);
    }

    .speech-bubble {
        position: relative;
        background: var(--white);
        color: var(--black);
        padding: 10px 18px;
        border: 3px solid var(--black);
        font-weight: 800;
        font-size: 13px;
        border-radius: 15px;
        box-shadow: 4px 4px 0 var(--black);
    }

    .speech-bubble::after {
        content: '';
        position: absolute;
        top: -15px;
        left: 20px;
        border-width: 0 10px 15px 10px;
        border-style: solid;
        border-color: transparent transparent var(--black) transparent;
    }

    /* ================= ACTION ELEMENTS ================= */
    .burst {
        position: absolute;
        top: 15%;
        right: 5%;
        font-family: 'Bangers', cursive;
        font-size: clamp(50px, 12vw, 80px);
        color: #ff2d55;
        -webkit-text-stroke: 3px var(--black);
        text-shadow: 5px 5px 0 var(--black);
        z-index: 15;
        animation: burstAnime 4s infinite;
        pointer-events: none;
    }

    .progress-wrap {
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 8px;
        background: rgba(0,0,0,0.3);
        z-index: 20;
    }

    .progress-bar {
        height: 100%;
        background: var(--yellow);
        width: 0%;
    }

    .dots {
        position: absolute;
        bottom: 20px;
        right: 5%;
        display: flex;
        gap: 8px;
        z-index: 20;
    }

    .dot {
        width: 40px;
        height: 10px;
        background: var(--white);
        border: 2px solid var(--black);
        cursor: pointer;
        transition: 0.3s;
        transform: skewX(-15deg);
    }

    .dot.active {
        background: var(--yellow);
        width: 60px;
    }

    /* ================= ANIMATIONS ================= */
    @keyframes rotateSpeed {
        from { transform: scale(1.5) rotate(0deg); }
        to { transform: scale(1.5) rotate(360deg); }
    }

    @keyframes burstAnime {
        0%, 100% { transform: scale(0) rotate(-20deg); opacity: 0; }
        10%, 40% { transform: scale(1.2) rotate(10deg); opacity: 1; }
        50% { transform: scale(1) rotate(0deg); opacity: 1; }
    }

    .hero-vignette {
        position: absolute;
        inset: 0;
        background: radial-gradient(circle, transparent 30%, rgba(0,0,0,0.8) 100%);
        z-index: 5;
        pointer-events: none;
    }
</style>
</head>

<body>

<section class="hero">
    <div class="progress-wrap">
        <div class="progress-bar" id="progressBar"></div>
    </div>

    <div class="slide active" style="background-image:url('https://i.ibb.co.com/R4Zfs7ZD/Chat-GPT-Image-Jul-12-2026-07-25-44-PM.png')"></div>
    <div class="slide" style="background-image:url('https://i.ibb.co.com/rfxdW3FC/Chat-GPT-Image-Jul-12-2026-07-46-24-PM.png')"></div>
    <div class="slide" style="background-image:url('https://i.ibb.co.com/Y4Lsg05c/Chat-GPT-Image-Jul-12-2026-07-51-19-PM.png')"></div>

    <div class="speed-lines"></div>
    <div class="halftone"></div>
    <div class="hero-vignette"></div>

    <div class="burst" id="burstText">BOOM!</div>

    <div class="content">
        <h1>PMII STAIM KENDAL</h1>
        <h3>NGAWI BERGERAK!</h3>
        <div class="speech-bubble" id="dateText">
            Memuat data...
        </div>
    </div>

    <div class="dots">
        <div class="dot active" onclick="manualSlide(0)"></div>
        <div class="dot" onclick="manualSlide(1)"></div>
        <div class="dot" onclick="manualSlide(2)"></div>
    </div>
</section>

<script>
    const slides = document.querySelectorAll(".slide");
    const dots = document.querySelectorAll(".dot");
    const progressBar = document.getElementById("progressBar");
    const burstText = document.getElementById("burstText");

    let index = 0;
    const duration = 6000; 
    let slideTimer;
    let startTime;

    const actionWords = ["POW!", "BOOM!", "ZAP!", "BANG!", "WHAM!"];

    function updateProgress() {
        const elapsed = Date.now() - startTime;
        const progress = (elapsed / duration) * 100;
        progressBar.style.width = Math.min(progress, 100) + "%";

        if (progress < 100) {
            requestAnimationFrame(updateProgress);
        }
    }

    function showSlide(n) {
        slides.forEach(s => s.classList.remove("active"));
        dots.forEach(d => d.classList.remove("active"));

        index = (n + slides.length) % slides.length;

        slides[index].classList.add("active");
        dots[index].classList.add("active");

        burstText.textContent = actionWords[Math.floor(Math.random() * actionWords.length)];

        startTime = Date.now();
        updateProgress();
    }

    function autoSlide() {
        showSlide(index + 1);
    }

    function manualSlide(n) {
        clearInterval(slideTimer);
        showSlide(n);
        slideTimer = setInterval(autoSlide, duration);
    }

    startTime = Date.now();
    updateProgress();
    slideTimer = setInterval(autoSlide, duration);

    function updateDate() {
        const now = new Date();
        const days = ["Minggu", "Senin", "Selasa", "Rabu", "Kamis", "Jumat", "Sabtu"];
        const months = ["Januari", "Februari", "Maret", "April", "Mei", "Juni", "Juli", "Agustus", "September", "Oktober", "November", "Desember"];

        const output = `${days[now.getDay()]}, ${now.getDate()} ${months[now.getMonth()]} ${now.getFullYear()} • NGAWI`;
        document.getElementById('dateText').innerHTML = `<i class="fas fa-map-marker-alt"></i> ${output}`;
    }
    updateDate();
</script>

</body>
