<style>
/* Reset & Font */
@import url('https://fonts.googleapis.com/css2?family=Bangers&display=swap');

.comic-clock-container {
  position: relative;
  padding: 40px;
  background: #f0f0f0; /* Background kontras */
  display: inline-block;
  border: 4px solid #000;
  border-radius: 8px;
}

.comic-clock-wrap {
  display: flex;
  align-items: center;
  gap: 30px;
  font-family: 'Bangers', cursive;
}

/* SPEECH BUBBLE DECOR */
.speech-bubble {
  position: absolute;
  top: -15px;
  left: -10px;
  background: #fff;
  border: 3px solid #000;
  padding: 5px 15px;
  font-family: 'Bangers';
  transform: rotate(-15deg);
  z-index: 20;
  box-shadow: 4px 4px 0 #000;
}

/* ANALOG CLOCK */
.analog-comic {
  width: 140px;
  height: 140px;
  border-radius: 50%;
  background: #fff200;
  position: relative;
  border: 5px solid #000;
  box-shadow: 8px 8px 0 #000;
  overflow: visible; /* Biar burst bisa keluar sedikit */
}

/* Halftone Pattern Effect */
.halftone-overlay {
  position: absolute;
  inset: 0;
  background-image: radial-gradient(#000 10%, transparent 11%);
  background-size: 6px 6px;
  opacity: 0.1;
  border-radius: 50%;
}

.burst-bg {
  position: absolute;
  inset: -15px;
  background: radial-gradient(circle, #ff2d55 30%, transparent 31%);
  background-size: 15px 15px;
  z-index: -1;
  animation: rotateBurst 10s linear infinite;
  opacity: 0.8;
}

@keyframes rotateBurst {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

.number {
  position: absolute;
  font-size: 18px;
  color: #000;
  -webkit-text-stroke: 1px #fff;
}

.n12 { top: 8px; left: 50%; transform: translateX(-50%); }
.n3 { right: 10px; top: 50%; transform: translateY(-50%); }
.n6 { bottom: 8px; left: 50%; transform: translateX(-50%); }
.n9 { left: 10px; top: 50%; transform: translateY(-50%); }

/* HANDS UPGRADE */
.hand {
  position: absolute;
  bottom: 50%;
  left: 50%;
  transform-origin: bottom center;
  border: 2px solid #000;
}

.hour {
  width: 8px;
  height: 35px;
  background: #000;
  z-index: 3;
}

.minute {
  width: 6px;
  height: 50px;
  background: #00aaff;
  z-index: 4;
}

.second {
  width: 3px;
  height: 60px;
  background: #ff2d55;
  z-index: 5;
  box-shadow: 3px 0 0 rgba(0,0,0,0.2);
}

.center-dot {
  position: absolute;
  width: 16px;
  height: 16px;
  background: #ff2d55;
  border: 3px solid #000;
  border-radius: 50%;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  z-index: 10;
}

/* DIGITAL PANEL */
.digital-panel {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.digital-label {
  font-size: 12px;
  background: #000;
  color: #fff;
  padding: 2px 8px;
  transform: skewX(-10deg);
  margin-bottom: -10px;
  z-index: 2;
}

.digital-comic {
  font-size: 40px;
  color: #fff;
  background: #00c3ff;
  padding: 10px 20px;
  border: 4px solid #000;
  box-shadow: 6px 6px 0 #ff2d55, 10px 10px 0 #000;
  transform: rotate(2deg);
  transition: all 0.1s ease;
}

/* Tick Animation */
.tick-active {
  transform: rotate(2deg) scale(1.05);
  filter: brightness(1.1);
}
</style>

<script>
(() => {
  const elHour = document.getElementById('hour');
  const elMin = document.getElementById('minute');
  const elSec = document.getElementById('second');
  const elDigital = document.getElementById('digitalTime');

  let lastSec = -1;

  function update() {
    const now = new Date();
    const h = now.getHours();
    const m = now.getMinutes();
    const s = now.getSeconds();
    const ms = now.getMilliseconds();

    // 1. Digital Update with Pulse Effect
    if (s !== lastSec) {
      elDigital.textContent = 
        `${h.toString().padStart(2,'0')}:${m.toString().padStart(2,'0')}:${s.toString().padStart(2,'0')}`;

      // Trigger visual kick
      elDigital.classList.add('tick-active');
      setTimeout(() => elDigital.classList.remove('tick-active'), 100);

      lastSec = s;
    }

    // 2. Smooth Analog Movement
    const secProgress = s + ms / 1000;
    const minProgress = m + secProgress / 60;
    const hourProgress = (h % 12) + minProgress / 60;

    // Apply rotation
    elSec.style.transform = `translateX(-50%) rotate(${secProgress * 6}deg)`;
    elMin.style.transform = `translateX(-50%) rotate(${minProgress * 6}deg)`;
    elHour.style.transform = `translateX(-50%) rotate(${hourProgress * 30}deg)`;

    requestAnimationFrame(update);
  }

  update();
})();
</script>				</div>
