					<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">

<title>Solar System Popup</title>

<link href="https://fonts.googleapis.com/css2?family=Bangers&family=Comic+Neue:wght@700&display=swap" rel="stylesheet">

<style>
body{margin:0;background:#000;overflow:hidden;}

#solar-popup-app{text-align:center;font-family:'Comic Neue',cursive;}

/* DATE */
.dateText{
font-family:'Bangers';
font-size:30px;
color:#ffe600;
text-shadow:3px 3px 0 #000,6px 6px 0 red;
margin-bottom:10px;
}

/* OPEN BUTTON */
.openBtn{
padding:12px 30px;
font-family:'Bangers';
background:#ff0033;
color:#fff;
border:4px solid #000;
box-shadow:5px 5px 0 #000;
cursor:pointer;
}

/* POPUP */
.popup{
position:fixed;inset:0;
background:#000;
display:none;
z-index:999999;
}

canvas{position:absolute;inset:0;}

/* CLOSE */
.closeBtn{
position:absolute;top:20px;right:20px;
background:#1e90ff;
padding:10px;
font-family:'Bangers';
cursor:pointer;
z-index:3;
}

/* 3D BUTTON */
.btn3D{
position:absolute;
top:20px;
left:20px;
background:#00ffcc;
color:#000;
padding:10px 18px;
font-family:'Bangers';
border:3px solid #000;
box-shadow:4px 4px 0 #000;
cursor:pointer;
z-index:3;
transition:0.2s;
}
.btn3D:hover{
transform:scale(1.1) rotate(-2deg);
background:#00e6b8;
}

/* INFO PANEL */
.infoPanel{
position:absolute;
bottom:20px;
left:20px;
background:rgba(0,0,0,0.7);
color:#fff;
padding:15px;
border:2px solid #fff;
max-width:300px;
z-index:3;
}

/* FORMULA */
.formula{
position:absolute;
bottom:20px;
right:20px;
background:rgba(0,0,0,0.7);
color:#fff;
padding:15px;
border:2px solid #fff;
max-width:280px;
z-index:3;
}
</style>
</head>

<body>

<div id="solar-popup-app">

<div class="dateText"></div>
<div class="openBtn">🚀 JELAJAH TATASURYA</div>

<div class="popup">
  <canvas></canvas>

  <div class="btn3D">🌌 MODE 3D ULTRA</div>
  <div class="closeBtn">TUTUP</div>

  <div class="infoPanel">Klik planet untuk info</div>

  <div class="formula">
    F = G(m₁m₂ / r²)<br>
    v = √(GM / r)<br>
    Einstein: Gμν = (8πG/c⁴)Tμν
  </div>
</div>

</div>

<script>
(function(){

const app=document.getElementById("solar-popup-app");
const canvas=app.querySelector("canvas");
const ctx=canvas.getContext("2d");

/* DATE */
app.querySelector(".dateText").innerText =
new Date().toLocaleDateString('id-ID',{
weekday:'long',day:'numeric',month:'long',year:'numeric'
});

/* RESIZE */
function resize(){
canvas.width=window.innerWidth;
canvas.height=window.innerHeight;
}
window.addEventListener("resize",resize);

let running=false,time=0,zoom=1;

/* PLANETS */
const planets=[
{name:"Mercury",r:4,d:60,s:0.04,color:"#888",mass:"3.30×10²³",gravity:"3.7",atm:"-",moon:"0"},
{name:"Venus",r:6,d:90,s:0.03,color:"#c9a86a",mass:"4.87×10²⁴",gravity:"8.87",atm:"CO2 tebal",moon:"0"},
{name:"Earth",r:7,d:130,s:0.02,color:"#2e6cff",mass:"5.97×10²⁴",gravity:"9.8",atm:"N2+O2",moon:"1"},
{name:"Mars",r:6,d:180,s:0.018,color:"#b22222",mass:"6.42×10²³",gravity:"3.7",atm:"CO2 tipis",moon:"2"},
{name:"Jupiter",r:14,d:250,s:0.01,color:"#cfae7b",mass:"1.90×10²⁷",gravity:"24.79",atm:"Gas raksasa",moon:"79"},
{name:"Saturn",r:12,d:310,s:0.008,color:"#d2b48c",ring:true,mass:"5.68×10²⁶",gravity:"10.44",atm:"Gas + cincin",moon:"83"},
{name:"Uranus",r:10,d:370,s:0.006,color:"#7fffd4",mass:"8.68×10²⁵",gravity:"8.69",atm:"Es + gas",moon:"27"},
{name:"Neptune",r:10,d:430,s:0.005,color:"#4169e1",mass:"1.02×10²⁶",gravity:"11.15",atm:"Es raksasa",moon:"14"}
];

/* STARS */
const stars=[];
for(let i=0;i<400;i++){
stars.push({x:Math.random()*innerWidth,y:Math.random()*innerHeight,r:Math.random()*1.5});
}

function drawStars(){
ctx.fillStyle="#fff";
stars.forEach(s=>{
ctx.beginPath();
ctx.arc(s.x,s.y,s.r,0,Math.PI*2);
ctx.fill();
});
}

/* SUN */
function drawSun(cx,cy){
let g=ctx.createRadialGradient(cx,cy,0,cx,cy,120);
g.addColorStop(0,"#fff");
g.addColorStop(0.2,"#ffd700");
g.addColorStop(0.5,"#ff8c00");
g.addColorStop(1,"transparent");

ctx.beginPath();
ctx.fillStyle=g;
ctx.arc(cx,cy,45*zoom,0,Math.PI*2);
ctx.fill();
}

/* PLANET */
function drawPlanet(cx,cy,p){

let a=time*p.s;
let x=cx+Math.cos(a)*p.d*zoom;
let y=cy+Math.sin(a)*(p.d*0.85)*zoom;

ctx.beginPath();
ctx.fillStyle=p.color;
ctx.arc(x,y,p.r*zoom,0,Math.PI*2);
ctx.fill();

/* SHADING */
let g=ctx.createRadialGradient(x-5,y-5,1,x,y,p.r*zoom);
g.addColorStop(0,"rgba(255,255,255,0.25)");
g.addColorStop(1,"rgba(0,0,0,0.5)");
ctx.fillStyle=g;
ctx.fill();

ctx.strokeStyle="rgba(255,255,255,0.25)";
ctx.stroke();

/* RING */
if(p.ring){
ctx.beginPath();
ctx.strokeStyle="rgba(200,200,200,0.6)";
ctx.ellipse(x,y,(p.r+8)*zoom,(p.r+3)*zoom,a,0,Math.PI*2);
ctx.stroke();
}

/* NAME */
ctx.fillStyle="#fff";
ctx.font=12*zoom+"px Arial";
ctx.fillText(p.name,x+10*zoom,y);

p.x=x;p.y=y;p.rz=p.r*zoom;
}

/* ANIMATE */
function animate(){
if(!running)return;

ctx.clearRect(0,0,canvas.width,canvas.height);

let cx=canvas.width/2;
let cy=canvas.height/2;

drawStars();
drawSun(cx,cy);

planets.forEach(p=>{
ctx.beginPath();
ctx.strokeStyle="rgba(255,255,255,0.2)";
ctx.arc(cx,cy,p.d*zoom,0,Math.PI*2);
ctx.stroke();

drawPlanet(cx,cy,p);
});

time+=1;
requestAnimationFrame(animate);
}

/* ZOOM */
canvas.addEventListener("wheel",(e)=>{
e.preventDefault();
zoom+=e.deltaY*-0.001;
zoom=Math.max(0.5,Math.min(zoom,4));
});

/* CLICK INFO */
const infoPanel=app.querySelector(".infoPanel");

canvas.addEventListener("click",(e)=>{
const rect=canvas.getBoundingClientRect();
const mx=e.clientX-rect.left;
const my=e.clientY-rect.top;

planets.forEach(p=>{
let dx=mx-p.x;
let dy=my-p.y;
let dist=Math.sqrt(dx*dx+dy*dy);

if(dist<p.rz){
infoPanel.innerHTML=`
<b>${p.name}</b><br>
Massa: ${p.mass} kg<br>
Gravitasi: ${p.gravity} m/s²<br>
Atmosfer: ${p.atm}<br>
Satelit: ${p.moon}
`;
}
});
});

/* OPEN */
app.querySelector(".openBtn").onclick=()=>{
app.querySelector(".popup").style.display="block";
resize();
running=true;
animate();
};

/* CLOSE */
app.querySelector(".closeBtn").onclick=()=>{
running=false;
app.querySelector(".popup").style.display="none";
};

/* 3D BUTTON */
app.querySelector(".btn3D").onclick=()=>{
window.open("http://pmiikomiskenda.42web.io/wp-content/uploads/2026/05/Simulasi-By-KhrisisS.html");
};

})();
</script>

</body>
</html>				</div>
				</div>
				<div class="elementor-element elementor-element-d017a2e elementor-widget elementor-widget-html" data-id="d017a2e" data-element_type="widget" data-widget_type="html.default">
				<div class="elementor-widget-container">
					<div id="comicNotif">
