<style>
#comicNotif{
  position:fixed;
  top:20%;
  left:-400px; /* awal dari kiri */
  background:#ffeb3b;
  color:#000;
  padding:15px 25px;
  border-radius:12px;
  font-family:'Impact','Arial Black',sans-serif;
  font-size:18px;
  font-weight:900;
  z-index:9999;

  border:3px solid #000;
  box-shadow:
    4px 4px 0 #ff0000,
    8px 8px 0 #000;

  -webkit-text-stroke:1px black;
  text-shadow:2px 2px 0 #fff;
}

/* efek masuk */
.show{
  animation:slideIn 0.5s forwards, shake 0.4s infinite;
}

/* keluar */
.hide{
  animation:slideOut 0.5s forwards;
}

/* animasi masuk kiri → kanan */
@keyframes slideIn{
  from{ left:-400px; }
  to{ left:20px; }
}

/* keluar */
@keyframes slideOut{
  from{ left:20px; }
  to{ left:-400px; }
}

/* efek getar */
@keyframes shake{
  0%{ transform:translate(0,0); }
  25%{ transform:translate(2px,-2px); }
  50%{ transform:translate(-2px,2px); }
  75%{ transform:translate(2px,2px); }
  100%{ transform:translate(0,0); }
}

/* emoji boom */
.boom{
  font-size:22px;
  margin-right:8px;
  animation:pop 0.5s infinite;
}

@keyframes pop{
  0%{ transform:scale(1); }
  50%{ transform:scale(1.3); }
  100%{ transform:scale(1); }
}
</style>

<script>
// suara alarm
function playComicSound(){
  const ctx = new (window.AudioContext || window.webkitAudioContext)();
  const osc = ctx.createOscillator();
  osc.type = "square";
  osc.frequency.setValueAtTime(600, ctx.currentTime);
  osc.connect(ctx.destination);
  osc.start();
  setTimeout(()=> osc.stop(), 400);
}

function showComicNotif(){
  const notif = document.getElementById("comicNotif");

  notif.classList.remove("hide");
  notif.classList.add("show");

  playComicSound();

  setTimeout(()=>{
    notif.classList.remove("show");
    notif.classList.add("hide");
  }, 4000);
}

// trigger tiap 5 menit
setInterval(()=>{
  const now = new Date();
  if(now.getMinutes() % 5 === 0 && now.getSeconds() === 0){
    showComicNotif();
  }
},1000);
</script>				</div>
