font-family:'Comic Neue',sans-serif;

background:

radial-gradient(circle,#000 1px,transparent 1px),
#ffe25a;

background-size:14px 14px;

color:#000;

transition:.4s;

}

/* DARK MODE */

body.dark-mode{

background:

radial-gradient(circle,#fff 1px,transparent 1px),
#111;

background-size:14px 14px;

color:#fff;

}

/* =====================
    SWITCH BAR
===================== */

.switch-bar{

width:100%;

display:flex;

justify-content:center;

margin-top:100px;

}

/* =====================
    PANEL KOMIK
===================== */

.switch-box{

width:80%;
max-width:700px;

padding:25px 40px;

display:flex;

align-items:center;

justify-content:center;

gap:30px;

background:#fff;

border:5px solid #000;

border-radius:18px;

box-shadow:

8px 8px 0 #000;

}

/* DARK PANEL */

body.dark-mode .switch-box{

background:#1c1c1c;

border:5px solid #fff;

box-shadow:8px 8px 0 #fff;

}

/* =====================
   LABEL
===================== */

.label{

font-family:'Bangers',cursive;

font-size:28px;

letter-spacing:1px;

}

/* =====================
   SWITCH
===================== */

.switch{

width:120px;
height:50px;

background:#ffd500;

border:4px solid #000;

border-radius:30px;

display:flex;

align-items:center;

justify-content:space-between;

padding:6px 10px;

cursor:pointer;

position:relative;

box-shadow:4px 4px 0 #000;

}

body.dark-mode .switch{

background:#333;

border:4px solid #fff;

box-shadow:4px 4px 0 #fff;

}

/* ICON */

.sun,
.moon{

font-size:22px;

}

/* CIRCLE */

.circle{

width:38px;
height:38px;

background:#fff;

border-radius:50%;

position:absolute;

left:6px;

border:3px solid #000;

transition:.35s;

}

body.dark-mode .circle{

transform:translateX(66px);

background:#eee;

}

/* =====================
   ELEMENTOR DARK
===================== */

body.dark-mode .elementor-section,
body.dark-mode .elementor-column,
body.dark-mode .elementor-widget-wrap{

background:#1a1a1a !important;

color:#fff !important;

border:3px solid #fff;

}

/* =====================
   COMIC BURST DECOR
===================== */

.switch-bar::before{

content:"POW!";

position:absolute;

top:30px;

font-family:'Bangers';

font-size:70px;

color:#ff3b3b;

text-shadow:

4px 4px 0 #000;

transform:rotate(-8deg);

}

body.dark-mode .switch-bar::before{

content:"NIGHT!";

color:#4da6ff;

}

</style>

