<style>
    /* --- SCOPED & COMPACT COMIC ZONE --- */

    .comic-isolated-zone, 
    .comic-isolated-zone * {
        box-sizing: border-box;
        margin: 0;
        padding: 0;
        font-family: 'Comic Neue', sans-serif;
        font-weight: 800;
    }

    /* Background Dibuat Transparan Total Tanpa Titik-Titik */
    .comic-isolated-zone {
        width: 100%;
        padding: 30px 10px;
        background: transparent; /* Bersih & Transparan */
        display: flex;
        justify-content: center;
        align-items: center;
    }

    /* KONTAINER UTAMA */
    .comic-isolated-zone .comic-wrapper {
        width: 100%;
        max-width: 780px; 
        background: #ffffff;
        border: 4px solid #000000;
        box-shadow: 8px 8px 0px #000000, 16px 16px 0px #00E5FF;
        position: relative;
        padding: 45px 20px 30px 20px;
        margin-top: 20px;
        border-radius: 4px;
    }

    /* JUDUL BAR */
    .comic-isolated-zone .comic-wrapper::before {
        content: "BERALIH MODE";
        position: absolute;
        top: -24px; 
        left: 20px;
        font-family: 'Bangers', cursive;
        font-size: 28px;
        letter-spacing: 2px;
        background: #FFDE4D;
        color: #000000;
        padding: 5px 20px;
        border: 4px solid #000000;
        box-shadow: 4px 4px 0px #FF0055;
        transform: rotate(-3deg);
        z-index: 10;
        transition: 0.2s ease;
    }

    .comic-isolated-zone .comic-wrapper:hover::before {
        transform: rotate(-1deg) scale(1.02);
    }

    /* GRID MINI */
    .comic-isolated-zone .comic-grid {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
        gap: 20px;
        width: 100%;
    }

    /* PANEL KOMIK MINI */
    .comic-isolated-zone .comic-panel {
        background: #ffffff;
        border: 4px solid #000000;
        box-shadow: 5px 5px 0px #000000;
        border-radius: 4px;
        cursor: pointer;
        position: relative;
        overflow: visible;
        display: flex;
        flex-direction: column;
        transition: transform 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275), 
                    box-shadow 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275);
    }

    .comic-isolated-zone .comic-panel:hover {
        transform: translateY(-8px) scale(1.02) rotate(1deg);
        box-shadow: 8px 12px 0px #000000, -3px 3px 10px rgba(0,229,255,0.3);
    }

    .comic-isolated-zone .comic-panel:nth-child(2):hover {
        transform: translateY(-8px) scale(1.02) rotate(-1deg);
    }

    /* BADGE MINI */
    .comic-isolated-zone .panel-badge {
        position: absolute;
        top: -13px;
        left: 12px;
        background: #FF0055;
        color: #ffffff;
        font-family: 'Bangers', cursive;
        font-size: 12px;
        padding: 2px 8px;
        border: 3px solid #000;
        transform: skewX(-10deg);
        z-index: 5;
        box-shadow: 2px 2px 0 #000;
        letter-spacing: 0.5px;
    }
    .comic-isolated-zone .comic-panel:nth-child(2) .panel-badge { background: #00E5FF; color: #000; }
    .comic-isolated-zone .comic-panel:nth-child(3) .panel-badge { background: #9D00FF; }

    /* BINGKAI GAMBAR */
    .comic-isolated-zone .panel-frame {
        width: 100%;
        aspect-ratio: 16 / 11;
        overflow: hidden;
        border-bottom: 4px solid #000000;
        position: relative;
        background: #000;
    }

    .comic-isolated-zone .panel-frame::after {
        content: "";
        position: absolute;
        inset: 0;
        background: linear-gradient(rgba(255,255,255,0.08) 50%, rgba(0,0,0,0.08) 50%);
        background-size: 100% 3px;
        z-index: 2;
        pointer-events: none;
    }

    .comic-isolated-zone .panel-frame img {
        width: 100%;
        height: 100%;
        object-fit: cover;
        display: block;
        transition: transform 0.4s ease;
    }

    .comic-isolated-zone .comic-panel:hover .panel-frame img {
        transform: scale(1.08) rotate(1deg);
    }

    /* FOOTER PANEL MINI */
    .comic-isolated-zone .panel-footer {
        padding: 12px 10px;
        background: #ffffff;
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 8px;
        flex-grow: 1;
    }

    .comic-isolated-zone .action-title {
        font-size: 14px;
        color: #000000;
        text-transform: uppercase;
        letter-spacing: -0.2px;
        text-align: center;
    }

    .comic-isolated-zone .comic-panel:hover .action-title {
        color: #FF0055;
    }

    /* POWER BAR MINI */
    .comic-isolated-zone .power-bar {
        width: 50%;
        height: 10px;
        border: 2px solid #000000;
        background: #EAEAEA;
        box-shadow: 2px 2px 0px #000000;
        position: relative;
        overflow: hidden;
        transition: width 0.3s ease;
    }

    .comic-isolated-zone .power-bar::before {
        content: "";
        position: absolute;
        left: 0; top: 0; bottom: 0;
        width: 0%;
        background: #FFDE4D;
        transition: width 0.3s ease;
    }

    .comic-isolated-zone .comic-panel:hover .power-bar {
        width: 85%;
    }
    .comic-isolated-zone .comic-panel:hover .power-bar::before {
        width: 100%;
        background: linear-gradient(90deg, #FF0055, #FFDE4D);
    }

    /* TRANSISI MINI SHAZAM */
    .safe-comic-shazam {
        position: fixed;
        inset: 0;
        z-index: 999999;
        display: none;
        background: #000000;
        clip-path: circle(0% at 50% 50%);
    }

    .safe-comic-vortex {
        position: absolute;
        inset: -50%;
        background: repeating-conic-gradient(from 0deg, 
            #FFDE4D 0deg 2deg, 
            #FF5F00 2deg 12deg, 
            #000000 12deg 13deg);
        animation: safeVortexSpin 0.3s linear infinite;
        opacity: 0.9;
    }

    @keyframes safeVortexSpin {
        100% { transform: rotate(360deg); }
    }

    .safe-comic-burst-text {
        position: absolute;
        top: 50%; left: 50%;
        transform: translate(-50%, -50%) scale(0);
        font-family: 'Bangers', cursive;
        font-size: clamp(50px, 10vw, 110px);
        color: #ffffff;
        text-shadow: 6px 6px 0px #FF0055, 12px 12px 0px #000000;
        -webkit-text-stroke: 2px #000000;
        white-space: nowrap;
        z-index: 10;
    }

    @keyframes safePopComic {
        0% { transform: translate(-50%, -50%) scale(0) rotate(-30deg); }
        60% { transform: translate(-50%, -50%) scale(1.3) rotate(15deg); }
        100% { transform: translate(-50%, -50%) scale(1.05) rotate(-5deg); }
    }
</style>

