<script>
(function() {
    const panels = document.querySelectorAll(".comic-isolated-zone .comic-panel");
    const transLayer = document.getElementById("safeTransLayer");
    const zoomText = document.getElementById("safeZoomText");

    panels.forEach(panel => {
        panel.addEventListener("click", function() {
            const link = this.getAttribute("data-link");
            const customText = this.getAttribute("data-text");

            if (!link) return;

            zoomText.innerText = customText;
            transLayer.style.display = "block";

            transLayer.animate([
                { clipPath: 'circle(0% at 50% 50%)' },
                { clipPath: 'circle(150% at 50% 50%)' }
            ], {
                duration: 450,
                easing: 'cubic-bezier(0.86, 0, 0.07, 1)',
                fill: 'forwards'
            });

            setTimeout(() => {
                zoomText.style.animation = "safePopComic 0.4s forwards cubic-bezier(0.175, 0.885, 0.32, 1.275)";
            }, 120);

            setTimeout(() => {
                window.location.href = link;
            }, 900);
        });
    });
})();
