					<div class="e-con-inner">
				<div class="elementor-element elementor-element-390c9c7 elementor-widget elementor-widget-html" data-id="390c9c7" data-element_type="widget" data-widget_type="html.default">
				<div class="elementor-widget-container">
					<div class="diagram-levelup-v3">
    <link href="https://fonts.googleapis.com/css2?family=Bangers&family=Comic+Neue:wght@800&display=swap" rel="stylesheet">

    <style>
        .diagram-levelup-v3 * { margin: 0; padding: 0; box-sizing: border-box; }

        .diagram-levelup-v3 {
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 700px;
            padding: 50px;
            /* UPGRADE: Background diubah menjadi transparan sesuai perintah */
            background: transparent;
            font-family: 'Comic Neue', cursive;
            perspective: 1000px; /* Untuk efek 3D */
        }

        /* CARD UTAMA */
        .diagram-levelup-v3 .main-card {
            background: white;
            padding: 70px 50px 50px;
            border: 10px solid #000;
            /* UPGRADE: Triple shadow untuk kedalaman ekstra */
            box-shadow: 
                10px 10px 0 #000,
                20px 20px 0 #ff4757,
                30px 30px 0 #000;
            display: flex;
            gap: 60px;
            align-items: center;
            position: relative;
            /* UPGRADE: Sedikit miring untuk kesan komik fisik */
            transform: rotate(-1deg);
            transition: all 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275);
        }

        .diagram-levelup-v3 .main-card:hover {
            transform: rotate(0deg) scale(1.02);
        }

        /* JUDUL GAYA KOMIK BLAST */
        .diagram-levelup-v3 .title-tag {
            position: absolute;
            top: -45px;
            left: -20px;
            background: #ff4757;
            border: 8px solid #000;
            padding: 10px 35px;
            transform: rotate(-5deg);
            z-index: 10;
            box-shadow: 8px 8px 0 #000;
        }

        .diagram-levelup-v3 .title-tag::before {
            content: '';
            position: absolute;
            top: -15px; left: -15px; width: 100%; height: 100%;
            background: #ffde00;
            border: 8px solid #000;
            z-index: -1;
            transform: rotate(3deg);
        }

        .diagram-levelup-v3 h1 {
            font-family: 'Bangers', cursive;
            font-size: 50px;
            color: white;
            text-shadow: 5px 5px 0 #000;
            letter-spacing: 2px;
        }

        /* DIAGRAM AREA */
        .diagram-levelup-v3 .chart-container {
            position: relative;
            width: 350px;
            height: 350px;
            /* UPGRADE: Lebih menonjol */
            filter: drop-shadow(15px 15px 0px #000);
        }

        /* PIE SEGMENTS */
        .diagram-levelup-v3 .segment {
            position: absolute;
            width: 100%; height: 100%;
            border-radius: 50%;
            transition: all 0.4s cubic-bezier(0.68, -0.55, 0.265, 1.55);
            cursor: pointer;
            border: 8px solid #000;
            /* UPGRADE: Tekstur Halftone Dots di dalam pie */
            background-image: radial-gradient(rgba(0,0,0,0.1) 10%, transparent 11%);
            background-size: 10px 10px;
        }

        .diagram-levelup-v3 .seg-putra {
            background-color: #3498db;
            clip-path: polygon(50% 50%, 50% 0%, 100% 0%, 100% 100%, 75% 100%, 19% 91%);
            z-index: 2;
        }

        .diagram-levelup-v3 .seg-putri {
            background-color: #f1c40f;
            clip-path: polygon(50% 50%, 19% 91%, 0% 80%, 0% 0%, 50% 0%);
            transform: scale(0.97); /* Sedikit celah */
        }

        /* HOVER EFFECTS ON PIE */
        .diagram-levelup-v3 .seg-putra:hover {
            transform: translate(15px, -15px) scale(1.08) rotate(2deg);
            z-index: 4;
            background-color: #5dade2;
        }

        .diagram-levelup-v3 .seg-putri:hover {
            transform: translate(-15px, -10px) scale(1.08) rotate(-2deg);
            z-index: 4;
            background-color: #f4d03f;
        }

        /* ACTION TEXTS (ZAP/POW) - UPGRADE: Elemen baru */
        .diagram-levelup-v3 .action-text {
            position: absolute;
            font-family: 'Bangers', cursive;
            font-size: 30px;
            color: white;
            padding: 5px 15px;
            border: 4px solid #000;
            background: #ff4757;
            text-shadow: 2px 2px 0 #000;
            opacity: 0;
            transition: 0.3s ease-out;
            pointer-events: none;
            z-index: 20;
        }

        .diagram-levelup-v3 .seg-putra:hover ~ .action-putra {
            opacity: 1;
            transform: translate(30px, -30px) rotate(15deg);
        }

        .diagram-levelup-v3 .seg-putri:hover ~ .action-putri {
            opacity: 1;
            transform: translate(-30px, 30px) rotate(-15deg);
        }

        /* LABEL PERSENTASE */
        .diagram-levelup-v3 .label-float {
            position: absolute;
            font-family: 'Bangers', cursive;
            font-size: 36px;
            background: white;
            border: 5px solid #000;
            padding: 5px 15px;
            pointer-events: none;
            z-index: 10;
            box-shadow: 6px 6px 0 #000;
        }

        .diagram-levelup-v3 .l-putra { top: 20%; right: 10%; color: #3498db; animation: float 3s infinite ease-in-out; }
        .diagram-levelup-v3 .l-putri { bottom: 25%; left: 5%; color: #f39c12; animation: float 3s infinite ease-in-out reverse; }

        /* DATA BOXES */
        .diagram-levelup-v3 .info-panel {
            display: flex;
            flex-direction: column;
            gap: 20px;
            width: 280px;
        }

        .diagram-levelup-v3 .card-info {
            padding: 20px;
            border: 6px solid #000;
            background: #fff;
            box-shadow: 8px 8px 0 #000;
            transition: all 0.3s;
            position: relative;
            overflow: hidden;
        }

        /* UPGRADE: Interaksi Silang Lebih Kuat */
        .diagram-levelup-v3 .info-putra:hover ~ .chart-container .seg-putra { 
            transform: scale(1.1) rotate(3deg); 
            border-width: 10px;
            background-color: #5dade2;
        }

        .diagram-levelup-v3 .info-putri:hover ~ .chart-container .seg-putri { 
            transform: scale(1.1) rotate(-3deg); 
            border-width: 10px;
            background-color: #f4d03f;
        }

        .diagram-levelup-v3 .card-info:hover {
            transform: translate(-5px, -5px) rotate(1deg);
            box-shadow: 12px 12px 0 #000;
            background: #fafafa;
        }

        .diagram-levelup-v3 .card-info h4 {
            font-family: 'Bangers', cursive;
            font-size: 26px;
            margin-bottom: 8px;
            display: flex;
            align-items: center;
            gap: 10px;
            text-shadow: 2px 2px 0 rgba(0,0,0,0.1);
        }

        /* DEKORASI */
        .diagram-levelup-v3 .status { font-size: 16px; font-weight: 800; text-transform: uppercase;}
        .diagram-levelup-v3 .blue { color: #3498db; }
        .diagram-levelup-v3 .yellow { color: #f39c12; }

        /* ANIMATIONS */
        @keyframes float {
            0%, 100% { transform: translateY(0) rotate(-3deg); }
            50% { transform: translateY(-12px) rotate(3deg); }
        }

        @keyframes shake {
            0% { transform: translate(1px, 1px); }
            50% { transform: translate(-1px, -1px); }
            100% { transform: translate(1px, -1px); }
        }
    </style>

    <div class="main-card">
        <div class="title-tag">
            <h1>KADER STATS</h1>
        </div>

        <div class="chart-container">
            <div class="segment seg-putra"></div>
            <div class="segment seg-putri"></div>

            <div class="action-text action-putra" style="top: 10%; right: -20px;">PUTRA!</div>
            <div class="action-text action-putri" style="bottom: 10%; left: -20px;">PUTRI!</div>

            <div class="label-float l-putra">55%</div>
            <div class="label-float l-putri">45%</div>
        </div>

        <div class="info-panel">
            <div class="card-info" style="border-color: #ff4757; background: #fff5f6;">
                <h4 style="color: #ff4757;">TOTAL: 120</h4>
                <div class="status">UNIT SIAGA TEMPUR</div>
            </div>

            <div class="card-info info-putra" style="border-color: #3498db;">
                <h4 class="blue">♂ PUTRA (66)</h4>
                <div class="status">AKTIF: 50 | OFF: 16</div>
            </div>

            <div class="card-info info-putri" style="border-color: #f1c40f;">
                <h4 class="yellow">♀ PUTRI (54)</h4>
                <div class="status">AKTIF: 40 | OFF: 14</div>
            </div>

            <p style="font-size: 12px; font-weight: 800; text-align: center; color: #333; margin-top: 10px; background: #eee; padding: 5px; border: 2px solid #000;">
                SOROT ELEMEN UNTUK AKSI KOMIK!
            </p>
        </div>
    </div>
</div>				</div>
