					<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">

<title>Ultra Comic Footer</title>

<link href="https://fonts.googleapis.com/css2?family=Bangers&family=Poppins:wght@400;600&display=swap" rel="stylesheet">

<style>

/* ===== RESET ===== */
html, body {
  margin:0;
  padding:0;
  font-family:'Poppins',sans-serif;
}

/* ===== WRAPPER ===== */
.footer-wrapper {
  position:relative;
}

/* ===== BOOOM TITLE ===== */
.comic-title {
  position:absolute;
  top:-60px;
  left:50%;
  transform:translateX(-50%) rotate(-4deg);
  font-family:'Bangers',cursive;
  font-size:90px;
  color:#ff0055;
  letter-spacing:3px;
  text-shadow:6px 6px 0 #000, 12px 12px 0 #ffe600;
  z-index:10;
  white-space:nowrap;
  animation:boomTitle 20s infinite;
}

/* ===== FOOTER ===== */
.comic-footer {
  width:100vw;
  margin-left:calc(-50vw + 50%);
  background:
    radial-gradient(circle,#000 3px,transparent 3px),
    #ffe600;
  background-size:24px 24px;
  border-top:12px solid #000;
  position:relative;
  overflow:hidden;
  padding-top:120px;
}

/* ===== EXPLOSION BULAT ===== */
.comic-footer:before,
.comic-footer:after {
  content:"";
  position:absolute;
  width:420px;
  height:420px;
  border-radius:50%;
  background:
    repeating-conic-gradient(
      #ff2e2e 0deg 10deg,
      #ffe600 10deg 20deg
    );
  animation:explode 20s infinite;
}

.comic-footer:before {
  top:-200px;
  left:-200px;
}

.comic-footer:after {
  bottom:-200px;
  right:-200px;
}

/* ===== INNER ===== */
.comic-footer-inner {
  max-width:1200px;
  margin:auto;
  padding:60px 20px;
  position:relative;
  z-index:2;
}

/* ===== PANELS ===== */
.comic-panels {
  display:grid;
  grid-template-columns:repeat(auto-fit,minmax(240px,1fr));
  gap:35px;
}

/* ===== PANEL ===== */
.panel {
  background:#fff;
  border:8px solid #000;
  padding:25px;
  box-shadow:12px 12px 0 #000;
  transform:rotate(-2deg);
}

.panel:nth-child(2){transform:rotate(3deg);}
.panel:nth-child(3){transform:rotate(-1deg);}
.panel:nth-child(4){transform:rotate(2deg);}

/* ===== PANEL TITLE ===== */
.panel h3 {
  font-family:'Bangers',cursive;
  font-size:30px;
  margin-bottom:15px;
}

/* ===== TEXT ===== */
.panel p,
.panel a {
  font-size:15px;
  color:#111;
  text-decoration:none;
  display:block;
  margin-bottom:8px;
}

.panel a:hover {
  color:#ff0055;
}

/* ===== FOOTER BOTTOM ===== */
.footer-bottom {
  background:#000;
  color:#fff;
  text-align:center;
  padding:20px;
  font-size:14px;
}

.footer-bottom span {
  color:#ffe600;
  font-weight:700;
}

/* ===== ANIMATIONS ===== */
@keyframes boomTitle {
  0%,100% { opacity:0; transform:translateX(-50%) rotate(-4deg) scale(0); }
  10%,25% { opacity:1; transform:translateX(-50%) rotate(-4deg) scale(1.2); }
  30% { transform:translateX(-50%) rotate(-4deg) scale(1); }
  35%,90% { opacity:0; transform:translateX(-50%) rotate(-4deg) scale(0); }
}

@keyframes explode {
  0%,100% { opacity:0; }
  10%,40% { opacity:0.8; }
  45%,95% { opacity:0; }
}

</style>
</head>

<body>

<div class="footer-wrapper">

  <div class="comic-title">BOOOM 💥</div>

  <footer class="comic-footer">

    <div class="comic-footer-inner">

      <div class="comic-panels">

        <div class="panel">
          <h3>CAPTER I</h3>
          <p>Website dengan gaya unik, beda, dan penuh karakter.</p>
          <p>Kami tidak mau menjadi biasa-biasa saja 😎</p>
        </div>

        <div class="panel">
          <h3>Menu</h3>
          <a href="#">🏠 Beranda</a>
          <a href="#">📚 Artikel</a>
          <a href="#">🧠 Edukasi</a>
        </div>

        <div class="panel">
          <h3>Sosial Media</h3>
          <a href="#">📸 Instagram</a>
          <a href="#">⚡ TikTok</a>
          <a href="#">▶ YouTube</a>
        </div>

        <div class="panel">
          <h3>Quote Komik</h3>
          <p>“Tetap berbuat baik seperti pahlawan,”</p>
          <p>“Walaupun dianggap sebagai villain.”</p>
        </div>

      </div>

    </div>

    <div class="footer-bottom">
      © 2025 <span>WEBSITE KOMIK STYLE</span> — Powered by SlametKarisna
    </div>

  </footer>

</div>

</body>
</html>				</div>
