a:1:{s:10:"custom_css";s:2277:"/* ===============================
   PMII HERO FULLSCREEN FIX
   =============================== */

.pmii-hero {
    position: fixed;           /* bikin nempel full layar */
    top: 0;
    left: 0;
    width: 100vw;             /* full width */
    height: 100vh;            /* full height */
    z-index: -1;              /* supaya tidak nutup konten lain */
    overflow: hidden;
    background: linear-gradient(120deg, #003DFF, #001D99);
    display: flex;
    align-items: center;
    padding-left: 60px;
    box-sizing: border-box;
}

/* wave dan animasi tetap */
.pmii-hero::before {
    content: "";
    position: absolute;
    width: 200%;
    height: 200%;
    top: -50%;
    left: -50%;
    background: radial-gradient(circle, rgba(255,255,255,0.05) 10%, transparent 60%);
    animation: waveMove 9s infinite linear;
}

@keyframes waveMove {
    0% { transform: translate(0,0) rotate(0deg); }
    100% { transform: translate(10%,10%) rotate(360deg); }
}

/* garis diagonal */
.pmii-hero::after {
    content: "";
    position: absolute;
    inset: 0;
    background-image: repeating-linear-gradient(
        135deg,
        rgba(255,255,255,0.04) 0,
        rgba(255,255,255,0.04) 2px,
        transparent 2px,
        transparent 12px
    );
    pointer-events: none;
}

/* text */
.pmii-text {
    position: relative;
    z-index: 10;
    color: white;
    max-width: 500px;
}

.pmii-title {
    font-size: 48px;
    font-weight: 700;
    line-height: 1.2;
}

.pmii-title span {
    color: #FFD500;
}

.pmii-sub {
    margin-top: 10px;
    opacity: 0.9;
    font-size: 18px;
}

.pmii-btn {
    margin-top: 25px;
    display: inline-block;
    background: #FFD500;
    padding: 13px 32px;
    border-radius: 8px;
    font-weight: 600;
    color: #333;
}

/* mockup ikut gelombang */
.pmii-mockup {
    position: absolute;
    right: 50px;
    bottom: 20px;
    width: 340px;
    animation: floatUpDown 4s ease-in-out infinite;
}

@keyframes floatUpDown {
    0% { transform: translateY(0px); }
    50% { transform: translateY(-18px); }
    100% { transform: translateY(0px); }
}

/* wave bawah */
.pmii-bottom-wave {
    position: absolute;
    bottom: 0;
    width: 100%;
    height: 110px;
    background-size: cover;
    background-position: center;
}








