[{"id":"2c90f73","elType":"container","settings":{"flex_direction":"column","background_background":"classic","background_color":"#180202"},"elements":[{"id":"d095914","elType":"widget","settings":{"space":{"unit":"px","size":22,"sizes":[]}},"elements":[],"widgetType":"spacer"}],"isInner":false},{"id":"6236145","elType":"container","settings":{"flex_direction":"column"},"elements":[{"id":"a84930c","elType":"widget","settings":{"html":"<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>PK PMII STAIM Kendal - Cyberpunk Futuristic</title>

<link href="https://fonts.googleapis.com/css2?family=DM+Serif+Display&family=Plus+Jakarta+Sans:wght@400;500;600;700&display=swap" rel="stylesheet">
<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css"/>

<style>
*{margin:0;padding:0;box-sizing:border-box;}
body{font-family:'Plus Jakarta Sans',sans-serif;background:#0c0c12;overflow-x:hidden;}

/* ===== HERO HEADER ===== */
.hero{
  position: relative;
  left:50%;
  transform: translateX(-50%);
  width:100vw;
  height:50vh;
  background:#0c0c12;
  overflow:hidden;
  display:flex;
  flex-direction:column;
  justify-content:space-between;
  padding:25px 90px;
  border-radius:0 0 40px 40px;
  top:-60px;
  box-shadow:0 15px 50px rgba(0,0,0,0.5);
}

/* ===== CYBER GRID BACKGROUND ===== */
.hero::before{
  content:"";
  position:absolute;
  inset:0;
  background: repeating-linear-gradient(
      0deg,
      rgba(0,255,255,0.05),
      rgba(0,255,255,0.05) 1px,
      transparent 1px,
      transparent 20px
    ),
    repeating-linear-gradient(
      90deg,
      rgba(255,0,255,0.05),
      rgba(255,0,255,0.05) 1px,
      transparent 1px,
      transparent 20px
    );
  pointer-events:none;
  z-index:0;
  animation: gridMove 10s linear infinite;
}
@keyframes gridMove{
  0%{background-position:0 0,0 0;}
  100%{background-position:200px 200px,200px 200px;}
}

/* ===== SHINE ANIMATION ===== */
.hero::after{
  content:"";
  position:absolute;
  top:0;
  left:-120%;
  width:60%;
  height:100%;
  background: linear-gradient(
    75deg,
    transparent,
    rgba(255,255,255,0.5),
    transparent
  );
  transform: skewX(-25deg);
  animation: shineMove 6s infinite ease-in-out;
  pointer-events:none;
}
@keyframes shineMove{
  0%{ left:-120%; }
  50%{ left:120%; }
  100%{ left:120%; }
}

/* ===== DECORATIVE CIRCLES ===== */
.hero .circle1, .hero .circle2{
  position:absolute;
  border-radius:50%;
  box-shadow:0 0 90px rgba(255,0,255,0.6);
  animation: float 8s ease-in-out infinite alternate;
}
.hero .circle1{
  width:380px;
  height:380px;
  top:-160px;
  right:-160px;
  background: rgba(255,0,255,0.15);
}
.hero .circle2{
  width:320px;
  height:320px;
  bottom:-140px;
  left:-140px;
  background: rgba(0,255,255,0.12);
}
@keyframes float{
  0%{transform: translateY(0);}
  100%{transform: translateY(20px);}
}

/* ===== NAVIGATION ===== */
.top-nav{display:flex;justify-content:space-between;align-items:center;position:relative;z-index:2;}
.logo{display:flex;align-items:center;gap:20px;}
.logo img{height:50px;transition:.3s;}
.logo img:hover{transform:scale(1.08);}

/* HEADER RIGHT */
.header-right{display:flex;align-items:center;gap:25px;}
.header-menu{display:flex;gap:18px;}
.header-menu a{
  color:#fff;
  text-decoration:none;
  font-size:14px;
  display:flex;
  align-items:center;
  gap:8px;
  padding:10px 20px;
  background: rgba(255,255,255,0.05);
  border-radius:12px;
  transition:.3s;
  backdrop-filter: blur(6px);
  font-weight:500;
  text-shadow:0 0 6px #ff00ff,0 0 12px #00ffff;
  animation: flicker 3s infinite alternate;
}
.header-menu a:hover{
  background: rgba(255,255,255,0.2);
  text-shadow:0 0 15px #ff00ff,0 0 20px #00ffff;
  transform: translateY(-2px);
}

/* SOCIAL ICONS */
.social-icons{display:flex;align-items:center;gap:20px;}
.social-icons a{
  color:white;
  font-size:24px;
  transition:.3s;
  text-shadow:0 0 6px #ff00ff,0 0 12px #00ffff;
  animation: flicker 3s infinite alternate;
}
.social-icons a:hover{
  color:#00ffff;
  transform: scale(1.2);
  text-shadow:0 0 15px #ff00ff,0 0 20px #00ffff;
}

/* HERO TEXT */
.hero-content{position:relative;z-index:2;margin-top:25px;}
.hero h1{
  font-family:'DM Serif Display',serif;
  font-size:40px;
  margin-bottom:12px;
  text-shadow:0 0 8px #ff00ff,0 0 12px #00ffff,0 0 20px #ff00ff,0 4px 15px rgba(0,0,0,0.3);
  animation: flicker 3s infinite alternate;
}
.hero p{
  font-size:16px;
  opacity:.95;
  letter-spacing:0.5px;
  text-shadow:0 0 6px #ff00ff,0 0 8px #00ffff;
  animation: flicker 4s infinite alternate;
}

/* FLICKER ANIMATION */
@keyframes flicker{
  0%,19%,21%,23%,25%,54%,56%,100%{opacity:1;}
  20%,24%,55%{opacity:0.6;}
}

/* RESPONSIVE */
@media(max-width:900px){
  .hero{padding:25px 25px;top:-60px;}
  .top-nav{flex-direction:column;gap:18px;}
  .header-right{flex-direction:column;gap:15px;}
  .hero h1{font-size:28px;text-align:center;}
  .hero p{text-align:center;}
  .social-icons{justify-content:center;}
}
</style>
</head>

<body>
<section class="hero">
  <div class="circle1"></div>
  <div class="circle2"></div>

  <div class="top-nav">
    <div class="logo">
      <img src="https://i.ibb.co/d0DY6w6Z/kopri-trans.png" alt="Logo Kopri">
      <img src="https://i.supaimg.com/7b6189cc-4918-4607-b366-60f9e935ff74/b378f489-1903-41d3-ae58-f662d434d36d.png" alt="Logo Tengah">
      <img src="https://i.ibb.co/wFRdPQwv/pmii-logo.png" alt="Logo PMII">
    </div>

    <div class="header-right">
      <div class="header-menu">
        <a href="#"><i class="fas fa-database"></i> Materi Data</a>
      </div>
      <div class="social-icons">
        <a href="#"><i class="fab fa-instagram"></i></a>
