<div class="neon-root scale-70 holo-grid">
  <h1 class="neon-line glitch">
    <span class="neon-word word-1">Progres</span>
    <span class="neon-word word-2">EVENT</span>
  </h1>
</div>

<style>
:root{
  --size: clamp(40px, 8vw, 96px);
  --gap: 18px;
  --scan: rgba(0,255,240,0.15);
}

/* TRANSPARENT FULL */
.neon-root{
  display:flex;
  align-items:center;
  justify-content:center;
  min-height:220px;
  background:transparent !important;
  padding:0;
  position:relative;
  overflow:hidden;
  mix-blend-mode:screen;
}

/* SCALE 70% */
.scale-70{
  transform:scale(.70);
  transform-origin:center;
}

/* HOLOGRAM GRID LINES floating */
.holo-grid::before{
  content:"";
  position:absolute;
  inset:0;
  background:
    repeating-linear-gradient(
      to right,
      rgba(255,255,255,0.08) 0px,
      rgba(255,255,255,0.01) 1px,
      transparent 3px
    ),
    repeating-linear-gradient(
      to bottom,
      rgba(255,255,255,0.08) 0px,
      rgba(255,255,255,0.01) 1px,
      transparent 3px
    );
  opacity:.35;
  animation:gridFloat 18s linear infinite;
}

@keyframes gridFloat{
  0%{ transform:translate(0,0); }
  100%{ transform:translate(-40px,-60px); }
}

/* SCANLINE HOLOGRAM BEAM */
.neon-root::after{
  content:"";
  position:absolute;
  top:-200%;
  left:0;
  width:100%;
  height:200%;
  background:linear-gradient(to bottom, transparent 0%, var(--scan) 45%, transparent 90%);
  mix-blend-mode:screen;
  animation:scanMove 6s linear infinite;
}
@keyframes scanMove{
  0%{ transform:translateY(-100%); }
  100%{ transform:translateY(100%); }
}

/* teks utama */
.neon-line{
  margin:0;
  padding:0;
  font-family:"Orbitron","Audiowide","Rajdhani",system-ui;
  font-weight:700;
  display:flex;
  gap:var(--gap);
  align-items:center;
  position:relative;
}

/* glitch layers */
.glitch{
  animation:glitchShift 3.5s infinite steps(2);
}
.glitch:before,
.glitch:after{
  content:attr(data-text);
  position:absolute;
  left:0;
  mix-blend-mode:screen;
  opacity:.65;
}
.glitch:before{
  color:#0ff;
  animation:glitchMove1 2.8s infinite;
}
.glitch:after{
  color:#f0f;
  animation:glitchMove2 3.1s infinite;
}

@keyframes glitchMove1{
  0%,100%{ transform:translate(0,0); }
  50%{ transform:translate(-2px,2px); }
}
@keyframes glitchMove2{
  0%,100%{ transform:translate(0,0); }
  50%{ transform:translate(2px,-2px); }
}
@keyframes glitchShift{
  0%,100%{ filter:brightness(1); }
  50%{ filter:brightness(1.45); }
}

/* neon word */
.neon-word{
  font-size:var(--size);
  line-height:1;
  position:relative;
  -webkit-text-stroke:1px rgba(255,255,255,0.08);
  transform:translateZ(0);
}

/* cyan electric */
.word-1{
  background:linear-gradient(90deg,rgba(0,255,246,1),rgba(0,190,255,0.9),rgba(0,120,255,0.8));
  -webkit-background-clip:text;
  color:transparent;
  text-shadow:
    0 0 18px rgba(0,255,246,0.9),
    0 0 48px rgba(0,190,255,0.6);
  animation: pulseCyan 2.6s ease-in-out infinite, flicker 6s infinite;
}

/* magenta deep neon */
.word-2{
  background:linear-gradient(90deg,rgba(255,92,255,1),rgba(255,48,168,0.9),rgba(200,20,120,0.8));
  -webkit-background-clip:text;
  color:transparent;
  text-shadow:
    0 0 18px rgba(255,92,255,0.9),
    0 0 48px rgba(255,48,168,0.6);
  animation:pulseMagenta 3s ease-in-out infinite, flicker 7s infinite reverse;
}

/* hologram neon pulse */
@keyframes pulseCyan{
  0%,100%{ filter:brightness(1); }
  50%{ filter:brightness(1.65); }
}
@keyframes pulseMagenta{
  0%,100%{ filter:brightness(1); }
  50%{ filter:brightness(1.65); }
}

/* flicker */
@keyframes flicker{
  0%,18%,22%,25%,53%,57%,100%{ opacity:1; }
  20%{ opacity:.75; }
  24%{ opacity:.45; }
  55%{ opacity:.88; }
}

/* responsif */
@media(max-width:600px){
  :root{ --gap:10px; }
  .neon-line{ flex-direction:column; }
  .neon-word{ font-size:clamp(28px, 10vw, 48px); }
  .scale-70{ transform:scale(.85); }
}
</style>
