}

/* GLITCH */
.glitch{
  position:relative;
}
.glitch::before,
.glitch::after{
  content: attr(data-text);
  position:absolute;
  top:0; left:0;
  width:100%; height:100%;
  overflow:hidden;
  opacity:0.6;
}
.glitch::before{ animation:glitchMove1 2s infinite linear; }
.glitch::after{ animation:glitchMove2 2.5s infinite linear; }

@keyframes glitchMove1{
  0%{transform:translate(0,0);}
  25%{transform:translate(-2px,2px);}
  50%{transform:translate(2px,-2px);}
