<!-- ===== BUTTON MODE HACKER ===== -->
<button id="hackerToggle">☠ MODE HACKER</button>

<!-- ===== BUTTON EDIT CODE ===== -->
<button id="editCodeBtn">EDIT CODE</button>

<!-- ===== NOTIFICATION ===== -->
<div id="hackerNotif">MODE HACKER DI AKTIFKAN</div>

<!-- ===== BIG EDITOR PANEL ===== -->
<div id="hackerEditorBox">
 <div class="editor-container">

 <!-- LEFT: CODING BOX -->
 <div class="editor-left">
 <div class="editor-left-header">
 <span>HACKER CODE EDITOR</span>
 <button onclick="exitCode()" style="background:none;border:1px solid #00ff9d;color:#00ff9d;padding:3px 10px;border-radius:4px;cursor:pointer;font-family:monospace;">
 Close
 </button>
 </div>

 <textarea id="hackerHTML" placeholder="HTML…"></textarea>
 <textarea id="hackerCSS" placeholder="CSS…"></textarea>
 <textarea id="hackerJS" placeholder="JS…"></textarea>
 </div>

 <!-- RIGHT: PREVIEW -->
 <div class="editor-right">
 <iframe id="hackerPreview"></iframe>
 </div>

 </div>
</div>

<script>
/* ELEMENT */
const toggle = document.getElementById("hackerToggle");
const notif = document.getElementById("hackerNotif");
const editCodeBtn = document.getElementById("editCodeBtn");
const editorBox = document.getElementById("hackerEditorBox");

let hackerMode = false;

/* ===== MODE HACKER (EDIT VISUAL TANPA KODING) ===== */
function enableVisualEdit(){
 document.querySelectorAll("body *").forEach(el=>{
 if(!el.closest("#hackerEditorBox")){
 el.setAttribute("contenteditable","true");
 el.classList.add("hacker-outline");
 }
 });
}

function disableVisualEdit(){
 document.querySelectorAll("body *").forEach(el=>{
 el.removeAttribute("contenteditable");
 el.classList.remove("hacker-outline");
 });
}

/* ===== NOTIFICATION ===== */
function showNotif(){
 notif.style.display = "block";
 setTimeout(()=> notif.style.display = "none", 1500);
}

/* ===== CLICK MODE HACKER ===== */
toggle.onclick = () => {
 hackerMode = !hackerMode;

 if(hackerMode){
 toggle.classList.add("active");
 editCodeBtn.style.display = "block";
 enableVisualEdit();
 showNotif();
 } else {
 toggle.classList.remove("active");
 editCodeBtn.style.display = "none";
 disableVisualEdit();
 editorBox.style.display = "none";
 }
};

/* ===== BUTTON EDIT CODE ===== */
editCodeBtn.onclick = () => {
 editorBox.style.display = "block";

 document.getElementById("hackerHTML").value = document.body.innerHTML;
 document.getElementById("hackerCSS").value = "";
 document.getElementById("hackerJS").value = "";

 updatePreview();
};

/* ===== PREVIEW ===== */
function updatePreview(){
 const html = document.getElementById("hackerHTML").value;
 const css = document.getElementById("hackerCSS").value;
 const js = document.getElementById("hackerJS").value;

 const out = `
 <html><head><style>${css}</style></head>
 <body>${html}<script>${js}<\/script></body>
 </html>
 `;

 document.getElementById("hackerPreview").srcdoc = out;
}

["hackerHTML","hackerCSS","hackerJS"].forEach(id=>{
 document.getElementById(id).addEventListener("input", updatePreview);
});

/* ===== EXIT CODE ===== */
function exitCode(){
 editorBox.style.display = "none";
}
</script>"},"elements":[],"widgetType":"html"}],"isInner":false},{"id":"a8ea335","elType":"container","settings":{"flex_direction":"column"},"elements":[{"id":"07ffa63","elType":"widget","settings":[],"elements":[],"widgetType":"html"}],"isInner":false},{"id":"5473424","elType":"container","settings":{"flex_direction":"column","background_background":"classic","background_color":"#000000"},"elements":[{"id":"238a6ed","elType":"widget","settings":{"html":"<!-- ====== HACKER TERMINAL HEADER 4.0 ====== -->
