 position: absolute;
 top: 50%;
 left: 50%;
 transform: translate(-50%, -50%);
 text-align: center;
 z-index: 10;
}

/* ===== GLITCH TITLE ===== */
.cyber-title {
 font-size: 52px;
 font-family: 'Courier New', monospace;
 color: #00ff95;
 text-shadow:
 0 0 15px #00ff95,
 0 0 25px #00ff95,
 0 0 45px #00ff95;
 position: relative;
 animation: glitchBlink 5s infinite;
}

.cyber-title::before,
.cyber-title::after {
 content: attr(data-text);
 position: absolute;
 left: 0;
 width: 100%;
}

.cyber-title::before {
 left: 3px;
 text-shadow: -3px 0 red;
 clip-path: inset(0 0 55% 0);
 animation: glitchTop 2s infinite;
}

.cyber-title::after {
 left: -3px;
 text-shadow: -3px 0 blue;
 clip-path: inset(55% 0 0 0);
 animation: glitchBottom 2.8s infinite;
}

/* Glitch animations */
@keyframes glitchTop {
 0% { transform: translate(0px); }
 20% { transform: translate(-3px, -1px); }
 40% { transform: translate(3px, 1px); }
 60% { transform: translate(-3px, 2px); }
 80% { transform: translate(2px, -2px); }
 100% { transform: translate(0px); }
}

@keyframes glitchBottom {
 0% { transform: translate(0px); }
 20% { transform: translate(-2px, 1px); }
 40% { transform: translate(2px, -1px); }
 60% { transform: translate(-2px, 2px); }
 80% { transform: translate(2px, 0px); }
 100% { transform: translate(0px); }
}

@keyframes glitchBlink {
 0%, 100% { opacity: 1; }
 50% { opacity: 0.85; }
}

/* ===== TERMINAL TYPING ===== */
.typing-line {
 margin-top: 15px;
 font-family: "Courier New", monospace;
 color: #9affc7;
 font-size: 22px;
}

.cursor {
 animation: blink 0.8s infinite;
}

@keyframes blink {
 0%, 50% { opacity: 1; }
 51%, 100% { opacity: 0; }
}

/* ===== SOCIAL ICONS ===== */
.social-icons {
 margin-top: 30px;
 display: flex;
 justify-content: center;
 gap: 30px;
}

.social {
 color: #00ff95;
 font-size: 28px;
 text-decoration: none;
 transition: all 0.3s ease;
 position: relative;
}

.social:hover {
 filter: drop-shadow(0 0 10px #00ff95)
 drop-shadow(0 0 20px #00ff95)
 drop-shadow(0 0 30px #00ff95);
 transform: scale(1.2);
}

/* Glitch effect on hover */
.social:hover::after {
 content: '';
 position: absolute;
 top: -2px; left: -2px;
 width: 100%; height: 100%;
 border: 1px dashed #00ff95;
 animation: iconGlitch 0.3s infinite;
}

@keyframes iconGlitch {
 0% { transform: translate(0,0); }
 25% { transform: translate(-2px,1px); }
 50% { transform: translate(2px,-1px); }
 75% { transform: translate(-1px,2px); }
 100% { transform: translate(0,0); }
}

/* Custom platform colors */
.social.youtube { color: #FF0000; }
.social.instagram { color: #E1306C; }
.social.tiktok { color: #69C9D0; }
</style>

<script>
/* ===== TEXT TYPING EFFECT ===== */
const typingElement = document.getElementById("typingText");
const typingWords = [
 "klick tombol di bawah ini...",
 "untuk masuk ke GALERY...",
 "kalok tidak devicemu akan di HACK...",
 "HUAHAHAHAHAHHAAAAAAAAAA."
];

let wordIndex = 0;
let charIndex = 0;

function type() {
 const currentWord = typingWords[wordIndex];
 typingElement.textContent = currentWord.slice(0, charIndex);

 charIndex++;

 if (charIndex > currentWord.length) {
 charIndex = 0;
 wordIndex = (wordIndex + 1) % typingWords.length;
 setTimeout(type, 900);
 } else {
 setTimeout(type, 50);
 }
}

type();
</script>
