4.24-AM-2.jpeg","id":2015,"alt":"","source":"library","size":""},"_id":"2e023e2"}],"custom_css":"/* ===== HYPER HACKER MATRIX MODE ===== */
selector .swiper-slide {
 position: relative;
 overflow: visible;
 transform-style: preserve-3d;
}

/* IMAGE – TETAP BERSIH */
selector img {
 border-radius: 18px;
 display: block;
 position: relative;
 z-index: 2;
 filter: contrast(1.15) brightness(1.05);
 transition: all .35s ease;
}

/* FLOAT + DEPTH */
selector .swiper-slide:hover img {
 transform: scale(1.04);
 filter: contrast(1.35) brightness(1.15);
 box-shadow:
 0 0 30px rgba(0,255,120,.9),
 0 0 80px rgba(0,255,120,.35);
}

/* ===== MATRIX RAIN (PINGGIR DOANG) ===== */
selector .swiper-slide::before {
 content: "01001101 01000001 01010100 01010010 01001001 01011000";
 position: absolute;
 inset: -12px;
 border-radius: 24px;
 font-family: monospace;
 font-size: 11px;
 line-height: 1.4;
 color: rgba(0,255,100,.45);
 background:
 linear-gradient(
 to bottom,
 transparent,
 rgba(0,255,100,.15),
 transparent
 );
 mask:
 linear-gradient(#000 0 0) content-box,
 linear-gradient(#000 0 0);
 -webkit-mask:
 linear-gradient(#000 0 0) content-box,
 linear-gradient(#000 0 0);
 padding: 18px;
 box-sizing: border-box;
 animation: matrix-flow 3s linear infinite;
 pointer-events: none;
 z-index: 0;
}

@keyframes matrix-flow {
 from { background-position: 0 -100%; }
 to { background-position: 0 100%; }
}

/* ===== DATA SCAN LINE ===== */
selector .swiper-slide::after {
 content: "";
 position: absolute;
 inset: -8px;
 border-radius: 22px;
 background:
 linear-gradient(
 90deg,
 transparent 30%,
 rgba(0,255,140,.9),
 transparent 70%
 );
 filter: blur(8px);
 opacity: .6;
 animation: scan-move 2.2s linear infinite;
 pointer-events: none;
}

@keyframes scan-move {
 from { transform: translateX(-60%); }
 to { transform: translateX(60%); }
}

/* ===== GLITCH MICRO SHAKE ===== */
selector .swiper-slide:hover {
 animation: cyber-glitch .18s infinite;
}

@keyframes cyber-glitch {
 0% { transform: translate(0,0); }
 25% { transform: translate(1px,-1px); }
 50% { transform: translate(-1px,1px); }
 75% { transform: translate(1px,1px); }
 100% { transform: translate(0,0); }
}

/* ===== HUD CORNER ===== */
selector .swiper-slide {
 outline:
 2px solid rgba(0,255,120,.6);
 outline-offset: 6px;
}

/* ===== NAV BUTTON HACKER NODE ===== */
selector .swiper-button-next,
selector .swiper-button-prev {
 width: 48px;
 height: 48px;
 border-radius: 50%;
 background: transparent;
 border: 1px solid #00ff78;
 box-shadow:
 0 0 18px rgba(0,255,120,.8),
 inset 0 0 14px rgba(0,255,120,.4);
}

selector .swiper-button-next::after,
selector .swiper-button-prev::after {
 color: #00ff78;
 font-size: 18px;
}

/* DOT MATRIX */
selector .swiper-pagination-bullet {
 background: rgba(0,255,120,.35);
}
selector .swiper-pagination-bullet-active {
 background: #00ff78;
 box-shadow: 0 0 12px #00ff78;
}
