<div class="hacker-header">
 <canvas id="matrixRain"></canvas>

 <div class="hacker-content">
 <h1 class="glitch-title" data-text="HACKER ZONE">HACKER ZONE</h1>
 <p class="subtitle">Access data ▓▒░ by slamet karisna</p>
 </div>
</div>

<style>
/* --- RESET --- */
.hacker-header {
 position: relative;
 width: 100%;
 height: 380px;
 overflow: hidden;
 background: #000;
 border-bottom: 2px solid #18ff62;
}

#matrixRain {
 position: absolute;
 width: 100%;
 height: 100%;
 display: block;
}

/* --- TEXT AREA --- */
.hacker-content {
 position: absolute;
 top: 50%;
 left: 50%;
 transform: translate(-50%, -50%);
 text-align: center;
 z-index: 10;
}

.glitch-title {
 font-family: 'Courier New', monospace;
 font-size: 60px;
 font-weight: 700;
 color: #18ff62;
 position: relative;
 text-shadow:
 0 0 10px #18ff62,
 0 0 20px #18ff62,
 0 0 40px #18ff62;
 animation: glitch 3s infinite;
}

.subtitle {
 font-family: 'Courier New', monospace;
 font-size: 20px;
 color: #9cffbe;
 margin-top: 10px;
 opacity: 0;
 animation: fadeIn 2s forwards 1s;
}

/* --- GLITCH EFFECT --- */
.glitch-title::before,
.glitch-title::after {
 content: attr(data-text);
 position: absolute;
 top: 0;
 left: 0;
 width: 100%;
 overflow: hidden;
 color: #18ff62;
}

.glitch-title::before {
 left: 2px;
 text-shadow: -2px 0 red;
 animation: glitchTop 2s infinite;
}

.glitch-title::after {
 left: -2px;
 text-shadow: -2px 0 blue;
 animation: glitchBottom 2.5s infinite;
}

@keyframes glitch {
 0% { transform: skew(0deg); }
 20% { transform: skew(2deg); }
 40% { transform: skew(-2deg); }
 60% { transform: skew(3deg); }
 80% { transform: skew(-3deg); }
 100% { transform: skew(0deg); }
}

@keyframes glitchTop {
 0% { clip-path: inset(0 0 80% 0); }
 20% { clip-path: inset(0 0 50% 0); }
 40% { clip-path: inset(0 0 60% 0); }
 60% { clip-path: inset(0 0 40% 0); }
 80% { clip-path: inset(0 0 70% 0); }
 100% { clip-path: inset(0 0 80% 0); }
}

@keyframes glitchBottom {
 0% { clip-path: inset(80% 0 0 0); }
 20% { clip-path: inset(50% 0 0 0); }
 40% { clip-path: inset(60% 0 0 0); }
 60% { clip-path: inset(40% 0 0 0); }
 80% { clip-path: inset(70% 0 0 0); }
 100% { clip-path: inset(80% 0 0 0); }
}

/* Fade subtitle */
@keyframes fadeIn {
 100% { opacity: 1; }
}
</style>

<script>
/* ===== MATRIX RAIN ===== */
const canvas = document.getElementById('matrixRain');
const ctx = canvas.getContext('2d');

canvas.height = canvas.offsetHeight;
canvas.width = canvas.offsetWidth;

const letters = "01<>|/*+-[]{}=#$%&@ABCDEFGHIJKLMN";
const matrix = letters.split("");

let fontSize = 16;
let columns = canvas.width / fontSize;
let drops = [];

for (let i = 0; i < columns; i++) {
 drops[i] = 1;
}

function draw() {
 ctx.fillStyle = "rgba(0, 0, 0, 0.06)";
 ctx.fillRect(0, 0, canvas.width, canvas.height);

 ctx.fillStyle = "#18ff62";
 ctx.font = fontSize + "px monospace";

 for (let i = 0; i < drops.length; i++) {
 let text = matrix[Math.floor(Math.random() * matrix.length)];
 ctx.fillText(text, i * fontSize, drops[i] * fontSize);

 if (drops[i] * fontSize > canvas.height && Math.random() > 0.95) {
 drops[i] = 0;
 }
 drops[i]++;
 }
}

setInterval(draw, 40);

/* Resize Fix */
window.addEventListener('resize', () => {
 canvas.height = canvas.offsetHeight;
 canvas.width = canvas.offsetWidth;
});
</script>
