<div class="coding-bg">
 <canvas id="codingCanvas" aria-hidden="true"></canvas>

 <!-- Optional: isi konten depan (Elementor biasa akan menimpa ini).
 Kalau hanya ingin background, kamu bisa kosongkan bagian ini. -->
 <div class="coding-foreground">
 <div class="typed-code" id="typedCode"></div>
 </div>
</div>

<style>
 /* Basic reset for the widget area */
 .coding-bg {
 position: relative;
 width: 100%;
 overflow: hidden;
 min-height: 420px; /* change as needed or let Elementor control height */
 background: radial-gradient(ellipse at top, rgba(10,12,20,0.8) 0%, rgba(6,8,12,0.85) 60%);
 }

 /* Canvas covers the entire area */
 .coding-bg canvas#codingCanvas {
 position: absolute;
 inset: 0; /* top:0; right:0; bottom:0; left:0 */
 width: 100% !important;
 height: 100% !important;
 display: block;
 z-index: 1;
 pointer-events: none; /* so it doesn't block clicks */
 }

 /* Foreground container for typed lines or other content */
 .coding-bg .coding-foreground {
 position: relative;
 z-index: 3; /* above canvas */
 display: flex;
 align-items: center;
 justify-content: center;
 height: 100%;
 padding: 40px;
 box-sizing: border-box;
 color: #cbd5e1;
 font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, "Roboto Mono", monospace;
 text-align: center;
 pointer-events: auto;
 }

 /* The typed code block style */
 .typed-code {
 max-width: 1100px;
 width: 100%;
 font-size: clamp(12px, 1.6vw, 18px);
 line-height: 1.45;
 letter-spacing: 0.2px;
 background: rgba(2,6,12,0.25);
 padding: 18px 22px;
 border-radius: 10px;
 box-shadow: 0 6px 30px rgba(0,0,0,0.6), inset 0 1px 0 rgba(255,255,255,0.02);
 border: 1px solid rgba(255,255,255,0.03);
 backdrop-filter: blur(4px);
 color: #e6f0ff;
 }

 /* small cursor effect */
 .typed-code .cursor {
 display: inline-block;
 width: 8px;
 height: 1.1em;
 background: linear-gradient(90deg, rgba(255,255,255,0.9), rgba(255,255,255,0.6));
 margin-left: 6px;
 animation: blink 1s steps(2, start) infinite;
 vertical-align: middle;
 border-radius: 2px;
 }

 @keyframes blink {
 0%, 50% { opacity: 1; }
 51%, 100% { opacity: 0; }
 }

 /* subtle gradient lines moving (optional visual) */
 .coding-bg::before{
 content: "";
 position: absolute;
 inset: 0;
 z-index: 2;
 background-image: linear-gradient(90deg, rgba(255,255,255,0.02) 0%, rgba(255,255,255,0.00) 50%, rgba(255,255,255,0.02) 100%);
 pointer-events: none;
 mix-blend-mode: overlay;
 animation: slide 12s linear infinite;
 opacity: 0.35;
 }

 @keyframes slide {
 from { transform: translateX(-20%); }
 to { transform: translateX(20%); }
 }

 /* Responsiveness: reduce density on small screens */
 @media (max-width:720px){
 .typed-code { padding: 14px; font-size: 13px; }
 .coding-bg { min-height: 360px; }
 }
</style>

<script>
(function() {
 // ========== Configuration (ubah sesuai selera) ==========
 const config = {
 charSet: "abcdefghijklmnopqrstuvwxyz0123456789<>[]{}()@#%&*-=+/:;.", // karakter jatuh
 fontSize: 16, // dasar font size untuk canvas matrix
 columnSpacing: 18, // jarak antar kolom matrix
 speedBase: 1.2, // kecepatan dasar
 greenHue: [120, 200], // tidak dipakai, kept for possible future color tweaks
 typingLines: [
 "function fetchData() {",
 " // request to API -> /v1/code",
 " return await api.get('/v1/data');",
 "}",
 "",
 "const user = { id: 43, role: 'admin' };",
 "render(user);"
 ],
 typingDelayBetweenLines: 900, // ms sebelum mulai garis berikut
 typingCharDelay: 34, // ms per karakter
 fadeOutTypingAfter: 2800 // ms menampilkan baris setelah selesai ketik sebelum hilang
 };
 // ======================================================

 // Setup canvas
 const canvas = document.getElementById('codingCanvas');
 const ctx = canvas.getContext('2d');
 let w = 0, h = 0, columns = [], DPR = Math.max(1, window.devicePixelRatio || 1);

 function resize() {
 w = canvas.width = Math.floor(canvas.clientWidth * DPR);
 h = canvas.height = Math.floor(canvas.clientHeight * DPR);
 ctx.scale(DPR, DPR);
 initColumns();
 }

 function initColumns() {
 const colWidth = config.columnSpacing;
 const cols = Math.floor((canvas.clientWidth) / colWidth) + 2;
 columns = [];
 for (let i = 0; i < cols; i++) {
 const x = i * colWidth;
 columns.push({
 x: x,
 y: Math.random() * (-1000),
 speed: (Math.random() * 1.6 + config.speedBase) * (0.6 + Math.random()*1.4),
 length: Math.floor(6 + Math.random() * 25),
 });
 }
 }

 // draw one frame
 function draw() {
 // translucent fill to create trail effect
 ctx.fillStyle = 'rgba(4,8,15,0.20)';
 ctx.fillRect(0, 0, canvas.clientWidth, canvas.clientHeight);

 ctx.font = `${config.fontSize}px "Roboto Mono", monospace`;
 ctx.textBaseline = 'top';

 columns.forEach(col => {
 const charsToDraw = col.length;
 let y = col.y;
 for (let i = 0; i < charsToDraw; i++) {
 const char = config.charSet.charAt(Math.floor(Math.random() * config.charSet.length));
 // brighter for the head
 if (i === 0) {
 ctx.fillStyle = 'rgba(180, 255, 200, 0.95)'; // head
 ctx.fillText(char, col.x + 2, y);
 } else if (i < 3) {
 ctx.fillStyle = 'rgba(130, 220, 160, 0.65)'; // near head
 ctx.fillText(char, col.x + 2, y);
 } else {
 ctx.fillStyle = `rgba(60, 140, 100, ${0.04 + (i / charsToDraw) * 0.5})`; // tail
 ctx.fillText(char, col.x + 2, y);
 }
 y -= config.fontSize;
 }

 col.y += col.speed * (config.fontSize / 12) ;
 if (col.y > canvas.clientHeight + (col.length * config.fontSize)) {
 // reset
 col.y = -Math.random() * 200;
 col.speed = (Math.random() * 1.6 + config.speedBase) * (0.6 + Math.random()*1.4);
 col.length = Math.floor(6 + Math.random() * 26);
 }
 });

 requestAnimationFrame(draw);
 }

 // Initialize and start
 function start() {
 resize();
 requestAnimationFrame(draw);
 }

 // Handle resizing nicely
 let resizeTimeout;
 window.addEventListener('resize', function(){
 clearTimeout(resizeTimeout);
 resizeTimeout = setTimeout(function(){
 // clear transform before resize
 ctx.setTransform(1,0,0,1,0,0);
 start();
 }, 120);
 });

 // Start after DOM ready
 if (document.readyState === 'complete' || document.readyState === 'interactive') {
 start();
 } else {
 window.addEventListener('DOMContentLoaded', start);
 }

 // -------------------------
 // Typing effect (foreground)
 // -------------------------
 const typedEl = document.getElementById('typedCode');
 function sleep(ms){ return new Promise(res=>setTimeout(res, ms)); }

 async function runTyping() {
 if (!typedEl) return;
 while (true) {
 typedEl.innerHTML = '';
 for (let i = 0; i < config.typingLines.length; i++) {
 const line = config.typingLines[i];
 const lineNode = document.createElement('div');
 lineNode.className = 'line';
 typedEl.appendChild(lineNode);

 for (let c = 0; c < line.length; c++){
 lineNode.textContent += line[c];
 await sleep(config.typingCharDelay + Math.random()*18);
 }

 // add cursor for current line
 const cursor = document.createElement('span');
 cursor.className = 'cursor';
 lineNode.appendChild(cursor);

 await sleep(config.fadeOutTypingAfter);
 // remove cursor
 cursor.remove();

 await sleep(config.typingDelayBetweenLines * (0.35 + Math.random()*0.8));
 }

 // linger with full block, then fade out
 typedEl.style.transition = 'opacity 750ms ease';
 typedEl.style.opacity = '1';
 await sleep(1200 + Math.random()*1000);
 typedEl.style.opacity = '0';
 await sleep(900);

 // clear lines, show again
 typedEl.innerHTML = '';
 typedEl.style.opacity = '1';
 }
 }

 // small helper to inject cursor CSS inside typed element (scoped)
 (function injectCursorStyles(){
 const s = document.createElement('style');
 s.textContent = `
 #typedCode .line { text-align: left; white-space: pre-wrap; word-break: break-word; }
 #typedCode .line .cursor { display:inline-block; width:8px; height:1em; background:linear-gradient(90deg,#fff,#bfe0ff); margin-left:4px; border-radius:2px; animation: blink 1s steps(2,start) infinite; vertical-align:middle; }
 @keyframes blink { 0%,50%{opacity:1} 51%,100%{opacity:0} }
 `;
 document.head.appendChild(s);
 })();

 // start typing after a small delay so canvas loads
 setTimeout(runTyping, 800);

})();
</script>
