<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Spider Web Particle Animation</title>
    <style>
        body {
            margin: 0;
            padding: 0;
            background-color: #111; /* Background tetap gelap */
            overflow: hidden;
        }

        #particle-container {
            position: absolute;
            width: 100%;
            height: 100vh;
            z-index: 1;
        }
    </style>
</head>
<body>

<div id="particle-container"></div>

<script src="https://cdn.jsdelivr.net/npm/particles.js"></script>

<script>
    // Initialize particles.js with yellow color for all elements
    particlesJS('particle-container', {
        particles: {
            number: {
                value: 150, // Jumlah partikel
                density: {
                    enable: true,
                    value_area: 800
                }
            },
            color: {
                value: "#ffff00" // Semua partikel dan garis penghubung jadi kuning
            },
            shape: {
                type: 'circle', // Bentuk partikel
                stroke: {
                    width: 0,
                    color: '#ffff00' // Warna stroke kuning
                },
            },
            opacity: {
                value: 0.7,
                random: true,
                anim: {
                    enable: true,
                    speed: 0.5,
                    opacity_min: 0,
                    sync: false
                }
            },
            size: {
                value: 5,
                random: true,
                anim: {
                    enable: true,
                    speed: 1,
                    size_min: 0.3,
                    sync: false
                }
            },
            line_linked: {
                enable: true,
                distance: 150, // Jarak antar partikel yang saling terhubung
                color: '#ffff00', // Garis penghubung antar partikel jadi kuning
                opacity: 0.7,
                width: 1
            },
            move: {
                enable: true,
                speed: 1.5,
                direction: 'none',
                random: true,
                straight: false,
                out_mode: 'out',
                bounce: false,
                attract: {
                    enable: true, // Tarik partikel ke tengah untuk jaring
                    rotateX: 600,
                    rotateY: 1200
                }
            }
        },
        interactivity: {
            detect_on: 'canvas',
            events: {
                onhover: {
                    enable: true,
                    mode: 'repulse'
                },
                onclick: {
                    enable: true,
                    mode: 'push'
                }
            }
        },
        retina_detect: true
    });
</script>

</body>
