<html lang="id">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>PMII & KOPRI Futuristik</title>

<!-- Google Fonts -->
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">

<!-- Font Awesome -->
<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css" />

<style>
/* === GLOBAL STYLES === */
body {
  margin: 0;
  padding: 0;
  font-family: 'Inter', sans-serif;
  background-color: #050712;
  /* Futuristic Grid & Glow Background */
  background-image: 
    radial-gradient(circle at 15% 50%, rgba(0, 208, 255, 0.05) 0%, transparent 50%),
    radial-gradient(circle at 85% 30%, rgba(122, 60, 255, 0.05) 0%, transparent 50%),
    linear-gradient(rgba(255, 255, 255, 0.02) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.02) 1px, transparent 1px);
  background-size: 100% 100%, 100% 100%, 40px 40px, 40px 40px;
  color: #dbefff;
  scroll-behavior: smooth;
  overflow-x: hidden;
}

/* === TOP MENU === */
.pmii-top-menu {
  width: 90%;
  max-width: 1200px;
  margin: 20px auto;
  padding: 16px 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: rgba(0, 15, 30, 0.65);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-radius: 16px;
  border: 1px solid rgba(120, 200, 255, 0.15);
  box-shadow: 0 8px 32px rgba(0, 150, 255, 0.1);
  transition: .4s ease;
  position: relative;
  z-index: 998;
  box-sizing: border-box;
}
.pmii-top-menu:hover {
  box-shadow: 0 8px 32px rgba(0, 200, 255, 0.25);
  border-color: rgba(120, 200, 255, 0.3);
}

.menu-title {
  font-size: 18px;
  font-weight: 700;
  color: #dffaff;
  letter-spacing: 0.5px;
  transition: .3s ease;
}
.menu-title:hover {
  color: #aef4ff;
  text-shadow: 0 0 15px rgba(0, 200, 255, 0.8);
}

.menu-download {
  padding: 10px 20px;
  background: linear-gradient(135deg, #00d0ff, #7a3cff);
  color: #031226;
  border-radius: 12px;
  font-weight: 700;
  font-size: 14px;
  text-decoration: none;
  display: flex;
  align-items: center;
  gap: 8px;
  transition: .3s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}
.menu-download:hover {
  transform: translateY(-3px) scale(1.05);
  box-shadow: 0 10px 25px rgba(0, 200, 255, 0.4);
}

/* === SCROLLABLE MENU VERTICAL === */
.pmii-scroll-menu {
  position: fixed;      
  top: 50%;            
  transform: translateY(-50%);
  right: 20px;         
  width: 140px;        
  max-height: 60vh;     
  overflow-y: auto;     
  padding: 12px;       
  display: flex;
  flex-direction: column; 
  align-items: center;
  background: rgba(5, 12, 25, 0.85);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-radius: 16px;   
  border: 1px solid rgba(120, 200, 255, 0.15);
  box-shadow: 0 10px 30px rgba(0, 150, 255, 0.2);
  z-index: 999;
  box-sizing: border-box;
}

.pmii-scroll-menu::-webkit-scrollbar { width: 4px; }
.pmii-scroll-menu::-webkit-scrollbar-track { background: rgba(255,255,255,0.02); }
.pmii-scroll-menu::-webkit-scrollbar-thumb { background: rgba(0,200,255,0.4); border-radius: 10px; }

.scroll-items {
  display: flex;
  flex-direction: column;
  gap: 12px;
  width: 100%;
}

.scroll-items a {
  padding: 10px;       
  border-radius: 10px;     
  text-decoration: none;
  font-weight: 600;
  font-size: 13px;       
  color: #aef4ff;
  transition: .3s;
  background: rgba(0, 200, 255, 0.05);
  border: 1px solid rgba(0, 200, 255, 0.1);
  text-align: center;
  width: 100%;
  box-sizing: border-box;
}
.scroll-items a:hover {
  background: linear-gradient(135deg, #00d0ff, #7a3cff);
  color: #031226;
  border-color: transparent;
  box-shadow: 0 0 20px rgba(0, 200, 255, 0.5);
  transform: translateY(-2px);
}

/* === MAIN CARDS STRUCTURE === */
.pmii-card-wrap { 
  padding: 20px; 
  display: flex; 
  justify-content: center; 
  align-items: center;
  min-height: 80vh;
}

.pmii-card, .kopri-section { 
  width: 100%; 
  max-width: 1080px; 
  background: linear-gradient(145deg, rgba(15, 20, 35, 0.7), rgba(5, 7, 12, 0.9)); 
  backdrop-filter: blur(20px);
  border-radius: 24px;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.5), inset 0 0 0 1px rgba(120, 200, 255, 0.1); 
  display: flex; 
  overflow: hidden; 
  position: relative;
}

.kopri-section {
  margin: 0 auto 60px auto;
  padding: 0;
}

/* === LEFT SIDE / LOGO AREA === */
.pmii-left, .kopri-image-wrapper { 
  flex: 0 0 400px; 
  padding: 40px; 
  display: flex; 
  flex-direction: column; 
  align-items: center; 
  justify-content: center;
  background: linear-gradient(135deg, rgba(0, 50, 100, 0.1), rgba(0, 0, 0, 0.4)); 
  border-right: 1px solid rgba(255,255,255,0.05);
}

.logo-frame { 
  position: relative; 
  width: 280px; 
  height: 280px; 
  border-radius: 50%;
  display: flex; 
  align-items: center; 
  justify-content: center;
  background: rgba(255, 255, 255, 0.02); 
  border: 1px solid rgba(120, 200, 255, 0.15); 
  overflow: hidden;
  transition: .4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}
.logo-frame:hover { 
  box-shadow: 0 0 30px rgba(0, 200, 255, 0.4), inset 0 0 20px rgba(0, 200, 255, 0.2);
  border-color: rgba(0, 200, 255, 0.5);
}

.pmii-logo { 
  width: 75%; 
  height: auto; 
  filter: drop-shadow(0 10px 15px rgba(0, 0, 0, 0.5)); 
  transition: .5s ease; 
  z-index: 2;
}
.logo-frame:hover .pmii-logo { 
  transform: scale(1.1); 
  filter: drop-shadow(0 0 25px rgba(0, 200, 255, 0.8));
}

.badge { 
  font-weight: 700; 
  padding: 8px 16px; 
  border-radius: 20px;
  background: rgba(0, 200, 255, 0.1); 
  color: #00d0ff; 
  border: 1px solid rgba(0, 200, 255, 0.2);
  margin-top: 24px;
  letter-spacing: 2px;
  text-transform: uppercase;
  font-size: 14px;
}

/* === RIGHT SIDE / CONTENT AREA === */
.pmii-right, .kopri-text { 
  flex: 1; 
  padding: 40px; 
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.title, .kopri-title { 
  margin: 0; 
  font-size: 32px; 
  position: relative; 
  font-weight: 700;
  color: #ffffff;
  display: inline-block;
  padding-bottom: 12px;
}
.title::after, .kopri-title::after { 
  content: ''; 
  position: absolute; 
  left: 0; 
  bottom: 0; 
  width: 60px; 
  height: 4px;
  background: linear-gradient(90deg, #00d0ff, #7a3cff); 
  border-radius: 4px; 
  transition: width .3s ease;
}
.title:hover::after, .kopri-title:hover::after {
  width: 100px;
}

.subtitle, .kopri-desc { 
  margin: 16px 0 24px 0; 
  color: #a0b8d0; 
  font-size: 15px; 
  line-height: 1.6;
}

/* Meanings Grid */
.meanings { 
  display: grid; 
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); 
  gap: 16px; 
}

.meaning { 
  background: rgba(255, 255, 255, 0.03); 
  padding: 20px; 
  border-radius: 16px; 
  border: 1px solid rgba(255, 255, 255, 0.05);
  transition: .3s ease; 
}
.meaning:hover { 
  transform: translateY(-5px); 
  background: rgba(0, 200, 255, 0.05);
  border-color: rgba(0, 200, 255, 0.3);
  box-shadow: 0 10px 30px rgba(0, 150, 255, 0.15);
}

.m-title { margin: 0 0 8px 0; font-size: 16px; color: #00d0ff; font-weight: 600;}
.m-text { margin: 0; font-size: 14px; color: #a0b8d0; line-height: 1.5; }

/* Kopri Specific List */
.kopri-meanings { list-style: none; padding: 0; margin: 0 0 24px 0; }
.kopri-meanings li {
  margin-bottom: 12px;
  font-size: 14px;
  line-height: 1.6;
  color: #a0b8d0;
  background: rgba(0, 0, 0, 0.2);
  padding: 16px;
  border-radius: 12px;
  border-left: 3px solid #7a3cff;
  transition: .3s;
}
.kopri-meanings li strong { color: #ffffff; }
.kopri-meanings li:hover {
  background: rgba(122, 60, 255, 0.1);
  border-left-color: #00d0ff;
  transform: translateX(5px);
}

/* Buttons */
.actions { display: flex; gap: 12px; margin-top: 24px; flex-wrap: wrap; }

.btn { 
  padding: 12px 24px; 
  border-radius: 12px; 
  font-weight: 600; 
  font-size: 14px;
  background: linear-gradient(135deg, #00d0ff, #7a3cff); 
  color: #031226; 
  text-decoration: none;
  transition: .3s cubic-bezier(0.175, 0.885, 0.32, 1.275); 
  text-align: center;
}
.btn:hover { 
  transform: translateY(-3px) scale(1.02);
  box-shadow: 0 10px 25px rgba(0, 200, 255, 0.4);
}

.btn.ghost {
  background: transparent; 
  color: #00d0ff; 
  border: 1px solid rgba(0, 200, 255, 0.3);
}
.btn.ghost:hover {
  background: rgba(0, 200, 255, 0.1);
  box-shadow: 0 0 20px rgba(0, 200, 255, 0.2);
  border-color: #00d0ff;
}

/* === ANIMATIONS & EFFECTS === */
.blue-glow, .blue-glow2 {
  position: absolute; 
  border-radius: 50%;
  top: 50%; left: 50%; 
  transform: translate(-50%, -50%);
  z-index: 1; pointer-events: none;
}
.blue-glow { width: 100%; height: 100%; background: radial-gradient(circle, rgba(0,200,255,0.2) 0%, transparent 70%); filter: blur(20px); }
.blue-glow2 { width: 150%; height: 150%; background: radial-gradient(circle, rgba(122,60,255,0.1) 0%, transparent 60%); filter: blur(40px); }

.scanline { 
  position: absolute; inset: 0; z-index: 3;
  background: linear-gradient(180deg, rgba(255,255,255,0.03) 0%, transparent 10%);
  background-size: 100% 8px; animation: scan 6s linear infinite; opacity: 0.5; pointer-events: none;
}
@keyframes scan { 0% { background-position: 0 0 } 100% { background-position: 0 100px } }


/* === RESPONSIVE DESIGN (MOBILE) === */
@media (max-width: 992px) {
  .pmii-top-menu { flex-direction: column; gap: 16px; text-align: center; }
  .pmii-scroll-menu { 
    position: static; 
    transform: none; 
    width: 90%; 
    max-width: 1200px; 
    margin: 0 auto 20px auto; 
    flex-direction: row; 
    overflow-x: auto; 
    max-height: auto;
  }
  .scroll-items { flex-direction: row; justify-content: center; }
  .scroll-items a { white-space: nowrap; width: auto; padding: 10px 20px; }

  .pmii-card, .kopri-section { flex-direction: column; width: 90%; }
  .pmii-left, .kopri-image-wrapper { flex: none; width: 100%; border-right: none; border-bottom: 1px solid rgba(255,255,255,0.05); padding: 40px 20px; box-sizing: border-box; }
  .pmii-right, .kopri-text { padding: 30px 20px; }
  .logo-frame { width: 220px; height: 220px; }
}

@media (max-width: 480px) {
  .title, .kopri-title { font-size: 26px; }
  .actions { flex-direction: column; }
  .btn { width: 100%; box-sizing: border-box; }
}
</style>
</head>
<body>

