[{"id":"c9a9d02","elType":"container","settings":[],"elements":[{"id":"bcf87f7","elType":"widget","settings":{"html":"<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Contact | Futuristic</title>

<!-- GOOGLE FONT -->
<link href="https://fonts.googleapis.com/css2?family=Orbitron:wght@400;600;800&family=Poppins:wght@300;400;600&display=swap" rel="stylesheet">

<!-- ICON -->
<link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css" rel="stylesheet">

<style>
*{
  box-sizing:border-box;
  margin:0;
  padding:0;
}

body{
  background:#000;
  color:#fff;
  font-family:'Poppins',sans-serif;
  overflow-x:hidden;
}

/* ===== BACKGROUND CYBER ===== */
.cyber-bg{
  position:fixed;
  inset:0;
  background:
    linear-gradient(transparent 96%, rgba(0,255,255,0.08) 97%),
    linear-gradient(90deg, transparent 96%, rgba(0,255,255,0.08) 97%),
    radial-gradient(circle at top, #0a1a2f, #000 75%);
  background-size:50px 50px,50px 50px,cover;
  animation:gridMove 25s linear infinite;
  z-index:-3;
}

@keyframes gridMove{
  from{background-position:0 0}
  to{background-position:500px 500px}
}

/* ===== SCANLINE ===== */
.scanline{
  position:fixed;
  top:-100%;
  left:0;
  width:100%;
  height:200%;
  background:linear-gradient(to bottom,
    transparent 0%,
    rgba(0,255,255,0.06) 50%,
    transparent 100%);
  animation:scan 7s linear infinite;
  z-index:-2;
}

@keyframes scan{
  from{transform:translateY(-50%)}
  to{transform:translateY(50%)}
}

/* ===== LAYOUT ===== */
.wrapper{
