<html lang="en">
<head>
<meta charset="UTF-8">
<title>PMII Logo Bar</title>

<style>
* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: "Segoe UI", Tahoma, Geneva, Verdana, sans-serif;
  background: #eef3f9;
}

/* ===============================
   FULL WIDTH BACKGROUND PMII
   =============================== */
.pmii-bg {
  width: 100%;
  padding: 26px 0; /* ⬅️ tinggi DIKONTROL di sini */
  background: linear-gradient(
    135deg,
    #003f8f,
    #005ecb,
    #0a74da
  );
  position: relative;
  overflow: hidden;
}

/* soft glow */
.pmii-bg::after {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(
    circle at center,
    rgba(255,255,255,0.18),
    transparent 65%
  );
}

/* ===============================
   INNER CONTAINER (CENTERED)
   =============================== */
.image-bar-wrapper {
  max-width: 1100px;
  margin: 0 auto;
  padding: 20px 40px;
  border-radius: 22px;
  background: rgba(255,255,255,0.06);
  backdrop-filter: blur(6px);
  box-shadow: 0 12px 30px rgba(0,0,0,0.25);
  position: relative;
  z-index: 2;
}

/* ===============================
   LOGO BAR
   =============================== */
.image-bar {
  display: flex;
  justify-content: center;
  gap: 70px;
}

.item {
  width: 180px; /* ⬅️ biar ramping */
  text-align: center;
}

.link-wrap {
  display: block;
  text-decoration: none;
}

/* ===============================
   LOGO BOX
   =============================== */
.glitch-box {
  border-radius: 16px;
  overflow: hidden;
  background: #fff;
  box-shadow: 0 10px 22px rgba(0,0,0,0.25);
  transition: transform 0.35s ease;
  cursor: pointer;
}

.glitch-box img {
  width: 100%;
  display: block;
}

/* hover clean (nggak lebay) */
.item:hover .glitch-box {
  transform: translateY(-8px) scale(1.05);
}

/* ===============================
   INDICATOR
   =============================== */
.indicator {
  margin: 10px auto 0;
  width: 52px;
  height: 5px;
  border-radius: 3px;
  background: rgba(255,255,255,0.55);
  transition: 0.3s ease;
}

.item:hover .indicator {
  background: #00a2ff;
  box-shadow: 0 0 8px #00a2ff;
}

/* ===============================
   CLICK ANIMATION
   =============================== */
.flip {
  transform: rotateY(180deg);
}

.fullscreen-pop {
  position: fixed;
  inset: 0;
  margin: auto;
  width: 75vw !important;
  z-index: 9999;
  transform: scale(1.35);
}
</style>
</head>

<body>

<div class="pmii-bg">
  <div class="image-bar-wrapper">
    <div class="image-bar">

      <!-- LEFT -->
      <div class="item">
        <a href="https://www.pmii.id/" class="link-wrap">
          <div class="glitch-box">
            <img src="https://i.ibb.co.com/8n4rJL3D/logoiguy.png">
          </div>
        </a>
        <div class="indicator"></div>
      </div>

      <!-- CENTER -->
      <div class="item">
        <a href="https://pmiikomiskenda.42web.io/halaman-2/" class="link-wrap">
          <div class="glitch-box">
            <img src="https://i.ibb.co.com/0yBKwGP4/bgh.jpg">
          </div>
        </a>
        <div class="indicator"></div>
      </div>

      <!-- RIGHT -->
      <div class="item">
        <a href="https://www.pmii.id/" class="link-wrap">
          <div class="glitch-box">
            <img src="https://i.ibb.co.com/Z6Lnj57j/kopri.png">
          </div>
        </a>
        <div class="indicator"></div>
      </div>

    </div>
  </div>
</div>

<script>
document.querySelectorAll(".glitch-box").forEach(box => {
  box.addEventListener("click", () => {
    box.classList.add("flip");
    setTimeout(() => {
      box.classList.add("fullscreen-pop");
    }, 300);
  });
});
</script>














