    0 0 0 1px rgba(147,197,253,.6),
    0 25px 70px rgba(79,70,229,.8);
  overflow:hidden;
  animation:barGlow 2.8s ease-in-out infinite;
}

.chat-ai-bar::before{
  content:"";
  position:absolute;
  inset:0;
  background:linear-gradient(
    120deg,
    transparent 35%,
    rgba(255,255,255,.35),
    transparent 70%
  );
  animation:holoScan 2.4s linear infinite;
}

.chat-ai-bar::after{
  content:"";
  position:absolute;
  inset:-2px;
  border-radius:999px;
  background:linear-gradient(90deg,#38bdf8,#facc15,#38bdf8);
  filter:blur(12px);
  opacity:.6;
  z-index:-1;
}

/* === AI CORE === */
.chat-ai-logo{
  position:relative;
  width:82px;
  height:82px;
  border-radius:50%;
  display:flex;
  align-items:center;
  justify-content:center;
  background:radial-gradient(circle at top,#020617,#020617 55%,#020617);
  overflow:hidden;
  animation:corePulse 3.5s ease-in-out infinite;
}

/* energy ring */
.chat-ai-logo::before{
  content:"";
  position:absolute;
  inset:-10px;
  background:conic-gradient(
    #2563eb,
    #38bdf8,
    #facc15,
    #2563eb
  );
  filter:blur(14px);
  animation:spin 4s linear infinite;
  opacity:.95;
}

/* glass core */
.chat-ai-logo::after{
  content:"";
  position:absolute;
  inset:10px;
  border-radius:50%;
  background:
    radial-gradient(circle at top,
      rgba(255,255,255,.35),
      rgba(255,255,255,.05) 60%);
  backdrop-filter:blur(8px);
  z-index:2;
}

/* AI TEXT */
.chat-ai-logo span{
  position:relative;
  z-index:3;
  font-size:26px;
  font-weight:900;
  letter-spacing:1px;
  background:linear-gradient(90deg,#7dd3fc,#fde68a);
  -webkit-background-clip:text;
  -webkit-text-fill-color:transparent;
  text-shadow:
    0 0 20px rgba(250,204,21,.9),
    0 0 40px rgba(56,189,248,.7);
}

/* === ORBIT PARTICLES === */
.orbit{
  position:absolute;
  inset:-18px;
  border-radius:50%;
  border:1px dashed rgba(147,197,253,.25);
  animation:spin 6s linear infinite reverse;
}

/* === HOVER POWER === */
.chat-ai-float:hover .chat-ai-logo{
  transform:scale(1.18) rotate(8deg);
}

.chat-ai-float:hover .chat-ai-bar{
  filter:brightness(1.2);
}

/* === ANIMATIONS === */
@keyframes spin{to{transform:rotate(360deg)}}

@keyframes holoScan{
  from{transform:translateX(-100%)}
  to{transform:translateX(100%)}
}

@keyframes corePulse{
  0%,100%{
    box-shadow:
      0 0 0 2px rgba(59,130,246,.9),
      0 0 55px rgba(250,204,21,.7),
      inset 0 0 28px rgba(165,180,252,.4)
  }
  50%{
    box-shadow:
      0 0 0 3px rgba(250,204,21,1),
      0 0 95px rgba(56,189,248,1),
      inset 0 0 40px rgba(165,180,252,.65)
  }
}

@keyframes barGlow{
  0%,100%{box-shadow:0 0 0 1px rgba(147,197,253,.6),0 25px 70px rgba(79,70,229,.8)}
  50%{box-shadow:0 0 0 2px rgba(250,204,21,.9),0 35px 100px rgba(56,189,248,1)}
}

/* MOBILE */
@media(max-width:600px){
  .chat-ai-bar{display:none}
