  </div>
</a>

<script>
/* AI gravity field */
document.addEventListener("mousemove",e=>{
  const core=document.querySelector(".chat-ai-logo");
  const x=(window.innerWidth/2-e.clientX)/45;
  const y=(window.innerHeight/2-e.clientY)/45;
  core.style.transform=`translate(${x}px,${y}px) scale(1.06)`;
});
</script>

</body>
</html>






















