<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Perpustakaan Digital PMII</title>

<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;800&display=swap" rel="stylesheet">

<style>
*{
  margin:0;
  padding:0;
  box-sizing:border-box;
  font-family:'Inter',system-ui,sans-serif;
}

body{
  min-height:100vh;
  background:linear-gradient(270deg,#0047ab,#f4c430,#0047ab);
  background-size:600% 600%;
  animation:bgMove 18s ease infinite;
}

/* ===== HERO BAR ===== */
.hero-wrap{
  background:
    linear-gradient(135deg,rgba(0,40,110,.95),rgba(0,90,180,.92)),
    url("https://i.ibb.co/99PRmvZK/loot.png");
  background-size:cover;
  background-position:center;
  padding:90px 0;
  animation:heroFade 1.2s ease both;
}

/* ===== GRID ===== */
.hero{
  max-width:1200px;
  margin:auto;
  padding:0 30px;
  display:grid;
  grid-template-columns:1.1fr 1fr;
  gap:60px;
  align-items:center;
}

/* ===== BADGE ===== */
.badge{
  display:inline-flex;
  padding:10px 18px;
  background:rgba(255,255,255,.22);
  color:#fff;
  border-radius:999px;
  backdrop-filter:blur(10px);
  font-weight:600;
  animation:badgePulse 3s ease-in-out infinite;
}

/* ===== TEXT ===== */
h1{
  margin-top:26px;
  font-size:56px;
  color:#fff;
  font-weight:800;
  line-height:1.1;
  animation:titleReveal .9s ease both;
}

h1 span{
  color:#ffeb3b;
  text-shadow:0 8px 35px rgba(0,0,0,.45);
}

p{
  margin-top:22px;
  max-width:520px;
  color:rgba(255,255,255,.95);
  line-height:1.7;
  animation:textReveal 1.1s ease both;
}

/* ===== BUTTON ===== */
.btn{
  margin-top:40px;
  padding:16px 28px;
  border-radius:16px;
  background:#ffeb3b;
  color:#003a8f;
  font-weight:700;
  border:none;
  cursor:pointer;
  box-shadow:0 18px 45px rgba(0,0,0,.3);
  animation:btnBreath 2.8s ease-in-out infinite;
}

.btn:hover{
  transform:translateY(-3px) scale(1.05);
  box-shadow:0 25px 70px rgba(255,235,59,.7);
}

/* ===== CARD ===== */
.card-wrap{perspective:1600px;}

.card{
  position:relative;
  width:100%;
  height:470px;
  border-radius:36px;
  overflow:hidden;
  transform-style:preserve-3d;
  animation:float 6s ease-in-out infinite, cardEnter 1.1s ease both;
  transition:transform .15s ease, box-shadow .2s ease;

  background:
    linear-gradient(to bottom,rgba(0,0,0,.15),rgba(0,0,0,.45)),
    url("https://i.ibb.co/99PRmvZK/loot.png");
  background-size:cover;
  background-position:center;

  box-shadow:
    0 45px 100px rgba(0,0,0,.6),
    inset 0 0 0 2px rgba(255,255,255,.12);
}

/* ===== GLASS ===== */
.glass{
  position:absolute;
  inset:0;
  pointer-events:none;
  background:
    linear-gradient(
      120deg,
      rgba(255,255,255,0) 38%,
      rgba(255,255,255,.28) 48%,
      rgba(255,255,255,0) 58%
    );
  animation:glassSweep 4s linear infinite;
  z-index:3;
}

/* ===== GLOW ===== */
.card::after{
  content:"";
  position:absolute;
  inset:0;
  background:
    radial-gradient(circle at top left,rgba(255,235,59,.4),transparent 60%),
    radial-gradient(circle at bottom right,rgba(0,71,171,.6),transparent 60%);
  animation:glowPulse 3.5s ease-in-out infinite;
  pointer-events:none;
}

/* ===== HOVER ===== */
.card:hover{
  transform:scale(1.06);
  box-shadow:
    0 70px 150px rgba(0,0,0,.75),
    0 0 90px rgba(255,235,59,.45);
}

/* ===== KEYFRAMES ===== */
@keyframes bgMove{
  0%{background-position:0% 50%}
  50%{background-position:100% 50%}
  100%{background-position:0% 50%}
}

@keyframes heroFade{
  from{opacity:0;transform:translateY(25px)}
  to{opacity:1;transform:none}
}

@keyframes badgePulse{
  0%,100%{box-shadow:0 0 0 rgba(255,255,255,0)}
  50%{box-shadow:0 0 18px rgba(255,255,255,.45)}
}

@keyframes titleReveal{
  from{opacity:0;transform:translateY(25px);filter:blur(6px)}
  to{opacity:1;transform:none;filter:none}
}

@keyframes textReveal{
  from{opacity:0;transform:translateY(18px)}
  to{opacity:1;transform:none}
}

@keyframes btnBreath{
  0%,100%{box-shadow:0 18px 45px rgba(0,0,0,.3)}
  50%{box-shadow:0 28px 70px rgba(255,235,59,.65)}
}

@keyframes float{
  0%,100%{transform:translateY(0)}
  50%{transform:translateY(-14px)}
}

@keyframes cardEnter{
  from{opacity:0;transform:scale(.9)}
  to{opacity:1;transform:scale(1)}
}

@keyframes glassSweep{
  from{transform:translateX(-60%)}
  to{transform:translateX(60%)}
}

@keyframes glowPulse{
  0%,100%{opacity:.5}
  50%{opacity:1}
}

/* ===== RESPONSIVE ===== */
@media(max-width:768px){
  .hero{grid-template-columns:1fr;text-align:center}
  p{margin-inline:auto}
  h1{font-size:40px}
  .card{height:300px;border-radius:28px}
}
</style>
</head>

<body>

<div class="hero-wrap">
  <section class="hero">

    <div>
      <div class="badge">✨ Perpustakaan Digital PMII</div>

      <h1>
        Membaca Untuk<br>
        Membangun Bangsa<br>
        <span>INDONESIA</span>
      </h1>

      <p>
        Akses literatur keislaman, kebangsaan, dan kepemimpinan
        untuk membentuk kader intelektual PMII yang progresif.
      </p>

      <button class="btn">📚 Jelajahi Katalog</button>
    </div>

    <div class="card-wrap">
      <div class="card" id="card">
        <div class="glass"></div>
      </div>
    </div>

  </section>
</div>

<script>
const card = document.getElementById('card');

if(window.innerWidth > 768){
  card.addEventListener('mousemove', e => {
    const r = card.getBoundingClientRect();
    const x = e.clientX - r.left;
    const y = e.clientY - r.top;
    const ry = ((x / r.width) - 0.5) * 20;
    const rx = ((y / r.height) - 0.5) * -20;
    card.style.transform = `scale(1.06) rotateX(${rx}deg) rotateY(${ry}deg)`;
  });
  card.addEventListener('mouseleave', () => {
    card.style.transform = '';
  });
}
</script>

</body>
</html>






















