[{"id":"23b4ada","elType":"container","settings":{"boxed_width":{"unit":"px","size":1600,"sizes":[]},"min_height":{"unit":"px","size":0,"sizes":[]},"margin":{"unit":"px","top":"8","right":"8","bottom":"8","left":"8","isLinked":true},"content_width":"full","width":{"unit":"%","size":100.5859999999999985220711096189916133880615234375},"_flex_size":"none","_element_width":"initial","background_background":"classic","background_color":"#1F2657","hide_mobile":"hidden-mobile"},"elements":[{"id":"15a7e13","elType":"widget","settings":{"html":"<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Header Premium Interactive</title>

<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css">
<link href="https://fonts.googleapis.com/css2?family=Montserrat:wght@400;600;700;800&family=Playfair+Display:wght@600;700&display=swap" rel="stylesheet">

<style>
/* ================= GLOBAL ================= */
html, body{
  margin:0;
  padding:0;
  font-family:'Montserrat',sans-serif;
  background:#081a33;
  overflow-x:hidden;
}
*{ box-sizing:border-box; }

.full-header{
  width:100vw;
  position:relative;
  left:50%;
  transform:translateX(-50%);
  overflow:hidden;
}

/* TEXTURE */
.full-header::before{
  content:"";
  position:absolute;
  inset:0;
  background:
    radial-gradient(circle at 20% 30%, rgba(255,215,0,.15), transparent 40%),
    radial-gradient(circle at 80% 70%, rgba(0,60,143,.25), transparent 40%);
  pointer-events:none;
}
.full-header::after{
  content:"";
  position:absolute;
  inset:0;
  background:url("https://www.transparenttextures.com/patterns/asfalt-dark.png");
  opacity:.08;
  pointer-events:none;
}

/* ================= TOP BAR ================= */
.top-bar{
  background:linear-gradient(90deg,#ffd000,#ffea00,#ffd000);
  padding:12px 6%;
  display:flex;
  justify-content:flex-end;
  gap:30px;
  font-size:12px;
  font-weight:700;
  letter-spacing:1px;
}
.top-bar a{
  text-decoration:none;
  color:#002b5c;
  position:relative;
}
.top-bar a:not(:last-child)::after{
  content:"";
  position:absolute;
  right:-15px;
  top:50%;
  transform:translateY(-50%);
  width:2px;
  height:14px;
  background:rgba(0,43,92,.4);
}

/* ================= HEADER ================= */
.header{
  background:linear-gradient(160deg,#002b5c,#001a3a);
  padding:30px 6%;
  display:flex;
  justify-content:space-between;
  align-items:center;
  box-shadow:0 20px 40px rgba(0,0,0,.4);
}
.logo img{ height:130px; }

.right{
  display:flex;
  align-items:center;
  gap:40px;
}

/* ===== SEARCH WORDPRESS (tetap terhubung) ===== */
.search{
  background:rgba(255,255,255,.06);
  border:1px solid rgba(255,255,255,.15);
  border-radius:50px;
  padding:14px 25px;
  width:420px;
  display:flex;
  align-items:center;
  gap:15px;
}
.search input{
  background:transparent;
  border:none;
  outline:none;
  color:#fff;
  width:100%;
  font-size:14px;
}
.search button, .search i{
  color:#ffd000;
  font-size:16px;
  cursor:pointer;
  border:none;
  background:none;
}

/* ===== LIVESTREAM ===== */
.live{
  color:#ffd000;
  font-weight:700;
  letter-spacing:1px;
  display:flex;
  align-items:center;
  gap:10px;
  position:relative;
  animation:liveFloat 3s ease-in-out infinite;
}
.live i{
  color:#ff2e2e;
  animation:pulseLive 1.5s infinite;
  text-shadow:0 0 10px rgba(255,0,0,.7);
}
.live::before{
  content:"";
  width:10px;
  height:10px;
  background:#ff2e2e;
  border-radius:50%;
  box-shadow:0 0 0 rgba(255,0,0,.7);
  animation:blinkDot 1.5s infinite;
}

@keyframes pulseLive{
  0%{ transform:scale(1); opacity:1; }
  50%{ transform:scale(1.25); opacity:.6; }
  100%{ transform:scale(1); opacity:1; }
}
@keyframes blinkDot{
  0%{ box-shadow:0 0 0 0 rgba(255,0,0,.7); }
  70%{ box-shadow:0 0 0 12px rgba(255,0,0,0); }
  100%{ box-shadow:0 0 0 0 rgba(255,0,0,0); }
}
@keyframes liveFloat{
  0%{ transform:translateY(0); }
  50%{ transform:translateY(-3px); }
  100%{ transform:translateY(0); }
}

/* ================= NAVBAR ================= */
.navbar{
  background:linear-gradient(90deg,#003c8f,#002b5c);
  padding:20px 0;
  display:flex;
  justify-content:center;
  position:relative;
  box-shadow:0 15px 30px rgba(0,0,0,.4);
}
.navbar::before{
  content:"";
  position:absolute;
  left:0;
  top:0;
  width:280px;
  height:100%;
  background:linear-gradient(135deg,#ffd000,#ffea00);
  clip-path:polygon(0 0,100% 0,80% 100%,0% 100%);
}

/* ===== LEFT NEWS BAR ===== */
.left-bar{
  position:absolute;
  left:35px;
  top:50%;
  transform:translateY(-50%);
  z-index:3;
  perspective:800px;
}
.left-bar span{
  display:inline-block;
  font-family:'Playfair Display',serif;
  font-weight:800;
  font-size:15px;
  letter-spacing:1.5px;
  padding:6px 22px;
  color:#002b5c;
  background:linear-gradient(145deg,#ffd000,#ffea00);
  border-radius:40px;
  transform:rotateX(15deg) rotateY(-12deg);
  box-shadow: 0 3px 0 #c9a600, 0 6px 0 #b39200, 0 12px 20px rgba(0,0,0,.45);
  position:relative;
  overflow:hidden;
  animation:floatNews 3s ease-in-out infinite;
}
.left-bar span::after{
  content:"";
  position:absolute;
  top:0; left:-100%;
  width:100%; height:100%;
  background:linear-gradient(120deg,transparent,rgba(255,255,255,.6),transparent);
  animation:shineMove 3s infinite;
}

@keyframes floatNews{
  0%{ transform:rotateX(15deg) rotateY(-12deg) translateY(0); }
  50%{ transform:rotateX(15deg) rotateY(-12deg) translateY(-6px); }
  100%{ transform:rotateX(15deg) rotateY(-12deg) translateY(0); }
}
@keyframes shineMove{
  0%{ left:-100%; }
  100%{ left:120%; }
}

/* ===== MENU ===== */
.menu{
  display:flex;
  gap:50px;
  z-index:2;
  margin-left:20px;
}
.menu a{
  text-decoration:none;
  color:#fff;
  font-weight:700;
  letter-spacing:1px;
  padding:5px 0;
  position:relative;
  transition:.3s;
}
.menu a:hover{ color:#ffd000; }
.menu a:not(:last-child)::after{
  content:"";
  position:absolute;
  right:-25px;
  top:50%;
  transform:translateY(-50%);
  width:1px;
  height:18px;
  background:rgba(255,255,255,.3);
}

/* SOCIAL */
.social{
  position:absolute;
  right:6%;
  display:flex;
  gap:22px;
  z-index:2;
}
.social a{
  color:#fff;
  font-size:18px;
  transition:.3s;
}
.social a:hover{
  color:#ffd000;
  transform:translateY(-4px);
}
</style>
</head>
<body>

<div class="full-header">

  <div class="top-bar">
    <a href="#">PMII PB</a>
    <a href="#">PMII CABANG</a>
    <a href="#">PMII KOMIS</a>
    <a href="#">RAYON</a>
  </div>

  <div class="header">
    <div class="logo">
      <img src="https://www.pmii.id/assets/frontend/images/apple-touch-icon2.png">
    </div>

    <div class="right">

      <!-- SEARCH TERHUBUNG WORDPRESS -->
      <form role="search" method="get" action="/">
        <div class="search">
          <input type="search" name="s" placeholder="Cari berita, artikel, kegiatan..." required>
          <button type="submit"><i class="fa-solid fa-magnifying-glass"></i></button>
        </div>
      </form>

      <div class="live">
        <i class="fa-solid fa-broadcast-tower"></i>
        LIVESTREAM
      </div>

    </div>
  </div>

  <div class="navbar">

    <div class="left-bar">
      <span>PERGERAKAN NEWS</span>
    </div>

    <div class="menu">
      <a href="#">Keorganisasian</a>
      <a href="#">Sosia Kemasyarakatan</a>
      <a href="#">Advocasi</a>
      <a href="#">Teknologi</a>

      <a href="#">TENTANG KAMI</a>
    </div>

    <div class="social">
      <a href="#"><i class="fa-brands fa-youtube"></i></a>
      <a href="#"><i class="fa-brands fa-instagram"></i></a>
      <a href="#"><i class="fa-brands fa-facebook-f"></i></a>
      <a href="#"><i class="fa-brands fa-twitter"></i></a>
    </div>

  </div>
</div>

</body>
</html>","_margin":{"unit":"px","top":"-26","right":"-26","bottom":"-26","left":"-26","isLinked":true},"_padding":{"unit":"px","top":"-2","right":"-2","bottom":"-2","left":"-2","isLinked":true},"_title":"HTML"},"elements":[],"widgetType":"html"}],"isInner":false},{"id":"1f99b71","elType":"container","settings":{"flex_direction":"column","boxed_width":{"unit":"px","size":1600,"sizes":[]},"background_background":"classic","background_color":"#262958","margin":{"unit":"px","top":"-8","right":"-8","bottom":"-8","left":"-8","isLinked":true},"padding":{"unit":"px","top":"16","right":"16","bottom":"16","left":"16","isLinked":true},"hide_mobile":"hidden-mobile"},"elements":[{"id":"980c866","elType":"widget","settings":{"html":"<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Hologram Futuristik Banner Animatif</title>
<link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;600;800&display=swap" rel="stylesheet">
<style>
*{margin:0;padding:0;box-sizing:border-box;}
body{background:#0b1e34;font-family:'Poppins',sans-serif;overflow:hidden;}

/* HERO FULL BLEED BANNER */
.hero{
  position:relative;
  width:100vw;
  left:50%;
  transform:translateX(-50%);
  aspect-ratio:2048/589; /* ukuran tetap seperti sebelumnya */
  overflow:hidden;
}

/* GRID + BACKGROUND */
.hero::before{
  content:""; position:absolute; inset:0;
  background: linear-gradient(to right, rgba(6,18,35,0.98) 0%, rgba(8,25,45,0.85) 35%, rgba(12,40,70,0.65) 60%, rgba(15,50,90,0.45) 80%, rgba(20,60,110,0.35) 100%), url("https://i.ibb.co/tNkLbXV/r-b.png");
  background-size:cover; background-position:center; z-index:1;
  animation: backgroundZoom 25s linear infinite alternate;
}
.hero::after{
  content:""; position:absolute; top:0; right:0; width:55%; height:100%; z-index:2;
  background-image: linear-gradient(rgba(255,255,255,0.06) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,0.06) 1px, transparent 1px);
  background-size:14px 14px;
  mask-image:linear-gradient(to left, rgba(0,0,0,1) 65%, rgba(0,0,0,0));
  animation: gridMove 30s linear infinite;
}

/* HERO CONTENT */
.hero-content{position:relative; z-index:3; height:100%; max-width:1200px; margin:auto; padding:0 5%; display:flex; flex-direction:column; justify-content:center; color:white; overflow:hidden;}
.hero-content h1,h3,p{opacity:0; transform:translateY(30px); animation:fadeUp 1s forwards;}
.hero-content h1{font-size:clamp(32px,4vw,64px);font-weight:800;letter-spacing:2px;margin-bottom:12px;animation-delay:0.3s;}
.hero-content h3{font-size:clamp(20px,2.5vw,32px);font-weight:600;letter-spacing:1px;margin-bottom:8px;animation-delay:0.6s;}
.hero-content p{font-size:clamp(14px,1.2vw,20px);opacity:.9;animation-delay:0.9s;}

/* HOLOGRAM FUTURISTIK RANDOM */
.hologram{
  position:absolute;
  top:50%;
  left:50%;
  transform:translate(-50%,-50%) scale(0.6);
  width:450px;
  height:450px;
  z-index:4;
}
.hologram svg polygon, .hologram svg circle, .hologram svg line, .hologram svg polyline{
  fill: rgba(0,255,255,0.05);
  stroke: rgba(0,255,255,0.6);
  stroke-width:1.5;
}
.hologram svg line, .hologram svg polyline{stroke-dasharray:4 4; animation:lineMove 3s linear infinite;}
.layer{transform-origin:100px 100px; animation:rotateLayer linear infinite;}
.layer1{animation-duration:5s;opacity:0.5;}
.layer2{animation-duration:6s;opacity:0.45;}
.layer3{animation-duration:7s;opacity:0.4;}
.layer4{animation-duration:4.5s;opacity:0.55;}
.layer5{animation-duration:6.5s;opacity:0.35;}
.layer6{animation-duration:5.5s;opacity:0.5;}
.layer7{animation-duration:8s;opacity:0.4;}
.layer8{animation-duration:7.5s;opacity:0.45;}
.layer9{animation-duration:5.8s;opacity:0.35;}
.layer10{animation-duration:9s;opacity:0.5;}

/* ANIMASI */
@keyframes fadeUp{0%{opacity:0;transform:translateY(30px);}100%{opacity:1;transform:translateY(0);}}
@keyframes gridMove{0%{background-position:0 0,0 0;}100%{background-position:100px 0,-100px 0;}}
@keyframes backgroundZoom{0%{transform: scale(1);}50%{transform: scale(1.05);}100%{transform: scale(1);}}
@keyframes lineMove{0%{stroke-dashoffset:0;}100%{stroke-dashoffset:100;}}
@keyframes rotateLayer{0%{transform:rotate(0deg) scale(0.8);}100%{transform:rotate(360deg) scale(1.1);}}
</style>
</head>
<body>

<section class="hero">
  <div class="hero-content">
    <h1>PMII STAIM KENDAL NGAWI</h1>
    <h3>Bergerak memberi dampak pada masyarakat</h3>
    <p>20–25 January 2026 • Jakarta</p>
  </div>

  <!-- HOLOGRAM RANDOM & ANIMATIF -->
  <div class="hologram">
    <svg viewBox="0 0 200 200" width="100%" height="100%">
      <polygon class="layer layer1" points="100,10 180,50 180,150 100,190 20,150 20,50"/>
      <polygon class="layer layer2" points="100,30 160,60 160,140 100,170 40,140 40,60"/>
      <circle class="layer layer3" cx="100" cy="100" r="60"/>
      <circle class="layer layer4" cx="100" cy="100" r="40"/>
      <polygon class="layer layer5" points="100,50 130,80 100,110 70,80"/>
      <polygon class="layer layer6" points="100,70 120,90 100,110 80,90"/>
      <line class="layer layer7" x1="20" y1="50" x2="180" y2="150"/>
      <line class="layer layer8" x1="180" y1="50" x2="20" y2="150"/>
      <polyline class="layer layer9" points="100,0 100,200"/>
      <polyline class="layer layer10" points="0,100 200,100"/>
    </svg>
  </div>
</section>

</body>
</html>"},"elements":[],"widgetType":"html"}],"isInner":false},{"id":"e1ae92b","elType":"container","settings":{"flex_direction":"column","background_background":"classic","background_color":"#0A0E4E","hide_mobile":"hidden-mobile"},"elements":[{"id":"7736c5c","elType":"widget","settings":{"text":"populer","typography_typography":"custom","typography_font_family":"Sarina","typography_font_size":{"unit":"px","size":22,"sizes":[]},"typography_font_weight":"500","typography_text_transform":"uppercase","typography_font_style":"normal","text_shadow_text_shadow_type":"yes","text_shadow_text_shadow":{"horizontal":0,"vertical":0,"blur":34,"color":"rgba(0,0,0,0.3)"},"button_text_color":"#E3E1D7","background_color":"#FFD307","button_background_hover_color":"#EDF322","border_radius":{"unit":"px","top":"7","right":"34","bottom":"0","left":"0","isLinked":false},"button_box_shadow_box_shadow_type":"yes","button_box_shadow_box_shadow":{"horizontal":5,"vertical":8,"blur":10,"spread":-2,"color":"rgba(0,0,0,0.5)"}},"elements":[],"widgetType":"button"}],"isInner":false},{"id":"f0430cf","elType":"container","settings":{"flex_direction":"column","boxed_width":{"unit":"px","size":1600,"sizes":[]},"background_background":"classic","background_color":"#215658","hide_tablet":"hidden-tablet","hide_mobile":"hidden-mobile"},"elements":[{"id":"30fed69","elType":"widget","settings":{"html":"<!DOCTYPE html>
<html lang="id">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>PMII STAIM KENDAL | OMEGA LEVEL UI</title>

    <link href="https://fonts.googleapis.com/css2?family=Syne:wght@800&family=Outfit:wght@300;400;600;800&display=swap" rel="stylesheet">

    <style>
        :root {
            --black: #030303;
            --white: #ffffff;
            --gold: #ffbd16;
            --accent: #ff3c00;
            --glass: rgba(255, 255, 255, 0.02);
            --border: rgba(255, 255, 255, 0.07);
        }

        * { margin: 0; padding: 0; box-sizing: border-box; cursor: none; }

        body {
            background-color: var(--black);
            color: var(--white);
            font-family: 'Outfit', sans-serif;
            overflow-x: hidden;
            background: radial-gradient(circle at 50% 50%, #0a0a0a 0%, #030303 100%);
        }

        /* --- FILM GRAIN OVERLAY --- */
        body::after {
            content: "";
            position: fixed; top: 0; left: 0; width: 100%; height: 100%;
            background-image: url('https://grainy-gradients.vercel.app/noise.svg');
            opacity: 0.04; pointer-events: none; z-index: 999;
        }

        /* --- ADVANCED CURSOR --- */
        #cursor {
            position: fixed; width: 10px; height: 10px; background: var(--white);
            border-radius: 50%; pointer-events: none; z-index: 10000;
            mix-blend-mode: difference; transition: transform 0.15s ease-out;
        }

        #cursor-follower {
            position: fixed; width: 40px; height: 40px; border: 1px solid var(--gold);
            border-radius: 50%; pointer-events: none; z-index: 9999;
            transition: all 0.3s cubic-bezier(0.23, 1, 0.32, 1);
        }

        .container { max-width: 1400px; margin: auto; padding: 100px 30px; }

        /* --- SPATIAL HEADER --- */
        .spatial-hero {
            display: grid; grid-template-columns: 1.2fr 0.8fr; gap: 80px;
            align-items: center; margin-bottom: 150px;
        }

        /* --- TEXT MASKING & GLITCH --- */
        .hero-title {
            font-family: 'Syne', sans-serif; font-size: clamp(3rem, 7vw, 6rem);
            line-height: 0.9; letter-spacing: -4px; text-transform: uppercase;
            background: linear-gradient(45deg, #fff 30%, var(--gold), var(--accent), #fff 70%);
            background-size: 200% auto;
            -webkit-background-clip: text; -webkit-text-fill-color: transparent;
            animation: shine 5s linear infinite;
        }

        @keyframes shine { to { background-position: 200% center; } }

        /* --- 3D INTERACTIVE IMAGE --- */
        .tilt-box {
            position: relative; width: 100%; height: 600px;
            perspective: 1000px; transform-style: preserve-3d;
        }

        .tilt-card {
            width: 100%; height: 100%; border-radius: 40px;
            background: url('https://i.ibb.co/ZzR3bLVj/bjsanmklshdugqehas.png') center/cover;
            border: 1px solid var(--border);
            box-shadow: 0 50px 100px rgba(0,0,0,0.5);
            transition: transform 0.1s;
        }

        /* --- OMEGA BENTO GRID --- */
        .omega-grid {
            display: grid; grid-template-columns: repeat(3, 1fr); gap: 30px;
        }

        .omega-card {
            background: var(--glass); backdrop-filter: blur(40px);
            padding: 40px; border-radius: 50px; border: 1px solid var(--border);
            transition: 0.5s cubic-bezier(0.2, 1, 0.3, 1);
            text-decoration: none; color: inherit;
        }

        .omega-card:hover {
            background: rgba(255, 255, 255, 0.05);
            transform: translateY(-20px) scale(1.02);
            border-color: var(--gold);
        }

        .omega-card img {
            width: 100%; height: 200px; border-radius: 30px;
            object-fit: cover; margin-bottom: 30px; filter: saturate(0);
            transition: 0.5s;
        }

        .omega-card:hover img { filter: saturate(1.2); }

        .omega-card h3 {
            font-family: 'Syne', sans-serif; font-size: 1.8rem;
            margin-bottom: 15px; color: #eee;
        }

        /* --- NEON BADGE --- */
        .badge-omega {
            display: inline-block; padding: 8px 20px; border-radius: 100px;
            background: rgba(255, 189, 22, 0.1); color: var(--gold);
            font-size: 10px; font-weight: 800; letter-spacing: 3px;
            text-transform: uppercase; border: 1px solid var(--gold);
            margin-bottom: 25px;
        }

        /* --- SIDEBAR MINIMALIS --- */
        .sidebar-omega {
            background: var(--glass); padding: 40px; border-radius: 50px;
            border: 1px solid var(--border); height: fit-content;
        }

        .trending-row {
            display: block; text-decoration: none; color: #888;
            padding: 20px 0; border-bottom: 1px solid var(--border);
            transition: 0.3s;
        }

        .trending-row:hover { color: var(--white); padding-left: 10px; }

        .trending-row span { font-size: 11px; color: var(--accent); font-weight: 800; }

        @media (max-width: 1100px) {
            .spatial-hero { grid-template-columns: 1fr; }
            .omega-grid { grid-template-columns: 1fr; }
        }
    </style>
</head>
<body>

    <div id="cursor"></div>
    <div id="cursor-follower"></div>

    <div class="container">
        <section class="spatial-hero">
            <div class="hero-content">
                <div class="badge-omega">Strategic News v.3.0</div>
                <h1 class="hero-title">PMII STAIM<br>KENDAL</h1>
                <p style="font-size: 1.2rem; color: #888; margin-top: 30px; max-width: 500px;">
                    Membangun narasi baru dalam gerakan mahasiswa melalui konsolidasi intelektual yang radikal dan progresif.
                </p>
                <div style="margin-top: 40px; display: flex; gap: 20px;">
                    <div style="width: 50px; height: 1px; background: var(--gold); align-self: center;"></div>
                    <span style="font-size: 12px; letter-spacing: 2px;">SCROLL TO EXPLORE</span>
                </div>
            </div>

            <div class="tilt-box" id="tilt">
                <div class="tilt-card"></div>
            </div>
        </section>

        <div class="omega-grid">
            <a href="#" class="omega-card">
                <img src="https://i.ibb.co/4nbQsgSc/Chat-GPT-Image-Jan-27-2026-02-10-16-PM.png" alt="1">
                <h3>Sahabat Literasi</h3>
                <p style="color: #666;">Gerakan membaca sebagai fondasi gerakan intelektual kader masa kini.</p>
            </a>

            <a href="#" class="omega-card">
                <img src="https://assets.pikiran-rakyat.com/crop/0x1283:3000x3345/720x0/webp/photo/2026/01/24/3220267689.jpg" alt="2">
                <h3>Regenerasi Total</h3>
                <p style="color: #666;">Melangkah lebih jauh dengan kepengurusan yang solid dan visioner.</p>
            </a>

            <div class="sidebar-omega">
                <h4 style="font-family: 'Syne'; margin-bottom: 20px; letter-spacing: 2px;">TERPOPULER</h4>
                <a href="#" class="trending-row">
                    <span>01 / ANALISIS</span>
                    <h4 style="margin-top: 5px;">Akselerasi Kaderisasi Digital</h4>
                </a>
                <a href="#" class="trending-row">
                    <span>02 / OPINI</span>
                    <h4 style="margin-top: 5px;">Retorika vs Realita Mahasiswa</h4>
                </a>
                <button style="width: 100%; padding: 20px; margin-top: 30px; background: var(--gold); border: none; border-radius: 20px; font-weight: 800; font-family: 'Syne';">GABUNG SEKARANG</button>
            </div>
        </div>
    </div>

    <script>
        const cursor = document.getElementById('cursor');
        const follower = document.getElementById('cursor-follower');
        const tiltCard = document.querySelector('.tilt-card');

        // Advanced Mouse Follower
        document.addEventListener('mousemove', (e) => {
            cursor.style.left = e.clientX + 'px';
            cursor.style.top = e.clientY + 'px';

            setTimeout(() => {
                follower.style.left = (e.clientX - 15) + 'px';
                follower.style.top = (e.clientY - 15) + 'px';
            }, 50);

            // 3D Tilt Calculation
            const x = (window.innerWidth / 2 - e.clientX) / 20;
            const y = (window.innerHeight / 2 - e.clientY) / 20;
            tiltCard.style.transform = `rotateY(${x}deg) rotateX(${-y}deg)`;
        });

        // Magnetic Effect on Cards
        document.querySelectorAll('.omega-card, button').forEach(el => {
            el.addEventListener('mouseenter', () => {
                follower.style.transform = 'scale(2.5)';
                follower.style.background = 'rgba(255, 189, 22, 0.1)';
                cursor.style.transform = 'scale(0.5)';
            });
            el.addEventListener('mouseleave', () => {
                follower.style.transform = 'scale(1)';
                follower.style.background = 'transparent';
                cursor.style.transform = 'scale(1)';
            });
        });
    </script>
</body>
</html>"},"elements":[],"widgetType":"html"},{"id":"ea26437","elType":"widget","settings":[],"elements":[],"widgetType":"html"},{"id":"2168822","elType":"widget","settings":[],"elements":[],"widgetType":"html"}],"isInner":false},{"id":"f100c05","elType":"container","settings":{"flex_direction":"column","hide_mobile":"hidden-mobile"},"elements":[{"id":"6d6c891","elType":"widget","settings":{"html":"<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Portal Berita PMII STAIM Kendal - Tablet/HP</title>

<link href="https://fonts.googleapis.com/css2?family=Playfair+Display:wght@600;700&family=Inter:wght@400;500;600&display=swap" rel="stylesheet">

<style>
:root{
  --primary:#0f172a;
  --accent:#c2410c;
  --bg:#f1f5f9;
  --card:#ffffff;
  --muted:#64748b;
}

*{
  margin:0;
  padding:0;
  box-sizing:border-box;
}

body{
  font-family:'Inter',sans-serif;
  background:var(--bg);
  color:var(--primary);
}

.wrapper{
  max-width:1200px;
  margin:auto;
  padding:20px 15px;
}

/* ================= GRID TABLET & HP ================= */
.news-grid{
  display:grid;
  grid-template-columns:1fr;
  gap:15px;
}

/* LABEL DAN IMAGE WRAPPER */
.label{
  position:absolute;
  top:8px;
  left:8px;
  background:var(--accent);
  color:#fff;
  font-size:10px;
  font-weight:600;
  padding:4px 10px;
  border-radius:20px;
  letter-spacing:1px;
  text-transform:uppercase;
  box-shadow:0 6px 15px rgba(0,0,0,.1);
  animation:float 3s ease-in-out infinite;
}
@keyframes float{
  0%{transform:translateY(0);}
  50%{transform:translateY(-3px);}
  100%{transform:translateY(0);}
}

.image-wrapper{
  position:relative;
  overflow:hidden;
  border-radius:16px;
}

.image-wrapper img{
  width:100%;
  object-fit:cover;
  transition:transform .5s ease;
}

.image-wrapper:hover img{
  transform:scale(1.05);
}

/* MAIN NEWS & SUB CARD KOTAK */
.main-news, .sub-card, .sidebar{
  background:var(--card);
  border-radius:16px;
  overflow:hidden;
  box-shadow:0 10px 30px rgba(0,0,0,.05);
  opacity:0;
  transform:translateY(10px);
  transition:all .5s ease;
}

.main-news.active, .sub-card.active, .sidebar.active{
  opacity:1;
  transform:translateY(0);
}

/* MAIN NEWS Paling Atas - TINGGI 400px */
.main-news .image-wrapper img{
  height:400px; /* ditambah tinggi */
}

.main-news h1{
  font-family:'Playfair Display',serif;
  font-size:18px;
  margin:10px 10px 5px;
}

.main-news p{
  font-size:13px;
  margin:0 10px 10px;
  color:var(--muted);
  line-height:1.5;
}

/* SUB NEWS KOTAK */
.sub-news{
  display:grid;
  grid-template-columns:repeat(auto-fill,minmax(150px,1fr));
  gap:10px;
}

.sub-card-content{
  padding:10px;
}

.sub-card-content h4{
  font-size:14px;
  margin-bottom:4px;
  line-height:1.3;
}

.sub-card-content p{
  font-size:12px;
  margin-bottom:4px;
  color:var(--muted);
}

.sub-card-content small{
  font-size:11px;
  color:var(--accent);
  font-weight:600;
}

/* SIDEBAR TABLET/HP */
.sidebar{
  padding:15px;
}

.sidebar h3{
  font-size:16px;
  margin-bottom:10px;
  position:relative;
}

.sidebar h3::after{
  content:"";
  width:50px;
  height:3px;
  background:var(--accent);
  position:absolute;
  left:0;
  bottom:-8px;
  border-radius:10px;
}

.sidebar ul{
  list-style:none;
  display:grid;
  grid-template-columns:repeat(auto-fill,minmax(120px,1fr));
  gap:10px;
}

.sidebar li a{
  display:block;
  text-decoration:none;
  color:inherit;
  font-size:12px;
}

.sidebar img{
  width:100%;
  height:80px;
  object-fit:cover;
  border-radius:12px;
  margin-bottom:4px;
}
</style>
</head>
<body>

<div class="wrapper">
  <div class="news-grid">

    <!-- MAIN NEWS -->
    <div class="main-news">
      <div class="image-wrapper">
        <span class="label">Kaderisasi</span>
        <img src="https://i.ibb.co/ZzR3bLVj/bjsanmklshdugqehas.png" alt="Main News">
      </div>
      <h1>PK PMII STAIM Kendal Perkuat Gerakan Kaderisasi Strategis</h1>
      <p>Pengurus Komisariat PMII STAIM Kendal terus memperkuat konsolidasi organisasi melalui program kaderisasi berkelanjutan yang progresif dan berbasis intelektual.</p>
    </div>

    <!-- SUB NEWS -->
    <div class="sub-news">
      <div class="sub-card">
        <div class="image-wrapper">
          <span class="label">Literasi</span>
          <img src="https://i.ibb.co/4nbQsgSc/Chat-GPT-Image-Jan-27-2026-02-10-16-PM.png" alt="Sub News">
        </div>
        <div class="sub-card-content">
          <h4>Program Sahabat Literasi Kader</h4>
          <p>Gerakan membaca & diskusi rutin memperkuat budaya akademik kader.</p>
          <small>08 Jan 2026</small>
        </div>
      </div>

      <div class="sub-card">
        <div class="image-wrapper">
          <span class="label">Pelantikan</span>
          <img src="https://assets.pikiran-rakyat.com/crop/0x1283:3000x3345/720x0/webp/photo/2026/01/24/3220267689.jpg" alt="Sub News">
        </div>
        <div class="sub-card-content">
          <h4>Pelantikan Kepengurusan Baru</h4>
          <p>Momentum regenerasi kepemimpinan & penguatan arah organisasi.</p>
          <small>24 Des 2025</small>
        </div>
      </div>

      <div class="sub-card">
        <div class="image-wrapper">
          <span class="label">Diskusi</span>
          <img src="https://i.ibb.co/ZzR3bLVj/bjsanmklshdugqehas.png" alt="Sub News">
        </div>
        <div class="sub-card-content">
          <h4>Diskusi Publik Kebangsaan</h4>
          <p>Forum intelektual membahas peran mahasiswa dalam demokrasi Indonesia.</p>
          <small>15 Des 2025</small>
        </div>
      </div>
    </div>

    <!-- SIDEBAR -->
    <aside class="sidebar">
      <h3>Terpopuler</h3>
      <ul>
        <li>
          <a href="#">
            <img src="https://i.ibb.co/ZzR3bLVj/bjsanmklshdugqehas.png" alt="Sidebar">
            <div>Gerakan Strategis PK PMII</div>
          </a>
        </li>
        <li>
          <a href="#">
            <img src="https://i.ibb.co/4nbQsgSc/Chat-GPT-Image-Jan-27-2026-02-10-16-PM.png" alt="Sidebar">
            <div>Program Literasi Organisasi</div>
          </a>
        </li>
        <li>
          <a href="#">
            <img src="https://assets.pikiran-rakyat.com/crop/0x1283:3000x3345/720x0/webp/photo/2026/01/24/3220267689.jpg" alt="Sidebar">
            <div>Pelantikan Kepengurusan Baru</div>
          </a>
        </li>
      </ul>
    </aside>

  </div>
</div>

<script>
window.addEventListener("load",()=>{
  document.querySelectorAll(".main-news, .sub-card, .sidebar").forEach((el,i)=>{
    setTimeout(()=>{el.classList.add("active");},200*i);
  });
});
</script>

</body>
</html>","hide_desktop":"hidden-desktop"},"elements":[],"widgetType":"html"}],"isInner":false},{"id":"3b4de79","elType":"container","settings":{"flex_direction":"column","background_background":"classic","background_color":"#282C42","hide_mobile":"hidden-mobile"},"elements":[{"id":"18fc0bf","elType":"widget","settings":{"html":"<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="UTF-8" />
<title>PMII Logo Bar Compact Interaktif</title>
<style>
  * { box-sizing: border-box; }
  body {
    margin: 0;
    padding: 0;
    background: #f5f7fa;
    font-family: "Segoe UI", Tahoma, Geneva, Verdana, sans-serif;
    overflow-x: hidden;
  }

  /* MAIN WRAPPER */
  .image-bar-wrapper {
    max-width: 900px;
    margin: 20px auto;
    padding: 15px 20px;
    border-radius: 15px;
    background: #0b3c78; /* biru PMII */
    box-shadow: 0 6px 15px rgba(0,0,0,0.15);
    position: relative;
  }

  /* LOGO BAR */
  .image-bar {
    display: flex;
    justify-content: space-around; /* biar 3 logo jelas terlihat */
    align-items: center;
    gap: 30px;
    position: relative;
    z-index: 2;
  }

  .item {
    width: 120px;
    cursor: pointer;
    text-align: center;
    transition: transform 0.25s ease;
  }
  .item:hover { transform: translateY(-6px) scale(1.05); }

  /* GLOW EFFECT */
  .glitch-box {
    position: relative;
    border-radius: 12px;
    overflow: hidden;
    box-shadow: 0 6px 15px rgba(0, 120, 255, 0.3);
    transition: transform .5s ease;
  }

  .glitch-box img {
    width: 100%;
    border-radius: 10px;
    display: block;
  }

  /* INDICATOR */
  .indicator {
    margin: 8px auto 0;
    width: 40px;
    height: 4px;
    border-radius: 3px;
    background: rgba(255,255,255,0.7);
    transition: 0.3s ease;
  }
  .item.active .indicator {
    background: #f5c400; /* kuning PMII */
    box-shadow: 0 0 8px #f5c400;
  }

  /* CLICK EFFECT */
  .flip { transform: rotateY(180deg); }
  .fullscreen-pop {
    position: fixed;
    inset: 0;
    margin: auto;
    width: 70vw !important;
    height: auto !important;
    z-index: 9999;
    transform: scale(1.3);
    transition: transform 0.6s ease;
  }

  /* RESPONSIVE */
  @media(max-width:768px){
    .image-bar { gap: 20px; justify-content: space-between; }
    .item { width: 90px; }
  }
</style>
</head>

<body>

<div class="image-bar-wrapper">
  <div class="image-bar">

    <!-- LEFT LOGO -->
    <div class="item">
   <div class="glitch-box" data-link="https://pmiikomiskenda.42web.io/">
        <img src="https://i.ibb.co/8n4rJL3D/logoiguy.png" alt="Logo PMII 1">
      </div>
      <div class="indicator"></div>
    </div>

    <!-- CENTER LOGO -->
    <div class="item">
      <div class="glitch-box" data-link="https://pmiikomiskenda.42web.io/halaman-2/">
        <img src="https://i.ibb.co/0yBKwGP4/bgh.jpg" alt="Logo PMII 2">
      </div>
      <div class="indicator"></div>
    </div>

    <!-- RIGHT LOGO -->
    <div class="item active">
      <div class="glitch-box" data-link="">
        <img src="https://i.ibb.co.com/fG9t9T2w/nsuwhoayuhkjnssjsss.png" alt="Logo PMII 3">
      </div>
      <div class="indicator"></div>
    </div>

  </div>
</div>

<script>
const items = document.querySelectorAll(".item");
const boxes = document.querySelectorAll(".glitch-box");

items.forEach((item, index) => {
  const box = item.querySelector(".glitch-box");

  // Ketika logo diklik
  box.addEventListener("click", () => {
    // Hapus active dari semua item
    items.forEach(i => i.classList.remove("active"));
    // Tambahkan active ke yang diklik
    item.classList.add("active");

    // Animasi klik
    box.classList.add("flip");
    setTimeout(() => box.classList.add("fullscreen-pop"), 400);

    // Redirect jika ada link
    setTimeout(() => {
      if(box.dataset.link) window.location.href = box.dataset.link;
    }, 900);
  });
});
</script>

</body>
</html>
