<html lang="id">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Berita PMII - Hero Premium</title>

<!-- Google Fonts -->
<link href="https://fonts.googleapis.com/css2?family=Raleway:wght@700;900&display=swap" rel="stylesheet">

<style>
:root{
  --bg:#f2f6fb;
  --content-max:1200px;
  --primary-color: deepskyblue;
}

*{
  box-sizing:border-box;
  font-family:'Raleway', sans-serif;
  transition:all .3s ease;
}

body{
  background:var(--bg);
  margin:0;
  color:#333;
}

a{
  text-decoration:none;
  color:inherit;
  display:block;
}

/* SECTION */
.news-section{
  max-width:var(--content-max);
  margin:30px auto;
  padding:0 20px 40px;
}

.news-section h2{
  font-size:26px;
  margin-bottom:20px;
  font-weight:900;
  color:var(--primary-color);
}

/* GRID */
.grid{
  display:grid;
  grid-template-columns:repeat(2,1fr);
  gap:28px;
}

/* CARD */
.card{
  background:white;
  border-radius:16px;
  overflow:hidden;
  box-shadow:0 12px 35px rgba(0,0,0,.07);
  cursor:pointer;
  transition:transform .6s ease, box-shadow .6s ease;
}

.card img{
  width:100%;
  height:190px;
  object-fit:cover;
  transition:transform .6s ease, filter .6s ease;
}

.card:hover img{
  transform:scale(1.08);
  filter:brightness(1.05);
}

.card h3{
  padding:18px;
  font-size:16px;
  line-height:1.6;
  color:#333;
}

.card:hover{
  transform:translateY(-8px);
  box-shadow:0 25px 60px rgba(0,0,0,.15);
}

/* RESPONSIVE */
@media(max-width:600px){
  .grid{
    grid-template-columns:1fr;
  }
}
</style>
</head>

<body>

<div class="news-section">
  <div class="grid">

    <!-- PELANTIKAN -->
    <a href="https://pmiikomiskenda.42web.io/pelantikan/">
      <div class="card">
        <img src="https://assets.pikiran-rakyat.com/crop/0x1283:3000x3345/720x0/webp/photo/2026/01/24/3220267689.jpg" alt="Pelantikan PMII">
        <h3>Pelantikan PK PMII STAIM Kendal 2025/2026</h3>
