<html lang="id">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>PMII News - Footer</title>

<!-- Link Font Awesome untuk ikon sosial media -->
<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.2/css/all.min.css" integrity="sha512-..." crossorigin="anonymous" referrerpolicy="no-referrer" />

<style>
:root{
  --blue-dark:#061a33;
  --blue:#0b3c78;
  --blue-light:#0f62c4;
  --yellow:#f5c400;
  --content-max:1200px;
}

*{
  box-sizing:border-box;
  font-family:'Segoe UI',system-ui,sans-serif;
  margin:0;
  padding:0;
  transition: all 0.3s ease;
}

/* FULL BLEED */
.full-bleed{
  width:100vw;
  position:relative;
  left:50%;
  margin-left:-50vw;
}

/* ===== FOOTER ===== */
footer{
  background:linear-gradient(135deg,var(--blue-dark),var(--blue-light));
  color:#fff;
  padding:40px 20px 20px 20px;
  position:relative;
  overflow:hidden;
}

footer .inner{
  max-width:var(--content-max);
  margin:auto;
  display:flex;
  flex-wrap:wrap;
  justify-content:space-between;
  align-items:center;
  gap:20px;
}

/* LEFT SIDE - BRAND */
footer .brand{
  font-size:18px;
  font-weight:700;
  color:var(--yellow);
}

footer .brand span{
  display:block;
  font-weight:400;
  color:#fff;
  margin-top:5px;
}

/* RIGHT SIDE - SOCIAL ICONS */
footer .social-icons{
  display:flex;
  gap:20px;
}

footer .social-icons a{
  display:flex;
  align-items:center;
  justify-content:center;
  width:40px;
  height:40px;
  border-radius:50%;
  background:rgba(255,255,255,0.1);
  color:#fff;
  font-size:18px;
  text-decoration:none;
  transition: all 0.3s ease;
}

footer .social-icons a:hover{
  background:var(--yellow);
  color:var(--blue-dark);
  transform:scale(1.2);
}

/* BOTTOM COPYRIGHT */
footer .bottom{
  width:100%;
  text-align:center;
  margin-top:30px;
  font-size:13px;
  color:#bbb;
}

/* Responsive */
@media(max-width:768px){
  footer .inner{
    flex-direction:column;
    text-align:center;
  }
  footer .social-icons{
    margin-top:15px;
  }
}
</style>
</head>

<body>

<footer class="full-bleed">
  <div class="inner">
    <!-- LEFT SIDE BRAND -->
    <div class="brand">

      <span></span>
    </div>

    <!-- RIGHT SIDE SOCIAL ICONS -->
    <div class="social-icons">
      <a href="#" aria-label="Facebook"><i class="fab fa-facebook-f"></i></a>
      <a href="#" aria-label="Instagram"><i class="fab fa-instagram"></i></a>
      <a href="#" aria-label="Twitter"><i class="fab fa-twitter"></i></a>
      <a href="#" aria-label="YouTube"><i class="fab fa-youtube"></i></a>
    </div>

    <!-- BOTTOM COPYRIGHT -->
    <div class="bottom">

    </div>
  </div>
</footer>

</body>
</html>
"},"elements":[],"widgetType":"html"}],"isInner":false},{"id":"2917130","elType":"container","settings":{"flex_direction":"column","hide_mobile":"hidden-mobile"},"elements":[{"id":"9255fb5","elType":"widget","settings":{"classic_meta_separator":"///","classic_read_more_text":"Read More »","cards_meta_separator":"•","cards_read_more_text":"Read More »","full_content_meta_separator":"///","pagination_page_limit":"5","pagination_prev_label":"&laquo; Previous","pagination_next_label":"Next &raquo;","text":"Load More","load_more_no_posts_custom_message":"No more posts to show","custom_css":"/* ===============================
   WIDGET POSTS CONTAINER - BACKGROUND GRID KOTAK
   =============================== */
selector {
  display: flex;
  flex-direction: column;
  gap: 30px;
  padding: 30px 20px;

  /* background kotak-kotak */
  background-color: #f9fafc;
  background-image:
    linear-gradient(0deg, #e0e3eb 1px, transparent 1px),
    linear-gradient(90deg, #e0e3eb 1px, transparent 1px);
  background-size: 40px 40px; /* ukuran tiap kotak */
}

/* ===============================
   POST BAR FULL WIDTH
   =============================== */
selector .elementor-post {
  display: flex;
  flex-direction: row;
  background: #ffffff;
  border-radius: 16px;
  overflow: hidden;
  box-shadow: 0 12px 25px rgba(0,0,0,0.08), 0 6px 10px rgba(0,0,0,0.05);
  transition: transform 0.35s ease, box-shadow 0.35s ease, background 0.35s ease;
  border-left: 6px solid #0073e6;
}

/* ===============================
   HOVER EFFECT POST
   =============================== */
selector .elementor-post:hover {
  transform: translateY(-8px);
  box-shadow: 0 28px 60px rgba(0,0,0,0.2), 0 12px 20px rgba(0,0,0,0.12);
  background: linear-gradient(90deg, #f7f9fc, #f0f4fb);
  border-left-color: #00c0ff;
}

/* ===============================
   THUMBNAIL LEFT
   =============================== */
selector .elementor-post__thumbnail {
  flex: 0 0 220px;
  height: 100%;
  overflow: hidden;
  border-right: 1px solid #e2e6eb;
  position: relative;
  border-radius: 0 0 0 16px;
}

selector .elementor-post__thumbnail img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.45s ease, filter 0.45s ease, box-shadow 0.45s ease;
}

selector .elementor-post:hover .elementor-post__thumbnail img {
  transform: scale(1.1) rotate(0.5deg);
  filter: brightness(1.15);
  box-shadow: 0 6px 20px rgba(0,0,0,0.15);
}

/* ===============================
   KONTEN POST RIGHT
   =============================== */
selector .elementor-post__text {
  flex: 1;
  padding: 20px 25px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

/* ===============================
   JUDUL POST
   =============================== */
selector .elementor-post__title {
  font-family: 'Poppins', sans-serif;
  font-weight: 700;
  font-size: 1.4rem;
  color: #222;
  margin: 0 0 10px 0;
  line-height: 1.3em;
  transition: color 0.3s ease, text-shadow 0.3s ease;
}

selector .elementor-post__title:hover {
  color: #0073e6;
  text-shadow: 0 3px 8px rgba(0,115,230,0.3);
}

/* ===============================
   EXCERPT / RINGKASAN 3 BARIS
   =============================== */
selector .elementor-post__excerpt {
  font-family: 'Roboto', sans-serif;
  font-size: 0.95rem;
  color: #555;
  margin: 0 0 16px 0;
  line-height: 1.5em;
  display: -webkit-box;
  -webkit-line-clamp: 3; 
  -webkit-box-orient: vertical;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* ===============================
   READ MORE BUTTON
   =============================== */
selector .elementor-post__read-more {
  align-self: flex-start;
  padding: 8px 20px;
  background: linear-gradient(135deg, #0073e6, #00c0ff);
  color: #fff;
  border-radius: 8px;
  font-weight: 600;
  text-decoration: none;
  transition: all 0.35s ease;
  box-shadow: 0 6px 18px rgba(0,0,0,0.15);
}

selector .elementor-post__read-more:hover {
  background: linear-gradient(135deg, #005bb5, #0073e6);
  transform: translateY(-3px) scale(1.03);
  box-shadow: 0 10px 28px rgba(0,0,0,0.25);
}

/* ===============================
   RESPONSIVE MOBILE
   =============================== */
@media (max-width: 768px) {
  selector .elementor-post {
    flex-direction: column;
    border-left: none;
    border-radius: 14px;
  }

  selector .elementor-post__thumbnail {
    width: 100%;
    height: 200px;
    border-right: none;
    border-bottom: 1px solid #e2e6eb;
    border-radius: 14px 14px 0 0;
  }
}

/* ===============================
   LOAD MORE / LIHAT SEMUA POST
   =============================== */

/* Sembunyikan post ke-10 ke atas */
selector .elementor-post:nth-child(n+10) {
  display: none;
}

/* Tombol Load More */
selector .load-more-posts {
  display: inline-block;
  margin: 20px 0 0 auto;
  padding: 12px 28px;
  background: linear-gradient(135deg, #0073e6, #00c0ff);
  color: #fff;
  font-weight: 600;
  border-radius: 12px;
  cursor: pointer;
  box-shadow: 0 6px 18px rgba(0,0,0,0.15);
  transition: all 0.35s ease;
  font-family: 'Poppins', sans-serif;
}

selector .load-more-posts:hover {
  background: linear-gradient(135deg, #005bb5, #0073e6);
  transform: translateY(-3px) scale(1.03);
  box-shadow: 0 10px 28px rgba(0,0,0,0.25);
