<html lang="id">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>PMII News - Footer</title>

<!-- Link Font Awesome untuk ikon sosial media -->
<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.2/css/all.min.css" integrity="sha512-..." crossorigin="anonymous" referrerpolicy="no-referrer" />

<style>
:root{
  --blue-dark:#061a33;
  --blue:#0b3c78;
  --blue-light:#0f62c4;
  --yellow:#f5c400;
  --content-max:1200px;
}

*{
  box-sizing:border-box;
  font-family:'Segoe UI',system-ui,sans-serif;
  margin:0;
  padding:0;
  transition: all 0.3s ease;
}

/* FULL BLEED */
.full-bleed{
  width:100vw;
  position:relative;
  left:50%;
  margin-left:-50vw;
}

/* ===== FOOTER ===== */
footer{
  background:linear-gradient(135deg,var(--blue-dark),var(--blue-light));
  color:#fff;
  padding:40px 20px 20px 20px;
  position:relative;
  overflow:hidden;
}

footer .inner{
  max-width:var(--content-max);
  margin:auto;
  display:flex;
  flex-wrap:wrap;
  justify-content:space-between;
  align-items:center;
  gap:20px;
}

/* LEFT SIDE - BRAND */
footer .brand{
  font-size:18px;
  font-weight:700;
  color:var(--yellow);
}

footer .brand span{
  display:block;
  font-weight:400;
  color:#fff;
  margin-top:5px;
}

/* RIGHT SIDE - SOCIAL ICONS */
footer .social-icons{
  display:flex;
  gap:20px;
}

footer .social-icons a{
  display:flex;
  align-items:center;
  justify-content:center;
  width:40px;
  height:40px;
  border-radius:50%;
  background:rgba(255,255,255,0.1);
  color:#fff;
  font-size:18px;
  text-decoration:none;
  transition: all 0.3s ease;
}

footer .social-icons a:hover{
  background:var(--yellow);
  color:var(--blue-dark);
  transform:scale(1.2);
}

/* BOTTOM COPYRIGHT */
footer .bottom{
  width:100%;
  text-align:center;
  margin-top:30px;
  font-size:13px;
  color:#bbb;
}

/* Responsive */
@media(max-width:768px){
  footer .inner{
    flex-direction:column;
    text-align:center;
  }
  footer .social-icons{
    margin-top:15px;
  }
}
</style>
</head>

<body>

<footer class="full-bleed">
  <div class="inner">
    <!-- LEFT SIDE BRAND -->
    <div class="brand">
      PMII News
      <span>— Biru Pergerakan, Kuning Perjuangan</span>
    </div>

    <!-- RIGHT SIDE SOCIAL ICONS -->
    <div class="social-icons">
      <a href="#" aria-label="Facebook"><i class="fab fa-facebook-f"></i></a>
      <a href="#" aria-label="Instagram"><i class="fab fa-instagram"></i></a>
      <a href="#" aria-label="Twitter"><i class="fab fa-twitter"></i></a>
      <a href="#" aria-label="YouTube"><i class="fab fa-youtube"></i></a>
    </div>

    <!-- BOTTOM COPYRIGHT -->
    <div class="bottom">
      © 2026 PMII News. Semua hak cipta dilindungi.
    </div>
  </div>
</footer>

</body>
</html>
