					<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Header Premium Interactive</title>

<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css">
<link href="https://fonts.googleapis.com/css2?family=Montserrat:wght@400;600;700;800&family=Playfair+Display:wght@600;700&display=swap" rel="stylesheet">

<style>
/* ================= GLOBAL ================= */
html, body{
  margin:0;
  padding:0;
  font-family:'Montserrat',sans-serif;
  background:#081a33;
  overflow-x:hidden;
}
*{ box-sizing:border-box; }

.full-header{
  width:100vw;
  position:relative;
  left:50%;
  transform:translateX(-50%);
  overflow:hidden;
}

/* TEXTURE */
.full-header::before{
  content:"";
  position:absolute;
  inset:0;
  background:
    radial-gradient(circle at 20% 30%, rgba(255,215,0,.15), transparent 40%),
    radial-gradient(circle at 80% 70%, rgba(0,60,143,.25), transparent 40%);
  pointer-events:none;
}
.full-header::after{
  content:"";
  position:absolute;
  inset:0;
  background:url("https://www.transparenttextures.com/patterns/asfalt-dark.png");
  opacity:.08;
  pointer-events:none;
}

/* ================= TOP BAR ================= */
.top-bar{
  background:linear-gradient(90deg,#ffd000,#ffea00,#ffd000);
  padding:12px 6%;
  display:flex;
  justify-content:flex-end;
  gap:30px;
  font-size:12px;
  font-weight:700;
  letter-spacing:1px;
}
.top-bar a{
  text-decoration:none;
  color:#002b5c;
  position:relative;
}
.top-bar a:not(:last-child)::after{
  content:"";
  position:absolute;
  right:-15px;
  top:50%;
  transform:translateY(-50%);
  width:2px;
  height:14px;
  background:rgba(0,43,92,.4);
}

/* ================= HEADER ================= */
.header{
  background:linear-gradient(160deg,#002b5c,#001a3a);
  padding:30px 6%;
  display:flex;
  justify-content:space-between;
  align-items:center;
  box-shadow:0 20px 40px rgba(0,0,0,.4);
}
.logo img{ height:130px; }

.right{
  display:flex;
  align-items:center;
  gap:40px;
}

/* ===== SEARCH WORDPRESS (tetap terhubung) ===== */
.search{
  background:rgba(255,255,255,.06);
  border:1px solid rgba(255,255,255,.15);
  border-radius:50px;
  padding:14px 25px;
  width:420px;
  display:flex;
  align-items:center;
  gap:15px;
}
.search input{
  background:transparent;
  border:none;
  outline:none;
  color:#fff;
  width:100%;
  font-size:14px;
}
.search button, .search i{
  color:#ffd000;
  font-size:16px;
  cursor:pointer;
  border:none;
  background:none;
}

/* ===== LIVESTREAM ===== */
.live{
  color:#ffd000;
  font-weight:700;
  letter-spacing:1px;
  display:flex;
  align-items:center;
  gap:10px;
  position:relative;
  animation:liveFloat 3s ease-in-out infinite;
}
.live i{
  color:#ff2e2e;
  animation:pulseLive 1.5s infinite;
  text-shadow:0 0 10px rgba(255,0,0,.7);
}
.live::before{
  content:"";
  width:10px;
  height:10px;
  background:#ff2e2e;
  border-radius:50%;
  box-shadow:0 0 0 rgba(255,0,0,.7);
  animation:blinkDot 1.5s infinite;
}

@keyframes pulseLive{
  0%{ transform:scale(1); opacity:1; }
  50%{ transform:scale(1.25); opacity:.6; }
  100%{ transform:scale(1); opacity:1; }
}
@keyframes blinkDot{
  0%{ box-shadow:0 0 0 0 rgba(255,0,0,.7); }
  70%{ box-shadow:0 0 0 12px rgba(255,0,0,0); }
  100%{ box-shadow:0 0 0 0 rgba(255,0,0,0); }
}
@keyframes liveFloat{
  0%{ transform:translateY(0); }
  50%{ transform:translateY(-3px); }
  100%{ transform:translateY(0); }
}

/* ================= NAVBAR ================= */
.navbar{
  background:linear-gradient(90deg,#003c8f,#002b5c);
  padding:20px 0;
  display:flex;
  justify-content:center;
  position:relative;
  box-shadow:0 15px 30px rgba(0,0,0,.4);
}
.navbar::before{
  content:"";
  position:absolute;
  left:0;
  top:0;
  width:280px;
  height:100%;
  background:linear-gradient(135deg,#ffd000,#ffea00);
  clip-path:polygon(0 0,100% 0,80% 100%,0% 100%);
}

/* ===== LEFT NEWS BAR ===== */
.left-bar{
  position:absolute;
  left:35px;
  top:50%;
  transform:translateY(-50%);
  z-index:3;
  perspective:800px;
}
.left-bar span{
  display:inline-block;
  font-family:'Playfair Display',serif;
  font-weight:800;
  font-size:15px;
  letter-spacing:1.5px;
  padding:6px 22px;
  color:#002b5c;
  background:linear-gradient(145deg,#ffd000,#ffea00);
  border-radius:40px;
  transform:rotateX(15deg) rotateY(-12deg);
  box-shadow: 0 3px 0 #c9a600, 0 6px 0 #b39200, 0 12px 20px rgba(0,0,0,.45);
  position:relative;
  overflow:hidden;
  animation:floatNews 3s ease-in-out infinite;
}
.left-bar span::after{
  content:"";
  position:absolute;
  top:0; left:-100%;
  width:100%; height:100%;
  background:linear-gradient(120deg,transparent,rgba(255,255,255,.6),transparent);
  animation:shineMove 3s infinite;
}

@keyframes floatNews{
  0%{ transform:rotateX(15deg) rotateY(-12deg) translateY(0); }
  50%{ transform:rotateX(15deg) rotateY(-12deg) translateY(-6px); }
  100%{ transform:rotateX(15deg) rotateY(-12deg) translateY(0); }
}
@keyframes shineMove{
  0%{ left:-100%; }
  100%{ left:120%; }
}

/* ===== MENU ===== */
.menu{
  display:flex;
  gap:50px;
  z-index:2;
  margin-left:20px;
}
.menu a{
  text-decoration:none;
  color:#fff;
  font-weight:700;
  letter-spacing:1px;
  padding:5px 0;
  position:relative;
  transition:.3s;
}
.menu a:hover{ color:#ffd000; }
.menu a:not(:last-child)::after{
  content:"";
  position:absolute;
  right:-25px;
  top:50%;
  transform:translateY(-50%);
  width:1px;
  height:18px;
  background:rgba(255,255,255,.3);
}

/* SOCIAL */
.social{
  position:absolute;
  right:6%;
  display:flex;
  gap:22px;
  z-index:2;
}
.social a{
  color:#fff;
  font-size:18px;
  transition:.3s;
}
.social a:hover{
  color:#ffd000;
  transform:translateY(-4px);
}
</style>
</head>
<body>

<div class="full-header">

  <div class="top-bar">
    <a href="#">PMII PB</a>
    <a href="#">PMII CABANG</a>
    <a href="#">PMII KOMIS</a>
    <a href="#">RAYON</a>
  </div>

  <div class="header">
    <div class="logo">
      <img src="https://www.pmii.id/assets/frontend/images/apple-touch-icon2.png">
    </div>

    <div class="right">

      <!-- SEARCH TERHUBUNG WORDPRESS -->
      <form role="search" method="get" action="/">
        <div class="search">
          <input type="search" name="s" placeholder="Cari berita, artikel, kegiatan..." required>
          <button type="submit"><i class="fa-solid fa-magnifying-glass"></i></button>
        </div>
      </form>

      <div class="live">
        <i class="fa-solid fa-broadcast-tower"></i>
        LIVESTREAM
      </div>

    </div>
  </div>

  <div class="navbar">

    <div class="left-bar">
      <span>PERGERAKAN NEWS</span>
    </div>

    <div class="menu">
