<title>Hologram Futuristik Banner Animatif</title>
<link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;600;800&display=swap" rel="stylesheet">
<style>
*{margin:0;padding:0;box-sizing:border-box;}
body{background:#0b1e34;font-family:'Poppins',sans-serif;overflow:hidden;}

/* HERO FULL BLEED BANNER */
.hero{
  position:relative;
  width:100vw;
  left:50%;
  transform:translateX(-50%);
  aspect-ratio:2048/589; /* ukuran tetap seperti sebelumnya */
  overflow:hidden;
}

/* GRID + BACKGROUND */
.hero::before{
  content:""; position:absolute; inset:0;
  background: linear-gradient(to right, rgba(6,18,35,0.98) 0%, rgba(8,25,45,0.85) 35%, rgba(12,40,70,0.65) 60%, rgba(15,50,90,0.45) 80%, rgba(20,60,110,0.35) 100%), url("https://i.ibb.co/tNkLbXV/r-b.png");
  background-size:cover; background-position:center; z-index:1;
  animation: backgroundZoom 25s linear infinite alternate;
}
.hero::after{
  content:""; position:absolute; top:0; right:0; width:55%; height:100%; z-index:2;
  background-image: linear-gradient(rgba(255,255,255,0.06) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,0.06) 1px, transparent 1px);
  background-size:14px 14px;
  mask-image:linear-gradient(to left, rgba(0,0,0,1) 65%, rgba(0,0,0,0));
  animation: gridMove 30s linear infinite;
}

/* HERO CONTENT */
.hero-content{position:relative; z-index:3; height:100%; max-width:1200px; margin:auto; padding:0 5%; display:flex; flex-direction:column; justify-content:center; color:white; overflow:hidden;}
.hero-content h1,h3,p{opacity:0; transform:translateY(30px); animation:fadeUp 1s forwards;}
.hero-content h1{font-size:clamp(32px,4vw,64px);font-weight:800;letter-spacing:2px;margin-bottom:12px;animation-delay:0.3s;}
.hero-content h3{font-size:clamp(20px,2.5vw,32px);font-weight:600;letter-spacing:1px;margin-bottom:8px;animation-delay:0.6s;}
.hero-content p{font-size:clamp(14px,1.2vw,20px);opacity:.9;animation-delay:0.9s;}

/* HOLOGRAM FUTURISTIK RANDOM */
.hologram{
  position:absolute;
  top:50%;
  left:50%;
  transform:translate(-50%,-50%) scale(0.6);
  width:450px;
  height:450px;
  z-index:4;
}
.hologram svg polygon, .hologram svg circle, .hologram svg line, .hologram svg polyline{
  fill: rgba(0,255,255,0.05);
  stroke: rgba(0,255,255,0.6);
  stroke-width:1.5;
}
.hologram svg line, .hologram svg polyline{stroke-dasharray:4 4; animation:lineMove 3s linear infinite;}
.layer{transform-origin:100px 100px; animation:rotateLayer linear infinite;}
.layer1{animation-duration:5s;opacity:0.5;}
.layer2{animation-duration:6s;opacity:0.45;}
.layer3{animation-duration:7s;opacity:0.4;}
.layer4{animation-duration:4.5s;opacity:0.55;}
.layer5{animation-duration:6.5s;opacity:0.35;}
.layer6{animation-duration:5.5s;opacity:0.5;}
.layer7{animation-duration:8s;opacity:0.4;}
.layer8{animation-duration:7.5s;opacity:0.45;}
.layer9{animation-duration:5.8s;opacity:0.35;}
.layer10{animation-duration:9s;opacity:0.5;}

/* ANIMASI */
@keyframes fadeUp{0%{opacity:0;transform:translateY(30px);}100%{opacity:1;transform:translateY(0);}}
@keyframes gridMove{0%{background-position:0 0,0 0;}100%{background-position:100px 0,-100px 0;}}
@keyframes backgroundZoom{0%{transform: scale(1);}50%{transform: scale(1.05);}100%{transform: scale(1);}}
@keyframes lineMove{0%{stroke-dashoffset:0;}100%{stroke-dashoffset:100;}}
@keyframes rotateLayer{0%{transform:rotate(0deg) scale(0.8);}100%{transform:rotate(360deg) scale(1.1);}}
</style>
</head>
<body>

