<html lang="id">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>PMII STAIM KENDAL | OMEGA LEVEL UI</title>

    <link href="https://fonts.googleapis.com/css2?family=Syne:wght@800&family=Outfit:wght@300;400;600;800&display=swap" rel="stylesheet">

    <style>
        :root {
            --black: #030303;
            --white: #ffffff;
            --gold: #ffbd16;
            --accent: #ff3c00;
            --glass: rgba(255, 255, 255, 0.02);
            --border: rgba(255, 255, 255, 0.07);
        }

        * { margin: 0; padding: 0; box-sizing: border-box; cursor: none; }

        body {
            background-color: var(--black);
            color: var(--white);
            font-family: 'Outfit', sans-serif;
            overflow-x: hidden;
            background: radial-gradient(circle at 50% 50%, #0a0a0a 0%, #030303 100%);
        }

        /* --- FILM GRAIN OVERLAY --- */
        body::after {
            content: "";
            position: fixed; top: 0; left: 0; width: 100%; height: 100%;
            background-image: url('https://grainy-gradients.vercel.app/noise.svg');
            opacity: 0.04; pointer-events: none; z-index: 999;
        }

        /* --- ADVANCED CURSOR --- */
        #cursor {
            position: fixed; width: 10px; height: 10px; background: var(--white);
            border-radius: 50%; pointer-events: none; z-index: 10000;
            mix-blend-mode: difference; transition: transform 0.15s ease-out;
        }

        #cursor-follower {
            position: fixed; width: 40px; height: 40px; border: 1px solid var(--gold);
            border-radius: 50%; pointer-events: none; z-index: 9999;
            transition: all 0.3s cubic-bezier(0.23, 1, 0.32, 1);
        }

        .container { max-width: 1400px; margin: auto; padding: 100px 30px; }

        /* --- SPATIAL HEADER --- */
        .spatial-hero {
            display: grid; grid-template-columns: 1.2fr 0.8fr; gap: 80px;
            align-items: center; margin-bottom: 150px;
        }

        /* --- TEXT MASKING & GLITCH --- */
        .hero-title {
            font-family: 'Syne', sans-serif; font-size: clamp(3rem, 7vw, 6rem);
            line-height: 0.9; letter-spacing: -4px; text-transform: uppercase;
            background: linear-gradient(45deg, #fff 30%, var(--gold), var(--accent), #fff 70%);
            background-size: 200% auto;
            -webkit-background-clip: text; -webkit-text-fill-color: transparent;
            animation: shine 5s linear infinite;
        }

        @keyframes shine { to { background-position: 200% center; } }

        /* --- 3D INTERACTIVE IMAGE --- */
        .tilt-box {
            position: relative; width: 100%; height: 600px;
            perspective: 1000px; transform-style: preserve-3d;
        }

        .tilt-card {
            width: 100%; height: 100%; border-radius: 40px;
            background: url('https://i.ibb.co/ZzR3bLVj/bjsanmklshdugqehas.png') center/cover;
            border: 1px solid var(--border);
            box-shadow: 0 50px 100px rgba(0,0,0,0.5);
            transition: transform 0.1s;
        }

        /* --- OMEGA BENTO GRID --- */
        .omega-grid {
            display: grid; grid-template-columns: repeat(3, 1fr); gap: 30px;
        }

        .omega-card {
            background: var(--glass); backdrop-filter: blur(40px);
            padding: 40px; border-radius: 50px; border: 1px solid var(--border);
            transition: 0.5s cubic-bezier(0.2, 1, 0.3, 1);
            text-decoration: none; color: inherit;
        }

        .omega-card:hover {
            background: rgba(255, 255, 255, 0.05);
            transform: translateY(-20px) scale(1.02);
            border-color: var(--gold);
        }

        .omega-card img {
            width: 100%; height: 200px; border-radius: 30px;
            object-fit: cover; margin-bottom: 30px; filter: saturate(0);
            transition: 0.5s;
        }

        .omega-card:hover img { filter: saturate(1.2); }

        .omega-card h3 {
            font-family: 'Syne', sans-serif; font-size: 1.8rem;
            margin-bottom: 15px; color: #eee;
        }

        /* --- NEON BADGE --- */
        .badge-omega {
            display: inline-block; padding: 8px 20px; border-radius: 100px;
            background: rgba(255, 189, 22, 0.1); color: var(--gold);
            font-size: 10px; font-weight: 800; letter-spacing: 3px;
            text-transform: uppercase; border: 1px solid var(--gold);
            margin-bottom: 25px;
        }

        /* --- SIDEBAR MINIMALIS --- */
        .sidebar-omega {
            background: var(--glass); padding: 40px; border-radius: 50px;
            border: 1px solid var(--border); height: fit-content;
        }

        .trending-row {
            display: block; text-decoration: none; color: #888;
            padding: 20px 0; border-bottom: 1px solid var(--border);
            transition: 0.3s;
        }

        .trending-row:hover { color: var(--white); padding-left: 10px; }

        .trending-row span { font-size: 11px; color: var(--accent); font-weight: 800; }

        @media (max-width: 1100px) {
            .spatial-hero { grid-template-columns: 1fr; }
            .omega-grid { grid-template-columns: 1fr; }
        }
    </style>
</head>
<body>

    <div id="cursor"></div>
    <div id="cursor-follower"></div>

    <div class="container">
        <section class="spatial-hero">
            <div class="hero-content">
                <div class="badge-omega">Strategic News v.3.0</div>
                <h1 class="hero-title">PMII STAIM<br>KENDAL</h1>
                <p style="font-size: 1.2rem; color: #888; margin-top: 30px; max-width: 500px;">
                    Membangun narasi baru dalam gerakan mahasiswa melalui konsolidasi intelektual yang radikal dan progresif.
                </p>
                <div style="margin-top: 40px; display: flex; gap: 20px;">
                    <div style="width: 50px; height: 1px; background: var(--gold); align-self: center;"></div>
                    <span style="font-size: 12px; letter-spacing: 2px;">SCROLL TO EXPLORE</span>
                </div>
            </div>

            <div class="tilt-box" id="tilt">
                <div class="tilt-card"></div>
            </div>
        </section>

        <div class="omega-grid">
            <a href="#" class="omega-card">
                <img src="https://i.ibb.co/4nbQsgSc/Chat-GPT-Image-Jan-27-2026-02-10-16-PM.png" alt="1">
                <h3>Sahabat Literasi</h3>
                <p style="color: #666;">Gerakan membaca sebagai fondasi gerakan intelektual kader masa kini.</p>
            </a>

            <a href="#" class="omega-card">
                <img src="https://assets.pikiran-rakyat.com/crop/0x1283:3000x3345/720x0/webp/photo/2026/01/24/3220267689.jpg" alt="2">
                <h3>Regenerasi Total</h3>
                <p style="color: #666;">Melangkah lebih jauh dengan kepengurusan yang solid dan visioner.</p>
            </a>

            <div class="sidebar-omega">
                <h4 style="font-family: 'Syne'; margin-bottom: 20px; letter-spacing: 2px;">TERPOPULER</h4>
                <a href="#" class="trending-row">
                    <span>01 / ANALISIS</span>
                    <h4 style="margin-top: 5px;">Akselerasi Kaderisasi Digital</h4>
                </a>
                <a href="#" class="trending-row">
                    <span>02 / OPINI</span>
                    <h4 style="margin-top: 5px;">Retorika vs Realita Mahasiswa</h4>
                </a>
                <button style="width: 100%; padding: 20px; margin-top: 30px; background: var(--gold); border: none; border-radius: 20px; font-weight: 800; font-family: 'Syne';">GABUNG SEKARANG</button>
            </div>
        </div>
    </div>

    <script>
        const cursor = document.getElementById('cursor');
        const follower = document.getElementById('cursor-follower');
        const tiltCard = document.querySelector('.tilt-card');

        // Advanced Mouse Follower
        document.addEventListener('mousemove', (e) => {
            cursor.style.left = e.clientX + 'px';
            cursor.style.top = e.clientY + 'px';

            setTimeout(() => {
                follower.style.left = (e.clientX - 15) + 'px';
                follower.style.top = (e.clientY - 15) + 'px';
            }, 50);

            // 3D Tilt Calculation
            const x = (window.innerWidth / 2 - e.clientX) / 20;
            const y = (window.innerHeight / 2 - e.clientY) / 20;
            tiltCard.style.transform = `rotateY(${x}deg) rotateX(${-y}deg)`;
        });

        // Magnetic Effect on Cards
        document.querySelectorAll('.omega-card, button').forEach(el => {
            el.addEventListener('mouseenter', () => {
                follower.style.transform = 'scale(2.5)';
                follower.style.background = 'rgba(255, 189, 22, 0.1)';
                cursor.style.transform = 'scale(0.5)';
            });
            el.addEventListener('mouseleave', () => {
                follower.style.transform = 'scale(1)';
                follower.style.background = 'transparent';
                cursor.style.transform = 'scale(1)';
            });
        });
    </script>
</body>
