					<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="UTF-8" />
<title>PMII Logo Bar Compact Interaktif</title>
<style>
  * { box-sizing: border-box; }
  body {
    margin: 0;
    padding: 0;
    background: #f5f7fa;
    font-family: "Segoe UI", Tahoma, Geneva, Verdana, sans-serif;
    overflow-x: hidden;
  }

  /* MAIN WRAPPER */
  .image-bar-wrapper {
    max-width: 900px;
    margin: 20px auto;
    padding: 15px 20px;
    border-radius: 15px;
    background: #0b3c78; /* biru PMII */
    box-shadow: 0 6px 15px rgba(0,0,0,0.15);
    position: relative;
  }

  /* LOGO BAR */
  .image-bar {
    display: flex;
    justify-content: space-around; /* biar 3 logo jelas terlihat */
    align-items: center;
    gap: 30px;
    position: relative;
    z-index: 2;
  }

  .item {
    width: 120px;
    cursor: pointer;
    text-align: center;
    transition: transform 0.25s ease;
  }
  .item:hover { transform: translateY(-6px) scale(1.05); }

  /* GLOW EFFECT */
  .glitch-box {
    position: relative;
    border-radius: 12px;
    overflow: hidden;
    box-shadow: 0 6px 15px rgba(0, 120, 255, 0.3);
    transition: transform .5s ease;
  }

  .glitch-box img {
    width: 100%;
    border-radius: 10px;
    display: block;
  }

  /* INDICATOR */
  .indicator {
    margin: 8px auto 0;
    width: 40px;
    height: 4px;
    border-radius: 3px;
    background: rgba(255,255,255,0.7);
    transition: 0.3s ease;
  }
  .item.active .indicator {
    background: #f5c400; /* kuning PMII */
    box-shadow: 0 0 8px #f5c400;
  }

  /* CLICK EFFECT */
  .flip { transform: rotateY(180deg); }
  .fullscreen-pop {
    position: fixed;
    inset: 0;
    margin: auto;
    width: 70vw !important;
    height: auto !important;
    z-index: 9999;
    transform: scale(1.3);
    transition: transform 0.6s ease;
  }

  /* RESPONSIVE */
  @media(max-width:768px){
    .image-bar { gap: 20px; justify-content: space-between; }
    .item { width: 90px; }
  }
</style>
</head>

<body>

<div class="image-bar-wrapper">
  <div class="image-bar">

    <!-- LEFT LOGO -->
    <div class="item">
   <div class="glitch-box" data-link="https://pmiikomiskenda.42web.io/">
        <img src="https://i.ibb.co/8n4rJL3D/logoiguy.png" alt="Logo PMII 1">
      </div>
      <div class="indicator"></div>
    </div>

    <!-- CENTER LOGO -->
    <div class="item">
      <div class="glitch-box" data-link="https://pmiikomiskenda.42web.io/halaman-2/">
        <img src="https://i.ibb.co/0yBKwGP4/bgh.jpg" alt="Logo PMII 2">
      </div>
      <div class="indicator"></div>
    </div>

    <!-- RIGHT LOGO -->
    <div class="item active">
      <div class="glitch-box" data-link="">
        <img src="https://i.ibb.co.com/fG9t9T2w/nsuwhoayuhkjnssjsss.png" alt="Logo PMII 3">
      </div>
      <div class="indicator"></div>
    </div>

  </div>
</div>

<script>
const items = document.querySelectorAll(".item");
const boxes = document.querySelectorAll(".glitch-box");

items.forEach((item, index) => {
  const box = item.querySelector(".glitch-box");

  // Ketika logo diklik
  box.addEventListener("click", () => {
    // Hapus active dari semua item
    items.forEach(i => i.classList.remove("active"));
    // Tambahkan active ke yang diklik
    item.classList.add("active");

    // Animasi klik
    box.classList.add("flip");
    setTimeout(() => box.classList.add("fullscreen-pop"), 400);

    // Redirect jika ada link
    setTimeout(() => {
      if(box.dataset.link) window.location.href = box.dataset.link;
    }, 900);
  });
});
</script>

</body>
</html>
