<html lang="id">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Peringatan Desktop</title>
<link href="https://fonts.googleapis.com/css2?family=Orbitron:wght@700&family=Inter:wght@400;600&display=swap" rel="stylesheet">
<style>
body.no-scroll { overflow: hidden; margin:0; }

/* Fullscreen overlay */
#desktop-warning {
  position: fixed;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(-45deg, #0f0c29, #302b63, #24243e, #0f0c29);
  background-size: 400% 400%;
  animation: gradientBG 15s ease infinite;
  z-index: 9999;
  font-family: 'Inter', sans-serif;
}

/* Floating card */
#desktop-warning .card {
  background: rgba(255,255,255,0.07);
  backdrop-filter: blur(18px) saturate(180%);
  border-radius: 20px;
  padding: 40px 30px;
  text-align: center;
  max-width: 400px;
  box-shadow: 0 15px 40px rgba(0,0,0,0.5);
  transition: transform 0.4s ease;
}

/* Icon */
#desktop-warning .icon {
  font-family: 'Orbitron', sans-serif;
  font-size: 80px;
  color: #ff6b81;
  margin-bottom: 20px;
  animation: float 2.5s ease-in-out infinite;
}

/* Headline */
#desktop-warning h1 {
  font-family: 'Orbitron', sans-serif;
  font-size: 1.9rem;
  color: #fff;
  margin-bottom: 15px;
  line-height: 1.2;
}

/* Text */
#desktop-warning p {
  font-size: 1rem;
  color: rgba(255,255,255,0.85);
  margin-bottom: 25px;
  line-height: 1.5;
  text-align: left;
}

/* Button */
#desktop-warning button {
  padding: 12px 30px;
  border: none;
  border-radius: 50px;
  font-size: 1rem;
  font-weight: 600;
  color: #fff;
  background: linear-gradient(135deg, #ff6b81, #ff4757);
  cursor: pointer;
  box-shadow: 0 0 20px rgba(255,107,129,0.5);
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}
#desktop-warning button:hover {
  transform: scale(1.05);
  box-shadow: 0 0 35px rgba(255,107,129,0.8);
}

/* Animations */
@keyframes float {
  0%,100% { transform: translateY(0); }
  50% { transform: translateY(-15px); }
}
@keyframes gradientBG {
  0%{background-position:0% 50%}
  50%{background-position:100% 50%}
  100%{background-position:0% 50%}
}

/* Responsive */
@media (max-width: 768px) {
  #desktop-warning .card { padding: 30px 20px; }
  #desktop-warning .icon { font-size: 60px; }
  #desktop-warning h1 { font-size: 1.6rem; }
  #desktop-warning p { font-size: 0.95rem; }
}
</style>
</head>
<body>

<div id="desktop-warning">
  <div class="card" id="warning-card">
    <div class="icon">🖥️</div>
    <h1 id="warning-title">Hanya Bisa Diakses di Desktop</h1>
    <p id="warning-text">Website ini didesain khusus untuk tampilan desktop. Gunakan komputer atau laptop untuk pengalaman penuh. Untuk lite version di HP, aktifkan mode desktop di browser.</p>
    <button onclick="showGuide()">Cara Aktifkan Mode Desktop</button>
  </div>
</div>

<script>
function isMobile() {
  return /Mobi|Android|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);
}

window.addEventListener('load', () => {
  const overlay = document.getElementById('desktop-warning');
  if (isMobile()) {
    document.body.classList.add('no-scroll');
    overlay.style.display = 'flex';
  } else {
    overlay.style.display = 'none';
  }
});

// Tampilkan panduan singkat
function showGuide() {
  const title = document.getElementById('warning-title');
  const text = document.getElementById('warning-text');
  const button = document.querySelector('#desktop-warning button');

  title.textContent = "Panduan Mode Desktop di HP";
  text.innerHTML = `
  1️⃣ Buka menu browser (ikon titik tiga / garis).<br>
  2️⃣ Pilih "Situs Desktop" / "Desktop Site".<br>
  3️⃣ Halaman akan menampilkan versi desktop lite.`;
  button.textContent = "Tutup Peringatan";
  button.onclick = hideWarning;
}

// Tutup overlay
function hideWarning() {
  const overlay = document.getElementById('desktop-warning');
  overlay.style.opacity = 0;
  setTimeout(() => {
    overlay.style.display = 'none';
    document.body.classList.remove('no-scroll');
  }, 500);
}
</script>

</body>
</html>				</div>
				</div>
					</div>
				</div>
