<title>PMII STAIM Kendal | News</title>

<link href="https://fonts.googleapis.com/css2?family=Raleway:wght@300;500;700;900&display=swap" rel="stylesheet">

<style>
:root{
  --blue:#0b3c78;
  --yellow:#f4c400;
  --dark:#070b16;
  --bg:#f4f6fb;
}

*{margin:0;padding:0;box-sizing:border-box;font-family:'Raleway',sans-serif}

body{
  background:var(--bg);
  overflow-x:hidden;
  color:#111;
}

/* ================= NOISE FILM ================= */
body::before{
  content:'';
  position:fixed;
  inset:0;
  background:url("https://grainy-gradients.vercel.app/noise.svg");
  opacity:.04;
  z-index:999;
  pointer-events:none;
}

/* ================= CONTAINER ================= */
.container{
  max-width:1400px;
  margin:auto;
  padding:50px 25px;
  display:grid;
  grid-template-columns:2.7fr 1fr;
  gap:45px;
}

/* ================= HERO ================= */
.hero{
  position:relative;
  height:520px;
  border-radius:22px;
  overflow:hidden;
  background:#000;
}

.hero img{
  width:100%;
  height:100%;
  object-fit:cover;
  transform:scale(1.2);
  animation:heroZoom 18s ease-in-out infinite alternate;
}

@keyframes heroZoom{
  from{transform:scale(1.15)}
  to{transform:scale(1.35)}
}

.hero::after{
  content:'';
  position:absolute;
  inset:0;
  background:
    linear-gradient(to top,rgba(7,11,22,.9),rgba(7,11,22,.2)),
    radial-gradient(circle at top right,rgba(244,196,0,.25),transparent 55%);
}

.hero-title{
  position:absolute;
  bottom:40px;
  left:40px;
  right:40px;
  color:#fff;
  z-index:2;
}

.hero-title span{
  font-size:13px;
  letter-spacing:3px;
  color:var(--yellow);
  display:inline-block;
  margin-bottom:10px;
  animation:slideUp .8s ease forwards;
}

.hero-title h1{
  font-size:28px;
  font-weight:900;
  max-width:720px;
  line-height:1.35;
  animation:slideUp 1s ease forwards;
}

@keyframes slideUp{
  from{opacity:0;transform:translateY(30px)}
  to{opacity:1;transform:translateY(0)}
}

/* ================= SECTION ================= */
.section-title{
  margin:55px 0 20px;
  font-size:18px;
  font-weight:900;
  color:var(--blue);
  position:relative;
}

.section-title::after{
  content:'';
  position:absolute;
  bottom:-8px;
  left:0;
  width:70px;
  height:4px;
  background:linear-gradient(90deg,var(--yellow),var(--blue));
  border-radius:5px;
}

/* ================= NEWS ================= */
.news-list{
  background:rgba(255,255,255,.7);
  backdrop-filter:blur(14px);
  border-radius:22px;
  overflow:hidden;
  box-shadow:0 40px 80px rgba(0,0,0,.08);
}

.news-item{
  display:flex;
  gap:22px;
  padding:22px;
  border-bottom:1px solid rgba(0,0,0,.06);
  align-items:center;
  opacity:0;
  transform:translateY(40px);
  transition:.9s cubic-bezier(.16,.8,.28,1);
}

.news-item.show{
  opacity:1;
  transform:translateY(0);
}

.news-item:hover{
  background:rgba(244,196,0,.08);
}

.news-item img{
  width:180px;
  height:105px;
  object-fit:cover;
  border-radius:14px;
  transition:.6s;
}

.news-item:hover img{
  transform:scale(1.12) rotate(.3deg);
}

.news-item h3{
  font-size:15.5px;
  font-weight:700;
  line-height:1.55;
}

/* ================= SIDEBAR ================= */
.sidebar{
  background:rgba(255,255,255,.75);
  backdrop-filter:blur(18px);
  padding:28px;
  border-radius:22px;
  box-shadow:0 40px 80px rgba(0,0,0,.08);
  opacity:0;
  transform:translateX(60px);
  transition:1s cubic-bezier(.16,.8,.28,1);
}

.sidebar.show{
  opacity:1;
  transform:translateX(0);
}

.sidebar h3{
  font-size:17px;
  font-weight:900;
  color:var(--blue);
  margin-bottom:18px;
}

.sidebar li{
  list-style:none;
  padding:12px 0;
  border-bottom:1px dashed rgba(0,0,0,.15);
  position:relative;
}

.sidebar li::before{
  content:'';
  width:7px;
  height:7px;
  background:linear-gradient(45deg,var(--yellow),var(--blue));
  border-radius:50%;
  position:absolute;
  left:-18px;
  top:18px;
}

/* ================= RESPONSIVE ================= */
@media(max-width:900px){
  .container{grid-template-columns:1fr}
  .hero{height:320px}
  .hero-title h1{font-size:20px}
}
</style>
</head>

<body>

<div class="container">

  <div>
    <div class="hero">
      <img src="https://assets.pikiran-rakyat.com/crop/0x1283:3000x3345/720x0/webp/photo/2026/01/24/3220267689.jpg">
      <div class="hero-title">
        <span>PMII STAIM KENDAL</span>
        <h1>Pelantikan PK PMII STAIM Kendal Periode 2025–2026 Berlangsung Khidmat</h1>
      </div>
    </div>

    <div class="section-title">Terkini</div>

    <div class="news-list">
      <div class="news-item">
        <img src="https://assets.pikiran-rakyat.com/crop/0x1283:3000x3345/720x0/webp/photo/2026/01/24/3220267689.jpg">
        <h3>Pelantikan PK PMII STAIM Kendal Resmi Digelar</h3>
      </div>

      <div class="news-item">
        <img src="https://pmiikomiskenda.42web.io/wp-content/uploads/2025/12/even-rtk-01-1024x512.png">
        <h3>RTK PMII STAIM Kendal ke-13 Sukses Diselenggarakan</h3>
      </div>
    </div>
  </div>

  <div class="sidebar">
    <h3>Agenda PMII</h3>
    <ul>
      <li>Pelantikan PK PMII</li>
      <li>RTK PMII ke-13</li>
      <li>Pelatihan Kaderisasi</li>
    </ul>
  </div>

</div>

<script>
const observer = new IntersectionObserver(entries=>{
  entries.forEach(e=>{
    if(e.isIntersecting){
      e.target.classList.add('show');
    }
  });
},{threshold:.15});

document.querySelectorAll('.news-item,.sidebar').forEach(el=>{
  observer.observe(el);
});
</script>

</body>
</html>
