[{"id":"77ca525","elType":"container","settings":{"boxed_width":{"unit":"px","size":1583,"sizes":[]},"margin":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"padding":{"unit":"px","top":"-38","right":"-38","bottom":"-38","left":"-38","isLinked":true},"background_background":"classic","background_color":"#FFF6F6","border_radius":{"unit":"px","top":"15","right":"15","bottom":"15","left":"15","isLinked":true},"box_shadow_box_shadow_type":"yes","box_shadow_box_shadow":{"horizontal":-9,"vertical":9,"blur":10,"spread":0,"color":"rgba(0, 0, 0, 0.78)"},"_title":"Kontainer"},"elements":[{"id":"f5990de","elType":"widget","settings":{"html":"<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>PK PMII STAIM Kendal</title>

<link href="https://fonts.googleapis.com/css2?family=DM+Serif+Display&family=Plus+Jakarta+Sans:wght@400;500;600;700&display=swap" rel="stylesheet">
<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css"/>

<style>

/* ===== RESET ===== */
*{margin:0;padding:0;box-sizing:border-box;}
body{
  font-family:'Plus Jakarta Sans',sans-serif;
  background:#eef3f1;
  overflow-x:hidden;
}

/* ===== HEADER / HERO ===== */
.hero{
  width:100%;
  height:40vh;
  background:#0e1623;
  color:white;
  padding:20px 40px;
  border-radius:0 0 30px 30px;
  position:relative;
  overflow:hidden;
  display:flex;
  flex-direction:column;
  justify-content:space-between;

  /* geser ke atas 100px */
  top: -100px;
}

.hero::before{
  content:"";
  position:absolute;
  width:300px;
  height:300px;
  background:#131d2b;
  border-radius:50%;
  top:-120px;
  right:-120px;
}

.hero::after{
  content:"";
  position:absolute;
  width:250px;
  height:250px;
  background:#182334;
  border-radius:50%;
  bottom:-100px;
  left:-100px;
}

/* ===== NAV ===== */
.top-nav{
  display:flex;
  justify-content:space-between;
  align-items:center;
  position:relative;
  z-index:2;
}

.logo{
  display:flex;
  align-items:center;
  gap:20px;
}

.logo img{
  height:45px;
}

.logo img:nth-child(2){
  height:55px;
}

/* ===== MENU ===== */
.header-menu{
  display:flex;
  align-items:center;
  gap:20px;
}

.header-menu a,
.dropdown-btn{
  color:#fff;
  text-decoration:none;
  font-size:14px;
  display:flex;
  align-items:center;
  gap:8px;
  padding:10px 18px;
  background:#1a2536;
  border-radius:12px;
  transition:.3s;
  cursor:pointer;
  border:none;
}

.header-menu a:hover,
.dropdown-btn:hover{
  background:#22a39f;
}

/* ===== DROPDOWN ===== */
.dropdown{
  position:relative;
}

.dropdown-content{
  position:absolute;
  top:55px;
  left:50%;
  transform:translateX(-50%);
  background:#1a2536;
  border-radius:12px;
  min-width:190px;
  display:flex;
  flex-direction:column;
  padding:8px 0;
  box-shadow:0 15px 30px rgba(0,0,0,.4);

  max-height:0;
  overflow:hidden;
  opacity:0;
  transition:.3s ease;
}

.dropdown.active .dropdown-content{
  max-height:300px;
  opacity:1;
}

.dropdown-content a{
  padding:10px 18px;
  text-decoration:none;
  color:#fff;
  font-size:14px;
}

.dropdown-content a:hover{
  background:#22a39f;
}

/* ICON ROTATE */
.dropdown.active .fa-chevron-down{
  transform:rotate(180deg);
  transition:.3s;
}

/* ===== HERO TEXT ===== */
.hero-content{
  position:relative;
  z-index:2;
}

.hero h1{
  font-family:'DM Serif Display',serif;
  font-size:32px;
  margin-bottom:8px;
}

.hero p{
  font-size:14px;
  opacity:.9;
}

/* ===== SECTION ===== */
.section{
  padding:80px 20px;
  max-width:1200px;
  margin:auto;
}

.section-title{
  font-family:'DM Serif Display',serif;
  font-size:32px;
  margin-bottom:50px;
  text-align:center;
}

.program-grid{
  display:grid;
  grid-template-columns:repeat(auto-fit,minmax(280px,1fr));
  gap:30px;
}

.card{
  padding:40px 30px;
  border-radius:24px;
  background:#ffffff;
  box-shadow:0 10px 30px rgba(0,0,0,.06);
  transition:.3s;
}

.card:hover{
  transform:translateY(-8px);
}

.card h3{
  font-family:'DM Serif Display',serif;
  font-size:22px;
  margin-bottom:15px;
}

.card p{
  font-size:15px;
  line-height:1.8;
  color:#555;
}

/* ===== PROFILE ===== */
.profile{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:60px;
  align-items:center;
}

.profile img{
  width:70%;
  max-width:280px;
  border-radius:20px;
  display:block;
  margin:auto;
  box-shadow:0 15px 35px rgba(0,0,0,.15);
}

.profile h3{
  font-family:'DM Serif Display',serif;
  font-size:30px;
  margin-bottom:10px;
}

.profile span{
  display:block;
  font-size:13px;
  text-transform:uppercase;
  letter-spacing:1px;
  font-weight:600;
  color:#145a5f;
  margin-bottom:20px;
}

.profile p{
  font-size:15px;
  line-height:1.8;
  color:#444;
}

@media(max-width:900px){
  .profile{
    grid-template-columns:1fr;
    text-align:center;
  }
}

</style>
</head>

<body>

<!-- HEADER -->
<section class="hero">

  <div class="top-nav">

    <div class="logo">
      <img src="https://i.ibb.co/d0DY6w6Z/kopri-trans.png">
      <img src="https://i.supaimg.com/7b6189cc-4918-4607-b366-60f9e935ff74/b378f489-1903-41d3-ae58-f662d434d36d.png">
      <img src="https://i.ibb.co/wFRdPQwv/pmii-logo.png">
    </div>

    <div class="header-menu">

      <a href="#">
        <i class="fas fa-database"></i>
        Materi Data
      </a>

      <div class="dropdown" id="kaderDropdown">
        <button class="dropdown-btn" id="kaderBtn">
          <i class="fas fa-users"></i>
          Kader
          <i class="fas fa-chevron-down"></i>
        </button>

        <div class="dropdown-content">
          <a href="https://pmiikomiskenda.42web.io/kaader/">jumlah Kader</a>

          <a href="#">Kader Baru</a>
          <a href="#">Kader Drop</a>
        </div>
      </div>

    </div>

  </div>

  <div class="hero-content">
    <h1>Program Kerja PK PMII STAIM Kendal</h1>
    <p>Masa Khidmad 2025 / 2026</p>
  </div>

</section>

<!-- PROGRAM -->
<section class="section">
  <h2 class="section-title">Fokus Utama</h2>
  <div class="program-grid">
    <div class="card">
      <h3>Kaderisasi Intensif</h3>
      <p>Pelaksanaan MAPABA, PKD, diskusi rutin, dan penguatan ideologi Ahlussunnah wal Jamaah.</p>
    </div>
    <div class="card">
      <h3>Penguatan Literasi</h3>
      <p>Gerakan menulis, kajian ilmiah, dan peningkatan budaya baca kader secara sistematis.</p>
    </div>
    <div class="card">
      <h3>Afinitas Kader</h3>
      <p>Membangun hubungan baik antar kader tanpa mempermasalahkan gender.</p>
    </div>
  </div>
</section>

<!-- PROFILE -->
<section class="section">
  <div class="profile">
    <div>
      <img src="https://i.supaimg.com/7b6189cc-4918-4607-b366-60f9e935ff74/6819e116-88bf-4532-adff-30ce7b03b82c.png">
    </div>
    <div>
      <h1>KhrisS</h1>
      <h3>Ketua 1</h3>
      <span>Bidang Kaderisasi</span>
      <p>Bertanggung jawab dalam perencanaan, pelaksanaan, dan evaluasi sistem kaderisasi yang berorientasi pada pembentukan kader progresif.</p>
    </div>
  </div>
</section>

<script>
const dropdown = document.getElementById("kaderDropdown");
const btn = document.getElementById("kaderBtn");

btn.addEventListener("click", function(e){
  e.stopPropagation();
  dropdown.classList.toggle("active");
});

document.addEventListener("click", function(e){
  if(!dropdown.contains(e.target)){
    dropdown.classList.remove("active");
  }
});
</script>

</body>
</html>
