<html lang="id">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Dashboard Progress Kaderisasi | PK PMII Kendal</title>

<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">

<style>
:root{
  --primary:#0f766e;
  --primary-light:#14b8a6;
  --accent:#0ea5e9;
  --text:#0f172a;
  --muted:#64748b;
}

*{
  margin:0;
  padding:0;
  box-sizing:border-box;
  font-family:'Inter',sans-serif;
}

body{
  min-height:100vh;
  background:linear-gradient(135deg,#ecfeff,#f0fdfa,#ffffff);
  padding:80px 20px;
  color:var(--text);
  position:relative;
  overflow-x:hidden;
}

/* Decorative Blur Background */
body::before,
body::after{
  content:"";
  position:absolute;
  width:450px;
  height:450px;
  border-radius:50%;
  filter:blur(130px);
  z-index:-1;
}

body::before{
  background:#14b8a6;
  top:-150px;
  left:-120px;
  opacity:.25;
}

body::after{
  background:#0ea5e9;
  bottom:-180px;
  right:-120px;
  opacity:.2;
}

/* HEADER */
.header{
  text-align:center;
  margin-bottom:70px;
}

.header h1{
  font-size:38px;
  font-weight:800;
  background:linear-gradient(90deg,var(--primary),var(--accent));
  -webkit-background-clip:text;
  -webkit-text-fill-color:transparent;
  margin-bottom:14px;
}

.header p{
  color:var(--muted);
  font-size:15px;
}

/* CONTAINER */
.container{
  max-width:1200px;
  margin:auto;
}

/* GRID */
.grid{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:50px;
}

/* CARD GLASS */
.card{
  background:rgba(255,255,255,0.7);
  backdrop-filter:blur(16px);
  padding:40px;
  border-radius:24px;
  border:1px solid rgba(255,255,255,0.5);
  box-shadow:
    0 20px 50px rgba(0,0,0,0.08),
    inset 0 1px 0 rgba(255,255,255,0.6);
  transition:.4s;
}

.card:hover{
  transform:translateY(-8px);
  box-shadow:
    0 30px 70px rgba(15,118,110,0.15),
    0 0 40px rgba(20,184,166,0.15);
}

.card h2{
  font-size:20px;
  font-weight:700;
  margin-bottom:30px;
  padding-bottom:12px;
  border-bottom:1px solid rgba(0,0,0,0.06);
}

/* PROGRAM */
.program{
  margin-bottom:22px;
}

.program-header{
  display:flex;
  justify-content:space-between;
  font-size:14px;
  margin-bottom:8px;
}

.program-header span:first-child{
  font-weight:500;
}

.percent{
  font-weight:600;
  color:var(--primary);
}

/* PROGRESS BAR */
.progress{
  width:100%;
  height:10px;
  background:rgba(0,0,0,0.05);
  border-radius:50px;
  overflow:hidden;
  position:relative;
}

.progress-bar{
  height:100%;
  border-radius:50px;
  background:linear-gradient(90deg,var(--primary),var(--primary-light));
  position:relative;
  transition:width 1s ease;
}

/* Shine Effect */
.progress-bar::after{
  content:"";
  position:absolute;
  top:0;
  left:-40%;
  width:40%;
  height:100%;
  background:linear-gradient(120deg,transparent,rgba(255,255,255,0.6),transparent);
  animation:shine 3s infinite;
}

@keyframes shine{
  0%{ left:-40%; }
  100%{ left:120%; }
}

/* SUMMARY */
.summary{
  margin-top:80px;
  background:linear-gradient(135deg,#0f766e,#14b8a6,#0ea5e9);
  background-size:200% 200%;
  animation:gradientMove 6s ease infinite;
  color:white;
  padding:60px;
  border-radius:30px;
  text-align:center;
  box-shadow:0 30px 80px rgba(15,118,110,0.35);
}

@keyframes gradientMove{
  0%{background-position:0% 50%;}
  50%{background-position:100% 50%;}
  100%{background-position:0% 50%;}
}

.summary h3{
  font-size:48px;
  font-weight:800;
  margin-bottom:10px;
}

.summary p{
  font-size:15px;
  opacity:.95;
}

/* RESPONSIVE */
@media(max-width:900px){
  .grid{
    grid-template-columns:1fr;
  }
}
</style>
</head>
<body>

<div class="container">

<div class="header">
  <h1>Dashboard Progress Bidang Kaderisasi</h1>
  <p>Monitoring pelaksanaan program kerja PK PMII Kendal</p>
</div>

<div class="grid">

<!-- NONFORMAL -->
<div class="card">
<h2>Kaderisasi Nonformal</h2>

<div class="program"><div class="program-header"><span>Sosialisasi & Rekrutmen Anggota</span><span class="percent">80%</span></div><div class="progress"><div class="progress-bar" style="width:80%"></div></div></div>

<div class="program"><div class="program-header"><span>Pesantren Aswaja</span><span class="percent">75%</span></div><div class="progress"><div class="progress-bar" style="width:75%"></div></div></div>

<div class="program"><div class="program-header"><span>Sahabat Literasi</span><span class="percent">60%</span></div><div class="progress"><div class="progress-bar" style="width:60%"></div></div></div>

<div class="program"><div class="program-header"><span>Kajian Jurnalistik</span><span class="percent">55%</span></div><div class="progress"><div class="progress-bar" style="width:55%"></div></div></div>

<div class="program"><div class="program-header"><span>Pelatihan Public Speaking</span><span class="percent">50%</span></div><div class="progress"><div class="progress-bar" style="width:50%"></div></div></div>

<div class="program"><div class="program-header"><span>NGOPER (Ngopi Pergerakan)</span><span class="percent">65%</span></div><div class="progress"><div class="progress-bar" style="width:65%"></div></div></div>

<div class="program"><div class="program-header"><span>Nobar (Nonton Bareng)</span><span class="percent">70%</span></div><div class="progress"><div class="progress-bar" style="width:70%"></div></div></div>

<div class="program"><div class="program-header"><span>Follow-up & Screening (MAPABA & PKD)</span><span class="percent">60%</span></div><div class="progress"><div class="progress-bar" style="width:60%"></div></div></div>

<div class="program"><div class="program-header"><span>Pelatihan Kepemimpinan</span><span class="percent">50%</span></div><div class="progress"><div class="progress-bar" style="width:50%"></div></div></div>

<div class="program"><div class="program-header"><span>MAKEDER</span><span class="percent">40%</span></div><div class="progress"><div class="progress-bar" style="width:40%"></div></div></div>

<div class="program"><div class="program-header"><span>PMII Peduli</span><span class="percent">65%</span></div><div class="progress"><div class="progress-bar" style="width:65%"></div></div></div>

</div>

<!-- FORMAL -->
<div class="card">
<h2>Kaderisasi Formal</h2>

<div class="program"><div class="program-header"><span>MAPABA</span><span class="percent">100%</span></div><div class="progress"><div class="progress-bar" style="width:100%"></div></div></div>

<div class="program"><div class="program-header"><span>PKD</span><span class="percent">70%</span></div><div class="progress"><div class="progress-bar" style="width:70%"></div></div></div>

</div>

</div>

<div class="summary">
  <h3>75%</h3>
  <p>Status: Sangat Baik & On Track</p>
</div>

</div>

</body>
</html>
