<html lang="id">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Program Kerja PMII</title>

<style>
*{
    margin:0;
    padding:0;
    box-sizing:border-box;
    font-family: Arial, Helvetica, sans-serif;
}

/* ===== BACKGROUND ===== */
body{
    background: linear-gradient(135deg,#1e3a8a,#3b82f6);
    min-height:100vh;
}

/* ===== CONTAINER ===== */
.container{
    max-width:1000px;
    margin:40px auto;
    background:white;
    border-radius:15px;
    padding:30px;
    box-shadow:0 10px 25px rgba(0,0,0,0.2);
}

/* ===== HEADER ===== */
.header{
    text-align:center;
    margin-bottom:25px;
}

.header h1{
    color:#1e3a8a;
    font-size:28px;
}

.header p{
    color:#555;
    margin-top:5px;
}

/* ===== TABLE ===== */
table{
    width:100%;
    border-collapse:collapse;
    overflow:hidden;
    border-radius:10px;
    border:2px solid #1f2937; /* garis tabel hitam kebiru-biruan */
}

thead{
    background: linear-gradient(90deg,#1f2937,#3b82f6); /* header hitam kebiru-biruan ke biru lembut */
    color:white;
}

th, td{
    padding:12px;
    text-align:center;
    border-bottom:1px solid #1f2937; /* garis antar row */
}

th{
    font-size:15px;
}

tbody tr:nth-child(even){
    background:#f0f4ff; /* biru sangat muda supaya kalem */
}

tbody tr:hover{
    background:#c7d2fe; /* biru muda saat hover */
    transition:0.3s;
}

td{
    color:#333;
    font-size:14px;
}

/* ===== BADGE STATUS ===== */
.badge{
    padding:5px 10px;
    border-radius:20px;
    color:white;
    font-size:12px;
}

.selesai{
    background:#4caf50;
}

.proses{
    background:#ff9800;
}

.belum{
    background:#f44336;
}

/* ===== FOOTER ===== */
.footer{
    margin-top:20px;
    text-align:center;
    font-size:13px;
    color:#777;
}

/* ===== RESPONSIVE ===== */
@media(max-width:700px){
    th,td{
        font-size:12px;
        padding:8px;
    }
}
</style>
</head>

<body>

<div class="container">

    <div class="header">
        <h1>PROGRAM KERJA  KADERISASI</h1>
        <p>Periode Kepengurusan 2026</p>
    </div>

    <table>
        <thead>
            <tr>
                <th>No</th>
                <th>Nama Kegiatan</th>
                <th>Bidang</th>
                <th>Waktu</th>
                <th>Penanggung Jawab</th>
                <th>Status</th>
            </tr>
        </thead>

        <tbody>
            <tr>
                <td>1</td>
                <td>MAPABA</td>
                <td>Kaderisasi</td>
                <td>Februari</td>
                <td>koordinator kaderisasi</td>
                <td><span class="badge selesai">Selesai</span></td>
            </tr>

            <tr>
                <td>2</td>
                <td>Sahabat literasi</td>
                <td>Kaderisasi</td>
                <td>Maret</td>
                <td>koordinator kaderisasi</td>
                <td><span class="badge proses">Proses</span></td>
            </tr>

            <tr>
                <td>3</td>
                <td>PKD</td>
                <td>Kaderisasi</td>
                <td>April</td>
                <td>koordinator kaderisasi</td>
                <td><span class="badge belum">Belum</span></td>
            </tr>

            <tr>
                <td>4</td>
                <td>Sahabat Ngopi</td>
                <td>Kaderisasi</td>
                <td>Mei</td>
                <td>koordinator kaderisasi</td>
                <td><span class="badge belum">Belum</span></td>
            </tr>

            <tr>
                <td>5</td>
                <td>Pelatihan Kepemimpinan</td>
                <td>Organisasi</td>
                <td>Juni</td>
                <td>BPH</td>
                <td><span class="badge belum">Belum</span></td>
            </tr>
        </tbody>
    </table>

    <div class="footer">
        © 2026 PMII — Sistem Program Kerja
    </div>

</div>

</body>
</html>
