<style>

/* ===== RESET ===== */
*{
  margin:0;
  padding:0;
  box-sizing:border-box;
}

body{
  font-family:'Plus Jakarta Sans',sans-serif;
  background:#fff8f0;
  overflow-x:hidden;
}

/* ===== HERO ===== */
.hero{
  position:relative;

  /* +30px total (15px kiri & kanan) */
  width: calc(100vw + 30px);
  left:50%;
  transform:translateX(-50%);

  height:40vh;
  background: linear-gradient(135deg, #ff7f50, #ffd700, #ffa500);
  color:white;

  padding:20px 60px;
  border-radius:0 0 30px 30px;
  top:-20px;
  overflow:hidden;

  display:flex;
  flex-direction:column;
  justify-content:space-between;

  box-shadow:0 18px 45px rgba(0,0,0,0.25);
}

/* ===== GLASS OVERLAY ===== */
.hero::before{
  content:"";
  position:absolute;
  inset:0;
  background: linear-gradient(
    120deg,
    rgba(255,255,255,0.08) 0%,
    rgba(255,255,255,0.18) 40%,
    rgba(255,255,255,0.05) 60%,
    rgba(255,255,255,0.08) 100%
  );
  backdrop-filter: blur(6px);
  pointer-events:none;
  z-index:1;
}

/* ===== SHINE EFFECT ===== */
.hero::after{
  content:"";
  position:absolute;
  top:0;
  left:-120%;
  width:60%;
  height:100%;
  background: linear-gradient(
    75deg,
    transparent,
    rgba(255,255,255,0.5),
    transparent
  );
  transform: skewX(-25deg);
  animation: shineMove 6s infinite ease-in-out;
  pointer-events:none;
  z-index:2;
}

@keyframes shineMove{
  0%{ left:-120%; }
  50%{ left:120%; }
  100%{ left:120%; }
}

/* ===== DECOR ===== */
.hero .circle1{
  position:absolute;
  width:350px;
  height:350px;
  background: rgba(255,255,255,0.15);
  border-radius:50%;
  top:-140px;
  right:-140px;
  z-index:0;
}

.hero .circle2{
  position:absolute;
  width:300px;
  height:300px;
  background: rgba(255,255,255,0.1);
  border-radius:50%;
  bottom:-120px;
  left:-120px;
  z-index:0;
}

/* ===== NAV ===== */
.top-nav{
  display:flex;
  justify-content:space-between;
  align-items:center;
  position:relative;
  z-index:3;
}

.logo{
  display:flex;
  align-items:center;
  gap:20px;
}

.logo img{
  height:45px;
  transition:.3s;
}

.logo img:hover{
  transform:scale(1.05);
}

.logo img:nth-child(2){ height:55px; }
.logo img:nth-child(3){ height:50px; }

.header-right{
  display:flex;
  align-items:center;
  gap:20px;
}

.header-menu{
  display:flex;
  gap:20px;
}

.header-menu a{
  color:#fff;
  text-decoration:none;
  font-size:14px;
  display:flex;
  align-items:center;
  gap:8px;
  padding:10px 18px;
  background: rgba(255,255,255,0.2);
  border-radius:12px;
  transition:.3s;
  backdrop-filter: blur(5px);
}

.header-menu a:hover{
  background: rgba(255,255,255,0.45);
  transform:translateY(-2px);
}

.social-icons{
  display:flex;
  align-items:center;
  gap:22px;
}

.social-icons a{
  color:white;
  font-size:24px;
  transition:.3s;
}

.social-icons a:hover{
  color:#222;
  transform:scale(1.2);
}

.hero-content{
  position:relative;
  z-index:3;
  margin-top:20px;
}

.hero h1{
  font-family:'DM Serif Display',serif;
  font-size:32px;
  margin-bottom:8px;
  text-shadow:0 4px 15px rgba(0,0,0,0.25);
}

.hero p{
  font-size:14px;
  opacity:.95;
}

/* ===== RESPONSIVE ===== */
@media(max-width:900px){
  .hero{
    width:100%;
    left:0;
    transform:none;
    padding:20px;
  }
  .top-nav{
    flex-direction:column;
    gap:15px;
  }
  .social-icons{
    justify-content:center;
  }
}

</style>
</head>

<body>

<section class="hero">

  <div class="circle1"></div>
  <div class="circle2"></div>

  <div class="top-nav">

    <div class="logo">
      <img src="https://i.ibb.co/d0DY6w6Z/kopri-trans.png" alt="Logo Kopri">
      <img src="https://i.supaimg.com/7b6189cc-4918-4607-b366-60f9e935ff74/b378f489-1903-41d3-ae58-f662d434d36d.png" alt="Logo Tengah">
      <img src="https://i.ibb.co/wFRdPQwv/pmii-logo.png" alt="Logo PMII">
    </div>

    <div class="header-right">
      <div class="header-menu">
        <a href="#">
          <i class="fas fa-database"></i>
          Materi Data
        </a>
      </div>

      <div class="social-icons">
        <a href="#"><i class="fab fa-instagram"></i></a>
        <a href="#"><i class="fab fa-youtube"></i></a>
        <a href="#"><i class="fab fa-tiktok"></i></a>
        <a href="#"><i class="fas fa-globe"></i></a>
      </div>
    </div>

  </div>

  <div class="hero-content">
    <h1>Program Kerja PK PMII STAIM Kendal</h1>
    <p>Masa Khidmad 2025 / 2026</p>
  </div>

</section>

</body>
</html>
