<title>Program Kerja Bidang Eksternal</title>

<style>
*{
    margin:0;
    padding:0;
    box-sizing:border-box;
    font-family: Arial, Helvetica, sans-serif;
}

/* ===== BACKGROUND ===== */
body{
    background: linear-gradient(135deg,#ffb347,#ffd54f);
    min-height:100vh;
}

/* ===== CONTAINER ===== */
.container{
    max-width:1000px;
    margin:40px auto;
    background:white;
    border-radius:15px;
    padding:30px;
    box-shadow:0 10px 25px rgba(0,0,0,0.2);
}

/* ===== HEADER ===== */
.header{
    text-align:center;
    margin-bottom:25px;
}

.header h1{
    color:#ff7a00;
    font-size:28px;
}

