table{
    width:100%;
    border-collapse:collapse;
    overflow:hidden;
    border-radius:10px;
}

thead{
    background:linear-gradient(90deg,#ff8c00,#ffc107);
    color:white;
}

th, td{
    padding:12px;
    text-align:center;
}

th{
    font-size:15px;
}

