    background:#ffe0a3;
    transition:0.3s;
}

td{
    color:#333;
    font-size:14px;
}

/* ===== BADGE STATUS ===== */
.badge{
    padding:5px 10px;
    border-radius:20px;
    color:white;
    font-size:12px;
}

.selesai{
    background:#4caf50;
}

.proses{
    background:#ff9800;
