    th,td{
        font-size:12px;
        padding:8px;
    }
}
</style>
</head>

<body>

<div class="container">

    <div class="header">
        <h1>PROGRAM  BIDANG EKSTERNA</h1>
        <p>Periode Kepengurusan 2026</p>
    </div>

