  left:-120px;
  width:350px;
  height:350px;
  background:radial-gradient(circle,rgba(255,183,3,0.2),transparent 70%);
  border-radius:50%;
}

/* Glow kanan */
.footer::after{
  content:"";
  position:absolute;
  bottom:-150px;
  right:-150px;
  width:400px;
  height:400px;
  background:radial-gradient(circle,rgba(255,140,66,0.2),transparent 70%);
  border-radius:50%;
}

/* GRID */
.footer-container{
  display:grid;
  grid-template-columns:repeat(auto-fit,minmax(220px,1fr));
  gap:60px;
