  bottom:-8px;
  left:0;
  width:50px;
  height:3px;
  background:linear-gradient(90deg,#ffb347,#ffe066);
  border-radius:20px;
}

.footer p,
.footer a{
  font-size:14px;
  color:rgba(255,255,255,0.9);
  text-decoration:none;
  line-height:1.9;
  transition:0.3s ease;
}

.footer a:hover{
  color:#ffb347;
  padding-left:6px;
}

/* ===== BOTTOM BAR ===== */
.footer-bottom{
  margin-top:70px;
  padding-top:30px;
  border-top:1px solid rgba(255,255,255,0.15);
  text-align:center;
  font-size:13px;
  color:rgba(255,255,255,0.7);
  position:relative;
}

/* Setengah Lingkaran Dalam Bar */
.footer-bottom::before{
  content:"";
  position:absolute;
  top:-35px;
  left:50%;
  transform:translateX(-50%);
  width:160px;
  height:80px;
  background:linear-gradient(135deg,#ffb347,#ffe066);
