<title> RTK PMII STAI Kendal 2025</title>

<link href="https://fonts.googleapis.com/css2?family=Orbitron:wght@500;700&family=Poppins:wght@300;400;600&display=swap" rel="stylesheet">

<style>
:root{
    --blue:#0a38ff;
    --yellow:#ffd000;
    --dark:#020617;
}
*{margin:0;padding:0;box-sizing:border-box}

body{
    font-family:'Poppins',sans-serif;
    background:var(--dark);
    color:#fff;
    overflow-x:hidden;
}

/* HERO FULL WIDTH */
.hero{
    width:100vw;
    height:90vh;
    margin-left:calc(50% - 50vw);
    background:
        linear-gradient(to bottom,rgba(0,0,0,.25),#020617),
        url('https://i.supaimg.com/478e0a60-8908-4937-ad89-40e43f8ca25c.jpg')
        center/cover no-repeat;
    display:flex;
    align-items:flex-end;
    padding:80px 8%;
}
.hero h1{
    font-family:'Orbitron',sans-serif;
    font-size:3.4rem;
    color:var(--yellow);
}
.hero span{
    display:block;
    margin-top:8px;
    color:#cbd5ff;
}

/* CONTENT */
.section{
    max-width:1300px;
    margin:auto;
    padding:120px 8%;
}
.section p{
    max-width:900px;
    font-size:1.15rem;
    line-height:2;
    color:#dbe2ff;
    margin-bottom:110px;
}

/* GALLERY */
.gallery{
    display:grid;
    grid-template-columns:repeat(auto-fit,minmax(300px,1fr));
    gap:40px;
}
.card{
    position:relative;
    height:420px;
    border-radius:24px;
    overflow:hidden;
}
.card img{
    width:100%;
    height:100%;
    object-fit:cover;
    transition:1.1s cubic-bezier(.19,1,.22,1);
    filter:contrast(1.15) saturate(1.25);
}
.card::after{
    content:'';
    position:absolute;
    inset:0;
    background:linear-gradient(to top,rgba(0,0,0,.85),transparent 65%);
}
.card::before{
