					<!DOCTYPE html>
<html lang="id">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Modern Professional Slider</title>
    <!-- Menggunakan font Poppins agar terlihat elegan -->
    <link href="https://fonts.googleapis.com/css2?family=Poppins:wght@300;400;600&display=swap" rel="stylesheet">
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
            font-family: 'Poppins', sans-serif;
        }

        body {
            background-color: #f0f2f5;
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            padding: 20px;
        }

        /* Container Utama Slider */
        .slider-container {
            position: relative;
            width: 100%;
            max-width: 900px;
            height: 500px;
            border-radius: 24px;
            overflow: hidden;
            box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.25);
            background-color: #000;
        }

        /* Wrapper untuk pergerakan slide */
        .slider-wrapper {
            display: flex;
            width: 100%;
            height: 100%;
            transition: transform 0.6s cubic-bezier(0.25, 1, 0.5, 1);
        }

        /* Individual Slide */
        .slide {
            min-width: 100%;
            height: 100%;
            position: relative;
        }

        .slide img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            filter: brightness(0.85); /* Sedikit digelapkan agar teks lebih terbaca */
            transition: transform 0.5s ease;
        }

        /* Efek Zoom in saat hover (opsional untuk menambah kesan premium) */
        .slider-container:hover .slide img {
            transform: scale(1.03);
        }

        /* Tombol Navigasi (Kiri & Kanan) bergaya Glassmorphism */
        .nav-btn {
            position: absolute;
            top: 50%;
            transform: translateY(-50%);
            width: 50px;
            height: 50px;
            border: none;
            border-radius: 50%;
            background: rgba(255, 255, 255, 0.2);
            backdrop-filter: blur(10px);
            -webkit-backdrop-filter: blur(10px);
            color: #fff;
            font-size: 24px;
            cursor: pointer;
            display: flex;
            justify-content: center;
            align-items: center;
            transition: all 0.3s ease;
            z-index: 10;
        }

        .nav-btn:hover {
            background: rgba(255, 255, 255, 0.4);
            transform: translateY(-50%) scale(1.1);
        }

        .prev-btn { left: 20px; }
        .next-btn { right: 20px; }

        /* Indikator Titik (Dots) di bawah slider */
        .dots-container {
            position: absolute;
            bottom: 25px;
            left: 50%;
            transform: translateX(-50%);
            display: flex;
            gap: 10px;
            z-index: 10;
            background: rgba(0, 0, 0, 0.3);
            padding: 8px 16px;
            border-radius: 30px;
            backdrop-filter: blur(5px);
        }

        .dot {
            width: 10px;
            height: 10px;
            border-radius: 50%;
            background-color: rgba(255, 255, 255, 0.4);
            cursor: pointer;
            transition: all 0.3s ease;
        }

        .dot.active {
            background-color: #fff;
            width: 25px; /* Efek memanjang untuk dot yang aktif */
            border-radius: 10px;
        }

        /* Teks Overlay pada Slide */
        .slide-content {
            position: absolute;
            bottom: 80px;
            left: 40px;
            color: #ffffff;
            z-index: 5;
            max-width: 80%;
            opacity: 0;
            transform: translateY(20px);
            transition: all 0.6s ease;
            transition-delay: 0.3s;
        }

        /* Animasi teks muncul saat slide aktif */
        .slide.active .slide-content {
            opacity: 1;
            transform: translateY(0);
        }

        .slide-content h2 {
            font-size: 32px;
            font-weight: 600;
            margin-bottom: 8px;
            text-shadow: 2px 2px 4px rgba(0,0,0,0.5);
        }

        .slide-content p {
            font-size: 16px;
            font-weight: 300;
            text-shadow: 1px 1px 3px rgba(0,0,0,0.5);
        }

        /* Responsif untuk layar HP */
        @media (max-width: 768px) {
            .slider-container { height: 400px; border-radius: 16px; }
            .nav-btn { width: 40px; height: 40px; font-size: 18px; }
            .slide-content h2 { font-size: 24px; }
            .slide-content p { font-size: 14px; }
            .slide-content { left: 20px; bottom: 60px; }
        }
    </style>
</head>
<body>

    <div class="slider-container" id="sliderContainer">
        <div class="slider-wrapper" id="sliderWrapper">

            <!-- Slide 1 -->
            <div class="slide active">
                <img src="http://pmiikomiskenda.42web.io/wp-content/uploads/2026/01/WhatsApp-Image-2026-02-13-at-09.05.57.jpeg" alt="Gambar 1">
                <div class="slide-content">
                    <h2>Kabar PMII Kendal</h2>
                    <p>Informasi terbaru seputar kegiatan dan pergerakan.</p>
                </div>
            </div>

            <!-- Slide 2 -->
            <div class="slide">
                <img src="http://pmiikomiskenda.42web.io/wp-content/uploads/2026/01/WhatsApp-Image-2026-02-13-at-09.05.57.jpeg" alt="Gambar 2">
                <div class="slide-content">
                    <h2>Solidaritas & Aksi</h2>
                    <p>Membangun komitmen bersama untuk kemajuan bangsa.</p>
                </div>
            </div>

            <!-- Slide 3 (Menggunakan gambar yang sama sebagai contoh slider bekerja) -->
            <div class="slide">
                <img src="http://pmiikomiskenda.42web.io/wp-content/uploads/2026/01/WhatsApp-Image-2026-02-13-at-09.05.57.jpeg" alt="Gambar 3">
                <div class="slide-content">
                    <h2>Kegiatan Komisariat</h2>
                    <p>Diskusi rutin dan pengembangan kapasitas kader.</p>
                </div>
            </div>

        </div>

        <!-- Tombol Navigasi Kiri Kanan -->
        <button class="nav-btn prev-btn" id="prevBtn">&#10094;</button>
        <button class="nav-btn next-btn" id="nextBtn">&#10095;</button>

        <!-- Indikator Slide (Dots) -->
        <div class="dots-container" id="dotsContainer">
            <!-- Dots akan di-generate otomatis via JavaScript sesuai jumlah slide -->
        </div>
    </div>

    <script>
        const sliderWrapper = document.getElementById('sliderWrapper');
        const slides = document.querySelectorAll('.slide');
        const prevBtn = document.getElementById('prevBtn');
        const nextBtn = document.getElementById('nextBtn');
        const dotsContainer = document.getElementById('dotsContainer');
        const sliderContainer = document.getElementById('sliderContainer');

        let currentIndex = 0;
        let slideInterval;

        // Membuat Dots secara dinamis
        slides.forEach((_, index) => {
            const dot = document.createElement('div');
            dot.classList.add('dot');
            if (index === 0) dot.classList.add('active');
            dot.addEventListener('click', () => goToSlide(index));
            dotsContainer.appendChild(dot);
        });

        const dots = document.querySelectorAll('.dot');

        // Fungsi utama untuk memindahkan slide
        function updateSlider() {
            // Geser gambar
            sliderWrapper.style.transform = `translateX(-${currentIndex * 100}%)`;

            // Update class active pada dots
            dots.forEach(dot => dot.classList.remove('active'));
            dots[currentIndex].classList.add('active');

            // Update class active pada slide untuk animasi teks
            slides.forEach(slide => slide.classList.remove('active'));
            slides[currentIndex].classList.add('active');
        }

        // Fungsi Tombol Next
        function nextSlide() {
            currentIndex = (currentIndex + 1) % slides.length;
            updateSlider();
        }

        // Fungsi Tombol Prev
        function prevSlide() {
            currentIndex = (currentIndex - 1 + slides.length) % slides.length;
            updateSlider();
        }

        // Fungsi klik dot
        function goToSlide(index) {
            currentIndex = index;
            updateSlider();
            resetInterval();
        }

        // Event Listeners
        nextBtn.addEventListener('click', () => {
            nextSlide();
            resetInterval();
        });

        prevBtn.addEventListener('click', () => {
            prevSlide();
            resetInterval();
        });

        // Fitur Auto-play (Gambar geser otomatis tiap 5 detik)
        function startInterval() {
            slideInterval = setInterval(nextSlide, 5000);
        }

        function resetInterval() {
            clearInterval(slideInterval);
            startInterval();
        }

        // Hentikan autoplay saat kursor berada di atas slider
        sliderContainer.addEventListener('mouseenter', () => clearInterval(slideInterval));
        sliderContainer.addEventListener('mouseleave', startInterval);

        // Mulai auto-play saat halaman dimuat
        startInterval();

    </script>
</body>
</html>				</div>
