<style>

/* ===== RESET ===== */
*{
  margin:0;
  padding:0;
  box-sizing:border-box;
}

body{
  font-family:'Plus Jakarta Sans',sans-serif;
  background:#fff8f0;
  overflow-x:hidden;
}

/* ===== HERO HEADER ===== */
.hero{
  position: relative;
  left: 50%;
  transform: translateX(-50%);
  width: 100vw;
  height: 40vh;

  background: linear-gradient(135deg, #4caf50, #2e7d32, #81c784);
  color:white;

  padding:25px 90px;
  border-radius:0 0 45px 45px;
  top:-94px;

  overflow:hidden;
  display:flex;
  flex-direction:column;
  justify-content:space-between;

  box-shadow: 0 18px 45px rgba(0,0,0,0.25);
}

/* ===== GLASS BASE LAYER ===== */
.hero::before{
  content:"";
  position:absolute;
  inset:0;
  background: linear-gradient(
    120deg,
    rgba(255,255,255,0.08) 0%,
    rgba(255,255,255,0.18) 40%,
    rgba(255,255,255,0.05) 60%,
    rgba(255,255,255,0.08) 100%
  );
  backdrop-filter: blur(6px);
  pointer-events:none;
}

/* ===== SHINE ANIMATION ===== */
.hero::after{
  content:"";
  position:absolute;
  top:0;
  left:-120%;
  width:60%;
  height:100%;
  background: linear-gradient(
    75deg,
    transparent,
    rgba(255,255,255,0.45),
    transparent
  );
  transform: skewX(-25deg);
  animation: shineMove 6s infinite ease-in-out;
  pointer-events:none;
}

@keyframes shineMove{
  0%{
    left:-120%;
  }
  50%{
    left:120%;
  }
  100%{
    left:120%;
  }
}

/* ===== DECORATION CIRCLES ===== */
.hero .circle1{
  position:absolute;
  width:380px;
  height:380px;
  background: rgba(255,255,255,0.15);
  border-radius:50%;
  top:-160px;
  right:-160px;
  box-shadow: 0 0 80px rgba(76,175,80,0.5);
}

.hero .circle2{
  position:absolute;
  width:320px;
  height:320px;
  background: rgba(255,255,255,0.1);
  border-radius:50%;
  bottom:-140px;
  left:-140px;
  box-shadow: 0 0 80px rgba(129,199,132,0.5);
}

/* ===== NAV ===== */
.top-nav{
  display:flex;
  justify-content:space-between;
  align-items:center;
  position:relative;
  z-index:2;
}

/* LOGO */
.logo{
  display:flex;
  align-items:center;
  gap:22px;
}

.logo img{
  height:50px;
  transition:.3s;
}

.logo img:hover{
  transform:scale(1.05);
}

/* HEADER RIGHT */
.header-right{
  display:flex;
  align-items:center;
  gap:30px;
}

/* MENU */
.header-menu{
  display:flex;
  gap:20px;
}

.header-menu a{
  color:#fff;
  text-decoration:none;
  font-size:14px;
  display:flex;
  align-items:center;
  gap:8px;
  padding:12px 22px;
  background: rgba(255,255,255,0.2);
  border-radius:14px;
  transition:.3s;
  backdrop-filter: blur(6px);
}

.header-menu a:hover{
  background: rgba(255,255,255,0.4);
  transform: translateY(-2px);
}

/* SOCIAL ICON */
.social-icons{
  display:flex;
  align-items:center;
  gap:22px;
}

.social-icons a{
  color:white;
  font-size:26px;
  transition:.3s;
}

.social-icons a:hover{
  color:#1a1a1a;
  transform: scale(1.2);
}

/* HERO TEXT */
.hero-content{
  position:relative;
  z-index:2;
  margin-top:20px;
}

.hero h1{
  font-family:'DM Serif Display',serif;
  font-size:34px;
  margin-bottom:10px;
  text-shadow:0 4px 15px rgba(0,0,0,0.25);
}

.hero p{
  font-size:15px;
  opacity:.95;
}

/* ===== RESPONSIVE ===== */
@media(max-width:900px){
  .hero{
    padding:25px 25px;
    top:-94px;
  }

  .top-nav{
    flex-direction:column;
    gap:20px;
  }

  .header-right{
    flex-direction:column;
    gap:18px;
  }

  .hero h1{
    font-size:26px;
    text-align:center;
  }

  .hero p{
    text-align:center;
  }

  .social-icons{
    justify-content:center;
  }
}

</style>
</head>

<body>

