<html lang="id">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Ketua III - Bidang Keagamaan</title>

<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;800&display=swap" rel="stylesheet">

<style>
:root{
  --primary:#0f9d58;
  --primary-light:#34d399;
  --accent:#22c55e;
  --bg-soft:#ecfdf5;
  --text:#1a1a1a;
  --muted:#6b7280;
}

*{
  margin:0;
  padding:0;
  box-sizing:border-box;
  font-family:'Inter',sans-serif;
}

body{
  min-height:100vh;
  background:linear-gradient(135deg,#ecfdf5,#f0fdf4,#ffffff);
  padding:80px 20px;
  color:var(--text);
}

/* HEADER */
.header{
  text-align:center;
  margin-bottom:60px;
}

.header h1{
  font-size:40px;
  font-weight:800;
  background:linear-gradient(90deg,var(--primary),var(--accent));
  -webkit-background-clip:text;
  -webkit-text-fill-color:transparent;
}

.header p{
  margin-top:10px;
  color:var(--muted);
}

/* CONTAINER */
.container{
  max-width:1000px;
  margin:auto;
}

/* CARD */
.card{
  background:rgba(255,255,255,0.9);
  backdrop-filter:blur(12px);
  padding:45px;
  border-radius:26px;
  box-shadow:0 25px 60px rgba(16,185,129,0.15);
}

/* PROGRAM */
.program{
  margin-bottom:28px;
}

.program-header{
  display:flex;
  justify-content:space-between;
  margin-bottom:10px;
  font-size:15px;
  font-weight:600;
}

.percent{
  color:var(--primary);
  font-weight:700;
}

/* PROGRESS BAR */
.progress{
  width:100%;
  height:12px;
  background:rgba(0,0,0,0.05);
  border-radius:50px;
  overflow:hidden;
}

.progress-bar{
  height:100%;
  border-radius:50px;
  background:linear-gradient(
    90deg,
    var(--primary),
    var(--primary-light),
    var(--accent)
  );
  box-shadow:0 0 15px rgba(34,197,94,0.4);
}

/* SUMMARY */
.summary{
  margin-top:60px;
  text-align:center;
  background:linear-gradient(
    135deg,
    var(--primary),
    var(--primary-light),
    var(--accent)
  );
  color:white;
  padding:50px;
  border-radius:28px;
  box-shadow:0 30px 80px rgba(34,197,94,0.35);
}

.summary h3{
  font-size:46px;
  font-weight:800;
  margin-bottom:8px;
}
</style>
</head>

<body>

<div class="container">

<div class="header">
  <h1>Ketua III – Bidang Keagamaan</h1>
  <p>Monitoring Program Kerja PK PMII STAIM Kendal</p>
</div>

<div class="card">

<div class="program">
<div class="program-header">
<span>Rutinan / Yasinan setiap malam Jumat</span>
<span class="percent">90%</span>
</div>
<div class="progress"><div class="progress-bar" style="width:90%"></div></div>
</div>

<div class="program">
<div class="program-header">
<span>Ziarah Wali (Tahun ini harus terealisasi)</span>
<span class="percent">60%</span>
</div>
<div class="progress"><div class="progress-bar" style="width:60%"></div></div>
</div>

<div class="program">
<div class="program-header">
<span>Bagi Takjil + Bukber + Tarawih + Studi Religi (Nuzulul Qur'an)</span>
<span class="percent">75%</span>
</div>
<div class="progress"><div class="progress-bar" style="width:75%"></div></div>
</div>

<div class="program">
<div class="program-header">
<span>Isra Mi'raj (Sudah Terealisasi)</span>
<span class="percent">100%</span>
</div>
<div class="progress"><div class="progress-bar" style="width:100%"></div></div>
</div>

<div class="program">
<div class="program-header">
<span>Kajian Bulanan (Ngaji Akhlak Ta'limul Muta'allim)</span>
<span class="percent">80%</span>
</div>
<div class="progress"><div class="progress-bar" style="width:80%"></div></div>
</div>

</div>

<div class="summary">
<h3>81%</h3>
<p>Status Program Keagamaan Berjalan Baik & Aktif</p>
</div>

</div>

</body>
</html>
