            font-family: 'Space Grotesk'; font-weight: 800; font-size: 24px; color: #fff;
            box-shadow: 0 0 25px var(--primary-glow);
            flex-shrink: 0;
        }

        .nav-link {
            width: 100%; padding: 15px; border-radius: 15px; margin-bottom: 8px;
            color: #666; display: flex; align-items: center; gap: 20px;
            transition: 0.3s; text-decoration: none; overflow: hidden; white-space: nowrap;
        }
        .nav-link:hover, .nav-link.active { background: rgba(255,255,255,0.05); color: #fff; }
        .nav-link i { font-style: normal; font-size: 20px; min-width: 25px; text-align: center; }

        /* --- MAIN INTERFACE --- */
        .container { margin-left: 130px; padding: 50px 60px; max-width: 1500px; position: relative; z-index: 1; }

