        .title-h1 span { color: var(--primary); text-shadow: 0 0 30px var(--primary-glow); }

        /* --- BENTO STATS --- */
        .stats-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 25px; margin-bottom: 45px; }
