        .stat-box:hover { transform: translateY(-10px); border-color: var(--primary); }
        .stat-box p { font-size: 11px; letter-spacing: 3px; color: #888; text-transform: uppercase; margin-bottom: 12px; font-weight: 700; }
        .stat-box h2 { font-size: 45px; font-weight: 800; font-family: 'Space Grotesk'; color: #fff; }

        /* --- DATA TABLE PANEL --- */
        .data-panel {
            background: var(--glass-heavy); border: 1px solid var(--border);
            border-radius: 45px; padding: 45px; backdrop-filter: blur(15px);
            box-shadow: 0 30px 60px rgba(0,0,0,0.5);
        }
        .panel-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 35px; }

        select {
            background: rgba(0,0,0,0.4); color: #fff; border: 1px solid var(--border);
            padding: 12px 25px; border-radius: 18px; outline: none; font-family: 'Outfit';
            font-weight: 600; cursor: pointer; transition: 0.3s;
        }
        select:hover { border-color: var(--primary); }

        .table-wrap { overflow-x: auto; }
        table { width: 100%; border-collapse: separate; border-spacing: 0 10px; }
        th { text-align: left; padding: 0 25px 15px; color: #556; font-size: 12px; text-transform: uppercase; letter-spacing: 2px; }

        td {
            padding: 22px 25px; background: rgba(255,255,255,0.02);
            border-top: 1px solid var(--border); border-bottom: 1px solid var(--border);
            transition: 0.3s; color: #ccc;
        }
        tr td:first-child { border-radius: 22px 0 0 22px; border-left: 1px solid var(--border); font-family: 'JetBrains Mono'; color: var(--primary); }
        tr td:last-child { border-radius: 0 22px 22px 0; border-right: 1px solid var(--border); text-align: right; }

        tr:hover td { background: rgba(99, 102, 241, 0.08); border-color: rgba(99, 102, 241, 0.3); color: #fff; }

        /* --- STATUS PILLS --- */
        .pill {
            padding: 8px 18px; border-radius: 12px; font-size: 11px; font-weight: 800;
            text-transform: uppercase; display: inline-flex; align-items: center; gap: 8px;
            border: 1px solid transparent;
        }
        .s-aktif { background: rgba(0, 255, 204, 0.05); color: var(--s-aktif); border-color: rgba(0, 255, 204, 0.2); box-shadow: 0 0 15px rgba(0,255,204,0.1); }
        .s-kurang-aktif { background: rgba(255, 221, 0, 0.05); color: var(--s-kurang); border-color: rgba(255, 221, 0, 0.2); }
        .s-tidak-pernah-aktif { background: rgba(255, 51, 102, 0.05); color: var(--s-tidak); border-color: rgba(255, 51, 102, 0.2); }
        .s-hilang { background: rgba(136, 136, 153, 0.05); color: var(--s-hilang); border-color: rgba(136, 136, 153, 0.2); }

        @keyframes slideUp { from { opacity: 0; transform: translateY(30px); } to { opacity: 1; transform: translateY(0); } }
        .stat-box, .data-panel { animation: slideUp 0.8s cubic-bezier(0.2, 1, 0.3, 1) both; }
    </style>
</head>
<body>

    <canvas id="matrixCanvas"></canvas>
    <div class="ambient-overlay"></div>

    <aside class="sidebar">
        <div class="logo-mark">Σ</div>
        <a href="#" class="nav-link active"><i>⚛</i> <span>Command Center</span></a>
        <a href="https://pmiikomiskenda.42web.io/laporan/" class="nav-link"><i>📂</i> <span> Report Kader</span></a>
        <a href="#" class="nav-link"><i>🛡</i> <span>Security System</span></a>
        <a href="#" class="nav-link"><i>⚙</i> <span>Settings</span></a>
    </aside>

    <div class="container">
        <header class="top-deck">
            <div>
                <p style="letter-spacing: 5px; color: var(--primary); font-weight: 800; font-size: 12px; margin-bottom: 8px;">DATA BASE BY KHRISISME v4.1</p>
                <h1 class="title-h1">PMII STAIM KENDAL<span>_</span></h1>
            </div>
            </header>

        <section class="stats-grid">
            <div class="stat-box" style="animation-delay: 0.1s">
                <p>Registry Capacity</p>
                <h2 id="total-val">0</h2>
            </div>
            <div class="stat-box" style="animation-delay: 0.2s">
                <p>Active Pulse</p>
                <h2 id="active-val" style="color: var(--s-aktif)">0</h2>
            </div>
            <div class="stat-box" style="animation-delay: 0.3s">
                <p>Dark Data</p>
                <h2 id="loss-val" style="color: var(--s-tidak)">0</h2>
            </div>
            <div class="stat-box" style="animation-delay: 0.4s">
                <p>System Stability</p>
                <h2 style="color: var(--primary)">99.9%</h2>
            </div>
        </section>

        <section class="data-panel">
            <div class="panel-header">
                <h3 style="font-family: 'Space Grotesk'; font-size: 1.6rem; letter-spacing: -1px;">Data Kader</h3>
                <select id="statusFilter">
                    <option value="all">Filter: Semua</option>
                    <option value="aktif">Status: Aktif</option>
                    <option value="kurang aktif">Status: Kurang Aktif</option>
                    <option value="tidak pernah aktif">Status: Tidak Aktif</option>
                    <option value="hilang">Status: Hilang</option>
                </select>
            </div>

            <div class="table-wrap">
                <table>
                    <thead>
                        <tr>
                            <th>UID Node</th>
                            <th>Nama Kader</th>
                            <th style="text-align: right;">STATUS</th>
                        </tr>
                    </thead>
                    <tbody id="singularityTable"></tbody>
                </table>
            </div>
        </section>
    </div>

    <script>
        // --- MATRIX ENGINE ---
        const canvas = document.getElementById('matrixCanvas');
        const ctx = canvas.getContext('2d');

        function resize() {
            canvas.width = window.innerWidth;
            canvas.height = window.innerHeight;
        }
        resize();
        window.addEventListener('resize', resize);

        const chars = "ｱｲｳｴｵｶｷｸｹｺｻｼｽｾｿﾀﾁﾂﾃﾄﾅﾆﾇﾈﾉﾊﾋﾌﾍﾎﾏﾐﾑﾒﾓﾔﾕﾖﾗﾘﾙﾚﾛﾜﾝ0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ".split("");
        const fontSize = 16;
        let columns = Math.floor(canvas.width / fontSize);
        let drops = Array(columns).fill(1);

        function drawMatrix() {
            ctx.fillStyle = "rgba(3, 3, 8, 0.08)";
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            ctx.font = fontSize + "px 'JetBrains Mono'";

            for (let i = 0; i < drops.length; i++) {
                const text = chars[Math.floor(Math.random() * chars.length)];

                // Shadow Color
                ctx.fillStyle = "#6366f1"; 
                ctx.fillText(text, i * fontSize, drops[i] * fontSize);

                // Glowing Head
                if (Math.random() > 0.9) {
                    ctx.fillStyle = "#fff";
                    ctx.fillText(text, i * fontSize, drops[i] * fontSize);
                }

                if (drops[i] * fontSize > canvas.height && Math.random() > 0.975) {
                    drops[i] = 0;
                }
                drops[i] += 0.8;
            }
        }
        setInterval(drawMatrix, 35);

        // --- DATA ENGINE ---
        const cadets = [
            {nama:"Muhammad Muhyidin", status:"aktif"},
            {nama:"Slamet Karisna", status:"aktif"},
            {nama:"Muhammad Fathulul Ghofur", status:"aktif"},
            {nama:"Balqis Ainu Rahma", status:"aktif"},
            {nama:"Muhammad Syahrul Aziz", status:"aktif"},
            {nama:"Nuril Mahmudi", status:"kurang aktif"},
            {nama:"Elsa Dwi Viana", status:"tidak pernah aktif"},
            {nama:"Iqyanaz Zaki Muhammad", status:"aktif"},
            {nama:"Nihayah Fatku Sholikah", status:"aktif"},
            {nama:"Aris Sugeng Prasetya", status:"hilang"},
            {nama:"Kholif Iqlimalaili", status:"aktif"},
            {nama:"Isyfi Royyan", status:"tidak pernah aktif"},
            {nama:"Rengga Tama Ghani", status:"aktif"},
            {nama:"Muhammad Syaiful Khamid", status:"aktif"},
            {nama:"Wahid Wahyudi", status:"kurang aktif"},
            {nama:"Khafidzurrahman", status:"aktif"},
            {nama:"Nur Hasan Fauzi", status:"hilang"},
            {nama:"Hernandi Fajar Pamungkas", status:"tidak pernah aktif"},
            {nama:"Nur Atoillah", status:"tidak pernah aktif"},
            {nama:"Eko Putra Nur Aini", status:"aktif"},
            {nama:"Erikha Masya Nur Fadilah", status:"aktif"},
            {nama:"Endang Sulastri", status:"kurang aktif"},
            {nama:"Lina Zahratul Muallimah", status:"hilang"},
            {nama:"Melinda Khorirotul Latifah", status:"tidak pernah aktif"},
            {nama:"Nurul Jannah", status:"tidak pernah aktif"},
            {nama:"Anisa Full Azzah", status:"tidak pernah aktif"},
            {nama:"Tarishah Azfa Azizah", status:"tidak pernah aktif"},
            {nama:"Salwa Nazilatunnimah", status:"hilang"},
            {nama:"Shoin Nur Aini", status:"tidak pernah aktif"},
            {nama:"Diah Ayu Munaroh", status:"tidak pernah aktif"},
            {nama:"Tri Rohana Habsari", status:"tidak pernah aktif"},
            {nama:"Vita Apriliani", status:"tidak pernah aktif"},
            {nama:"Salma Nazilatunnimah", status:"tidak pernah aktif"},
            {nama:"Asyifa Lesta", status:"hilang"},
            {nama:"Yuga Nurhayati", status:"tidak pernah aktif"},
            {nama:"Clianta Feodora", status:"tidak pernah aktif"},
            {nama:"Laily Rochmatuzzuhriyah", status:"tidak pernah aktif"}
        ];

        function getPill(s) {
            const safeClass = s.replace(/\s+/g, '-');
            return `<span class="pill s-${safeClass}">◈ ${s.toUpperCase()}</span>`;
        }

        function counter(id, target) {
            let n = 0;
            const obj = document.getElementById(id);
            const step = target / 50;
            const timer = setInterval(() => {
                n += step;
                if (n >= target) {
                    obj.innerText = target;
                    clearInterval(timer);
                } else {
                    obj.innerText = Math.floor(n);
                }
            }, 30);
        }

        function render() {
            const table = document.getElementById("singularityTable");
            const filter = document.getElementById("statusFilter").value;
            table.innerHTML = "";

            let a = 0, l = 0;
            cadets.forEach(c => {
                if(c.status === 'aktif') a++;
                if(c.status === 'hilang' || c.status === 'tidak pernah aktif') l++;
            });

            if(window.isFirst) {
                counter("total-val", cadets.length);
                counter("active-val", a);
                counter("loss-val", l);
                window.isFirst = false;
            }

            cadets.forEach((c, i) => {
                const matchF = filter === "all" || c.status === filter;

                if(matchF) {
                    const tr = document.createElement("tr");
                    tr.innerHTML = `
                        <td>NODE-${(i+1).toString().padStart(3,'0')}</td>
                        <td style="color:#fff; font-weight:600;">${c.nama}</td>
                        <td style="text-align:right;">${getPill(c.status)}</td>
                    `;
                    table.appendChild(tr);
                }
            });
        }

        window.isFirst = true;
        document.getElementById("statusFilter").onchange = render;
        window.onload = () => setTimeout(render, 100);
    </script>
</body>
