<style>
*{margin:0;padding:0;box-sizing:border-box;}
body{font-family:'Plus Jakarta Sans',sans-serif;background:#0c0c12;overflow-x:hidden;}

/* ===== HERO HEADER ===== */
.hero{
  position: relative;
  left:50%;
  transform: translateX(-50%);
  width:100vw;
  height:50vh;
  background:#0c0c12;
  overflow:hidden;
  display:flex;
  flex-direction:column;
