}

/* ===== CYBER GRID BACKGROUND ===== */
.hero::before{
  content:"";
  position:absolute;
  inset:0;
  background: repeating-linear-gradient(
      0deg,
      rgba(0,255,255,0.05),
      rgba(0,255,255,0.05) 1px,
      transparent 1px,
      transparent 20px
    ),
    repeating-linear-gradient(
      90deg,
      rgba(255,0,255,0.05),
      rgba(255,0,255,0.05) 1px,
      transparent 1px,
      transparent 20px
    );
  pointer-events:none;
  z-index:0;
  animation: gridMove 10s linear infinite;
}
@keyframes gridMove{
  0%{background-position:0 0,0 0;}
  100%{background-position:200px 200px,200px 200px;}
}

/* ===== SHINE ANIMATION ===== */
.hero::after{
  content:"";
  position:absolute;
  top:0;
  left:-120%;
  width:60%;
  height:100%;
  background: linear-gradient(
