  left:-140px;
  background: rgba(0,255,255,0.12);
}
@keyframes float{
  0%{transform: translateY(0);}
  100%{transform: translateY(20px);}
}

/* ===== NAVIGATION ===== */
.top-nav{display:flex;justify-content:space-between;align-items:center;position:relative;z-index:2;}
.logo{display:flex;align-items:center;gap:20px;}
