  transform: translateY(-2px);
}

/* SOCIAL ICONS */
.social-icons{display:flex;align-items:center;gap:20px;}
.social-icons a{
  color:white;
  font-size:24px;
  transition:.3s;
  text-shadow:0 0 6px #ff00ff,0 0 12px #00ffff;
  animation: flicker 3s infinite alternate;
}
.social-icons a:hover{
  color:#00ffff;
  transform: scale(1.2);
  text-shadow:0 0 15px #ff00ff,0 0 20px #00ffff;
}

/* HERO TEXT */
.hero-content{position:relative;z-index:2;margin-top:25px;}
.hero h1{
  font-family:'DM Serif Display',serif;
  font-size:40px;
  margin-bottom:12px;
  text-shadow:0 0 8px #ff00ff,0 0 12px #00ffff,0 0 20px #ff00ff,0 4px 15px rgba(0,0,0,0.3);
  animation: flicker 3s infinite alternate;
}
.hero p{
  font-size:16px;
  opacity:.95;
  letter-spacing:0.5px;
  text-shadow:0 0 6px #ff00ff,0 0 8px #00ffff;
  animation: flicker 4s infinite alternate;
}

/* FLICKER ANIMATION */
@keyframes flicker{
  0%,19%,21%,23%,25%,54%,56%,100%{opacity:1;}
  20%,24%,55%{opacity:0.6;}
}

/* RESPONSIVE */
@media(max-width:900px){
  .hero{padding:25px 25px;top:-60px;}
  .top-nav{flex-direction:column;gap:18px;}
