.ramadhan-bg{
  position:absolute;
  top:0; left:0;
  width:100%;
  height:100vh;
  z-index:0;
  overflow:hidden;
  background: linear-gradient(135deg,#0c0c12,#100021);
}

/* Neon grid lines */
.ramadhan-bg::after{
  content:"";
  position:absolute;
  width:200%;
  height:200%;
  top:-50%;
  left:-50%;
  background-image:
    linear-gradient(to right, rgba(0,255,255,0.08) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(255,0,255,0.08) 1px, transparent 1px);
  background-size:40px 40px;
  animation: gridMove 15s linear infinite;
}

@keyframes gridMove{
  0%{transform:translate(0,0);}
  100%{transform:translate(40px,40px);}
}

/* Floating neon circles */
.ramadhan-bg .circle{
  position:absolute;
  border-radius:50%;
  width:200px;
  height:200px;
  background: rgba(255,0,255,0.1);
  box-shadow:0 0 60px rgba(255,0,255,0.5);
  animation: float 6s ease-in-out infinite alternate;
}
.ramadhan-bg .circle:nth-child(2){
  width:160px; height:160px;
  background: rgba(0,255,255,0.1);
  box-shadow:0 0 60px rgba(0,255,255,0.5);
  bottom:10px; left:50px;
  animation-duration:8s;
}
.ramadhan-bg .circle:nth-child(3){
  width:100px; height:100px;
  background: rgba(255,255,0,0.1);
  box-shadow:0 0 40px rgba(255,255,0,0.5);
  top:150px; right:120px;
  animation-duration:10s;
}

@keyframes float{
  0%{transform: translateY(0);}
  100%{transform: translateY(20px);}
}

/* ===== SECTION ===== */
.section{
  padding:140px 20px 80px;
  max-width:1100px;
  margin:auto;
  position:relative;
  z-index:1;
  overflow:visible;
}

/* Section title */
.section-title{
  font-family:'DM Serif Display',serif;
  font-size:42px;
  margin-bottom:60px;
  text-align:center;
  background: linear-gradient(90deg,#ff00ff,#00ffff);
  -webkit-background-clip:text;
  -webkit-text-fill-color:transparent;
  text-shadow:0 0 8px #ff00ff,0 0 12px #00ffff;
  animation: flicker 3s infinite alternate;
}

/* ===== PROFILE CARD ===== */
.profile{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:60px;
  align-items:center;
  position:relative;
  z-index:2;
  background: rgba(0,0,0,0.3);
