<div class="coding-bg">
  <canvas id="codingCanvas" aria-hidden="true"></canvas>
  <canvas id="holoCanvas" aria-hidden="true"></canvas>

  <div class="coding-foreground">
    <div class="typed-code" id="typedCode"></div>
  </div>
</div>

<style>
.coding-bg {
  position: relative;
  width: 100%;
  height: 320px; /* lebih pendek */
  overflow: hidden;
  background: radial-gradient(circle at top, #ff3fff 0%, #3fb0ff 60%, #0a0c20 100%);
  perspective: 800px;
}

/* Canvases */
.coding-bg canvas {
  position: absolute;
  inset: 0;
  width: 100% !important;
  height: 100% !important;
  display: block;
  z-index: 1;
  pointer-events: none;
  mix-blend-mode: screen;
}

#holoCanvas { z-index: 2; filter: blur(2px); }

/* Foreground Typing */
.coding-bg .coding-foreground {
  position: relative;
  z-index: 3;
  display: flex;
  align-items: center;
  justify-content: center;
  height: 100%;
  padding: 20px;
  box-sizing: border-box;
  color: #e6f0ff;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, "Roboto Mono", monospace;
  text-align: center;
  pointer-events: auto;
}

.typed-code {
  max-width: 1100px;
  width: 100%;
  font-size: clamp(12px, 1.4vw, 16px);
  line-height: 1.45;
  letter-spacing: 0.2px;
  background: rgba(2,6,12,0.25);
  padding: 14px 20px;
  border-radius: 10px;
  box-shadow: 0 6px 20px rgba(0,0,0,0.5), inset 0 1px 0 rgba(255,255,255,0.02);
  border: 1px solid rgba(255,255,255,0.03);
  backdrop-filter: blur(6px);
  color: #e6f0ff;
}

.typed-code .cursor {
  display: inline-block;
  width: 6px;
  height: 1em;
  background: linear-gradient(90deg, #fff, #bfe0ff);
  margin-left: 4px;
  animation: blink 1s steps(2, start) infinite;
  vertical-align: middle;
  border-radius: 2px;
}

@keyframes blink { 0%,50% {opacity:1;} 51%,100% {opacity:0;} }

/* Hologram overlay scanlines */
.coding-bg::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 4;
  pointer-events: none;
  background:
    repeating-linear-gradient(45deg, rgba(255,255,255,0.05) 0px, rgba(255,255,255,0.05) 2px, transparent 2px, transparent 10px),
    repeating-linear-gradient(-45deg, rgba(255,255,255,0.03) 0px, rgba(255,255,255,0.03) 1px, transparent 1px, transparent 6px);
  mix-blend-mode: overlay;
  animation: holoSlide 15s linear infinite;
}

@keyframes holoSlide {
  from { transform: translateX(-50%) translateY(0) rotate(2deg); }
  to { transform: translateX(50%) translateY(-30%) rotate(2deg); }
}

@media (max-width:720px){
  .typed-code { padding: 12px; font-size: 12px; }
  .coding-bg { height: 280px; }
}
</style>

<script>
(function(){
const config = {
  charSet: "abcdefghijklmnopqrstuvwxyz0123456789<>[]{}()@#%&*-=+/:;.",
  fontSize: 14,
  columnSpacing: 16,
  speedBase: 1.2,
  typingLines: [
    "function fetchData() {",
    "  // request to API -> /v1/code",
    "  return await api.get('/v1/data');",
    "}",
    "",
    "const user = { id: 43, role: 'admin' };",
    "render(user);"
  ],
  typingDelayBetweenLines: 900,
  typingCharDelay: 30,
  fadeOutTypingAfter: 2500,
  orbCount: 22
};

// MATRIX CANVAS
const canvas=document.getElementById('codingCanvas');
const ctx=canvas.getContext('2d');
let w=0,h=0,columns=[],DPR=Math.max(1,window.devicePixelRatio||1);

function resizeCanvas(){
  w=canvas.width=Math.floor(canvas.clientWidth*DPR);
  h=canvas.height=Math.floor(canvas.clientHeight*DPR);
  ctx.scale(DPR,DPR);
  initColumns();
}

function initColumns(){
  const colWidth=config.columnSpacing;
  const cols=Math.floor(canvas.clientWidth/colWidth)+2;
  columns=[];
  for(let i=0;i<cols;i++){
    const x=i*colWidth;
    columns.push({
      x:x,
      y:Math.random()*(-800),
      speed:(Math.random()*1.5+config.speedBase)*(0.6+Math.random()*1.4),
      length:Math.floor(5+Math.random()*20)
    });
  }
}

function drawMatrix(){
  ctx.fillStyle='rgba(10,5,20,0.18)';
  ctx.fillRect(0,0,canvas.clientWidth,canvas.clientHeight);
  ctx.font=`${config.fontSize}px "Roboto Mono", monospace`;
  ctx.textBaseline='top';
  columns.forEach(col=>{
    let y=col.y;
    for(let i=0;i<col.length;i++){
      const char=config.charSet.charAt(Math.floor(Math.random()*config.charSet.length));
      let glowColor='';
      if(i===0) glowColor='rgba(255,100,220,0.95)';
      else if(i<3) glowColor='rgba(180,150,255,0.75)';
      else {
        const alpha=0.04+(i/col.length)*0.5;
        const r=255-i*3,g=100+i*1,b=220-i*5;
        glowColor=`rgba(${r},${g},${b},${alpha})`;
      }
      ctx.fillStyle=glowColor;
      ctx.shadowColor=glowColor;
      ctx.shadowBlur=5;
      ctx.fillText(char,col.x+2,y);
      y-=config.fontSize;
    }
    col.y+=col.speed*(config.fontSize/12);
    if(col.y>canvas.clientHeight+(col.length*config.fontSize)){
      col.y=-Math.random()*200;
      col.speed=(Math.random()*1.5+config.speedBase)*(0.6+Math.random()*1.4);
      col.length=Math.floor(5+Math.random()*21);
    }
  });
}

// HOLOGRAM ORBS
const holoCanvas=document.getElementById('holoCanvas');
const hctx=holoCanvas.getContext('2d');
let orbs=[];

function resizeHolo(){
  holoCanvas.width=canvas.width;
  holoCanvas.height=canvas.height;
  initOrbs();
}

function initOrbs(){
  orbs=[];
  for(let i=0;i<config.orbCount;i++){
    orbs.push({
      x: Math.random()*canvas.clientWidth,
      y: Math.random()*canvas.clientHeight,
      radius: Math.random()*5 + 2,
      speedX: (Math.random()-0.5)*0.2,
      speedY: (Math.random()-0.5)*0.4,
      color: Math.random()<0.5?'#ff3fff':'#3fb0ff',
      alpha: Math.random()*0.5+0.2
    });
  }
}

function drawOrbs(){
  hctx.clearRect(0,0,holoCanvas.width,holoCanvas.height);
  orbs.forEach(o=>{
    hctx.beginPath();
    hctx.arc(o.x,o.y,o.radius,0,Math.PI*2);
    hctx.fillStyle=o.color;
    hctx.globalAlpha=o.alpha;
    hctx.shadowColor=o.color;
    hctx.shadowBlur=12;
    hctx.fill();
    o.x+=o.speedX;
    o.y+=o.speedY;
    if(o.x<0) o.x=canvas.clientWidth;
    if(o.x>canvas.clientWidth) o.x=0;
    if(o.y<0) o.y=canvas.clientHeight;
    if(o.y>canvas.clientHeight) o.y=0;
  });
  hctx.globalAlpha=1;
}

// ANIMATE
function animate(){
  drawMatrix();
  drawOrbs();
  requestAnimationFrame(animate);
}

// INITIALIZE
function start(){
  resizeCanvas();
  resizeHolo();
  animate();
}

window.addEventListener('resize',start);
if(document.readyState==='complete'||document.readyState==='interactive'){start();}
else{window.addEventListener('DOMContentLoaded',start);}

// TYPING EFFECT
const typedEl=document.getElementById('typedCode');
function sleep(ms){return new Promise(res=>setTimeout(res,ms));}
async function runTyping(){
  if(!typedEl)return;
  while(true){
    typedEl.innerHTML='';
    for(let i=0;i<config.typingLines.length;i++){
      const line=config.typingLines[i];
      const lineNode=document.createElement('div');
      lineNode.className='line';
      typedEl.appendChild(lineNode);
      for(let c=0;c<line.length;c++){
        lineNode.textContent+=line[c];
        await sleep(config.typingCharDelay+Math.random()*18);
      }
      const cursor=document.createElement('span');
      cursor.className='cursor';
      lineNode.appendChild(cursor);
      await sleep(config.fadeOutTypingAfter);
      cursor.remove();
      await sleep(config.typingDelayBetweenLines*(0.35+Math.random()*0.8));
    }
    typedEl.style.transition='opacity 750ms ease';
    typedEl.style.opacity='1';
    await sleep(1200+Math.random()*1000);
    typedEl.style.opacity='0';
    await sleep(900);
    typedEl.innerHTML='';
    typedEl.style.opacity='1';
  }
}

(function injectCursorStyles(){
  const s=document.createElement('style');
  s.textContent=`
    #typedCode .line { text-align: left; white-space: pre-wrap; word-break: break-word; }
    #typedCode .line .cursor { display:inline-block; width:6px; height:1em; background:linear-gradient(90deg,#ff9fff,#3fb0ff); margin-left:3px; border-radius:2px; animation: blink 1s steps(2,start) infinite; vertical-align:middle; }
    @keyframes blink { 0%,50%{opacity:1} 51%,100%{opacity:0} }
  `;
  document.head.appendChild(s);
})();
setTimeout(runTyping,800);
})();
</script>
