<div class="master-container">

    <div class="side-panel">

        <div class="brand">

            <h2>Kader Portal</h2>

            <p>Sistem manajemen integritas dan pelaporan kendala organisasi secara real-time.</p>

        </div>


        <div class="stats">

            <div class="stat-item">

                <span class="stat-value">End-to-End</span>

                <span class="stat-label">Encryption</span>

            </div>

            <div class="stat-item">

                <span class="stat-value">24/7</span>

                <span class="stat-label">Admin Support</span>

            </div>

            <p style="font-size: 12px; color: #475569; margin-top: 30px;">© 2026 Organization Integrity System</p>

        </div>

    </div>


    <div class="form-panel">

        <div class="nav-header">

            <h3>Pilih Tipe Laporan</h3>

            <div class="tab-switcher">

                <div class="tab-btn active" id="btn-1" onclick="switchTab('keluhan')">Keluhan</div>

                <div class="tab-btn" id="btn-2" onclick="switchTab('laporan')">Laporkan Kader</div>

            </div>

        </div>


        <form id="form-keluhan" class="active">

            <div class="grid-inputs">

                <div class="field-box">

                    <label>Nama Lengkap</label>

                    <input type="text" id="k-nama" placeholder="Masukkan nama Anda">

                </div>

                <div class="field-box">

                    <label>Divisi Aktif</label>

                    <input type="text" id="k-divisi" placeholder="Contoh: Media Kreatif">

                </div>

                <div class="field-box full-width">

                    <label>Kendala / Masalah Utama</label>

                    <textarea id="k-masalah" placeholder="Jelaskan secara mendetail apa yang menghambat kinerja Anda..."></textarea>

                </div>

            </div>

            <button type="button" class="submit-btn" onclick="sendWA('keluhan')">Kirim Keluhan via WhatsApp</button>

        </form>


        <form id="form-laporan">

            <div class="grid-inputs">

                <div class="field-box">

                    <label>Pelapor</label>

                    <input type="text" id="l-nama" placeholder="Nama Anda (Bisa Anonim)">

                </div>

                <div class="field-box">

                    <label>Kader yang Dilaporkan</label>

                    <input type="text" id="l-target" placeholder="Nama lengkap target">

                </div>

                <div class="field-box full-width">

                    <label>Kategori Pelanggaran Perilaku</label>

                    <select id="l-kategori">

                        <option value="Toxic & Unprofessional">Toxic & Unprofessional</option>

                        <option value="Manipulation/Gaslighting">Manipulation / Gaslighting</option>

                        <option value="Disciplinary Issues">Masalah Kedisiplinan</option>

                        <option value="Ethics Violation">Pelanggaran Etika</option>

                    </select>

                </div>

                <div class="field-box full-width">

                    <label>Kronologi / Bukti Kejadian</label>

                    <textarea id="l-bukti" placeholder="Tuliskan fakta yang terjadi di lapangan..."></textarea>

                </div>

            </div>

            <button type="button" class="submit-btn" onclick="sendWA('laporan')" style="background: #ef4444;">Proses Laporan Kedisiplinan</button>

        </form>

    </div>

</div>


<script>

    function switchTab(type) {

        const btn1 = document.getElementById('btn-1');

        const btn2 = document.getElementById('btn-2');

        const f1 = document.getElementById('form-keluhan');

        const f2 = document.getElementById('form-laporan');


        if(type === 'keluhan') {

            btn1.classList.add('active');

            btn2.classList.remove('active');

            f1.classList.add('active');

            f2.classList.remove('active');

        } else {

            btn2.classList.add('active');

            btn1.classList.remove('active');

            f2.classList.add('active');

            f1.classList.remove('active');

        }

    }


    function sendWA(type) {

        const PHONE = "6281234567890";

        let text = "";


        if(type === 'keluhan') {

            const n = document.getElementById('k-nama').value;

            const d = document.getElementById('k-divisi').value;

            const m = document.getElementById('k-masalah').value;

            if(!n || !m) return alert("Mohon lengkapi data!");

            text = `*FORM KELUHAN KADER*%0A%0A*Nama:* ${n}%0A*Divisi:* ${d}%0A*Keluhan:* ${m}`;

        } else {

            const p = document.getElementById('l-nama').value || 'Anonim';

            const t = document.getElementById('l-target').value;

            const k = document.getElementById('l-kategori').value;

            const b = document.getElementById('l-bukti').value;

            if(!t || !b) return alert("Mohon lengkapi data!");

            text = `*LAPORAN DISIPLIN KADER*%0A%0A*Dari:* ${p}%0A*Target Laporan:* ${t}%0A*Kategori:* ${k}%0A*Kronologi:* ${b}`;

        }


        window.open(`https://wa.me/${PHONE}?text=${text}`, '_blank');

    }

</script>


</body>

