        <button type="button" class="btn btn-db" onclick="sendToDatabase()">
          <i class="fas fa-server"></i> Database Only
        </button>
        <button type="button" class="btn btn-wa" onclick="sendToWhatsApp()">
          <i class="fab fa-whatsapp"></i> WhatsApp Only
        </button>
      </div>
    </form>
  </section>
</main>

<script>
// --- MATRIX BACKGROUND ---
const canvas = document.getElementById('matrix-canvas');
const ctx = canvas.getContext('2d');
canvas.width = window.innerWidth; canvas.height = window.innerHeight;
const alphabet = "0101010101ABCDEF";
const fontSize = 16;
const columns = canvas.width / fontSize;
const drops = Array(Math.floor(columns)).fill(1);
function draw() {
  ctx.fillStyle = "rgba(0, 0, 0, 0.05)"; ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = "#00f2fe"; ctx.font = fontSize + "px monospace";
  for (let i = 0; i < drops.length; i++) {
    const text = alphabet.charAt(Math.floor(Math.random() * alphabet.length));
    ctx.fillText(text, i * fontSize, drops[i] * fontSize);
    if (drops[i] * fontSize > canvas.height && Math.random() > 0.975) drops[i] = 0;
    drops[i]++;
  }
}
setInterval(draw, 50);

const loader = document.getElementById("loader");
const form = document.getElementById("pkdForm");

// --- FUNGSI 1: KIRIM KE GOOGLE SHEET (DATABASE) ---
function sendToDatabase() {
  if(!form.checkValidity()) { form.reportValidity(); return; }

  loader.style.display = "flex";
  const formData = new FormData(form);

  // URL Google Apps Script Anda
  fetch("https://script.google.com/macros/s/AKfycbwylTR_vi5Zsvq_pRQI0zGxhoN4j1JUYOSuwA9ZgjV2WVRH5E2soM3I2_e1SHBtRSAl/exec", {
    method: "POST",
    body: formData
  })
  .then(() => {
    loader.innerHTML = `
      <i class="fas fa-check-circle" style="font-size:60px; color:var(--neon); text-shadow:0 0 20px var(--neon);"></i>
      <h2 style="margin-top:20px; font-family:'Orbitron'; color:var(--neon);">DATABASE_UPDATED</h2>
    `;
    setTimeout(() => { location.reload(); }, 2000);
  })
  .catch(() => {
    alert("SYSTEM_ERROR: CONNECTION FAILED");
    loader.style.display = "none";
  });
}

// --- FUNGSI 2: KIRIM KE WHATSAPP ---
function sendToWhatsApp() {
  if(!form.checkValidity()) { form.reportValidity(); return; }

  const nama = document.getElementById("nama").value;
  const email = document.getElementById("email").value;
  const komisariat = document.getElementById("komisariat").value;
  const motivasi = document.getElementById("motivasi").value;
  const skill = document.getElementById("skill").value;

  const waText = `*FORM PKD PMII*%0A%0A` +
                 `*Nama:* ${nama}%0A` +
                 `*Email:* ${email}%0A` +
                 `*Komisariat:* ${komisariat}%0A%0A` +
                 `*Motivasi:*%0A${motivasi}%0A%0A` +
                 `*Skill:*%0A${skill}`;

  window.open("https://wa.me/6287846719613?text=" + waText, "_blank");
}
</script>

</body>
</html>"},"elements":[],"widgetType":"html"}],"isInner":false}]

