    <link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css" rel="stylesheet">

    <style>
        :root {
            --primary: #6366f1;
            --primary-light: #818cf8;
            --primary-dark: #4338ca;
            --accent: #f59e0b;
            --accent-light: #fbbf24;
            --bg-base: #060b14;
            --card-grad: linear-gradient(145deg, rgba(30, 41, 59, 0.7) 0%, rgba(15, 23, 42, 0.4) 100%);
            --border-light: rgba(255, 255, 255, 0.08);
            --transition: all 0.4s cubic-bezier(0.25, 0.8, 0.25, 1);
        }

        * { margin: 0; padding: 0; box-sizing: border-box; }

        body {
            font-family: 'Plus Jakarta Sans', sans-serif;
            background-color: var(--bg-base);
            color: #f8fafc;
            padding: 50px 20px;
            overflow-x: hidden;
            position: relative;
            min-height: 100vh;
        }

        /* BACKGROUND ELEMENTS */
        .bg-grid {
            position: fixed;
            top: 0; left: 0; width: 100vw; height: 100vh;
            background-size: 50px 50px;
            background-image: 
                linear-gradient(to right, rgba(255, 255, 255, 0.03) 1px, transparent 1px),
                linear-gradient(to bottom, rgba(255, 255, 255, 0.03) 1px, transparent 1px);
            mask-image: radial-gradient(ellipse at center, black 40%, transparent 80%);
            -webkit-mask-image: radial-gradient(ellipse at center, black 40%, transparent 80%);
            z-index: -2;
            pointer-events: none;
        }

        .glow-orb {
            position: fixed;
            border-radius: 50%;
            filter: blur(140px);
            z-index: -1;
            opacity: 0.6;
            animation: orbFloat 15s infinite alternate ease-in-out;
            pointer-events: none;
        }

        .glow-orb-1 { width: 50vw; height: 50vw; background: rgba(99, 102, 241, 0.15); top: -20%; left: -10%; }
        .glow-orb-2 { width: 40vw; height: 40vw; background: rgba(245, 158, 11, 0.12); bottom: -10%; right: -10%; animation-delay: -5s; }

        @keyframes orbFloat {
            0% { transform: translate(0, 0) scale(1); }
            100% { transform: translate(50px, 80px) scale(1.2); }
        }

        /* HEADER SECTION */
        .pkd-wrapper { max-width: 1300px; margin: auto; position: relative; z-index: 1; }
        .header-box { text-align: center; margin-bottom: 50px; display: flex; flex-direction: column; align-items: center; }

        .badge {
            background: rgba(99, 102, 241, 0.1); color: var(--primary-light);
            padding: 8px 16px; border-radius: 50px; font-size: 13px; font-weight: 700;
            letter-spacing: 1px; text-transform: uppercase; border: 1px solid rgba(99, 102, 241, 0.3);
            margin-bottom: 20px; box-shadow: 0 0 20px rgba(99, 102, 241, 0.2);
        }

        .pkd-title {
            font-size: clamp(32px, 5vw, 46px); font-weight: 800; margin-bottom: 15px;
            display: flex; align-items: center; justify-content: center; gap: 15px;
            color: #fff; text-shadow: 0 10px 30px rgba(0,0,0,0.5);
        }

        .pkd-title span {
            background: linear-gradient(to right, #fff 20%, #a5b4fc 50%, #fde68a 80%);
            background-size: 200% auto; -webkit-background-clip: text; -webkit-text-fill-color: transparent;
            animation: shine 4s linear infinite;
        }

        @keyframes shine { to { background-position: 200% center; } }

        .pkd-title i { color: var(--accent); filter: drop-shadow(0 0 15px rgba(245, 158, 11, 0.6)); }

        .header-box p { color: #94a3b8; font-size: 17px; max-width: 600px; line-height: 1.6; margin-bottom: 30px; }

        /* TABS SWITCHER */
        .tabs-container {
            display: flex; background: rgba(15, 23, 42, 0.6); backdrop-filter: blur(10px);
            border: 1px solid var(--border-light); border-radius: 50px; padding: 6px; gap: 5px;
            box-shadow: 0 10px 25px rgba(0,0,0,0.3); margin-bottom: 20px; flex-wrap: wrap; justify-content: center;
        }

        .tab-btn {
            background: transparent; border: none; color: #94a3b8; font-family: inherit;
            font-size: 15px; font-weight: 700; padding: 12px 30px; border-radius: 50px;
            cursor: pointer; transition: var(--transition); display: flex; align-items: center; gap: 8px;
        }

        .tab-btn:hover { color: #fff; }
        .tab-btn.active {
            background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
            color: white; box-shadow: 0 4px 15px rgba(99, 102, 241, 0.4);
        }

        /* GRID & CARDS */
        .pkd-grid {
            display: grid; grid-template-columns: repeat(auto-fill, minmax(320px, 1fr)); gap: 28px;
        }

        .pkd-card {
            background: var(--card-grad); backdrop-filter: blur(16px); border: 1px solid var(--border-light);
            padding: 30px 25px; border-radius: 28px; transition: transform 0.4s ease, border-color 0.4s ease;
            display: none; /* Default tersembunyi sepenuhnya */
            flex-direction: column; position: relative; overflow: hidden;
            box-shadow: 0 10px 30px -10px rgba(0, 0, 0, 0.5);
        }

        .pkd-card.show-card {
            display: flex;
            animation: fadeUp 0.6s ease both; 
        }

        @keyframes fadeUp {
            0% { opacity: 0; transform: translateY(40px); }
            100% { opacity: 1; transform: translateY(0); }
        }

        .pkd-card::before {
            content: ''; position: absolute; top: 0; left: 0; right: 0; height: 3px;
            background: linear-gradient(90deg, transparent, var(--primary), var(--accent), transparent);
            opacity: 0; transition: var(--transition); transform: translateX(-100%);
        }

        .pkd-card:hover {
            transform: translateY(-8px); border-color: rgba(129, 140, 248, 0.4);
            box-shadow: 0 25px 50px -12px rgba(99, 102, 241, 0.25), 0 0 15px rgba(245, 158, 11, 0.1) inset;
        }
        .pkd-card:hover::before { opacity: 1; transform: translateX(0); }

        .card-header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 20px; }

        .icon-area {
            width: 55px; height: 55px; background: linear-gradient(135deg, rgba(99, 102, 241, 0.2), rgba(67, 56, 202, 0.1));
            border-radius: 16px; display: flex; align-items: center; justify-content: center;
            color: var(--primary-light); font-size: 24px; transition: var(--transition);
            border: 1px solid rgba(129, 140, 248, 0.2);
        }

        .pkd-card:hover .icon-area {
            background: var(--primary); color: white; transform: scale(1.1) rotate(-8deg);
            box-shadow: 0 15px 25px -5px rgba(99, 102, 241, 0.5); border-color: transparent;
        }

        .pkd-number {
            background: rgba(255, 255, 255, 0.05); padding: 5px 12px; border-radius: 20px;
            font-size: 11px; font-weight: 700; color: var(--accent-light); text-transform: uppercase;
            letter-spacing: 1px; border: 1px solid rgba(255, 255, 255, 0.05);
        }

        .pkd-card h3 { font-size: 19px; font-weight: 700; margin: 0 0 12px; color: #f8fafc; line-height: 1.4; }

        /* SUB-MATERI LIST */
        .sub-materi {
            list-style: none; margin-bottom: 25px; flex-grow: 1;
        }
        .sub-materi li {
            font-size: 13px; color: #94a3b8; margin-bottom: 8px; display: flex; align-items: flex-start; gap: 8px;
            line-height: 1.5;
        }
        .sub-materi li i {
            color: var(--primary-light); font-size: 12px; margin-top: 3px;
        }

        .btn-container { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: auto; }
        .pkd-btn {
            padding: 12px 10px; border-radius: 12px; text-decoration: none; font-size: 13px; font-weight: 600;
            display: flex; align-items: center; justify-content: center; gap: 6px; transition: var(--transition);
        }

        .view-btn { background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%); color: white; border: 1px solid transparent; }
        .view-btn:hover { box-shadow: 0 8px 25px -5px rgba(99, 102, 241, 0.6); transform: translateY(-3px); }
        .download-btn { background: rgba(255, 255, 255, 0.03); color: #cbd5e1; border: 1px solid rgba(255, 255, 255, 0.1); }
        .download-btn:hover { background: #fff; color: var(--bg-base); transform: translateY(-3px); box-shadow: 0 8px 25px -5px rgba(255, 255, 255, 0.2); }

        @media (max-width: 768px) {
            body { padding: 30px 15px; }
            .pkd-title { font-size: 26px; }
            .pkd-card { padding: 25px 20px; }
            .tab-btn { padding: 10px 20px; font-size: 13px; }
        }
    </style>
</head>
