                <li><i class="fa-solid fa-check"></i> Perangkat Aksi, Agitasi, dan Teknik Orasi</li>
                <li><i class="fa-solid fa-check"></i> Manajemen Lapangan dan Negosiasi</li>
            </ul>
            <div class="btn-container">
                <a href="#" class="pkd-btn view-btn"><i class="fa-solid fa-eye"></i> Lihat</a>
