    </div>
</div>

<script>
    document.addEventListener('DOMContentLoaded', () => {
        const tabs = document.querySelectorAll('.tab-btn');
        const cards = document.querySelectorAll('.pkd-card');

        function filterCards(targetCategory) {
            let delayCount = 0;

            cards.forEach(card => {
                card.classList.remove('show-card');
            });

            setTimeout(() => {
                cards.forEach(card => {
                    if (card.getAttribute('data-category') === targetCategory) {
                        card.style.animationDelay = `${delayCount * 0.08}s`;
                        card.classList.add('show-card');
                        delayCount++;
                    }
                });
            }, 30); 
        }

        filterCards('mapaba');

        tabs.forEach(tab => {
            tab.addEventListener('click', () => {
                tabs.forEach(t => t.classList.remove('active'));
                tab.classList.add('active');
                filterCards(tab.getAttribute('data-target'));
            });
        });
    });
</script>

</body>
