<body>

<div class="mapaba-container">

<div class="mapaba-title">
RECAP MAPABA 2026 – 2035
</div>

<div class="mapaba-filter">
<select id="mapabaYearSelect" onchange="loadMapabaData()">
<option value="2026">Tahun 2026</option>
<option value="2027">Tahun 2027</option>
<option value="2028">Tahun 2028</option>
<option value="2029">Tahun 2029</option>
<option value="2030">Tahun 2030</option>
<option value="2031">Tahun 2031</option>
<option value="2032">Tahun 2032</option>
<option value="2033">Tahun 2033</option>
<option value="2034">Tahun 2034</option>
<option value="2035">Tahun 2035</option>
</select>
</div>

<table class="mapaba-table">
<thead>
<tr>
<th style="width:8%">No</th>
<th style="width:30%">Nama</th>
<th style="width:25%">Komisariat</th>
<th style="width:17%">Status</th>
<th style="width:20%">Sertifikat</th>
</tr>
</thead>
<tbody id="mapabaTableBody"></tbody>
</table>

<div class="mapaba-total" id="mapabaTotal">
Total: 0
</div>

</div>

<script>
































/./ DATA MAPABA
const mapabaData = {
2026:[
{nama:"Ahmad Rizki", komisariat:"Komisariat UNMUH", status:"Lulus"},
{nama:"Siti Aisyah", komisariat:"Komisariat IAIN", status:"Tidak Lulus"}
],
2027:[
{nama:"Fajar Ramadhan", komisariat:"Komisariat UNTAG", status:"Lulus"}
],
2028:[
{nama:"Nabila Putri", komisariat:"Komisariat IAIN", status:"Lulus"},
{nama:"Ilham Maulana", komisariat:"Komisariat UNMUH", status:"Tidak Lulus"}
],
2029:[],
2030:[],
2031:[],
2032:[],
2033:[],
2034:[],
2035:[]
};

function loadMapabaData(){
const year=document.getElementById("mapabaYearSelect").value;
const table=document.getElementById("mapabaTableBody");
const totalBox=document.getElementById("mapabaTotal");

table.innerHTML="";
let totalLulus=0;
let totalTidak=0;

const data=mapabaData[year];

if(data.length===0){
table.innerHTML=`<tr><td colspan="5">Belum ada data tahun ${year}</td></tr>`;
totalBox.innerHTML=`Total Lulus: 0 | Tidak Lulus: 0`;
return;
}

data.forEach((item,index)=>{
let statusClass=item.status==="Lulus"?"status-lulus":"status-tidak";

let sertifikatBtn=item.status==="Lulus"
? `<button class="btn-sertifikat" onclick="lihatSertifikat('${item.nama}','${year}')">Lihat</button>`
: `-`;

if(item.status==="Lulus") totalLulus++;
else totalTidak++;

table.innerHTML+=`
<tr>
<td>${index+1}</td>
<td>${item.nama}</td>
<td>${item.komisariat}</td>
<td class="${statusClass}">${item.status}</td>
<td>${sertifikatBtn}</td>
</tr>
`;
});

totalBox.innerHTML=`Total Lulus: ${totalLulus} | Tidak Lulus: ${totalTidak}`;
}

function lihatSertifikat(nama,tahun){
alert("Menampilkan Sertifikat\n\nNama: "+nama+"\nTahun: "+tahun+"\n\n(Integrasikan ke PDF / Gambar Sertifikat di sini)");
}

window.onload=loadMapabaData;
</script>

</body>
</html>"},"elements":[],"widgetType":"html"}],"isInner":false}]

