<style>

/* ===============================
   RESET
   =============================== */
body {
  margin: 0;
  font-family: 'Poppins', sans-serif;
}

/* ===============================
   HEADER BERITA PREMIUM
   =============================== */
.news-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 25px;
  padding: 22px 26px;

  background: linear-gradient(135deg, #ffffff, #eef3ff);
  border-radius: 18px;

  box-shadow: 0 10px 30px rgba(0,0,0,0.08);
  position: relative;
  overflow: hidden;
}

/* glow background */
.news-header::before {
  content: "";
  position: absolute;
  width: 250px;
  height: 250px;
  background: rgba(0,115,230,0.12);
  filter: blur(90px);
  top: -60px;
  right: -60px;
}

/* ===============================
   LEFT SIDE
   =============================== */
.news-header-left {
  z-index: 2;
}

.news-badge {
  display: inline-block;
  background: linear-gradient(135deg, #0073e6, #00c0ff);
  color: #fff;
  font-size: 0.75rem;
  padding: 6px 14px;
  border-radius: 20px;
  margin-bottom: 10px;
  font-weight: 600;
  letter-spacing: 0.5px;
}

.news-title {
  font-size: 1.9rem;
  font-weight: 700;
  color: #1a1a1a;
  margin: 0;
}

.news-subtitle {
  font-size: 0.95rem;
  color: #666;
  margin-top: 6px;
}

/* ===============================
   RIGHT SIDE LINE
   =============================== */
.news-header-right {
  flex: 1;
  display: flex;
  justify-content: flex-end;
}

.news-line {
  width: 140px;
  height: 4px;
  border-radius: 10px;
  background: linear-gradient(90deg, #0073e6, #00c0ff);
  position: relative;
  overflow: hidden;
}

/* animasi garis */
.news-line::after {
  content: "";
  position: absolute;
  width: 40%;
  height: 100%;
  background: rgba(255,255,255,0.8);
  left: -40%;
  animation: lineMove 2s linear infinite;
}

@keyframes lineMove {
  0% { left: -40%; }
  100% { left: 120%; }
}

/* ===============================
   ANIMASI MASUK
   =============================== */
.news-header {
  opacity: 0;
  transform: translateY(30px);
  animation: fadeUp 0.8s ease forwards;
}

@keyframes fadeUp {
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* ===============================
   RESPONSIVE
   =============================== */
@media (max-width: 768px) {
  .news-header {
    flex-direction: column;
    align-items: flex-start;
    gap: 12px;
    padding: 18px;
  }

  .news-title {
    font-size: 1.4rem;
  }

  .news-line {
    width: 90px;
  }
}

</style>
</head>

