  padding: 30px 20px;

  background-color: #f9fafc;
  background-image:
    linear-gradient(0deg, #e0e3eb 1px, transparent 1px),
    linear-gradient(90deg, #e0e3eb 1px, transparent 1px);
  background-size: 40px 40px;
}

/* ===============================
   POST CARD / BAR
   =============================== */
selector .elementor-post {
  display: flex;
  flex-direction: row;
  background: #ffffff;
  border-radius: 16px;
  overflow: hidden;
  border-left: 6px solid #0073e6;

  box-shadow: 0 10px 25px rgba(0,0,0,0.08);
  transition: all 0.35s ease;
}

/* Hover Effect */
selector .elementor-post:hover {
  transform: translateY(-6px);
  box-shadow: 0 25px 50px rgba(0,0,0,0.18);
  background: linear-gradient(90deg, #f7f9fc, #eef5ff);
  border-left-color: #00c0ff;
}

/* ===============================
   THUMBNAIL (GAMBAR)
   =============================== */
selector .elementor-post__thumbnail {
  flex: 0 0 230px;
  height: auto;
  overflow: hidden;
  position: relative;
}

selector .elementor-post__thumbnail img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 0.4s ease, filter 0.4s ease;
}

/* Hover image */
selector .elementor-post:hover .elementor-post__thumbnail img {
  transform: scale(1.08);
  filter: brightness(1.1);
}

/* ===============================
   KONTEN TEXT
   =============================== */
selector .elementor-post__text {
  flex: 1;
  padding: 20px 25px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

/* ===============================
   JUDUL
   =============================== */
selector .elementor-post__title {
  font-family: 'Poppins', sans-serif;
  font-weight: 700;
  font-size: 1.35rem;
  color: #222;
  margin-bottom: 10px;
  line-height: 1.3;
  transition: 0.3s;
}

selector .elementor-post__title:hover {
  color: #0073e6;
  text-shadow: 0 3px 8px rgba(0,115,230,0.3);
}

/* ===============================
   EXCERPT
   =============================== */
selector .elementor-post__excerpt {
  font-family: 'Roboto', sans-serif;
  font-size: 0.95rem;
  color: #555;
  line-height: 1.6;

  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* ===============================
   READ MORE BUTTON
   =============================== */
selector .elementor-post__read-more {
  align-self: flex-start;
  margin-top: 12px;
  padding: 8px 18px;
  background: linear-gradient(135deg, #0073e6, #00c0ff);
