    font-size: 1.2rem;
  }
}

/* ===============================
   FIX GAMBAR TIDAK MUNCUL
   =============================== */
selector .elementor-post__thumbnail a {
  display: block;
  width: 100%;
  height: 100%;
}

selector .elementor-post__thumbnail img {
  min-height: 100%;
}

/* ===============================
   OPTIONAL: SMOOTH ANIMATION MASUK
   =============================== */
selector .elementor-post {
  animation: fadeUp 0.6s ease forwards;
  opacity: 0;
}

@keyframes fadeUp {
  from {
    transform: translateY(20px);
    opacity: 0;
  }
  to {
    transform: translateY(0);
    opacity: 1;
  }
}"},"elements":[],"widgetType":"posts"}],"isInner":false}]

[{"id":"fed1bab","elType":"container","settings":[],"elements":[{"id":"3d510d0","elType":"widget","settings":{"html":"<!DOCTYPE html>
<html lang="id">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Portal Pendaftaran Kaderisasi PMII</title>
    <link rel="preconnect" href="https://fonts.googleapis.com">
