<script>
const ucapanText = `Dengan penuh rasa hormat dan kebahagiaan, kami segenap keluarga besar PMII STAIM Kendal Ngawi mengucapkan Selamat Hari Raya Idulfitri 1447 Hijriah.

Semoga pada hari yang penuh berkah ini, kita semua diberikan kesehatan, keselamatan, dan kesempatan untuk meningkatkan ketakwaan kepada Allah SWT.

Kami juga berharap agar silaturahmi dan persaudaraan senantiasa terjaga, serta segala kesalahan di masa lalu dapat dimaafkan.

Semoga Allah SWT menerima amal ibadah kita dan menjadikan kita termasuk hamba-hamba-Nya yang bertaqwa.`;

const hadisArab = `إِنَّ لِكُلِّ قَوْمٍ عِيدًا وَهَذَا عِيدُنَا`;
const hadisText = `"Setiap kaum memiliki hari raya, dan ini adalah hari raya kita."`;

function type(el,text,speed=20){
  let i=0;
  function t(){
    if(i<text.length){
      el.innerHTML+=text[i];
      i++;
      setTimeout(t,speed);
    }
  }
  t();
}

/* GOLD LOVE STABIL */
function createLove(){
  const love = document.createElement("div");
  love.classList.add("love");

  const symbols = ["❤","✦","★","✧"];
  love.innerHTML = symbols[Math.floor(Math.random()*symbols.length)];

  const container = document.getElementById("loveContainer");
  love.style.left = Math.random()*window.innerWidth+"px";
  love.style.animationDuration = (3+Math.random()*3)+"s";

  container.appendChild(love);
  setTimeout(()=>love.remove(),6000);
}

const cover = document.getElementById("coverClone");
const bar = document.querySelector(".loaderBar");
const wrap = document.querySelector(".loaderClone");

let loveInterval;

cover.onclick = ()=>{
  wrap.style.opacity=1;
  bar.style.width="100%";

  if(!loveInterval){
    loveInterval = setInterval(createLove,200);
  }

  setTimeout(()=>{
    cover.classList.toggle("active");
    wrap.style.opacity=0;

    type(document.getElementById("ucapan"),ucapanText,18);
    setTimeout(()=>type(document.getElementById("hadisArab"),hadisArab,25),2000);
    setTimeout(()=>type(document.getElementById("hadisText"),hadisText,20),3500);

  },2000);
};
</script>

