  border-radius: 20px;
  box-shadow: 0 10px 40px rgba(0,0,0,0.5);
  display: flex;
  justify-content: center;
  align-items: center;
  cursor: pointer;
  transition: transform 0.4s ease;
}

.card:hover {
  transform: scale(1.03);
}

.card h2 {
  color: gold;
  font-family: 'Playfair Display', serif;
  text-align: center;
}

/* OVERLAY UCAPAN */
.overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: radial-gradient(circle, #020617, #000);
  display: flex;
  justify-content: center;
  align-items: center;
  flex-direction: column;
  opacity: 0;
  pointer-events: none;
  transition: 0.5s;
}

.overlay.active {
  opacity: 1;
  pointer-events: all;
}

.overlay h1 {
  color: gold;
  font-family: 'Playfair Display', serif;
}

/* 🔥 WARNING TRANSPARAN */
.warning {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  display: none;
  justify-content: center;
  align-items: center;

  background: rgba(0, 0, 0, 0.3);
  backdrop-filter: blur(10px);

  z-index: 9999;
}

.warning.active {
  display: flex;
}

/* BOX */
.warning-box {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255,255,255,0.2);
